std::vector<std::uint8_t> LocalContainerOccurrencePartitionPayload(
    std::uint64_t packStableId, std::uint64_t revision,
    VnObjectId soundId, VnObjectId containerId) {
    const PlayablePropertyProgramViewV1 sound = MakeSoundProperty(soundId, 0);
    const PlayablePropertyProgramViewV1 containerProperty =
        MakeContainerProperty(containerId, 1);
    const PlayableRefV1 soundRef = PlayableRefFromProperty(sound);
    ContainerChildProgramViewV2 child{};
    child.playable = soundRef;
    child.frequencyWeight = 1;
    ContainerProgramViewV3 container = MakeContainerProgram(
        containerId, containerProperty.programSemanticFingerprint);
    container.childCount = 1;
    container.children = &child;
    PlayableOccurrencePropertyViewV1 occurrence{};
    occurrence.parentKind =
        playableproperties::ContentPropertyKindV1::Container;
    occurrence.parentStableId = harkentest::ObjectId(containerId);
    occurrence.parentProgramSemanticFingerprint =
        containerProperty.programSemanticFingerprint;
    occurrence.childPlayable = soundRef;
    occurrence.payload = EmptyOccurrencePayload();
    occurrence.occurrenceSemanticFingerprint =
        ComputePlayableOccurrenceFingerprintV1(occurrence);
    const PlayablePropertyProgramViewV1 properties[2] = {sound,
                                                         containerProperty};
    ContainerWorldInstallViewV1 world{};
    world.playableProperties = properties;
    world.playablePropertyCount = 2;
    world.playableOccurrences = &occurrence;
    world.playableOccurrenceCount = 1;
    world.containers = &container;
    world.containerCount = 1;
    FinishPlayableWorld(&world, kWorldCapabilityRandomDraw);
    return WrapWorldPartition(packStableId, revision, world, 2);
}

enum class CompositeAggregateRow : std::uint8_t {
    Variable,
    Property,
    Occurrence,
    Track,
    Piece,
    Container,
    Action,
};

std::vector<std::uint8_t> AggregateRowPartitionPayload(
    CompositeAggregateRow row, std::uint64_t packStableId,
    std::uint64_t partitionRevision, VnObjectId stableId) {
    switch (row) {
    case CompositeAggregateRow::Variable:
    case CompositeAggregateRow::Action:
        return ActionPartitionPayload(packStableId, partitionRevision,
                                      harkentest::OffsetObjectId(stableId, 1), stableId);
    case CompositeAggregateRow::Property: {
        const PlayablePropertyProgramViewV1 sound =
            MakeSoundProperty(stableId);
        return SharedSoundPartitionPayload(packStableId, partitionRevision,
                                           sound);
    }
    case CompositeAggregateRow::Occurrence:
        return LocalContainerOccurrencePartitionPayload(
            packStableId, partitionRevision, stableId, harkentest::OffsetObjectId(stableId, 1));
    case CompositeAggregateRow::Track:
        return TrackOnlyPartitionPayload(packStableId, partitionRevision,
                                         stableId);
    case CompositeAggregateRow::Piece:
        return PieceOnlyPartitionPayload(packStableId, partitionRevision,
                                         stableId);
    case CompositeAggregateRow::Container:
        return LegalContainerPartitionPayload(packStableId, partitionRevision,
                                              stableId);
    }
    ADD_FAILURE() << "unknown aggregate row";
    return {};
}

std::uint32_t AggregateRowCount(
    CompositeAggregateRow row, const ContainerWorldInstallViewV1& world) {
    switch (row) {
    case CompositeAggregateRow::Variable:
        return world.variableCount;
    case CompositeAggregateRow::Property:
        return world.playablePropertyCount;
    case CompositeAggregateRow::Occurrence:
        return world.playableOccurrenceCount;
    case CompositeAggregateRow::Track:
        return world.trackScheduleCount;
    case CompositeAggregateRow::Piece:
        return world.pieceScheduleCount;
    case CompositeAggregateRow::Container:
        return world.containerCount;
    case CompositeAggregateRow::Action:
        return world.actionCount;
    }
    ADD_FAILURE() << "unknown aggregate row";
    return 0;
}

std::vector<std::uint8_t> CapacityLimitedContainerChildPartitionPayload(
    std::uint64_t packStableId, std::uint64_t revision,
    VnObjectId containerId, const PlayableRefV1& childPlayable,
    std::uint32_t maxKnownScheduleLeaves) {
    const PlayablePropertyProgramViewV1 property =
        MakeContainerProperty(containerId);
    ContainerChildProgramViewV2 child{};
    child.playable = childPlayable;
    child.stableChildOrdinal = 0;
    child.frequencyWeight = 1;
    ContainerProgramViewV3 container = MakeContainerProgram(
        containerId, property.programSemanticFingerprint);
    container.childCount = 1;
    container.children = &child;
    PlayableOccurrencePropertyViewV1 occurrence{};
    occurrence.parentKind =
        playableproperties::ContentPropertyKindV1::Container;
    occurrence.parentStableId = harkentest::ObjectId(containerId);
    occurrence.parentProgramSemanticFingerprint =
        property.programSemanticFingerprint;
    occurrence.stableOccurrenceOrdinal = 0;
    occurrence.childPlayable = childPlayable;
    occurrence.payload = EmptyOccurrencePayload();
    occurrence.occurrenceSemanticFingerprint =
        ComputePlayableOccurrenceFingerprintV1(occurrence);
    ContainerWorldInstallViewV1 world{};
    world.playableProperties = &property;
    world.playablePropertyCount = 1;
    world.playableOccurrences = &occurrence;
    world.playableOccurrenceCount = 1;
    world.containers = &container;
    world.containerCount = 1;
    FinishPlayableWorld(&world, kWorldCapabilityRandomDraw);
    world.capacity.maxKnownScheduleLeaves = maxKnownScheduleLeaves;
    world.identity.runtimeSemanticFingerprint =
        ComputeCurrentWorldFingerprintV4(world);
    return WrapWorldPartition(packStableId, revision, world, 1);
}

VnResult CommitParsedPack(PackComposition* composition,
                          const std::vector<std::uint8_t>& bytes,
                          VnPackHandle handle, std::uint32_t maxActions) {
    PackCanonicalImage image;
    const VnResult parsed =
        ParsePackCanonicalImage(bytes.data(), bytes.size(), &image);
    if (parsed != VN_OK) {
        return parsed;
    }
    PackComposition::CandidateOwner owner;
    const VnResult prepared =
        composition->PrepareCandidate(image, handle, &owner);
    if (prepared != VN_OK) {
        return prepared;
    }
    std::vector<PackComposition::CandidateOwner> owners;
    owners.push_back(std::move(owner));
    const VnResult committed =
        composition->Commit(std::move(owners), nullptr, 0, maxActions, 0);
    return committed;
}

std::vector<std::uint8_t> BuildPostActionPack(
    std::uint64_t packStableId, std::uint64_t contentRevision,
    std::uint64_t partitionRevision, VnObjectId actionId,
    VnObjectId targetActionId, std::uint64_t targetFingerprint,
    std::uint64_t requiredProvider) {
    ImageBuilder builder(kPackKindCanonicalContent);
    builder.AddEntry(kPackEntryKindPackRequirementBlock, packStableId,
                     RequirementPayload(packStableId, contentRevision,
                                        partitionRevision));
    builder.AddEntry(
        kPackEntryKindCanonicalDefinitionPartition, packStableId,
        PostActionPartitionPayload(packStableId, partitionRevision, actionId,
                                   targetActionId, targetFingerprint));
    builder.AddEntry(kPackEntryKindPackDependencyEdge, 0,
                     RequiredEdgePayload(requiredProvider));
    return builder.Build();
}

std::string WriteTemp(const std::string& name,
                      const std::vector<std::uint8_t>& bytes) {
    const std::string path = std::string(HARKEN_TEMP_DIR "/") + name;
    std::filesystem::create_directories(std::filesystem::path(path).parent_path());
    std::ofstream out(path, std::ios::binary | std::ios::trunc);
    out.write(reinterpret_cast<const char*>(bytes.data()),
              static_cast<std::streamsize>(bytes.size()));
    return path;
}

std::vector<std::uint8_t> BuildInitWithoutCatalog() {
    constexpr std::uint64_t kInitId = 11;
    ImageBuilder builder(kPackKindInit);
    builder.AddEntry(kPackEntryKindPackRequirementBlock, kInitId,
                     RequirementPayload(kInitId, 1, 1));
    builder.AddEntry(kPackEntryKindCanonicalDefinitionPartition, kInitId,
                     EmptyPartitionPayload(kInitId, 1));
    harkentest::packfoundation::AppendNeutralMasterSnapshotV1(&builder);
    return builder.Build();
}

TEST(PackComposition, RootActivationNeedsNoCatalogWhileProvisionalLookupDoes) {
    const std::filesystem::path directory =
        std::filesystem::path(HARKEN_TEMP_DIR) / "path-load-no-catalog";
    std::filesystem::create_directories(directory);
    const std::vector<std::uint8_t> initBytes = BuildInitWithoutCatalog();
    const std::vector<std::uint8_t> contentBytes = BuildContentPack(22, 1, 7, harkentest::ObjectId(2002));
    const std::string initPath = (directory / "Init.pack").string();
    const std::string contentPath = (directory / "Content.pack").string();
    {
        std::ofstream out(initPath, std::ios::binary | std::ios::trunc);
        out.write(reinterpret_cast<const char*>(initBytes.data()),
                  static_cast<std::streamsize>(initBytes.size()));
    }
    {
        std::ofstream out(contentPath, std::ios::binary | std::ios::trunc);
        out.write(reinterpret_cast<const char*>(contentBytes.data()),
                  static_cast<std::streamsize>(contentBytes.size()));
    }

    harken::PackCanonicalImage initImage;
    ASSERT_EQ(VN_OK, ParsePackCanonicalImage(initBytes.data(), initBytes.size(),
                                             &initImage));
    EXPECT_FALSE(initImage.hasCatalog);

    EngineSession session(MakeNullConfig());
    ASSERT_EQ(VN_OK, session.InitResult());
    const std::string root = directory.string();
    VnCanonicalPackSetMemberV1 members[2]{};
    VnCanonicalPackSetMemberResultV1 rows[2]{};
    const char* paths[] = {initPath.c_str(), contentPath.c_str()};
    for (std::size_t i = 0; i < 2; ++i) {
        members[i].structSize = sizeof(members[i]);
        members[i].packStableId = i == 0 ? 11 : 22;
        members[i].packKind = i == 0 ? VN_CANONICAL_PACK_SET_MEMBER_INIT
                                    : VN_CANONICAL_PACK_SET_MEMBER_CONTENT;
        members[i].flags = VN_CANONICAL_PACK_SET_MEMBER_ROOT;
        members[i].utf8Path = paths[i];
        members[i].utf8ContainmentRoot = root.c_str();
        rows[i].structSize = sizeof(rows[i]);
    }
    VnCanonicalPackSetActivationReportV1 initial{};
    ASSERT_EQ(VN_OK, harkentest::ActivateCanonicalMembersV1(
                          members, 1, rows, initial));
    members[0].expectedHandle = initial.initHandle;

    VnPackLoadDesc catalogLookup{};
    catalogLookup.structSize = sizeof(catalogLookup);
    catalogLookup.flags = VN_PACK_LOAD_FLAG_ROOT;
    catalogLookup.packStableId = 22;
    catalogLookup.utf8ContainmentRoot = root.c_str();
    VnPackHandle missing = 0;
    EXPECT_EQ(VN_UNKNOWN_ID,
              LoadProvisionalCanonicalContentForTests(
                  *session.Engine(), &catalogLookup, &missing));
    EXPECT_EQ(0u, missing);

    VnCanonicalPackSetActivationReportV1 added{};
    ASSERT_EQ(VN_OK, harkentest::ActivateCanonicalMembersV1(
                          members, 2, rows, added, initial.initHandle,
                          initial.resultSetRevision));
    ASSERT_NE(0u, rows[1].handle);

    members[0].expectedHandle = added.initHandle;
    members[1].packStableId = 99;
    const auto published = session.Engine()->packComposition.PublishedHandle();
    const auto generation = session.Engine()->packComposition.CompositeGeneration();
    VnCanonicalPackSetMemberResultV1 refusedRows[2]{};
    for (auto& result : refusedRows) result.structSize = sizeof(result);
    VnCanonicalPackSetActivationReportV1 refused{};
    EXPECT_EQ(VN_UNKNOWN_ID, harkentest::ActivateCanonicalMembersV1(
                                members, 2, refusedRows, refused, added.initHandle,
                                added.resultSetRevision));
    EXPECT_EQ(0u, refusedRows[1].handle);
    EXPECT_EQ(published.get(), session.Engine()->packComposition.Published());
    EXPECT_EQ(generation, session.Engine()->packComposition.CompositeGeneration());
}

VnResult ProviderReturnsOwnedBytes(void* userData, std::uint64_t, const char*,
                                   std::uint32_t, std::uint64_t,
                                   VnPackByteSpan* outSpan) {
    const auto* bytes = static_cast<const std::vector<std::uint8_t>*>(userData);
    if (bytes == nullptr || outSpan == nullptr) {
        return VN_INVALID_ARG;
    }
    outSpan->structSize = sizeof(VnPackByteSpan);
    outSpan->reserved0 = 0;
    outSpan->bytes = bytes->data();
    outSpan->byteCount = bytes->size();
    return VN_OK;
}

TEST(PackComposition, CataloglessProviderRefusesStableIdMismatch) {
    const std::vector<std::uint8_t> initBytes = BuildInitWithoutCatalog();
    const std::vector<std::uint8_t> contentBytes =
        BuildContentPack(22, 1, 7, harkentest::ObjectId(2002));
    EngineSession session(MakeNullConfig());
    ASSERT_EQ(VN_OK, session.InitResult());

    VnCanonicalPackSetMemberV1 members[2]{};
    VnCanonicalPackSetMemberResultV1 rows[2]{};
    const std::vector<std::uint8_t>* bytes[] = {&initBytes, &contentBytes};
    for (std::size_t i = 0; i < 2; ++i) {
        members[i].structSize = sizeof(members[i]);
        members[i].packStableId = i == 0 ? 11 : 99;
        members[i].packKind = i == 0 ? VN_CANONICAL_PACK_SET_MEMBER_INIT
                                    : VN_CANONICAL_PACK_SET_MEMBER_CONTENT;
        members[i].flags = VN_CANONICAL_PACK_SET_MEMBER_PROVIDER;
        members[i].providerUserData = const_cast<std::vector<std::uint8_t>*>(bytes[i]);
        members[i].provide = ProviderReturnsOwnedBytes;
        members[i].release = +[](void*, std::uint64_t, VnPackByteSpan) {};
        rows[i].structSize = sizeof(rows[i]);
    }
    VnCanonicalPackSetActivationReportV1 initial{};
    ASSERT_EQ(VN_OK, harkentest::ActivateCanonicalMembersV1(
                          members, 1, rows, initial));
    members[0].expectedHandle = initial.initHandle;
    const auto published = session.Engine()->packComposition.PublishedHandle();
    const auto generation = session.Engine()->packComposition.CompositeGeneration();
    VnCanonicalPackSetActivationReportV1 refused{};
    EXPECT_EQ(VN_UNKNOWN_ID, harkentest::ActivateCanonicalMembersV1(
                                members, 2, rows, refused, initial.initHandle,
                                initial.resultSetRevision));
    EXPECT_EQ(0u, rows[1].handle);
    EXPECT_EQ(published.get(), session.Engine()->packComposition.Published());
    EXPECT_EQ(generation, session.Engine()->packComposition.CompositeGeneration());

    members[1].packStableId = 22;
    VnCanonicalPackSetActivationReportV1 added{};
    ASSERT_EQ(VN_OK, harkentest::ActivateCanonicalMembersV1(
                          members, 2, rows, added, initial.initHandle,
                          initial.resultSetRevision));
    EXPECT_NE(0u, rows[1].handle);
}

