TEST(PackComposition, KeptPackAIdentitySurvivesPackBUnload) {
    const std::vector<std::uint8_t> packABytes =
        BuildContentPack(22, 1, 7, harkentest::ObjectId(2002));
    const std::vector<std::uint8_t> packBBytes =
        BuildContentPack(33, 1, 9, harkentest::ObjectId(3003), harkentest::ObjectId(8));
    const std::vector<std::uint8_t> initBytes = BuildKeepIdentityInit(
        Fnv1a64(packABytes.data(), packABytes.size()),
        Fnv1a64(packBBytes.data(), packBBytes.size()));
    const std::string initPath = WriteTemp("f2-keep-a-init.pack", initBytes);
    const std::string packAPath = WriteTemp("f2-keep-a.pack", packABytes);
    const std::string packBPath = WriteTemp("f2-keep-b.pack", packBBytes);

    EngineSession session(MakeNullConfig());
    ASSERT_EQ(VN_OK, session.InitResult());
    VnCanonicalPackSetMemberV1 members[3]{};
    VnCanonicalPackSetMemberResultV1 rows[3]{};
    for (std::size_t i = 0; i < 3; ++i) {
        members[i].structSize = sizeof(members[i]);
        rows[i].structSize = sizeof(rows[i]);
    }
    members[0].packStableId = 11;
    members[0].packKind = VN_CANONICAL_PACK_SET_MEMBER_INIT;
    members[0].utf8Path = initPath.c_str();
    members[1].packStableId = 22;
    members[1].packKind = VN_CANONICAL_PACK_SET_MEMBER_CONTENT;
    members[1].utf8Path = packAPath.c_str();
    members[2].packStableId = 33;
    members[2].packKind = VN_CANONICAL_PACK_SET_MEMBER_CONTENT;
    members[2].utf8Path = packBPath.c_str();
    VnCanonicalPackSetActivationReportV1 initial{};
    ASSERT_EQ(VN_OK, harkentest::ActivateCanonicalMembersV1(
                          members, 2, rows, initial));
    const VnPackHandle initHandle = initial.initHandle;
    const VnPackHandle packA = rows[1].handle;

    const PackIdentityLookup before =
        session.Engine()->packComposition.Lookup(harkentest::ObjectId(2002));
    ASSERT_EQ(PackIdentityReadiness::Active, before.readiness);
    ASSERT_NE(nullptr, before.action);
    EXPECT_EQ(harkentest::ObjectId(2002u), before.action->actionStableId);
    EXPECT_EQ(7u, before.lease.partitionRevision);
    const ActionProgramViewV1* pinnedAction = before.action;

    VnPostActionDesc post{};
    post.structSize = sizeof(post);
    post.actionId = harkentest::ObjectId(2002);
    VnActionFiringHandle firing = 0;
    EXPECT_EQ(VN_OK, Vn_PostAction(&post, &firing));
    EXPECT_NE(0u, firing);
    ActionFiringSnapshot admitted{};
    ASSERT_TRUE(session.Engine()->actionFirings.Capture(firing, &admitted));
    ASSERT_EQ(ActionFiringOwnerKind::Pack, admitted.owner.kind);

    members[0].expectedHandle = initHandle;
    members[1].expectedHandle = packA;
    VnCanonicalPackSetActivationReportV1 added{};
    ASSERT_EQ(VN_OK, harkentest::ActivateCanonicalMembersV1(
                          members, 3, rows, added, initHandle,
                          initial.resultSetRevision));
    EXPECT_EQ(packA, rows[1].handle);
    EXPECT_EQ(VN_OK, session.Engine()->packComposition.ValidateLease(
                         admitted.owner.pack));
    EXPECT_EQ(pinnedAction, session.Engine()->packComposition.FindActionAtLease(
                                admitted.owner.pack, harkentest::ObjectId(2002)).programView);
    const PackIdentityLookup beforeUnload =
        session.Engine()->packComposition.Lookup(harkentest::ObjectId(2002));
    ASSERT_EQ(PackIdentityReadiness::Active, beforeUnload.readiness);
    ASSERT_NE(nullptr, beforeUnload.action);
    const VnPackHandle packB = rows[2].handle;
    ASSERT_EQ(VN_OK, Vn_UnloadPack(packB));

    const PackIdentityLookup after =
        session.Engine()->packComposition.Lookup(harkentest::ObjectId(2002));
    ASSERT_EQ(PackIdentityReadiness::Active, after.readiness);
    ASSERT_NE(nullptr, after.action);
    EXPECT_EQ(harkentest::ObjectId(2002u), after.action->actionStableId);
    EXPECT_EQ(7u, after.lease.partitionRevision);
    EXPECT_EQ(beforeUnload.action, after.action);
    EXPECT_EQ(VN_OK, session.Engine()->packComposition.ValidateLease(
                         admitted.owner.pack));
    EXPECT_EQ(pinnedAction, session.Engine()->packComposition.FindActionAtLease(
                                admitted.owner.pack, harkentest::ObjectId(2002)).programView);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    firing = 0;
    EXPECT_EQ(VN_OK, Vn_PostAction(&post, &firing));
    EXPECT_NE(0u, firing);
    EXPECT_EQ(VN_CONTENT_NOT_LOADED, [&] {
        post.actionId = harkentest::ObjectId(3003);
        return Vn_PostAction(&post, &firing);
    }());
}

TEST(PackComposition, ImmediateSetValueAppliesFromLoadedPack) {
    const std::vector<std::uint8_t> packABytes =
        BuildContentPack(22, 1, 7, harkentest::ObjectId(2002));
    const std::vector<std::uint8_t> packBBytes =
        BuildContentPack(33, 1, 9, harkentest::ObjectId(3003), harkentest::ObjectId(8));
    const std::vector<std::uint8_t> initBytes = BuildKeepIdentityInit(
        Fnv1a64(packABytes.data(), packABytes.size()),
        Fnv1a64(packBBytes.data(), packBBytes.size()));
    const std::string initPath = WriteTemp("f2-setvalue-init.pack", initBytes);
    const std::string packAPath = WriteTemp("f2-setvalue-a.pack", packABytes);
    const std::string packBPath = WriteTemp("f2-setvalue-b.pack", packBBytes);

    EngineSession session(MakeNullConfig());
    ASSERT_EQ(VN_OK, session.InitResult());
    VnCanonicalPackSetMemberV1 members[3]{};
    VnCanonicalPackSetMemberResultV1 rows[3]{};
    const std::string paths[] = {initPath, packAPath, packBPath};
    const std::uint64_t stableIds[] = {11, 22, 33};
    for (std::size_t i = 0; i < 3; ++i) {
        members[i].structSize = sizeof(members[i]);
        members[i].packStableId = stableIds[i];
        members[i].packKind = i == 0 ? VN_CANONICAL_PACK_SET_MEMBER_INIT
                                      : VN_CANONICAL_PACK_SET_MEMBER_CONTENT;
        members[i].utf8Path = paths[i].c_str();
        rows[i].structSize = sizeof(rows[i]);
    }
    VnCanonicalPackSetActivationReportV1 report{};
    ASSERT_EQ(VN_OK, harkentest::ActivateCanonicalMembersV1(
                          members, 3, rows, report));
    const VnPackHandle packB = rows[2].handle;
    ASSERT_EQ(VN_OK, Vn_UnloadPack(packB));

    VnPostActionDesc post{};
    post.structSize = sizeof(post);
    post.actionId = harkentest::ObjectId(2002);
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&post, &firing));
    EXPECT_NE(0u, firing);

    ActionFiringSnapshot snapshot{};
    ASSERT_TRUE(session.Engine()->actionFirings.Capture(firing, &snapshot));
    ASSERT_EQ(ActionFiringOwnerKind::Pack, snapshot.owner.kind);
    EXPECT_EQ(snapshot.owner.pack.compositeGeneration,
              snapshot.worldGeneration);
    EXPECT_EQ(VN_OK,
              session.Engine()->packComposition.ValidateLease(
                  snapshot.owner.pack));
    EXPECT_EQ(VN_OK,
              session.Engine()->packs.ValidateResourceClosure(
                  snapshot.owner.pack.resourceClosureToken));

    harkentest::AdvanceVariableWrite(session.Engine());
    float value = 0.0f;
    ASSERT_TRUE(session.Engine()->variables.CurrentValue(harkentest::ObjectId(7), &value));
    EXPECT_FLOAT_EQ(0.5f, value);

    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    EXPECT_EQ(VN_STALE_HANDLE,
              session.Engine()->packComposition.ValidateLease(
                  snapshot.owner.pack));
    EXPECT_EQ(VN_STALE_HANDLE,
              session.Engine()->packs.ValidateResourceClosure(
                  snapshot.owner.pack.resourceClosureToken));
}

TEST(PackComposition, FirstInitPublicationTerminatesProvisionalContentWritesOnlyAtCommit) {
    EngineSession session(MakeNullConfig());
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& e = *session.Engine();
    const auto contentBytes = BuildContentPack(22, 1, 7, harkentest::ObjectId(2002));
    const auto contentPath = WriteTemp("variable-publication-content.pack", contentBytes);
    const auto initPath = WriteTemp("variable-publication-init.pack",
        BuildKeepIdentityInit(Fnv1a64(contentBytes.data(), contentBytes.size()), 0));
    const auto provisionalWorld = e.variables.CurrentWorldGeneration();
    const auto initialPublication = e.packComposition.PublishedHandle();
    VnPackLoadDesc desc{};
    desc.structSize = sizeof(desc);
    desc.utf8Path = initPath.c_str();
    VnPackHandle refusedInit = 99;
    ASSERT_EQ(VN_PACK_INIT_LIFECYCLE,
              harken::LoadProvisionalCanonicalContentForTests(e, &desc, &refusedInit));
    EXPECT_EQ(0u, refusedInit);
    EXPECT_EQ(initialPublication.get(), e.packComposition.Published());
    EXPECT_EQ(provisionalWorld, e.variables.CurrentWorldGeneration());
    desc.utf8Path = contentPath.c_str();
    VnPackHandle content = 0;
    ASSERT_EQ(VN_OK,
              harken::LoadProvisionalCanonicalContentForTests(e, &desc, &content));
    ASSERT_NE(0u, content);
    EXPECT_EQ(PackAuthorityMode::Pack, e.packComposition.Authority());
    EXPECT_EQ(0u, provisionalWorld);
    EXPECT_EQ(1u, e.variables.CurrentWorldGeneration());
    EXPECT_EQ(0u, e.variables.TerminationCount());
    const auto* provisional = e.packComposition.Published();
    ASSERT_NE(nullptr, provisional);
    ASSERT_EQ(1u, provisional->owners.size());
    EXPECT_EQ(22u, provisional->owners[0].packStableId);
    EXPECT_EQ(content, provisional->owners[0].handle);
    PackRevisionKey provisionalKey{};
    PackResourceRevisionToken provisionalToken = 0;
    ASSERT_TRUE(e.packs.ActiveRevisionIdentity(
        content, &provisionalKey, &provisionalToken));
    EXPECT_NE(0u, provisionalToken);
    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(7), 0.75f));
    const auto ticket = e.logicCommits.IssuedCount();
    const auto world = e.variables.CurrentWorldGeneration();
    const auto transport = e.variables.CurrentTransportEpoch();
    const auto published = e.packComposition.PublishedHandle();
    const auto frame = e.serviceFrameClock;
    desc.utf8Path = initPath.c_str();
    VnPackHandle init = 0;
    const auto activateInit = [&](VnPackHandle* result) {
        std::array<VnCanonicalPackSetMemberV1, 2> members{};
        std::array<VnCanonicalPackSetMemberResultV1, 2> rows{};
        for (std::size_t i = 0; i < members.size(); ++i) {
            members[i].structSize = sizeof(members[i]);
            rows[i].structSize = sizeof(rows[i]);
        }
        members[0].packStableId = 11;
        members[0].packKind = VN_CANONICAL_PACK_SET_MEMBER_INIT;
        members[0].utf8Path = initPath.c_str();
        members[1].packStableId = 22;
        members[1].packKind = VN_CANONICAL_PACK_SET_MEMBER_CONTENT;
        members[1].expectedHandle = content;
        members[1].utf8Path = contentPath.c_str();
        VnCanonicalPackSetActivationReportV1 report{};
        const auto status = harkentest::ActivateCanonicalMembersV1(
            members.data(), 2, rows.data(), report);
        *result = status == VN_OK ? report.initHandle : 0;
        return status;
    };
    SetPackStagingFaultForTests(PackStagingFault::AfterAllPreparedBeforeCommit);
    const auto failed = activateInit(&init);
    SetPackStagingFaultForTests(PackStagingFault::None);
    ASSERT_EQ(VN_PACK_RESIDENT_CAPACITY, failed);
    EXPECT_EQ(0u, init);
    EXPECT_EQ(published.get(), e.packComposition.Published());
    EXPECT_EQ(world, e.variables.CurrentWorldGeneration());
    EXPECT_EQ(1u, e.variables.PendingCount());
    EXPECT_EQ(0u, e.variables.TerminationCount());
    detail::ArmLogicAllocFaultForTests(1, detail::LogicAllocSite::PackVariablePublication);
    const auto allocationFailed = activateInit(&init);
    detail::DisarmLogicAllocFaultForTests();
    ASSERT_EQ(VN_BACKPRESSURE, allocationFailed);
    EXPECT_EQ(published.get(), e.packComposition.Published());
    EXPECT_EQ(world, e.variables.CurrentWorldGeneration());
    EXPECT_EQ(1u, e.variables.PendingCount());
    EXPECT_EQ(0u, e.variables.TerminationCount());
    harkentest::VariableOutcomeCapture outcomes(e);
    ASSERT_EQ(VN_OK, activateInit(&init));
    EXPECT_EQ(world + 1, e.variables.CurrentWorldGeneration());
    EXPECT_EQ(0u, e.variables.PendingCount());
    VariableOutcomeRecord record{};
    ASSERT_TRUE(outcomes.Pop(&record));
    EXPECT_EQ(ticket, record.acceptedTicket.sequence);
    EXPECT_EQ(VariableOutcomeKind::WorldReplacement, record.outcome);
    EXPECT_EQ(world, record.world);
    EXPECT_EQ(transport, record.transport);
    EXPECT_EQ(frame, record.actualFrame);
    VnVariableTicketQueryDescV1 query{};
    query.structSize = sizeof(query);
    query.ticket = {ticket, world, transport};
    VnVariableTicketQueryResultV1 result{};
    result.structSize = sizeof(result);
    ASSERT_EQ(VN_OK, Vn_QueryVariableTicket(&query, &result));
    EXPECT_EQ(VN_VARIABLE_TICKET_FOUND, result.status);
    EXPECT_EQ(VN_VARIABLE_OUTCOME_TERMINATED_WORLD, result.outcome);
    EXPECT_FALSE(outcomes.Pop(&record));
    EXPECT_EQ(world + 1, e.variables.CurrentWorldGeneration());
    EXPECT_EQ(1u, e.variables.TerminationCount());
    ASSERT_NO_FATAL_FAILURE(harkentest::AdvanceVariableWrite(&e));
    float value = 99;
    ASSERT_TRUE(e.variables.CurrentValue(harkentest::ObjectId(7), &value));
    EXPECT_FLOAT_EQ(0, value);
}

class NativeSlicePack : public ::testing::Test {
protected:
    EngineSession session{MakeNullConfig(4, 64, 48000)};
    VnPackHandle content = 0;

    void Load(const std::vector<std::uint8_t>& bytes) {
        ASSERT_EQ(VN_OK, session.InitResult());
        const auto init = BuildKeepIdentityInit(Fnv1a64(bytes.data(), bytes.size()), 0);
        const auto initPath = WriteTemp("native-slice-init.pack", init);
        const auto path = WriteTemp("native-slice-content.pack", bytes);
        VnCanonicalPackSetMemberV1 members[2]{};
        members[0].structSize = sizeof(members[0]);
        members[0].packStableId = 11;
        members[0].packKind = VN_CANONICAL_PACK_SET_MEMBER_INIT;
        members[0].utf8Path = initPath.c_str();
        members[1].structSize = sizeof(members[1]);
        members[1].packStableId = 22;
        members[1].packKind = VN_CANONICAL_PACK_SET_MEMBER_CONTENT;
        members[1].utf8Path = path.c_str();
        VnCanonicalPackSetMemberResultV1 rows[2]{};
        for (auto& row : rows) row.structSize = sizeof(row);
        VnCanonicalPackSetActivationReportV1 report{};
        ASSERT_EQ(VN_OK, harkentest::ActivateCanonicalMembersV1(
                              members, 2, rows, report));
        content = rows[1].handle;
    }

    VnResult Replace(const std::vector<std::uint8_t>& bytes) {
        const auto path = WriteTemp("native-slice-next.pack", bytes);
        VnPackLoadDesc desc{};
        desc.structSize = sizeof(desc);
        desc.utf8Path = path.c_str();
        return Vn_ReplacePack(content, reinterpret_cast<const VnPackDesc*>(&desc));
    }

    static VnPostActionDesc Post() {
        VnPostActionDesc post{};
        post.structSize = sizeof(post);
        post.actionId = harkentest::ObjectId(2002);
        return post;
    }

    std::array<std::uint64_t, 9> State() {
        const auto& e = *session.Engine();
        return {e.logicCommits.IssuedCount(), e.commands.PublishedHead(),
            e.commands.FreeSlots(), e.actionFirings.LiveCount(),
            e.actionFirings.FreeCount(), e.actionDeferredRecords.LiveCount(),
            e.variables.AcceptedCount(), e.variables.PendingCount(),
            e.playableInstances.LiveCount()};
    }

    struct Validation {
        const PackComposition::PublishedView* expected = nullptr;
        const ActionProgramViewV1* action = nullptr;
        std::uint64_t partition = 0;
        std::uint64_t checksum = 0;
        PackResourceRevisionToken resource = 0;
        VnResult result = VN_OK;
        mutable std::uint32_t calls = 0;
        mutable bool matched = false;

        static VnResult Check(const detail::ActionAdmissionView& view,
                              const void* context) noexcept {
            const auto& check = *static_cast<const Validation*>(context);
            ++check.calls;
            check.matched = view.packBacked && view.publication == check.expected &&
                view.action == check.action && view.action != nullptr &&
                view.action->actionStableId == harkentest::ObjectId(2002) && view.lease.packStableId == 22 &&
                view.lease.partitionRevision == check.partition &&
                view.lease.resourceToken == check.resource &&
                view.lease.leaseToken != 0 && view.lease.resourceClosureToken != 0 &&
                view.lease.compositeGeneration == view.publication->compositeGeneration;
            bool checksumMatches = false;
            if (view.publication != nullptr) {
                for (const auto& row : view.publication->catalog.catalogRows) {
                    if (row.ownerPackStableId == 22) {
                        checksumMatches = row.expectedContentHash == check.checksum;
                    }
                }
            }
            check.matched = check.matched && checksumMatches;
            return check.matched ? check.result : VN_STALE_HANDLE;
        }
    };

    Validation Expected(const std::vector<std::uint8_t>& bytes) {
        const auto& composition = session.Engine()->packComposition;
        const auto* published = composition.Published();
        Validation check;
        check.expected = published;
        check.action = composition.FindActionIn(*published, harkentest::ObjectId(2002)).programView;
        check.checksum = Fnv1a64(bytes.data(), bytes.size());
        for (const auto& owner : published->owners) {
            if (owner.packStableId == 22) {
                check.partition = owner.partitionRevision;
                check.resource = owner.resourceToken;
            }
        }
        return check;
    }
};

TEST_F(NativeSlicePack, CanonicalMediaPreservesLoopRegionAcrossLoadAndReplace) {
    constexpr VnObjectId kSoundId = harkentest::ObjectId(4511);
    const auto initial = BuildContentPack(
        22, 1, 7, harkentest::ObjectId(2002), harkentest::ObjectId(7), 0,
        0x3f000000u, kSoundId, harkentest::MakeDC(8, 0.25f),
        VariableScopeV1::Global, 2, 6);
    ASSERT_NO_FATAL_FAILURE(Load(initial));

    PCMView view = session.Engine()->registry.Lookup(kSoundId);
    ASSERT_TRUE(view.Valid());
    EXPECT_EQ(2u, view.loop.startFrame);
    EXPECT_EQ(6u, view.loop.endFrame);

    const auto replacement = BuildContentPack(
        22, 2, 8, harkentest::ObjectId(2002), harkentest::ObjectId(7), 0,
        0xbf000000u, kSoundId, harkentest::MakeDC(12, 0.5f),
        VariableScopeV1::Global, 3, 10);
    ASSERT_EQ(VN_OK, Replace(replacement));

    view = session.Engine()->registry.Lookup(kSoundId);
    ASSERT_TRUE(view.Valid());
    EXPECT_EQ(3u, view.loop.startFrame);
    EXPECT_EQ(10u, view.loop.endFrame);
}

TEST_F(NativeSlicePack, ValidatorRefusalHasNoEffectsAndRawPostStillSucceeds) {
    const auto bytes = BuildContentPack(22, 1, 7, harkentest::ObjectId(2002));
    ASSERT_NO_FATAL_FAILURE(Load(bytes));
    auto& e = *session.Engine();
    auto check = Expected(bytes);
    check.result = VN_CAPABILITY_UNAVAILABLE;
    const auto before = State();
    auto post = Post();
    VnActionFiringHandle firing = 99;
    ASSERT_EQ(VN_CAPABILITY_UNAVAILABLE, detail::PostActionWithValidation(
        &post, &firing, Validation::Check, &check));
    EXPECT_EQ(1u, check.calls);
    EXPECT_TRUE(check.matched);
    EXPECT_EQ(0u, firing);
    EXPECT_EQ(before, State());
    EXPECT_FALSE(e.packComposition.HasLiveResourceToken(check.resource));
    float value = -1.0f;
    ASSERT_TRUE(e.variables.CurrentValue(harkentest::ObjectId(7), &value));
    EXPECT_FLOAT_EQ(0.0f, value);
    ASSERT_EQ(VN_OK, Vn_PostAction(&post, &firing));
    ASSERT_NE(0u, firing);
    EXPECT_EQ(before[0] + 1, e.logicCommits.IssuedCount());
    ASSERT_NO_FATAL_FAILURE(harkentest::AdvanceVariableWrite(&e));
    ASSERT_TRUE(e.variables.CurrentValue(harkentest::ObjectId(7), &value));
    EXPECT_FLOAT_EQ(0.5f, value);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    EXPECT_FALSE(e.packComposition.HasLiveResourceToken(check.resource));
}

TEST_F(NativeSlicePack, AcceptedValidatorExecutesOnceAndReleasesItsOwnerNormally) {
    const auto bytes = BuildContentPack(22, 1, 7, harkentest::ObjectId(2002));
    ASSERT_NO_FATAL_FAILURE(Load(bytes));
    auto& e = *session.Engine();
    auto check = Expected(bytes);
    auto post = Post();
    const auto before = State();
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, detail::PostActionWithValidation(&post, &firing, Validation::Check, &check));
    EXPECT_EQ(1u, check.calls);
    EXPECT_TRUE(check.matched);
    EXPECT_EQ(before[0] + 1, e.logicCommits.IssuedCount());
    EXPECT_EQ(before[3] + 1, e.actionFirings.LiveCount());
    EXPECT_EQ(before[6] + 1, e.variables.AcceptedCount());
    ActionFiringSnapshot owner{};
    ASSERT_TRUE(e.actionFirings.Capture(firing, &owner));
    EXPECT_EQ(ActionFiringOwnerKind::Pack, owner.owner.kind);
    EXPECT_EQ(VN_OK, e.packComposition.ValidateLease(owner.owner.pack));
    EXPECT_EQ(VN_OK, e.packs.ValidateResourceClosure(owner.owner.pack.resourceClosureToken));
    ASSERT_NO_FATAL_FAILURE(harkentest::AdvanceVariableWrite(&e));
    VnActionFiringInfo validated{};
    validated.structSize = sizeof(validated);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &validated));
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    EXPECT_EQ(VN_STALE_HANDLE, e.packComposition.ValidateLease(owner.owner.pack));
    EXPECT_EQ(VN_STALE_HANDLE, e.packs.ValidateResourceClosure(owner.owner.pack.resourceClosureToken));
    EXPECT_FALSE(e.packComposition.HasLiveResourceToken(owner.owner.pack.resourceToken));
    ASSERT_EQ(VN_OK, detail::PostActionWithValidation(&post, &firing, nullptr, &check));
    ASSERT_NO_FATAL_FAILURE(harkentest::AdvanceVariableWrite(&e));
    VnActionFiringInfo raw{};
    raw.structSize = sizeof(raw);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &raw));
    EXPECT_EQ(validated.state, raw.state);
    EXPECT_EQ(1u, check.calls);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

TEST_F(NativeSlicePack, EarlierFailuresNeverInvokeValidator) {
    const auto bytes = BuildContentPack(22, 1, 7, harkentest::ObjectId(2002));
    ASSERT_NO_FATAL_FAILURE(Load(bytes));
    auto check = Expected(bytes);
    auto post = Post();
    const auto before = State();
    VnActionFiringHandle firing = 99;
    EXPECT_EQ(VN_INVALID_ARG, detail::PostActionWithValidation(nullptr, &firing, Validation::Check, &check));
    EXPECT_EQ(0u, firing);
    EXPECT_EQ(VN_INVALID_ARG, detail::PostActionWithValidation(&post, nullptr, Validation::Check, &check));
    for (int invalid = 0; invalid < 4; ++invalid) {
        post = Post();
        if (invalid == 0) --post.structSize;
        if (invalid == 1) post.flags = 1;
        if (invalid == 2) post.actionId = harkentest::ObjectId(0);
        if (invalid == 3) post.reserved0 = 1;
        firing = 99;
        EXPECT_EQ(VN_INVALID_ARG, detail::PostActionWithValidation(&post, &firing, Validation::Check, &check));
        EXPECT_EQ(0u, firing);
    }
    post = Post();
    VnEmitterHandle stale = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&stale));
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(stale));
    post.emitter = stale;
    for (const auto& [id, result] : std::array<std::pair<VnActionId, VnResult>, 3>{
             {{harkentest::ObjectId(2002), VN_STALE_HANDLE}, {harkentest::ObjectId(3003), VN_CONTENT_NOT_LOADED}, {harkentest::ObjectId(9999), VN_UNKNOWN_ID}}}) {
        post.actionId = id;
        firing = 99;
        EXPECT_EQ(result, detail::PostActionWithValidation(&post, &firing, Validation::Check, &check));
        EXPECT_EQ(0u, firing);
    }
    EXPECT_EQ(0u, check.calls);
    EXPECT_EQ(before, State());
    EXPECT_FALSE(session.Engine()->packComposition.HasLiveResourceToken(check.resource));
}

TEST_F(NativeSlicePack, ReplacedContentRejectsOldContextAndAcceptsFreshContext) {
    const auto bytes = BuildContentPack(22, 1, 7, harkentest::ObjectId(2002));
    ASSERT_NO_FATAL_FAILURE(Load(bytes));
    const auto oldPublication = session.Engine()->packComposition.PublishedHandle();
    auto stale = Expected(bytes);
    const auto next = BuildContentPack(22, 2, 8, harkentest::ObjectId(2002), harkentest::ObjectId(7), 0, 0xbf000000u);
    ASSERT_EQ(VN_OK, Replace(next));
    EXPECT_NE(oldPublication.get(), session.Engine()->packComposition.Published());
    const auto before = State();
    auto post = Post();
    VnActionFiringHandle firing = 99;
    ASSERT_EQ(VN_STALE_HANDLE, detail::PostActionWithValidation(&post, &firing, Validation::Check, &stale));
    EXPECT_EQ(1u, stale.calls);
    EXPECT_FALSE(stale.matched);
    EXPECT_EQ(0u, firing);
    EXPECT_EQ(before, State());
    auto fresh = Expected(next);
    ASSERT_EQ(VN_OK, detail::PostActionWithValidation(&post, &firing, Validation::Check, &fresh));
    EXPECT_EQ(1u, fresh.calls);
    EXPECT_TRUE(fresh.matched);
    ASSERT_NO_FATAL_FAILURE(harkentest::AdvanceVariableWrite(session.Engine()));
    float value = 0.0f;
    ASSERT_TRUE(session.Engine()->variables.CurrentValue(harkentest::ObjectId(7), &value));
    EXPECT_FLOAT_EQ(-0.5f, value);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

TEST_F(NativeSlicePack, FailedPublicationPreservesAppliedBanksAndPendingTicket) {
    ASSERT_NO_FATAL_FAILURE(Load(BuildContentPack(
        22, 1, 7, harkentest::ObjectId(2002), harkentest::ObjectId(7), 0, 0x3f000000u, harkentest::ObjectId(0), {}, VariableScopeV1::Emitter)));
    auto& e = *session.Engine();
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(7), 0.25f));
    ASSERT_NO_FATAL_FAILURE(harkentest::AdvanceVariableWrite(&e));
    ASSERT_EQ(VN_OK, Vn_SetEmitterValue(emitter, harkentest::ObjectId(7), -0.25f));
    ASSERT_NO_FATAL_FAILURE(harkentest::AdvanceVariableWrite(&e));
    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(7), 0.75f));
    const auto ticket = e.logicCommits.IssuedCount();
    const auto before = State();
    const auto generation = e.variables.CurrentWorldGeneration();
    const auto publication = e.packComposition.PublishedHandle();
    const VnVariableId id = harkentest::ObjectId(7);
    BankVersionToken globalBefore{}, emitterBefore{};
    float value = 0;
    ASSERT_TRUE(e.variables.CaptureCurrentBank(0, &id, 1, &value, &globalBefore));
    ASSERT_TRUE(e.variables.CaptureCurrentBank(emitter, &id, 1, &value, &emitterBefore));
    for (auto fault : {PackStagingFault::CompositionPublish, PackStagingFault::AfterAllPreparedBeforeCommit}) {
        SetPackStagingFaultForTests(fault);
        const auto result = Replace(BuildContentPack(22, 2, 8, harkentest::ObjectId(2002), harkentest::ObjectId(9)));
        SetPackStagingFaultForTests(PackStagingFault::None);
        ASSERT_EQ(VN_PACK_RESIDENT_CAPACITY, result);
        EXPECT_EQ(before, State());
        EXPECT_EQ(publication.get(), e.packComposition.Published());
        EXPECT_EQ(generation, e.variables.CurrentWorldGeneration());
        BankVersionToken globalAfter{}, emitterAfter{};
        ASSERT_TRUE(e.variables.CaptureCurrentBank(0, &id, 1, &value, &globalAfter));
        EXPECT_FLOAT_EQ(0.25f, value);
        EXPECT_EQ(globalBefore.slot, globalAfter.slot);
        EXPECT_EQ(globalBefore.generation, globalAfter.generation);
        ASSERT_TRUE(e.variables.CaptureCurrentBank(emitter, &id, 1, &value, &emitterAfter));
        EXPECT_FLOAT_EQ(-0.25f, value);
        EXPECT_EQ(emitterBefore.slot, emitterAfter.slot);
        EXPECT_EQ(emitterBefore.generation, emitterAfter.generation);
        ASSERT_TRUE(e.emitters.LocalValue(emitter, id, &value));
        EXPECT_FLOAT_EQ(-0.25f, value);
        EXPECT_FALSE(e.variables.CurrentValue(harkentest::ObjectId(9), &value));
    }
    harkentest::VariableOutcomeCapture outcomes(e);
    std::uint32_t applied = 0;
    for (std::uint32_t block = 0; block < 32 && e.variables.PendingCount() != 0; ++block) {
        e.nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        VariableOutcomeRecord outcome{};
        while (outcomes.Pop(&outcome)) {
            if (outcome.acceptedTicket.sequence == ticket) {
                EXPECT_EQ(VariableOutcomeKind::Applied, outcome.outcome);
                ++applied;
            }
        }
    }
    EXPECT_EQ(0u, e.variables.PendingCount());
    EXPECT_EQ(1u, applied);
    ASSERT_TRUE(e.variables.CurrentValue(harkentest::ObjectId(7), &value));
    EXPECT_FLOAT_EQ(0.75f, value);
    ASSERT_TRUE(e.variables.CurrentValue(emitter, harkentest::ObjectId(7), &value));
    EXPECT_FLOAT_EQ(0.75f, value);
    EXPECT_FALSE(e.emitters.LocalValue(emitter, id, &value));
}

TEST_F(NativeSlicePack, SuccessfulPublicationPreservesProjectsAndRemovesDefinitions) {
    ASSERT_NO_FATAL_FAILURE(Load(BuildContentPack(
        22, 1, 7, harkentest::ObjectId(2002), harkentest::ObjectId(7), 0, 0x3f000000u, harkentest::ObjectId(0), {}, VariableScopeV1::Emitter)));
    auto& e = *session.Engine();
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    VnBindingDesc binding{};
    binding.structSize = sizeof(binding);
    binding.variableId = harkentest::ObjectId(7);
    binding.targetScopeKind = VN_TARGET_SCOPE_BUS;
    binding.targetId = kBusTargetBusVolume;
    binding.curve.structSize = sizeof(binding.curve);
    binding.curve.pointCount = 2;
    binding.curve.points[0] = {-1.0f, -12.0f};
    binding.curve.points[1] = {1.0f, 0.0f};
    binding.curve.handles[0] = harkentest::EndpointHandles(binding.curve.points[0], binding.curve.points[1]);
    ASSERT_EQ(VN_OK, Vn_RegisterBinding(harkentest::ObjectId(71), &binding));
    VnBindingAttachDesc attach{};
    attach.structSize = sizeof(attach);
    attach.scopeKind = VN_TARGET_SCOPE_BUS;
    attach.objectId = VN_BUS_MASTER;
    ASSERT_EQ(VN_OK, Vn_AttachBinding(harkentest::ObjectId(71), &attach));
    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(7), 0.5f));
    ASSERT_NO_FATAL_FAILURE(harkentest::AdvanceVariableWrite(&e));
    ASSERT_EQ(VN_OK, Vn_SetEmitterValue(emitter, harkentest::ObjectId(7), -0.5f));
    ASSERT_NO_FATAL_FAILURE(harkentest::AdvanceVariableWrite(&e));
    const auto generation = e.variables.CurrentWorldGeneration();
    const auto bus = e.buses.FindIndex(VN_BUS_MASTER);
    const float expectedVolumeDb = 20.0f * std::log10(0.25f * std::pow(10.0f, -12.0f / 20.0f) + 0.75f);
    EXPECT_NEAR(expectedVolumeDb, e.busTargets.Reduce(bus, kBusTargetBusVolume), 0.001f);
    ASSERT_EQ(VN_OK, Replace(BuildContentPack(
        22, 2, 8, harkentest::ObjectId(2002), harkentest::ObjectId(7), 0, 0x3f000000u, harkentest::ObjectId(0), {}, VariableScopeV1::Emitter)));
    EXPECT_EQ(generation, e.variables.CurrentWorldGeneration());
    float value = 0;
    ASSERT_TRUE(e.variables.CurrentValue(harkentest::ObjectId(7), &value));
    EXPECT_FLOAT_EQ(0.5f, value);
    ASSERT_TRUE(e.params.ScopedVariableValue(&e.emitters, 0, harkentest::ObjectId(7), &value));
    EXPECT_FLOAT_EQ(0.5f, value);
    ASSERT_TRUE(e.variables.CurrentValue(emitter, harkentest::ObjectId(7), &value));
    EXPECT_FLOAT_EQ(-0.5f, value);
    ASSERT_TRUE(e.emitters.LocalValue(emitter, harkentest::ObjectId(7), &value));
    EXPECT_FLOAT_EQ(-0.5f, value);
    EXPECT_GT(e.busTargets.DemandCount(), 0u);
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_NEAR(expectedVolumeDb, e.busTargets.Reduce(bus, kBusTargetBusVolume), 0.001f);
    {
        VariableServiceV1::PreparedPackDefinitions discarded;
        EXPECT_EQ(VN_INVALID_ARG, PreparePackVariables(e, *e.packComposition.Published(), nullptr));
        ASSERT_EQ(VN_OK, PreparePackVariables(e, *e.packComposition.Published(), &discarded));
        EXPECT_TRUE(discarded.IsPrepared());
    }
    ASSERT_TRUE(e.variables.CurrentValue(emitter, harkentest::ObjectId(7), &value));
    EXPECT_FLOAT_EQ(-0.5f, value);
    ASSERT_EQ(VN_OK, Replace(BuildContentPack(22, 3, 9, harkentest::ObjectId(2002), harkentest::ObjectId(9))));
    EXPECT_FALSE(e.variables.CurrentValue(harkentest::ObjectId(7), &value));
    EXPECT_FALSE(e.params.ScopedVariableValue(&e.emitters, 0, harkentest::ObjectId(7), &value));
    EXPECT_FALSE(e.emitters.LocalValue(emitter, harkentest::ObjectId(7), &value));
    ASSERT_TRUE(e.variables.CurrentValue(harkentest::ObjectId(9), &value));
    EXPECT_FLOAT_EQ(0.0f, value);
    EXPECT_EQ(generation, e.variables.CurrentWorldGeneration());
    ASSERT_EQ(VN_OK, Vn_UnloadPack(content));
    EXPECT_FALSE(e.variables.CurrentValue(harkentest::ObjectId(9), &value));
}

TEST(PackComposition,
     CrossPackPostActionRetainsExactChildRevisionUntilFiringRelease) {
    constexpr VnObjectId kSoundId = harkentest::ObjectId(4510);
    constexpr std::uint32_t kValueBits = 0x3f000000u;
    const std::uint64_t childFingerprint =
        SetValueActionFingerprint(harkentest::ObjectId(3003), kValueBits);
    const std::vector<std::uint8_t> packBOldBytes = BuildContentPack(
        33, 1, 9, harkentest::ObjectId(3003), harkentest::ObjectId(7), 0, kValueBits, kSoundId,
        harkentest::MakeDC(8, 0.25f));
    const std::vector<std::uint8_t> packBNextBytes = BuildContentPack(
        33, 2, 10, harkentest::ObjectId(3003), harkentest::ObjectId(7), 0, kValueBits, kSoundId,
        harkentest::MakeDC(8, 0.75f));
    const std::vector<std::uint8_t> packABytes = BuildPostActionPack(
        22, 1, 7, harkentest::ObjectId(2002), harkentest::ObjectId(3003), childFingerprint, 33);
    const std::vector<std::uint8_t> initBytes = BuildKeepIdentityInit(
        Fnv1a64(packABytes.data(), packABytes.size()),
        Fnv1a64(packBOldBytes.data(), packBOldBytes.size()));
    const std::string initPath =
        WriteTemp("f3-cross-post-init.pack", initBytes);
    const std::string packAPath =
        WriteTemp("f3-cross-post-a.pack", packABytes);
    const std::string packBOldPath =
        WriteTemp("f3-cross-post-b-old.pack", packBOldBytes);
    const std::string packBNextPath =
        WriteTemp("f3-cross-post-b-next.pack", packBNextBytes);

    EngineSession session(MakeNullConfig());
    ASSERT_EQ(VN_OK, session.InitResult());
    VnCanonicalPackSetMemberV1 members[3]{};
    VnCanonicalPackSetMemberResultV1 rows[3]{};
    const std::string paths[] = {initPath, packAPath, packBOldPath};
    const std::uint64_t stableIds[] = {11, 22, 33};
    for (std::size_t i = 0; i < 3; ++i) {
        members[i].structSize = sizeof(members[i]);
        members[i].packStableId = stableIds[i];
        members[i].packKind = i == 0 ? VN_CANONICAL_PACK_SET_MEMBER_INIT
                                      : VN_CANONICAL_PACK_SET_MEMBER_CONTENT;
        members[i].utf8Path = paths[i].c_str();
        rows[i].structSize = sizeof(rows[i]);
    }
    VnCanonicalPackSetActivationReportV1 report{};
    ASSERT_EQ(VN_OK, harkentest::ActivateCanonicalMembersV1(
                          members, 3, rows, report));
    const VnPackHandle packB = rows[2].handle;
    VnPackLoadDesc desc{};
    desc.structSize = sizeof(desc);

    VnPostActionDesc post{};
    post.structSize = sizeof(post);
    post.actionId = harkentest::ObjectId(2002);
    VnActionFiringHandle root = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&post, &root));
    ActionFiringStepResult postResult{};
    ASSERT_TRUE(session.Engine()->actionFirings.CaptureStep(
        root, 0, &postResult));
    ASSERT_NE(0u, postResult.childFiring);
    ActionFiringSnapshot rootSnapshot{};
    ActionFiringSnapshot childSnapshot{};
    ASSERT_TRUE(session.Engine()->actionFirings.Capture(root,
                                                        &rootSnapshot));
    ASSERT_TRUE(session.Engine()->actionFirings.Capture(
        postResult.childFiring, &childSnapshot));
    ASSERT_EQ(ActionFiringOwnerKind::Pack, rootSnapshot.owner.kind);
    ASSERT_EQ(ActionFiringOwnerKind::Pack, childSnapshot.owner.kind);
    EXPECT_EQ(22u, rootSnapshot.owner.pack.packStableId);
    EXPECT_EQ(33u, childSnapshot.owner.pack.packStableId);
    EXPECT_EQ(9u, childSnapshot.owner.pack.partitionRevision);
    EXPECT_EQ(VN_OK, session.Engine()->packComposition.ValidateLease(
                         childSnapshot.owner.pack));
    EXPECT_EQ(VN_OK, session.Engine()->packs.ValidateResourceClosure(
                         childSnapshot.owner.pack.resourceClosureToken));

    desc.utf8Path = packBNextPath.c_str();
    ASSERT_EQ(VN_OK,
              Vn_ReplacePack(packB,
                             reinterpret_cast<const VnPackDesc*>(&desc)));
    const auto activeChild =
        session.Engine()->packComposition.FindAction(harkentest::ObjectId(3003));
    const auto anchoredChild =
        session.Engine()->packComposition.FindActionAtLease(
            childSnapshot.owner.pack, harkentest::ObjectId(3003));
    ASSERT_NE(nullptr, activeChild);
    ASSERT_NE(nullptr, anchoredChild);
    EXPECT_NE(activeChild, anchoredChild);
    EXPECT_EQ(childFingerprint, anchoredChild->programSemanticFingerprint);
    PCMView exact{};
    ASSERT_EQ(VN_OK, session.Engine()->packs.LookupExactClosure(
                         childSnapshot.owner.pack.resourceClosureToken,
                         kSoundId, session.Engine()->registry, &exact));
    ASSERT_TRUE(exact.Valid());
    EXPECT_FLOAT_EQ(0.25f, exact.channels[0][0]);

    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(root));
    EXPECT_EQ(VN_STALE_HANDLE,
              session.Engine()->packComposition.ValidateLease(
                  rootSnapshot.owner.pack));
    EXPECT_EQ(VN_STALE_HANDLE,
              session.Engine()->packComposition.ValidateLease(
                  childSnapshot.owner.pack));
    EXPECT_EQ(VN_STALE_HANDLE,
              session.Engine()->packs.ValidateResourceClosure(
                  childSnapshot.owner.pack.resourceClosureToken));
}

TEST(PackCompositionContract, DelayedPlayKeepsAdmissionPackRevisionAfterReplace) {
    constexpr VnObjectId kSoundId = harkentest::ObjectId(4510);
    constexpr VnObjectId kActionId = harkentest::ObjectId(2002);
    const std::vector<std::uint8_t> oldBytes = BuildDelayedPlayPack(
        22, 1, 7, kActionId, kSoundId, harkentest::MakeDC(8, 0.25f),
        1000000000);
    const std::vector<std::uint8_t> nextBytes = BuildDelayedPlayPack(
        22, 2, 8, kActionId, kSoundId, harkentest::MakeDC(8, 0.75f),
        1000000000);
    const std::vector<std::uint8_t> initBytes = BuildSingleIdentityInit(
        Fnv1a64(oldBytes.data(), oldBytes.size()), kActionId);
    const std::string initPath =
        WriteTemp("u3-delayed-play-init.pack", initBytes);
    const std::string oldPath =
        WriteTemp("u3-delayed-play-old.pack", oldBytes);
    const std::string nextPath =
        WriteTemp("u3-delayed-play-next.pack", nextBytes);

    EngineSession session(MakeNullConfig(2, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    VnCanonicalPackSetMemberV1 members[2]{};
    members[0].structSize = sizeof(members[0]);
    members[0].packStableId = 11;
    members[0].packKind = VN_CANONICAL_PACK_SET_MEMBER_INIT;
    members[0].utf8Path = initPath.c_str();
    members[1].structSize = sizeof(members[1]);
    members[1].packStableId = 22;
    members[1].packKind = VN_CANONICAL_PACK_SET_MEMBER_CONTENT;
    members[1].utf8Path = oldPath.c_str();
    VnCanonicalPackSetMemberResultV1 rows[2]{};
    for (auto& row : rows) row.structSize = sizeof(row);
    VnCanonicalPackSetActivationReportV1 report{};
    ASSERT_EQ(VN_OK, harkentest::ActivateCanonicalMembersV1(
                          members, 2, rows, report));
    const VnPackHandle pack = rows[1].handle;
    VnPackLoadDesc desc{};
    desc.structSize = sizeof(desc);

    VnPostActionDesc post{};
    post.structSize = sizeof(post);
    post.actionId = harkentest::ObjectId(kActionId);
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&post, &firing));
    EXPECT_EQ(1u, session.Engine()->actionDeferredRecords.LiveCount());
    ActionDeferredRecordToken token{};
    ActionDeferredRecord record{};
    ActionDeferredRecordState state = ActionDeferredRecordState::Free;
    ASSERT_TRUE(session.Engine()->actionDeferredRecords.CaptureAt(
        0, &token, &record, &state));
    EXPECT_NE(0u, record.targetPackLease.leaseToken);
    EXPECT_EQ(7u, record.targetPackLease.partitionRevision);
    EXPECT_EQ(1u, record.targetPackLease.contentRevision);

    desc.utf8Path = nextPath.c_str();
    ASSERT_EQ(VN_OK, Vn_ReplacePack(pack, reinterpret_cast<const VnPackDesc*>(&desc)));
    ASSERT_EQ(VN_OK, session.Engine()->packComposition.ValidateLease(
                         record.targetPackLease));
    PlayableWorldViewV1 anchored{};
    ASSERT_TRUE(session.Engine()->packComposition.PlayableWorldAtLease(
        record.targetPackLease, &anchored));
    ASSERT_EQ(1u, anchored.propertyCount);
    EXPECT_NE(0u, anchored.properties[0].contentRevision);
    EXPECT_NE(anchored.properties[0].contentRevision,
              session.Engine()->registry.Lookup(kSoundId).contentRevision);
    PCMView exact{};
    ASSERT_EQ(VN_OK, session.Engine()->packs.LookupExactClosure(
                         record.targetPackLease.resourceClosureToken, kSoundId,
                         session.Engine()->registry, &exact));
    EXPECT_FLOAT_EQ(0.25f, exact.channels[0][0]);
    EXPECT_FLOAT_EQ(0.75f,
                    session.Engine()->registry.Lookup(kSoundId).channels[0][0]);
    EXPECT_EQ(VN_IN_USE, Vn_ReleaseActionFiring(firing));
}

