TEST(PackComposition, RequiredSelfEdgeIsCycle) {
    const std::vector<std::uint8_t> packABytes =
        BuildContentPack(22, 1, 7, harkentest::ObjectId(2002), harkentest::ObjectId(7), 22);
    const std::vector<std::uint8_t> packBBytes =
        BuildContentPack(33, 1, 9, harkentest::ObjectId(3003), harkentest::ObjectId(8));
    const std::vector<std::uint8_t> initBytes = BuildKeepIdentityInit(
        Fnv1a64(packABytes.data(), packABytes.size()),
        Fnv1a64(packBBytes.data(), packBBytes.size()));
    const std::string initPath = WriteTemp("f2-cycle-init.pack", initBytes);
    const std::string packAPath = WriteTemp("f2-cycle-a.pack", packABytes);

    EngineSession session(MakeNullConfig());
    ASSERT_EQ(VN_OK, session.InitResult());
    VnCanonicalPackSetMemberV1 members[2]{};
    VnCanonicalPackSetMemberResultV1 rows[2]{};
    const std::string paths[] = {initPath, packAPath};
    for (std::size_t i = 0; i < 2; ++i) {
        members[i].structSize = sizeof(members[i]);
        members[i].packStableId = i == 0 ? 11 : 22;
        members[i].packKind = i == 0 ? VN_CANONICAL_PACK_SET_MEMBER_INIT
                                    : VN_CANONICAL_PACK_SET_MEMBER_CONTENT;
        members[i].utf8Path = paths[i].c_str();
        rows[i].structSize = sizeof(rows[i]);
    }
    VnCanonicalPackSetActivationReportV1 initial{};
    ASSERT_EQ(VN_OK, harkentest::ActivateCanonicalMembersV1(
                          members, 1, rows, initial));
    const auto published = session.Engine()->packComposition.PublishedHandle();
    const auto generation = session.Engine()->packComposition.CompositeGeneration();
    members[0].expectedHandle = initial.initHandle;
    VnCanonicalPackSetActivationReportV1 refused{};
    EXPECT_EQ(VN_PACK_CYCLE, harkentest::ActivateCanonicalMembersV1(
                                     members, 2, rows, refused, initial.initHandle,
                                     initial.resultSetRevision));
    EXPECT_EQ(0u, rows[1].handle);
    EXPECT_EQ(published.get(), session.Engine()->packComposition.Published());
    EXPECT_EQ(generation, session.Engine()->packComposition.CompositeGeneration());
    EXPECT_EQ(PackIdentityReadiness::KnownUnloaded,
              session.Engine()->packComposition.Lookup(harkentest::ObjectId(2002)).readiness);
}

TEST(PackComposition, RequiredConsumerBlocksProviderUnload) {
    const std::vector<std::uint8_t> packABytes =
        BuildContentPack(22, 1, 7, harkentest::ObjectId(2002));
    const std::vector<std::uint8_t> packBBytes =
        BuildContentPack(33, 1, 9, harkentest::ObjectId(3003), harkentest::ObjectId(8), 22);
    const std::vector<std::uint8_t> initBytes = BuildKeepIdentityInit(
        Fnv1a64(packABytes.data(), packABytes.size()),
        Fnv1a64(packBBytes.data(), packBBytes.size()));
    const std::string initPath = WriteTemp("f2-inuse-init.pack", initBytes);
    const std::string packAPath = WriteTemp("f2-inuse-a.pack", packABytes);
    const std::string packBPath = WriteTemp("f2-inuse-b.pack", packBBytes);

    EngineSession session(MakeNullConfig());
    ASSERT_EQ(VN_OK, session.InitResult());
    VnCanonicalPackSetMemberV1 members[3]{};
    VnCanonicalPackSetMemberResultV1 rows[3]{};
    const std::string paths[] = {initPath, packAPath, packBPath};
    const std::uint64_t stableIds[] = {11, 22, 33};
    for (std::size_t i = 0; i < 3; ++i) {
        members[i].structSize = sizeof(members[i]);
        members[i].packStableId = stableIds[i];
        members[i].packKind = i == 0 ? VN_CANONICAL_PACK_SET_MEMBER_INIT
                                      : VN_CANONICAL_PACK_SET_MEMBER_CONTENT;
        members[i].utf8Path = paths[i].c_str();
        rows[i].structSize = sizeof(rows[i]);
    }
    VnCanonicalPackSetActivationReportV1 report{};
    ASSERT_EQ(VN_OK, harkentest::ActivateCanonicalMembersV1(
                          members, 3, rows, report));
    const VnPackHandle packA = rows[1].handle;
    const VnPackHandle packB = rows[2].handle;

    EXPECT_EQ(VN_IN_USE, Vn_UnloadPack(packA));
    const PackIdentityLookup stillA =
        session.Engine()->packComposition.Lookup(harkentest::ObjectId(2002));
    ASSERT_EQ(PackIdentityReadiness::Active, stillA.readiness);
    VnPostActionDesc post{};
    post.structSize = sizeof(post);
    post.actionId = harkentest::ObjectId(2002);
    VnActionFiringHandle firing = 0;
    EXPECT_EQ(VN_OK, Vn_PostAction(&post, &firing));

    ASSERT_EQ(VN_OK, Vn_UnloadPack(packB));
    ASSERT_EQ(VN_OK, Vn_UnloadPack(packA));
    EXPECT_EQ(PackIdentityReadiness::KnownUnloaded,
              session.Engine()->packComposition.Lookup(harkentest::ObjectId(2002)).readiness);
}

TEST(PackComposition, ActivationWithIdenticalVariableKeepsCommittedState) {
    const auto packABytes = BuildContentPack(
        22, 1, 7, harkentest::ObjectId(2002), harkentest::ObjectId(7));
    const auto packBBytes = BuildContentPack(
        33, 1, 9, harkentest::ObjectId(3003), harkentest::ObjectId(7));
    const auto initBytes = BuildKeepIdentityInit(
        Fnv1a64(packABytes.data(), packABytes.size()),
        Fnv1a64(packBBytes.data(), packBBytes.size()));
    const std::string paths[] = {
        WriteTemp("f2-identical-set-init.pack", initBytes),
        WriteTemp("f2-identical-set-a.pack", packABytes),
        WriteTemp("f2-identical-set-b.pack", packBBytes)};
    EngineSession session(MakeNullConfig());
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    VnCanonicalPackSetMemberV1 members[3]{};
    VnCanonicalPackSetMemberResultV1 rows[3]{};
    const std::uint64_t stableIds[] = {11, 22, 33};
    for (std::size_t i = 0; i < 3; ++i) {
        members[i].structSize = sizeof(members[i]);
        members[i].packStableId = stableIds[i];
        members[i].packKind = i == 0 ? VN_CANONICAL_PACK_SET_MEMBER_INIT
                                    : VN_CANONICAL_PACK_SET_MEMBER_CONTENT;
        members[i].utf8Path = paths[i].c_str();
        rows[i].structSize = sizeof(rows[i]);
    }
    VnCanonicalPackSetActivationReportV1 initial{};
    ASSERT_EQ(VN_OK, harkentest::ActivateCanonicalMembersV1(
                          members, 2, rows, initial));
    const auto packA = rows[1].handle;
    EXPECT_EQ(PackIdentityReadiness::Active,
              engine.packComposition.Lookup(harkentest::ObjectId(2002)).readiness);
    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(7), 0.75f));
    ASSERT_NO_FATAL_FAILURE(harkentest::AdvanceVariableWrite(&engine));
    const VnVariableId variable = harkentest::ObjectId(7);
    BankVersionToken bank{};
    float value = 0;
    ASSERT_TRUE(engine.variables.CaptureCurrentBank(0, &variable, 1, &value, &bank));
    ASSERT_FLOAT_EQ(0.75f, value);
    const auto world = engine.variables.CurrentWorldGeneration();
    const auto generation = engine.packComposition.CompositeGeneration();
    members[0].expectedHandle = initial.initHandle;
    members[1].expectedHandle = packA;
    VnCanonicalPackSetActivationReportV1 added{};
    ASSERT_EQ(VN_OK, harkentest::ActivateCanonicalMembersV1(
                          members, 3, rows, added, initial.initHandle,
                          initial.resultSetRevision));
    EXPECT_EQ(packA, rows[1].handle);
    EXPECT_NE(0u, rows[2].handle);
    EXPECT_EQ(generation + 1, engine.packComposition.CompositeGeneration());
    EXPECT_EQ(world + 1, engine.variables.CurrentWorldGeneration());
    ASSERT_TRUE(engine.variables.CaptureCurrentBank(0, &variable, 1, &value, &bank));
    EXPECT_FLOAT_EQ(0.75f, value);
    EXPECT_EQ(PackIdentityReadiness::Active,
              engine.packComposition.Lookup(harkentest::ObjectId(2002)).readiness);
    EXPECT_EQ(PackIdentityReadiness::Active,
              engine.packComposition.Lookup(harkentest::ObjectId(3003)).readiness);
}

