    world.utf8Path = worldPath.c_str();
    VnCurrentWorldLoadReport report{};
    report.structSize = sizeof(report);
    ASSERT_EQ(VN_OK, Vn_LoadCurrentWorld(&world, &report));
    EXPECT_EQ(PackAuthorityMode::DirectWorld,
              session.Engine()->packComposition.Authority());
    EXPECT_EQ(nullptr, session.Engine()->packComposition.Published());

