TEST(PackComposition, ResidentOverBudgetKeepsInitComposite) {
    const std::vector<std::uint8_t> packABytes = BuildContentPack(22, 1, 7, harkentest::ObjectId(2002));
    const std::vector<std::uint8_t> packBBytes = BuildContentPack(33, 1, 9, harkentest::ObjectId(3003), harkentest::ObjectId(8));
    const std::vector<std::uint8_t> initBytes = BuildKeepIdentityInit(
        Fnv1a64(packABytes.data(), packABytes.size()),
        Fnv1a64(packBBytes.data(), packBBytes.size()));
    PackCanonicalImage initImage;
    PackCanonicalImage contentImage;
    ASSERT_EQ(VN_OK, ParsePackCanonicalImage(initBytes.data(), initBytes.size(),
                                             &initImage));
    ASSERT_EQ(VN_OK,
              ParsePackCanonicalImage(packABytes.data(), packABytes.size(),
                                      &contentImage));
    ASSERT_TRUE(initImage.hasPartition);
    ASSERT_TRUE(contentImage.hasPartition);
    ASSERT_GT(contentImage.partitionBody.size(), initImage.partitionBody.size());

    const std::string initPath = WriteTemp("f2-resident-init.pack", initBytes);
    const std::string packAPath = WriteTemp("f2-resident-a.pack", packABytes);
    VnConfig config = MakeNullConfig();
    config.maxResidentDefinitionBytes = initImage.partitionBody.size();
    EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());

    VnCanonicalPackSetMemberV1 members[2]{};
    VnCanonicalPackSetMemberResultV1 rows[2]{};
    const std::string paths[] = {initPath, packAPath};
    for (std::size_t i = 0; i < 2; ++i) {
        members[i].structSize = sizeof(members[i]);
        members[i].packStableId = i == 0 ? 11 : 22;
        members[i].packKind = i == 0 ? VN_CANONICAL_PACK_SET_MEMBER_INIT
                                    : VN_CANONICAL_PACK_SET_MEMBER_CONTENT;
        members[i].utf8Path = paths[i].c_str();
        rows[i].structSize = sizeof(rows[i]);
    }
    VnCanonicalPackSetActivationReportV1 initial{};
    ASSERT_EQ(VN_OK, harkentest::ActivateCanonicalMembersV1(
                          members, 1, rows, initial));
    const auto initHandle = initial.initHandle;
    const std::uint64_t generation =
        session.Engine()->packComposition.CompositeGeneration();
    ASSERT_NE(0u, generation);
    const auto published = session.Engine()->packComposition.PublishedHandle();
    ASSERT_NE(nullptr, published);

    members[0].expectedHandle = initHandle;
    VnCanonicalPackSetActivationReportV1 refused{};
    EXPECT_EQ(VN_PACK_RESIDENT_CAPACITY, harkentest::ActivateCanonicalMembersV1(
                    members, 2, rows, refused, initHandle, initial.resultSetRevision));
    EXPECT_EQ(0u, rows[1].handle);
    EXPECT_EQ(published.get(), session.Engine()->packComposition.Published());
    EXPECT_EQ(generation,
              session.Engine()->packComposition.CompositeGeneration());
    ASSERT_NE(nullptr, session.Engine()->packComposition.Published());
    EXPECT_EQ(initHandle,
              session.Engine()->packComposition.Published()->initHandle);
    EXPECT_EQ(PackIdentityReadiness::KnownUnloaded,
              session.Engine()->packComposition.Lookup(harkentest::ObjectId(2002)).readiness);
}

VnResult ProviderReturnsDeviceError(void*, std::uint64_t, const char*,
                                    std::uint32_t, std::uint64_t,
                                    VnPackByteSpan* outSpan) {
    if (outSpan != nullptr) {
        outSpan->structSize = sizeof(VnPackByteSpan);
        outSpan->reserved0 = 0;
        outSpan->bytes = nullptr;
        outSpan->byteCount = 0;
    }
    return VN_DEVICE_ERROR;
}

VnResult ProviderReturnsEmptyOk(void*, std::uint64_t, const char*,
                                std::uint32_t, std::uint64_t,
                                VnPackByteSpan* outSpan) {
    if (outSpan == nullptr) {
        return VN_INVALID_ARG;
    }
    outSpan->structSize = sizeof(VnPackByteSpan);
    outSpan->reserved0 = 0;
    outSpan->bytes = nullptr;
    outSpan->byteCount = 0;
    return VN_OK;
}

TEST(PackCompositionContract, ProviderFailurePublishesNothing) {
    EngineSession session(MakeNullConfig());
    ASSERT_EQ(VN_OK, session.InitResult());

    VnPackLoadDesc desc{};
    desc.structSize = sizeof(desc);
    desc.flags = VN_PACK_LOAD_FLAG_PROVIDER;
    desc.provide = ProviderReturnsDeviceError;
    VnPackHandle handle = 0;
    EXPECT_EQ(VN_PACK_PROVIDER_FAILED,
              Vn_LoadPack(reinterpret_cast<const VnPackDesc*>(&desc), &handle));
    EXPECT_EQ(0u, handle);
    EXPECT_EQ(PackAuthorityMode::Unspecified,
              session.Engine()->packComposition.Authority());
    EXPECT_EQ(nullptr, session.Engine()->packComposition.Published());

    desc.provide = ProviderReturnsEmptyOk;
    EXPECT_EQ(VN_PACK_PROVIDER_FAILED,
              Vn_LoadPack(reinterpret_cast<const VnPackDesc*>(&desc), &handle));
    EXPECT_EQ(0u, handle);
    EXPECT_EQ(PackAuthorityMode::Unspecified,
              session.Engine()->packComposition.Authority());
    EXPECT_EQ(nullptr, session.Engine()->packComposition.Published());
}

TEST(PackComposition, InjectedComposeFaultsKeepPriorGeneration) {
    const std::vector<std::uint8_t> packABytes = BuildContentPack(22, 1, 7, harkentest::ObjectId(2002));
    const std::vector<std::uint8_t> packBBytes =
        BuildContentPack(33, 1, 9, harkentest::ObjectId(3003), harkentest::ObjectId(8));
    const std::vector<std::uint8_t> initBytes = BuildKeepIdentityInit(
        Fnv1a64(packABytes.data(), packABytes.size()),
        Fnv1a64(packBBytes.data(), packBBytes.size()));
    const std::string initPath = WriteTemp("f2-fault-init.pack", initBytes);
    const std::string packAPath = WriteTemp("f2-fault-a.pack", packABytes);

    EngineSession session(MakeNullConfig());
    ASSERT_EQ(VN_OK, session.InitResult());
    VnCanonicalPackSetMemberV1 members[2]{};
    VnCanonicalPackSetMemberResultV1 rows[2]{};
    const std::string paths[] = {initPath, packAPath};
    for (std::size_t i = 0; i < 2; ++i) {
        members[i].structSize = sizeof(members[i]);
        members[i].packStableId = i == 0 ? 11 : 22;
        members[i].packKind = i == 0 ? VN_CANONICAL_PACK_SET_MEMBER_INIT
                                    : VN_CANONICAL_PACK_SET_MEMBER_CONTENT;
        members[i].utf8Path = paths[i].c_str();
        rows[i].structSize = sizeof(rows[i]);
    }
    VnCanonicalPackSetActivationReportV1 initial{};
    ASSERT_EQ(VN_OK, harkentest::ActivateCanonicalMembersV1(
                          members, 1, rows, initial));
    members[0].expectedHandle = initial.initHandle;

    const PackAuthorityMode authority =
        session.Engine()->packComposition.Authority();
    const std::uint64_t generation =
        session.Engine()->packComposition.CompositeGeneration();
    const auto published = session.Engine()->packComposition.PublishedHandle();
    ASSERT_NE(nullptr, published);
    EXPECT_EQ(PackIdentityReadiness::KnownUnloaded,
              session.Engine()->packComposition.Lookup(harkentest::ObjectId(2002)).readiness);

    struct Case {
        PackStagingFault fault;
        VnResult expected;
    };
    const Case cases[] = {
        {PackStagingFault::AfterParse, VN_BAD_PACK},
        {PackStagingFault::PartitionDecode, VN_BAD_PACK},
        {PackStagingFault::CompositeReserve, VN_PACK_RESIDENT_CAPACITY},
        {PackStagingFault::CompositionPublish, VN_PACK_RESIDENT_CAPACITY},
    };
    for (const Case& item : cases) {
        SetPackStagingFaultForTests(item.fault);
        VnCanonicalPackSetActivationReportV1 refused{};
        EXPECT_EQ(item.expected, harkentest::ActivateCanonicalMembersV1(
                      members, 2, rows, refused, initial.initHandle,
                      initial.resultSetRevision))
            << static_cast<std::uint32_t>(item.fault);
        EXPECT_EQ(0u, rows[1].handle);
        EXPECT_EQ(authority, session.Engine()->packComposition.Authority());
        EXPECT_EQ(generation,
                  session.Engine()->packComposition.CompositeGeneration());
        EXPECT_EQ(published,
                  session.Engine()->packComposition.PublishedHandle());
        EXPECT_EQ(PackIdentityReadiness::KnownUnloaded,
                  session.Engine()->packComposition.Lookup(harkentest::ObjectId(2002)).readiness);
        SetPackStagingFaultForTests(PackStagingFault::None);
    }

    VnCanonicalPackSetActivationReportV1 added{};
    ASSERT_EQ(VN_OK, harkentest::ActivateCanonicalMembersV1(
                          members, 2, rows, added, initial.initHandle,
                          initial.resultSetRevision));
    EXPECT_NE(0u, rows[1].handle);
    EXPECT_EQ(PackIdentityReadiness::Active,
              session.Engine()->packComposition.Lookup(harkentest::ObjectId(2002)).readiness);
}

TEST(PackComposition, SameIdContainerPropertyAndProgramIndexOnce) {
    constexpr std::uint64_t kPackStableId = 22;
    constexpr VnObjectId kContainerId = harkentest::ObjectId(8101);
    constexpr VnPackHandle kPackHandle =
        static_cast<VnPackHandle>(1) << 32;
    const std::vector<std::uint8_t> bytes = BuildCanonicalPartitionPack(
        kPackStableId, 1, 7,
        LegalContainerPartitionPayload(kPackStableId, 7, kContainerId));
    PackComposition composition(1);
    ASSERT_EQ(VN_OK, CommitParsedPack(&composition, bytes, kPackHandle, 8));
    ASSERT_NE(nullptr, composition.Published());
    ASSERT_EQ(1u, composition.Published()->index.size());
    EXPECT_EQ(kContainerId, composition.Published()->index[0].stableId);
    EXPECT_EQ(kInitCatalogIdentityClassPlayable,
              composition.Published()->index[0].identityClass);
    EXPECT_EQ(0u, composition.Published()->index[0].localRow);
    EXPECT_EQ(1u, composition.Facts().loadedCount);

    const ContainerProgramViewV3* program =
        composition.FindContainer(kContainerId);
    ASSERT_NE(nullptr, program);
    EXPECT_EQ(kContainerId, program->containerStableId);

    PackIdentityLookup lookup;
    ASSERT_EQ(VN_OK, composition.PrepareLookup(kContainerId, &lookup));
    ASSERT_NE(nullptr, lookup.playableRow);
    const auto* property = static_cast<const PlayablePropertyProgramViewV1*>(
        lookup.playableRow);
    EXPECT_EQ(kContainerId, property->stableId);
    EXPECT_EQ(playableproperties::ContentPropertyKindV1::Container,
              property->contentPropertyKind);
    EXPECT_EQ(property->programSemanticFingerprint,
              program->programSemanticFingerprint);
    composition.AbandonPreparedLease(lookup.lease);
}

