TEST(PackComposition, DeclaredSharedChildPublishesFromContentRoot) {
    constexpr std::uint64_t kContentPack = 22;
    constexpr std::uint64_t kSharedPack = 33;
    constexpr VnObjectId kContainerId = harkentest::ObjectId(8101);
    constexpr VnObjectId kSoundId = harkentest::ObjectId(8201);
    constexpr VnPackHandle kContentHandle =
        static_cast<VnPackHandle>(1) << 32;
    constexpr VnPackHandle kSharedHandle =
        static_cast<VnPackHandle>(2) << 32;
    const PlayablePropertyProgramViewV1 sound = MakeSoundProperty(kSoundId, 1);
    const PlayableRefV1 child = PlayableRefFromProperty(sound);
    const std::vector<std::uint8_t> contentBytes = BuildCanonicalPartitionPack(
        kContentPack, 1, 7,
        ContentContainerWithChildPartitionPayload(kContentPack, 7, kContainerId,
                                                  child),
        kSharedPack);
    const std::vector<std::uint8_t> sharedBytes = BuildCanonicalPartitionPack(
        kSharedPack, 1, 9,
        SharedSoundPartitionPayload(kSharedPack, 9, sound));
    PackCanonicalImage contentImage;
    PackCanonicalImage sharedImage;
    ASSERT_EQ(VN_OK, ParsePackCanonicalImage(contentBytes.data(),
                                             contentBytes.size(), &contentImage));
    ASSERT_EQ(VN_OK, ParsePackCanonicalImage(sharedBytes.data(),
                                             sharedBytes.size(), &sharedImage));
    PackComposition composition(2, 1, 2);
    PackComposition::CandidateOwner contentOwner;
    PackComposition::CandidateOwner sharedOwner;
    ASSERT_EQ(VN_OK, composition.PrepareCandidate(contentImage, kContentHandle,
                                                  &contentOwner));
    ASSERT_EQ(VN_OK, composition.PrepareCandidate(sharedImage, kSharedHandle,
                                                  &sharedOwner));
    std::vector<PackComposition::CandidateOwner> owners;
    owners.push_back(std::move(contentOwner));
    owners.push_back(std::move(sharedOwner));
    ASSERT_EQ(VN_OK, composition.Commit(std::move(owners), nullptr, 0, 8, 0));
    ASSERT_NE(nullptr, composition.Published());
    ASSERT_EQ(2u, composition.Published()->index.size());
    EXPECT_NE(nullptr, composition.FindContainer(kContainerId));
    PackIdentityLookup containerLookup;
    PackIdentityLookup soundLookup;
    ASSERT_EQ(VN_OK, composition.PrepareLookup(kContainerId, &containerLookup));
    ASSERT_EQ(VN_OK, composition.PrepareLookup(kSoundId, &soundLookup));
    ASSERT_NE(nullptr, containerLookup.playableRow);
    ASSERT_NE(nullptr, soundLookup.playableRow);
    const auto* containerProperty =
        static_cast<const PlayablePropertyProgramViewV1*>(
            containerLookup.playableRow);
    const auto* soundProperty =
        static_cast<const PlayablePropertyProgramViewV1*>(
            soundLookup.playableRow);
    EXPECT_EQ(playableproperties::ContentPropertyKindV1::Container,
              containerProperty->contentPropertyKind);
    EXPECT_EQ(playableproperties::ContentPropertyKindV1::Sound,
              soundProperty->contentPropertyKind);
    composition.AbandonPreparedLease(containerLookup.lease);
    composition.AbandonPreparedLease(soundLookup.lease);

    std::uint64_t sharedPartition = 0;
    std::uint64_t sharedResource = 0;
    PackResourceRevisionToken sharedToken = 0;
    for (const auto& owner : composition.Published()->owners) {
        if (owner.packStableId == kSharedPack) {
            sharedPartition = owner.partitionRevision;
            sharedResource = owner.resourceRevision;
            sharedToken = owner.resourceToken;
            break;
        }
    }
    PackIdentityLookup playable;
    ASSERT_EQ(VN_OK, composition.PrepareLookup(
                         kContainerId, PackLeaseSlice::Playable, &playable));
    PackPlaybackView preparedView;
    EXPECT_FALSE(composition.PlaybackViewAtLease(playable.lease, &preparedView));
    ASSERT_EQ(VN_OK, composition.CommitPreparedLease(&playable.lease, 0));
    PackPlaybackView view;
    ASSERT_TRUE(composition.PlaybackViewAtLease(playable.lease, &view));
    EXPECT_EQ(2u, view.OwnerCount());
    ASSERT_NE(nullptr, view.ResolveContainer(kContainerId, 0));
    const auto containerHandle = view.ResolveContainer(kContainerId, 0);
    EXPECT_EQ(kContentPack, containerHandle.source.ownerStableId);
    EXPECT_EQ(7u, containerHandle.source.ownerRevision);
    EXPECT_EQ(playable.lease.leaseToken, containerHandle.source.leaseIdentity);
    EXPECT_EQ(18u, containerHandle.source.sourceBodyVintage);
    const auto providerSource = view.ResolveProgramSource(
        playableproperties::ContentPropertyKindV1::Sound, kSoundId);
    EXPECT_EQ(kSharedPack, providerSource.ownerStableId);
    EXPECT_EQ(9u, providerSource.ownerRevision);
    EXPECT_EQ(playable.lease.leaseToken, providerSource.leaseIdentity);
    ResolvedPlayablePropertyCutStorageV1 cut;
    ASSERT_TRUE(cut.Reset({}));
    const auto selectedOrdinal = containerHandle->children[0].stableChildOrdinal;
    ASSERT_EQ(ResolvedPlayablePropertyCutStatusV1::Ok,
              cut.Resolve(view, PlayableRefFromProperty(*containerProperty), &selectedOrdinal, 1));
    for (std::uint32_t i = 0; i < cut.View().pathCount; ++i) {
        const auto& path = cut.View().path[i];
        EXPECT_EQ(path.stableId == kSoundId ? kSharedPack : kContentPack,
                  path.source.ownerStableId);
    }
    ASSERT_NE(nullptr,
              view.ResolveProperty(
                  playableproperties::ContentPropertyKindV1::Sound, kSoundId));
    EXPECT_EQ(nullptr, view.ResolveContainer(kContainerId, 1));
    PlayableWorldViewV1 world{};
    ASSERT_TRUE(composition.PlayableWorldAtLease(playable.lease, &world));
    EXPECT_EQ(containerHandle.source, world.ProgramSource());
    bool sawSharedSound = false;
    for (std::uint32_t i = 0; i < world.propertyCount; ++i) {
        if (world.properties[i].stableId == kSoundId) {
            sawSharedSound = true;
            break;
        }
    }
    EXPECT_FALSE(sawSharedSound);
    EXPECT_TRUE(composition.HasLiveLease(kSharedPack, sharedPartition,
                                         sharedResource));
    if (sharedToken != 0) {
        EXPECT_TRUE(composition.HasLiveResourceToken(sharedToken));
    }
    EXPECT_EQ(VN_OK, composition.ReleaseLease(playable.lease));
    EXPECT_FALSE(composition.HasLiveLease(kSharedPack, sharedPartition,
                                          sharedResource));
}

