TEST(PackComposition,
     CrossPackTransitionEndpointMustBeDirectChildOfConsumerContainer) {
    constexpr std::uint64_t kConsumerPack = 22;
    constexpr std::uint64_t kProviderPack = 33;
    constexpr VnObjectId kConsumerContainerId = harkentest::ObjectId(8601);
    constexpr VnObjectId kProviderSoundId = harkentest::ObjectId(8602);
    constexpr VnPackHandle kConsumerHandle =
        static_cast<VnPackHandle>(1) << 32;
    constexpr VnPackHandle kProviderHandle =
        static_cast<VnPackHandle>(2) << 32;

    const PlayablePropertyProgramViewV1 consumerProperty =
        MakeContainerProperty(kConsumerContainerId);
    const PlayablePropertyProgramViewV1 providerProperty =
        MakeSoundProperty(kProviderSoundId);
    const PlayableRefV1 providerRef =
        PlayableRefFromProperty(providerProperty);
    ContainerProgramViewV3 consumerProgram = MakeContainerProgram(
        kConsumerContainerId, consumerProperty.programSemanticFingerprint);
    TransitionRuleViewV1 rules[2]{};
    rules[0].stableRuleOrdinal = 0;
    rules[0].sourceAny = 1;
    rules[0].targetAny = 1;
    rules[1].stableRuleOrdinal = 1;
    rules[1].source = providerRef;
    rules[1].targetAny = 1;
    TransitionProgramViewV1 transition{};
    transition.ownerContainerStableId = harkentest::ObjectId(kConsumerContainerId);
    transition.ruleCount = 2;
    transition.defaultRuleIndex = 0;
    transition.rules = rules;
    consumerProgram.transitionProgramIndex = 0;

    ContainerWorldInstallViewV1 consumerView{};
    consumerView.playableProperties = &consumerProperty;
    consumerView.playablePropertyCount = 1;
    consumerView.containers = &consumerProgram;
    consumerView.containerCount = 1;
    consumerView.transitions = &transition;
    consumerView.transitionCount = 1;
    consumerView.capacity.maxKnownScheduleLeaves = 16;
    consumerView.capacity.maxTrackPieceScheduleDepth = 8;

    ContainerWorldInstallViewV1 providerView{};
    providerView.playableProperties = &providerProperty;
    providerView.playablePropertyCount = 1;
    providerView.capacity.maxKnownScheduleLeaves = 16;
    providerView.capacity.maxTrackPieceScheduleDepth = 8;

    FinishPlayableWorld(&consumerView, kWorldCapabilityRandomDraw);
    FinishPlayableWorld(&providerView);

    std::vector<std::uint8_t> consumerBodyBytes;
    ASSERT_TRUE(EncodeCurrentWorldShippingBody(consumerView,
                                               consumerBodyBytes));
    auto consumerBody = std::make_shared<CurrentWorldBodyImage>();
    ASSERT_EQ(CurrentWorldBodyDecodeResult::Ok,
              consumerBody->DecodeWithResult(
                  consumerBodyBytes.data(), consumerBodyBytes.size(),
                  kCurrentWorldShippingBodyVintage,
                  CurrentWorldDecodeMode::StrictArtifact));

    std::vector<std::uint8_t> providerBodyBytes;
    ASSERT_TRUE(EncodeCurrentWorldShippingBody(providerView,
                                               providerBodyBytes));
    auto providerBody = std::make_shared<CurrentWorldBodyImage>();
    ASSERT_EQ(CurrentWorldBodyDecodeResult::Ok,
              providerBody->DecodeWithResult(
                  providerBodyBytes.data(), providerBodyBytes.size(),
                  kCurrentWorldShippingBodyVintage,
                  CurrentWorldDecodeMode::StrictArtifact));

    PackComposition::CandidateOwner consumerOwner;
    consumerOwner.packStableId = kConsumerPack;
    consumerOwner.handle = kConsumerHandle;
    consumerOwner.contentRevision = 1;
    consumerOwner.partitionRevision = 7;
    consumerOwner.resourceRevision = 1;
    consumerOwner.hasPartition = true;
    consumerOwner.body = std::move(consumerBody);
    consumerOwner.view = *consumerOwner.body->ProductionView();
    PackDependencyEdge requiredEdge;
    requiredEdge.prerequisitePackStableId = kProviderPack;
    requiredEdge.edgeKind = kPackDependencyEdgeKindContent;
    requiredEdge.required01 = 1;
    consumerOwner.dependencyEdges.push_back(requiredEdge);

    PackComposition::CandidateOwner providerOwner;
    providerOwner.packStableId = kProviderPack;
    providerOwner.handle = kProviderHandle;
    providerOwner.contentRevision = 1;
    providerOwner.partitionRevision = 9;
    providerOwner.resourceRevision = 1;
    providerOwner.hasPartition = true;
    providerOwner.body = std::move(providerBody);
    providerOwner.view = *providerOwner.body->ProductionView();

    PackComposition composition(2, 0, 2);
    std::vector<PackComposition::CandidateOwner> owners;
    owners.push_back(std::move(consumerOwner));
    owners.push_back(std::move(providerOwner));
    EXPECT_EQ(VN_BAD_PACK,
              composition.Commit(std::move(owners), nullptr, 0, 8, 0));
    EXPECT_EQ(nullptr, composition.Published());
}

