std::vector<std::uint8_t> ImmediateVariableControlDiscretePlayPartitionPayload(
    std::uint64_t packStableId, std::uint64_t partitionRevision,
    VnObjectId actionId, VnObjectId containerId,
    VnObjectId firstSoundId, VnObjectId secondSoundId,
    std::uint64_t firstRevision, std::uint64_t secondRevision,
    bool logicalTrackChildren = false,
    std::int64_t delayNanoseconds = 0) {
    PlayablePropertyProgramViewV1 firstSound = MakeSoundProperty(firstSoundId);
    firstSound.contentRevision = firstRevision;
    firstSound.programSemanticFingerprint =
        ComputePlayablePropertyFingerprintV1(firstSound);
    PlayablePropertyProgramViewV1 secondSound = MakeSoundProperty(secondSoundId);
    secondSound.authoredStableOrder = 1;
    secondSound.contentRevision = secondRevision;
    secondSound.compatibilityFingerprint = 5;
    secondSound.programSemanticFingerprint =
        ComputePlayablePropertyFingerprintV1(secondSound);
    PlayablePropertyProgramViewV1 containerProperty =
        MakeContainerProperty(containerId, 2);
    const PlayableRefV1 firstRef = PlayableRefFromProperty(firstSound);
    const PlayableRefV1 secondRef = PlayableRefFromProperty(secondSound);

    PlayablePropertyProgramViewV1 trackProperties[2]{};
    ScheduleClipPlacementV1 placements[2]{};
    TrackScheduleProgramViewV1 trackSchedules[2]{};
    const PlayableRefV1 soundRefs[2] = {firstRef, secondRef};
    for (std::uint32_t index = 0; index < 2; ++index) {
        auto& track = trackProperties[index];
        track.contentPropertyKind =
            playableproperties::ContentPropertyKindV1::Track;
        track.stableId = harkentest::ObjectId(4520u + index);
        track.authoredStableOrder = 3u + index;
        track.contentRevision = 10u + index;
        track.routeStableId = VN_BUS_MASTER;
        track.compatibilityFingerprint = 20u + index;
        track.payload = DelayedPlayPayload();
        track.programSemanticFingerprint =
            ComputePlayablePropertyFingerprintV1(track);

        auto& placement = placements[index];
        placement.stablePlacementOrdinal = 0;
        placement.stableOccurrenceOrdinal = 20u + index;
        placement.content = soundRefs[index];
        placement.clipId = harkentest::ObjectId(9000u + index);
        placement.clipGuidHigh = 1u + index;
        if (index == 1) {
            placement.authoredStart = INT64_C(100000000);
            placement.authoredDuration = 1;
        }

        auto& schedule = trackSchedules[index];
        schedule.rootDefinition = PlayableRefFromProperty(track);
        schedule.placementCount = 1;
        schedule.placements = &placement;
        schedule.scheduleSemanticFingerprint =
            ComputeTrackScheduleFingerprintV1(schedule);
    }

    ContainerChildProgramViewV2 children[2]{};
    children[0].playable = logicalTrackChildren
        ? PlayableRefFromProperty(trackProperties[0]) : firstRef;
    children[0].stableChildOrdinal = 7;
    children[1] = children[0];
    children[1].playable = logicalTrackChildren
        ? PlayableRefFromProperty(trackProperties[1]) : secondRef;
    children[1].stableChildOrdinal = 8;
    children[1].authoredStableOrder = 1;

    const VariableDefinitionV1 variable = harkentest::MakeVariableDefinition(
        harkentest::ObjectId(41), VariableKindV1::Step, 0.0f, 8.0f, 3.0f);
    GridAxisV1 axis{0, 0, variable.variableId};
    DiscreteGridCellV1 cells[2] = {
        {DiscreteCellKindV1::Exact, 3},
        {DiscreteCellKindV1::Exact, 1},
    };
    DiscreteGridRowViewV1 rows[2]{};
    for (std::uint32_t index = 0; index < 2; ++index) {
        rows[index].stableRowOrdinal = index + 1;
        rows[index].authoredStableOrder = index;
        rows[index].childStableOrdinal = children[index].stableChildOrdinal;
        rows[index].cellCount = 1;
        rows[index].cells = &cells[index];
    }

    ContainerProgramViewV3 program = MakeContainerProgram(
        containerId, containerProperty.programSemanticFingerprint, 2);
    program.mode = ContainerModeV1::VariableControl;
    program.randomDiscipline = {};
    program.memoryScope = MemoryScopeV1::Emitter;
    program.discreteTiming = logicalTrackChildren ? 1 : 0;
    program.childCount = 2;
    program.children = children;
    program.discreteAxisCount = 1;
    program.discreteAxes = &axis;
    program.discreteRowCount = 2;
    program.discreteRows = rows;
    program.evaluationPeriodFrames = logicalTrackChildren ? 64 : 0;
    TransitionRuleViewV1 transitionRule{};
    transitionRule.stableRuleOrdinal = 1;
    transitionRule.sourceAny = 1;
    transitionRule.targetAny = 1;
    TransitionProgramViewV1 transition{};
    transition.ownerContainerStableId = harkentest::ObjectId(containerId);
    transition.ruleCount = 1;
    transition.defaultRuleIndex = 0;
    transition.rules = &transitionRule;
    if (logicalTrackChildren) {
        program.transitionProgramIndex = 0;
    }

    PlayableOccurrencePropertyViewV1 occurrences[2]{};
    occurrences[0].parentKind =
        playableproperties::ContentPropertyKindV1::Container;
    occurrences[0].parentStableId = harkentest::ObjectId(containerId);
    occurrences[0].parentProgramSemanticFingerprint =
        containerProperty.programSemanticFingerprint;
    occurrences[0].stableOccurrenceOrdinal = children[0].stableChildOrdinal;
    occurrences[0].childPlayable = children[0].playable;
    occurrences[0].payload = EmptyOccurrencePayload();
    occurrences[0].occurrenceSemanticFingerprint =
        ComputePlayableOccurrenceFingerprintV1(occurrences[0]);
    occurrences[1] = occurrences[0];
    occurrences[1].stableOccurrenceOrdinal = children[1].stableChildOrdinal;
    occurrences[1].childPlayable = children[1].playable;
    occurrences[1].occurrenceSemanticFingerprint =
        ComputePlayableOccurrenceFingerprintV1(occurrences[1]);
    PlayableOccurrencePropertyViewV1 trackOccurrences[2]{};
    for (std::uint32_t index = 0; index < 2; ++index) {
        trackOccurrences[index].parentKind =
            playableproperties::ContentPropertyKindV1::Track;
        trackOccurrences[index].parentStableId =
            trackProperties[index].stableId;
        trackOccurrences[index].parentProgramSemanticFingerprint =
            trackProperties[index].programSemanticFingerprint;
        trackOccurrences[index].stableOccurrenceOrdinal =
            placements[index].stableOccurrenceOrdinal;
        trackOccurrences[index].childPlayable = soundRefs[index];
        trackOccurrences[index].payload = EmptyOccurrencePayload();
        trackOccurrences[index].occurrenceSemanticFingerprint =
            ComputePlayableOccurrenceFingerprintV1(trackOccurrences[index]);
    }
    PlayablePropertyProgramViewV1 properties[5] = {
        firstSound, secondSound, containerProperty,
        trackProperties[0], trackProperties[1]};

    ActionStepProgramViewV1 step{};
    step.opcode = ActionOpcodeV1::Play;
    step.target.kind = ActionTargetKindV1::Container;
    step.target.stableId = harkentest::ObjectId(containerId);
    step.target.expectedProgramSemanticFingerprint =
        containerProperty.programSemanticFingerprint;
    SetAbsoluteTime(&step.delay, delayNanoseconds);
    SetAbsoluteTime(&step.fade, 0);
    SetAbsoluteTime(&step.cooldown, 0);
    ActionProgramViewV1 action{};
    action.actionStableId = actionId;
    action.steps = &step;
    action.stepCount = 1;
    action.directFeatureMask = delayNanoseconds != 0 ? 1u : 0u;
    action.transitiveFeatureMask = action.directFeatureMask;
    action.expandedStepOccurrenceCount = 1;
    action.expandedFiringCount = 1;
    action.programSemanticFingerprint = ComputeActionProgramFingerprintV1(action);

    ContainerWorldInstallViewV1 world{};
    world.identity.capabilityMask = kWorldCapabilityActionDefinitions |
                                    kWorldCapabilityPlayableProperties |
                                    kWorldCapabilityVariableDefinitions |
                                    kWorldCapabilityVariableControl;
    if (logicalTrackChildren) {
        world.identity.capabilityMask |= kWorldCapabilityTransition;
    }
    world.variables = &variable;
    world.variableCount = 1;
    world.playableProperties = properties;
    world.playablePropertyCount = logicalTrackChildren ? 5 : 3;
    PlayableOccurrencePropertyViewV1 allOccurrences[4] = {
        occurrences[0], occurrences[1], trackOccurrences[0],
        trackOccurrences[1]};
    world.playableOccurrences = allOccurrences;
    world.playableOccurrenceCount = logicalTrackChildren ? 4 : 2;
    world.trackSchedules = logicalTrackChildren ? trackSchedules : nullptr;
    world.trackScheduleCount = logicalTrackChildren ? 2 : 0;
    world.containers = &program;
    world.containerCount = 1;
    world.transitions = logicalTrackChildren ? &transition : nullptr;
    world.transitionCount = logicalTrackChildren ? 1 : 0;
    world.actions = &action;
    world.actionCount = 1;
    world.capacity.maxKnownScheduleLeaves = 16;
    world.capacity.maxTrackPieceScheduleDepth = 8;
    if (logicalTrackChildren) {
        world.identity.capabilityMask =
            harken::detail::ComputeCurrentWorldLocalCapabilityMaskV1(world);
    }
    world.identity.runtimeSemanticFingerprint =
        ComputeCurrentWorldFingerprintV4(world);
    return WrapWorldPartition(
        packStableId, partitionRevision, world,
        logicalTrackChildren ? 7 : 5);
}

std::vector<std::uint8_t> BuildImmediateVariableControlDiscretePlayPack(
    std::uint64_t packStableId, std::uint64_t contentRevision,
    std::uint64_t partitionRevision, VnObjectId actionId,
    VnObjectId containerId, VnObjectId firstSoundId,
    VnObjectId secondSoundId, std::vector<float> firstPlanar,
    std::vector<float> secondPlanar, bool logicalTrackChildren = false,
    std::int64_t delayNanoseconds = 0) {
    const float* firstChannels[1] = {firstPlanar.data()};
    const float* secondChannels[1] = {secondPlanar.data()};
    std::uint64_t firstRevision = 0;
    std::uint64_t secondRevision = 0;
    EXPECT_TRUE(ComputeMediaPcmContentRevisionV1(
        48000, 1, static_cast<std::uint64_t>(firstPlanar.size()), firstChannels,
        1, &firstRevision));
    EXPECT_TRUE(ComputeMediaPcmContentRevisionV1(
        48000, 1, static_cast<std::uint64_t>(secondPlanar.size()),
        secondChannels, 1, &secondRevision));
    ImageBuilder builder(kPackKindCanonicalContent);
    builder.AddEntry(kPackEntryKindPackRequirementBlock, packStableId,
                     RequirementPayload(packStableId, contentRevision,
                                        partitionRevision));
    builder.AddEntry(kPackEntryKindCanonicalDefinitionPartition, packStableId,
                     ImmediateVariableControlDiscretePlayPartitionPayload(
                         packStableId, partitionRevision, actionId, containerId,
                         firstSoundId, secondSoundId, firstRevision,
                         secondRevision, logicalTrackChildren,
                         delayNanoseconds));
    builder.AddMedia(firstSoundId, std::move(firstPlanar));
    builder.AddMedia(secondSoundId, std::move(secondPlanar));
    return builder.Build();
}

std::vector<std::uint8_t>
ImmediateRandomContainerToVariableControlPlayPartitionPayload(
    std::uint64_t packStableId, std::uint64_t partitionRevision,
    VnObjectId actionId, VnObjectId outerContainerId,
    VnObjectId variableControlId, VnObjectId firstSoundId,
    std::uint64_t firstRevision, std::uint32_t outerLoopCount = 1) {
    PlayablePropertyProgramViewV1 firstSound = MakeSoundProperty(firstSoundId);
    firstSound.contentRevision = firstRevision;
    firstSound.programSemanticFingerprint =
        ComputePlayablePropertyFingerprintV1(firstSound);
    PlayablePropertyProgramViewV1 variableControlProperty =
        MakeContainerProperty(variableControlId, 1);
    PlayablePropertyProgramViewV1 outerContainerProperty =
        MakeContainerProperty(outerContainerId, 2);
    outerContainerProperty.payload.presentMask |= UINT64_C(1) << 3u;
    outerContainerProperty.payload.values[3].bits = outerLoopCount;
    outerContainerProperty.programSemanticFingerprint =
        ComputePlayablePropertyFingerprintV1(outerContainerProperty);
    const PlayableRefV1 firstRef = PlayableRefFromProperty(firstSound);
    const PlayableRefV1 variableControlRef =
        PlayableRefFromProperty(variableControlProperty);

    ContainerChildProgramViewV2 variableControlChildren[2]{};
    variableControlChildren[0].playable = firstRef;
    variableControlChildren[0].stableChildOrdinal = 7;
    variableControlChildren[1] = variableControlChildren[0];
    variableControlChildren[1].stableChildOrdinal = 8;
    variableControlChildren[1].authoredStableOrder = 1;

    const VariableDefinitionV1 variable = harkentest::MakeVariableDefinition(
        harkentest::ObjectId(41), VariableKindV1::Step, 0.0f, 8.0f, 3.0f);
    GridAxisV1 axis{0, 0, variable.variableId};
    DiscreteGridCellV1 cells[2] = {
        {DiscreteCellKindV1::Exact, 3},
        {DiscreteCellKindV1::Exact, 1},
    };
    DiscreteGridRowViewV1 rows[2]{};
    for (std::uint32_t index = 0; index < 2; ++index) {
        rows[index].stableRowOrdinal = index + 1;
        rows[index].authoredStableOrder = index;
        rows[index].childStableOrdinal =
            variableControlChildren[index].stableChildOrdinal;
        rows[index].cellCount = 1;
        rows[index].cells = &cells[index];
    }

    ContainerProgramViewV3 variableControlProgram = MakeContainerProgram(
        variableControlId, variableControlProperty.programSemanticFingerprint,
        1);
    variableControlProgram.mode = ContainerModeV1::VariableControl;
    variableControlProgram.randomDiscipline = {};
    variableControlProgram.memoryScope = MemoryScopeV1::Emitter;
    variableControlProgram.childCount = 2;
    variableControlProgram.children = variableControlChildren;
    variableControlProgram.discreteAxisCount = 1;
    variableControlProgram.discreteAxes = &axis;
    variableControlProgram.discreteRowCount = 2;
    variableControlProgram.discreteRows = rows;

    ContainerChildProgramViewV2 outerChild{};
    outerChild.playable = variableControlRef;
    outerChild.stableChildOrdinal = 7;
    outerChild.frequencyWeight = 1;
    ContainerProgramViewV3 outerProgram = MakeContainerProgram(
        outerContainerId, outerContainerProperty.programSemanticFingerprint, 2);
    outerProgram.mode = ContainerModeV1::Random;
    outerProgram.randomDiscipline = RandomDisciplineV1::Draw;
    outerProgram.memoryScope = MemoryScopeV1::Global;
    outerProgram.childCount = 1;
    outerProgram.children = &outerChild;

    PlayableOccurrencePropertyViewV1 occurrences[3]{};
    occurrences[0].parentKind =
        playableproperties::ContentPropertyKindV1::Container;
    occurrences[0].parentStableId = harkentest::ObjectId(outerContainerId);
    occurrences[0].parentProgramSemanticFingerprint =
        outerContainerProperty.programSemanticFingerprint;
    occurrences[0].stableOccurrenceOrdinal = outerChild.stableChildOrdinal;
    occurrences[0].childPlayable = outerChild.playable;
    occurrences[0].payload = EmptyOccurrencePayload();
    occurrences[0].occurrenceSemanticFingerprint =
        ComputePlayableOccurrenceFingerprintV1(occurrences[0]);
    for (std::uint32_t index = 0; index < 2; ++index) {
        occurrences[index + 1].parentKind =
            playableproperties::ContentPropertyKindV1::Container;
        occurrences[index + 1].parentStableId = harkentest::ObjectId(variableControlId);
        occurrences[index + 1].parentProgramSemanticFingerprint =
            variableControlProperty.programSemanticFingerprint;
        occurrences[index + 1].stableOccurrenceOrdinal =
            variableControlChildren[index].stableChildOrdinal;
        occurrences[index + 1].childPlayable =
            variableControlChildren[index].playable;
        occurrences[index + 1].payload = EmptyOccurrencePayload();
        occurrences[index + 1].occurrenceSemanticFingerprint =
            ComputePlayableOccurrenceFingerprintV1(occurrences[index + 1]);
    }

    PlayablePropertyProgramViewV1 properties[3] = {
        firstSound, outerContainerProperty, variableControlProperty};
    ActionStepProgramViewV1 step{};
    step.opcode = ActionOpcodeV1::Play;
    step.target.kind = ActionTargetKindV1::Container;
    step.target.stableId = harkentest::ObjectId(outerContainerId);
    step.target.expectedProgramSemanticFingerprint =
        outerContainerProperty.programSemanticFingerprint;
    SetAbsoluteTime(&step.delay, 0);
    SetAbsoluteTime(&step.fade, 0);
    SetAbsoluteTime(&step.cooldown, 0);
    ActionProgramViewV1 action{};
    action.actionStableId = actionId;
    action.steps = &step;
    action.stepCount = 1;
    action.directFeatureMask = 0;
    action.transitiveFeatureMask = 0;
    action.expandedStepOccurrenceCount = 1;
    action.expandedFiringCount = 1;
    action.programSemanticFingerprint = ComputeActionProgramFingerprintV1(action);

    ContainerWorldInstallViewV1 world{};
    world.identity.capabilityMask =
        kWorldCapabilityActionDefinitions |
        kWorldCapabilityPlayableProperties |
        kWorldCapabilityVariableDefinitions |
        kWorldCapabilityRandomDraw | kWorldCapabilityVariableControl;
    world.variables = &variable;
    world.variableCount = 1;
    world.playableProperties = properties;
    world.playablePropertyCount = 3;
    world.playableOccurrences = occurrences;
    world.playableOccurrenceCount = 3;
    ContainerProgramViewV3 containers[2] = {outerProgram,
                                             variableControlProgram};
    world.containers = containers;
    world.containerCount = 2;
    world.actions = &action;
    world.actionCount = 1;
    world.capacity.maxKnownScheduleLeaves = 16;
    world.capacity.maxTrackPieceScheduleDepth = 8;
    world.identity.runtimeSemanticFingerprint =
        ComputeCurrentWorldFingerprintV4(world);
    return WrapWorldPartition(packStableId, partitionRevision, world, 6);
}

std::vector<std::uint8_t> BuildImmediateRandomContainerToVariableControlPack(
    std::uint64_t packStableId, std::uint64_t contentRevision,
    std::uint64_t partitionRevision, VnObjectId actionId,
    VnObjectId outerContainerId, VnObjectId variableControlId,
    VnObjectId firstSoundId, std::vector<float> firstPlanar,
    std::uint32_t outerLoopCount = 1) {
    const float* firstChannels[1] = {firstPlanar.data()};
    std::uint64_t firstRevision = 0;
    EXPECT_TRUE(ComputeMediaPcmContentRevisionV1(
        48000, 1, static_cast<std::uint64_t>(firstPlanar.size()),
        firstChannels, 1, &firstRevision));
    ImageBuilder builder(kPackKindCanonicalContent);
    builder.AddEntry(kPackEntryKindPackRequirementBlock, packStableId,
                     RequirementPayload(packStableId, contentRevision,
                                        partitionRevision));
    builder.AddEntry(
        kPackEntryKindCanonicalDefinitionPartition, packStableId,
        ImmediateRandomContainerToVariableControlPlayPartitionPayload(
            packStableId, partitionRevision, actionId, outerContainerId,
            variableControlId, firstSoundId, firstRevision,
            outerLoopCount));
    builder.AddMedia(firstSoundId, std::move(firstPlanar));
    return builder.Build();
}

std::vector<std::uint8_t> ImmediateVariableControlNestedLoopPlayPayload(
    std::uint64_t packStableId, std::uint64_t partitionRevision,
    VnObjectId actionId, VnObjectId outerId,
    VnObjectId variableControlId, VnObjectId initialNestedId,
    VnObjectId retargetNestedId, VnObjectId firstSoundId,
    VnObjectId secondSoundId, std::uint64_t firstRevision,
    std::uint64_t secondRevision) {
    PlayablePropertyProgramViewV1 firstSound = MakeSoundProperty(firstSoundId);
    firstSound.authoredStableOrder = 0;
    firstSound.contentRevision = firstRevision;
    firstSound.programSemanticFingerprint =
        ComputePlayablePropertyFingerprintV1(firstSound);
    PlayablePropertyProgramViewV1 secondSound = MakeSoundProperty(secondSoundId);
    secondSound.authoredStableOrder = 1;
    secondSound.contentRevision = secondRevision;
    secondSound.programSemanticFingerprint =
        ComputePlayablePropertyFingerprintV1(secondSound);
    PlayablePropertyProgramViewV1 outerProperty =
        MakeContainerProperty(outerId, 2);
    PlayablePropertyProgramViewV1 variableControlProperty =
        MakeContainerProperty(variableControlId, 3);
    PlayablePropertyProgramViewV1 initialNestedProperty =
        MakeContainerProperty(initialNestedId, 4);
    PlayablePropertyProgramViewV1 retargetNestedProperty =
        MakeContainerProperty(retargetNestedId, 5);
    SetContainerPropertyLoopCount(&outerProperty, 4);
    SetContainerPropertyLoopCount(&initialNestedProperty, 2);
    SetContainerPropertyLoopCount(&retargetNestedProperty, 3);

    const PlayableRefV1 firstRef = PlayableRefFromProperty(firstSound);
    const PlayableRefV1 secondRef = PlayableRefFromProperty(secondSound);
    const PlayableRefV1 variableControlRef =
        PlayableRefFromProperty(variableControlProperty);
    const PlayableRefV1 initialNestedRef =
        PlayableRefFromProperty(initialNestedProperty);
    const PlayableRefV1 retargetNestedRef =
        PlayableRefFromProperty(retargetNestedProperty);

    ContainerChildProgramViewV2 outerChild{};
    outerChild.playable = variableControlRef;
    outerChild.stableChildOrdinal = 7;
    outerChild.frequencyWeight = 1;
    ContainerChildProgramViewV2 variableChildren[2]{};
    variableChildren[0].playable = initialNestedRef;
    variableChildren[0].stableChildOrdinal = 7;
    variableChildren[1].playable = retargetNestedRef;
    variableChildren[1].stableChildOrdinal = 8;
    variableChildren[1].authoredStableOrder = 1;
    ContainerChildProgramViewV2 initialChild{};
    initialChild.playable = firstRef;
    initialChild.stableChildOrdinal = 7;
    ContainerChildProgramViewV2 retargetChild{};
    retargetChild.playable = secondRef;
    retargetChild.stableChildOrdinal = 7;

    const VariableDefinitionV1 variable = harkentest::MakeVariableDefinition(
        harkentest::ObjectId(41), VariableKindV1::Step, 0.0f, 8.0f, 3.0f);
    GridAxisV1 axis{0, 0, variable.variableId};
    DiscreteGridCellV1 cells[2] = {
        {DiscreteCellKindV1::Exact, 3},
        {DiscreteCellKindV1::Exact, 1},
    };
    DiscreteGridRowViewV1 rows[2]{};
    for (std::uint32_t index = 0; index < 2; ++index) {
        rows[index].stableRowOrdinal = index + 1u;
        rows[index].authoredStableOrder = index;
        rows[index].childStableOrdinal = variableChildren[index].stableChildOrdinal;
        rows[index].cellCount = 1;
        rows[index].cells = &cells[index];
    }

    ContainerProgramViewV3 outerProgram = MakeContainerProgram(
        outerId, outerProperty.programSemanticFingerprint, 0);
    outerProgram.mode = ContainerModeV1::Random;
    outerProgram.randomDiscipline = RandomDisciplineV1::Draw;
    outerProgram.memoryScope = MemoryScopeV1::Global;
    outerProgram.childCount = 1;
    outerProgram.children = &outerChild;
    ContainerProgramViewV3 variableProgram = MakeContainerProgram(
        variableControlId, variableControlProperty.programSemanticFingerprint,
        1);
    variableProgram.mode = ContainerModeV1::VariableControl;
    variableProgram.randomDiscipline = {};
    variableProgram.memoryScope = MemoryScopeV1::Emitter;
    variableProgram.childCount = 2;
    variableProgram.children = variableChildren;
    variableProgram.discreteAxisCount = 1;
    variableProgram.discreteAxes = &axis;
    variableProgram.discreteRowCount = 2;
    variableProgram.discreteRows = rows;
    variableProgram.discreteTiming = 1;
    variableProgram.evaluationPeriodFrames = 64;
    ContainerProgramViewV3 initialProgram = MakeContainerProgram(
        initialNestedId, initialNestedProperty.programSemanticFingerprint, 2);
    initialProgram.mode = ContainerModeV1::Sequence;
    initialProgram.randomDiscipline = {};
    initialProgram.memoryScope = MemoryScopeV1::Global;
    initialProgram.childCount = 1;
    initialProgram.children = &initialChild;
    ContainerProgramViewV3 retargetProgram = MakeContainerProgram(
        retargetNestedId, retargetNestedProperty.programSemanticFingerprint, 3);
    retargetProgram.mode = ContainerModeV1::Sequence;
    retargetProgram.randomDiscipline = {};
    retargetProgram.memoryScope = MemoryScopeV1::Global;
    retargetProgram.childCount = 1;
    retargetProgram.children = &retargetChild;

    PlayableOccurrencePropertyViewV1 occurrences[5]{};
    const auto setOccurrence = [](PlayableOccurrencePropertyViewV1* occurrence,
                                  VnObjectId parentId,
                                  std::uint64_t parentFingerprint,
                                  std::uint32_t ordinal,
                                  const PlayableRefV1& child) {
        occurrence->parentKind =
            playableproperties::ContentPropertyKindV1::Container;
        occurrence->parentStableId = harkentest::ObjectId(parentId);
        occurrence->parentProgramSemanticFingerprint = parentFingerprint;
        occurrence->stableOccurrenceOrdinal = ordinal;
        occurrence->childPlayable = child;
        occurrence->payload = EmptyOccurrencePayload();
        occurrence->occurrenceSemanticFingerprint =
            ComputePlayableOccurrenceFingerprintV1(*occurrence);
    };
    setOccurrence(&occurrences[0], outerId,
                  outerProperty.programSemanticFingerprint, 7,
                  variableControlRef);
    setOccurrence(&occurrences[1], variableControlId,
                  variableControlProperty.programSemanticFingerprint, 7,
                  initialNestedRef);
    setOccurrence(&occurrences[2], variableControlId,
                  variableControlProperty.programSemanticFingerprint, 8,
                  retargetNestedRef);
    setOccurrence(&occurrences[3], initialNestedId,
                  initialNestedProperty.programSemanticFingerprint, 7,
                  firstRef);
    setOccurrence(&occurrences[4], retargetNestedId,
                  retargetNestedProperty.programSemanticFingerprint, 7,
                  secondRef);

    PlayablePropertyProgramViewV1 properties[6] = {
        firstSound, secondSound, outerProperty, variableControlProperty,
        initialNestedProperty, retargetNestedProperty};
    ContainerProgramViewV3 containers[4] = {
        outerProgram, variableProgram, initialProgram, retargetProgram};
    ActionStepProgramViewV1 step{};
    step.opcode = ActionOpcodeV1::Play;
    step.target.kind = ActionTargetKindV1::Container;
    step.target.stableId = harkentest::ObjectId(outerId);
    step.target.expectedProgramSemanticFingerprint =
        outerProperty.programSemanticFingerprint;
    SetAbsoluteTime(&step.delay, 0);
    SetAbsoluteTime(&step.fade, 0);
    SetAbsoluteTime(&step.cooldown, 0);
    ActionProgramViewV1 action{};
    action.actionStableId = actionId;
    action.steps = &step;
    action.stepCount = 1;
    action.directFeatureMask = 0;
    action.transitiveFeatureMask = 0;
    action.expandedStepOccurrenceCount = 1;
    action.expandedFiringCount = 1;
    action.programSemanticFingerprint = ComputeActionProgramFingerprintV1(action);

    ContainerWorldInstallViewV1 world{};
    world.identity.capabilityMask =
        kWorldCapabilityActionDefinitions | kWorldCapabilityPlayableProperties |
        kWorldCapabilityVariableDefinitions | kWorldCapabilityRandomDraw |
        kWorldCapabilitySequence | kWorldCapabilityVariableControl;
    world.variables = &variable;
    world.variableCount = 1;
    world.playableProperties = properties;
    world.playablePropertyCount = 6;
    world.playableOccurrences = occurrences;
    world.playableOccurrenceCount = 5;
    world.containers = containers;
    world.containerCount = 4;
    world.actions = &action;
    world.actionCount = 1;
    world.capacity.maxKnownScheduleLeaves = 16;
    world.capacity.maxTrackPieceScheduleDepth = 8;
    world.identity.runtimeSemanticFingerprint =
        ComputeCurrentWorldFingerprintV4(world);
    return WrapWorldPartition(packStableId, partitionRevision, world, 10);
}

std::vector<std::uint8_t> BuildVariableControlNestedLoopPlayPack(
    std::uint64_t packStableId, std::uint64_t contentRevision,
    std::uint64_t partitionRevision, VnObjectId actionId,
    VnObjectId outerId, VnObjectId variableControlId,
    VnObjectId initialNestedId, VnObjectId retargetNestedId,
    VnObjectId firstSoundId, VnObjectId secondSoundId,
    std::vector<float> firstPlanar, std::vector<float> secondPlanar) {
    const float* firstChannels[1] = {firstPlanar.data()};
    const float* secondChannels[1] = {secondPlanar.data()};
    std::uint64_t firstRevision = 0;
    std::uint64_t secondRevision = 0;
    EXPECT_TRUE(ComputeMediaPcmContentRevisionV1(
        48000, 1, firstPlanar.size(), firstChannels, 1, &firstRevision));
    EXPECT_TRUE(ComputeMediaPcmContentRevisionV1(
        48000, 1, secondPlanar.size(), secondChannels, 1, &secondRevision));
    ImageBuilder builder(kPackKindCanonicalContent);
    builder.AddEntry(kPackEntryKindPackRequirementBlock, packStableId,
                     RequirementPayload(packStableId, contentRevision,
                                        partitionRevision));
    builder.AddEntry(
        kPackEntryKindCanonicalDefinitionPartition, packStableId,
        ImmediateVariableControlNestedLoopPlayPayload(
            packStableId, partitionRevision, actionId, outerId,
            variableControlId, initialNestedId, retargetNestedId,
            firstSoundId, secondSoundId, firstRevision, secondRevision));
    builder.AddMedia(firstSoundId, std::move(firstPlanar));
    builder.AddMedia(secondSoundId, std::move(secondPlanar));
    return builder.Build();
}

std::vector<std::uint8_t> ImmediateVariableControlContinuousPlayPartitionPayload(
    std::uint64_t packStableId, std::uint64_t partitionRevision,
    VnObjectId actionId, VnObjectId containerId,
    VnObjectId firstSoundId, VnObjectId secondSoundId,
    std::uint64_t firstRevision, std::uint64_t secondRevision,
    float intervalLower, std::uint32_t evaluationPeriodFrames) {
    PlayablePropertyProgramViewV1 firstSound = MakeSoundProperty(firstSoundId);
    firstSound.contentRevision = firstRevision;
    firstSound.programSemanticFingerprint =
        ComputePlayablePropertyFingerprintV1(firstSound);
    PlayablePropertyProgramViewV1 secondSound = MakeSoundProperty(secondSoundId);
    secondSound.authoredStableOrder = 1;
    secondSound.contentRevision = secondRevision;
    secondSound.compatibilityFingerprint = 5;
    secondSound.programSemanticFingerprint =
        ComputePlayablePropertyFingerprintV1(secondSound);
    PlayablePropertyProgramViewV1 containerProperty =
        MakeContainerProperty(containerId, 2);
    const PlayableRefV1 firstRef = PlayableRefFromProperty(firstSound);
    const PlayableRefV1 secondRef = PlayableRefFromProperty(secondSound);

    ContainerChildProgramViewV2 children[2]{};
    children[0].playable = firstRef;
    children[0].stableChildOrdinal = 7;
    children[1] = children[0];
    children[1].playable = secondRef;
    children[1].stableChildOrdinal = 8;
    children[1].authoredStableOrder = 1;

    const VariableDefinitionV1 variable = harkentest::MakeVariableDefinition(
        harkentest::ObjectId(41), VariableKindV1::Step, 0.0f, 8.0f, 3.0f);
    GridAxisV1 axis{0, 0, variable.variableId};
    ContinuousGridCellV1 cell{};
    cell.kind = ContinuousCellKindV1::Interval;
    cell.lower = intervalLower;
    cell.upper = 8.0f;
    cell.lowerInclusive = 1;
    cell.upperInclusive = 1;
    ContinuousGridRowViewV1 row{};
    row.stableRowOrdinal = 3;
    row.childStableOrdinal = children[1].stableChildOrdinal;
    row.cellCount = 1;
    row.cells = &cell;

    ContainerProgramViewV3 program = MakeContainerProgram(
        containerId, containerProperty.programSemanticFingerprint, 2);
    program.mode = ContainerModeV1::VariableControl;
    program.randomDiscipline = {};
    program.memoryScope = MemoryScopeV1::Emitter;
    program.childCount = 2;
    program.children = children;
    program.continuousAxisCount = 1;
    program.continuousAxes = &axis;
    program.continuousRowCount = 1;
    program.continuousRows = &row;
    program.evaluationPeriodFrames = evaluationPeriodFrames;
    program.maxActiveRows = 1;
    program.maxLiveRows = 1;

    PlayableOccurrencePropertyViewV1 occurrences[2]{};
    occurrences[0].parentKind =
        playableproperties::ContentPropertyKindV1::Container;
    occurrences[0].parentStableId = harkentest::ObjectId(containerId);
    occurrences[0].parentProgramSemanticFingerprint =
        containerProperty.programSemanticFingerprint;
    occurrences[0].stableOccurrenceOrdinal = children[0].stableChildOrdinal;
    occurrences[0].childPlayable = firstRef;
    occurrences[0].payload = EmptyOccurrencePayload();
    occurrences[0].occurrenceSemanticFingerprint =
        ComputePlayableOccurrenceFingerprintV1(occurrences[0]);
    occurrences[1] = occurrences[0];
    occurrences[1].stableOccurrenceOrdinal = children[1].stableChildOrdinal;
    occurrences[1].childPlayable = secondRef;
    occurrences[1].occurrenceSemanticFingerprint =
        ComputePlayableOccurrenceFingerprintV1(occurrences[1]);
    PlayablePropertyProgramViewV1 properties[3] = {
        firstSound, secondSound, containerProperty};

    ActionStepProgramViewV1 step{};
    step.opcode = ActionOpcodeV1::Play;
    step.target.kind = ActionTargetKindV1::Container;
    step.target.stableId = harkentest::ObjectId(containerId);
    step.target.expectedProgramSemanticFingerprint =
        containerProperty.programSemanticFingerprint;
    SetAbsoluteTime(&step.delay, 0);
    SetAbsoluteTime(&step.fade, 0);
    SetAbsoluteTime(&step.cooldown, 0);
    ActionProgramViewV1 action{};
    action.actionStableId = actionId;
    action.steps = &step;
    action.stepCount = 1;
    action.directFeatureMask = 0;
    action.transitiveFeatureMask = 0;
    action.expandedStepOccurrenceCount = 1;
    action.expandedFiringCount = 1;
    action.programSemanticFingerprint = ComputeActionProgramFingerprintV1(action);

    ContainerWorldInstallViewV1 world{};
    world.identity.capabilityMask = kWorldCapabilityActionDefinitions |
                                    kWorldCapabilityPlayableProperties |
                                    kWorldCapabilityVariableDefinitions |
                                    kWorldCapabilityVariableControl;
    world.variables = &variable;
    world.variableCount = 1;
    world.playableProperties = properties;
    world.playablePropertyCount = 3;
    world.playableOccurrences = occurrences;
    world.playableOccurrenceCount = 2;
    world.containers = &program;
    world.containerCount = 1;
    world.actions = &action;
    world.actionCount = 1;
    world.capacity.maxKnownScheduleLeaves = 16;
    world.capacity.maxTrackPieceScheduleDepth = 8;
    world.identity.runtimeSemanticFingerprint =
        ComputeCurrentWorldFingerprintV4(world);
    return WrapWorldPartition(packStableId, partitionRevision, world, 5);
}

std::vector<std::uint8_t> BuildImmediateVariableControlContinuousPlayPack(
    std::uint64_t packStableId, std::uint64_t contentRevision,
    std::uint64_t partitionRevision, VnObjectId actionId,
    VnObjectId containerId, VnObjectId firstSoundId,
    VnObjectId secondSoundId, std::vector<float> firstPlanar,
    std::vector<float> secondPlanar, float intervalLower,
    std::uint32_t evaluationPeriodFrames) {
    const float* firstChannels[1] = {firstPlanar.data()};
    const float* secondChannels[1] = {secondPlanar.data()};
    std::uint64_t firstRevision = 0;
    std::uint64_t secondRevision = 0;
    EXPECT_TRUE(ComputeMediaPcmContentRevisionV1(
        48000, 1, static_cast<std::uint64_t>(firstPlanar.size()), firstChannels,
        1, &firstRevision));
    EXPECT_TRUE(ComputeMediaPcmContentRevisionV1(
        48000, 1, static_cast<std::uint64_t>(secondPlanar.size()),
        secondChannels, 1, &secondRevision));
    ImageBuilder builder(kPackKindCanonicalContent);
    builder.AddEntry(kPackEntryKindPackRequirementBlock, packStableId,
                     RequirementPayload(packStableId, contentRevision,
                                        partitionRevision));
    builder.AddEntry(kPackEntryKindCanonicalDefinitionPartition, packStableId,
                     ImmediateVariableControlContinuousPlayPartitionPayload(
                         packStableId, partitionRevision, actionId, containerId,
                         firstSoundId, secondSoundId, firstRevision,
                         secondRevision, intervalLower,
                         evaluationPeriodFrames));
    builder.AddMedia(firstSoundId, std::move(firstPlanar));
    builder.AddMedia(secondSoundId, std::move(secondPlanar));
    return builder.Build();
}

std::vector<std::uint8_t> ImmediatePiecePlayPartitionPayload(
    std::uint64_t packStableId, std::uint64_t partitionRevision,
    VnObjectId actionId, VnObjectId pieceId, VnObjectId trackId,
    VnObjectId soundId, std::uint64_t contentRevision,
    std::uint32_t loopCount = 1,
    std::int64_t authoredDuration = 0) {
    PlayablePropertyProgramViewV1 sound = MakeSoundProperty(soundId);
    if (loopCount != 1) {
        sound.payload.presentMask |= UINT64_C(1) << 3;
    }
    sound.payload.values[3].bits = loopCount;
    sound.contentRevision = contentRevision;
    sound.programSemanticFingerprint = ComputePlayablePropertyFingerprintV1(sound);
    PlayablePropertyProgramViewV1 trackProperty{};
    trackProperty.contentPropertyKind =
        playableproperties::ContentPropertyKindV1::Track;
    trackProperty.stableId = harkentest::ObjectId(trackId);
    trackProperty.authoredStableOrder = 1;
    trackProperty.contentRevision = 1;
    trackProperty.routeStableId = VN_BUS_MASTER;
    trackProperty.compatibilityFingerprint = 1;
    trackProperty.payload = DelayedPlayPayload();
    trackProperty.programSemanticFingerprint =
        ComputePlayablePropertyFingerprintV1(trackProperty);
    PlayablePropertyProgramViewV1 pieceProperty{};
    pieceProperty.contentPropertyKind =
        playableproperties::ContentPropertyKindV1::Piece;
    pieceProperty.stableId = harkentest::ObjectId(pieceId);
    pieceProperty.authoredStableOrder = 2;
    pieceProperty.contentRevision = 1;
    pieceProperty.routeStableId = VN_BUS_MASTER;
    pieceProperty.compatibilityFingerprint = 1;
    pieceProperty.payload = DelayedPlayPayload();
    pieceProperty.programSemanticFingerprint =
        ComputePlayablePropertyFingerprintV1(pieceProperty);
    const PlayableRefV1 trackRef = PlayableRefFromProperty(trackProperty);
    const PlayableRefV1 soundRef = PlayableRefFromProperty(sound);
    const PlayableRefV1 pieceRef = PlayableRefFromProperty(pieceProperty);

    ScheduleClipPlacementV1 placement{};
    placement.stablePlacementOrdinal = 0;
    placement.stableOccurrenceOrdinal = 0;
    placement.content = soundRef;
    placement.authoredDuration = authoredDuration;
    placement.clipId = harkentest::ObjectId(soundId.low * 1000u + 1u);
    placement.clipGuidHigh = 1;
    TrackScheduleProgramViewV1 trackSchedule{};
    trackSchedule.rootDefinition = trackRef;
    trackSchedule.placementCount = 1;
    trackSchedule.placements = &placement;
    trackSchedule.scheduleSemanticFingerprint =
        ComputeTrackScheduleFingerprintV1(trackSchedule);

    ScheduleTrackRefV1 trackScheduleRef{};
    trackScheduleRef.trackDefinition = trackRef;
    trackScheduleRef.trackScheduleSemanticFingerprint =
        trackSchedule.scheduleSemanticFingerprint;
    PieceScheduleProgramViewV1 pieceSchedule{};
    pieceSchedule.rootDefinition = pieceRef;
    pieceSchedule.trackRefCount = 1;
    pieceSchedule.trackRefs = &trackScheduleRef;
    pieceSchedule.scheduleSemanticFingerprint =
        ComputePieceScheduleFingerprintV1(pieceSchedule);

    PlayableOccurrencePropertyViewV1 occurrence{};
    occurrence.parentKind = playableproperties::ContentPropertyKindV1::Track;
    occurrence.parentStableId = harkentest::ObjectId(trackId);
    occurrence.parentProgramSemanticFingerprint =
        trackProperty.programSemanticFingerprint;
    occurrence.stableOccurrenceOrdinal = 0;
    occurrence.childPlayable = soundRef;
    occurrence.payload = EmptyOccurrencePayload();
    occurrence.occurrenceSemanticFingerprint =
        ComputePlayableOccurrenceFingerprintV1(occurrence);
    PlayablePropertyProgramViewV1 properties[3] = {sound, trackProperty,
                                                   pieceProperty};

    ActionStepProgramViewV1 step{};
    step.opcode = ActionOpcodeV1::Play;
    step.target.kind = ActionTargetKindV1::Piece;
    step.target.stableId = harkentest::ObjectId(pieceId);
    step.target.expectedProgramSemanticFingerprint =
        pieceProperty.programSemanticFingerprint;
    SetAbsoluteTime(&step.delay, 0);
    SetAbsoluteTime(&step.fade, 0);
    SetAbsoluteTime(&step.cooldown, 0);
    ActionProgramViewV1 action{};
    action.actionStableId = actionId;
    action.steps = &step;
    action.stepCount = 1;
    action.directFeatureMask = 0;
    action.transitiveFeatureMask = 0;
    action.expandedStepOccurrenceCount = 1;
    action.expandedFiringCount = 1;
    action.programSemanticFingerprint = ComputeActionProgramFingerprintV1(action);

    ContainerWorldInstallViewV1 world{};
    world.identity.capabilityMask = kWorldCapabilityActionDefinitions |
                                    kWorldCapabilityPlayableProperties;
    world.playableProperties = properties;
    world.playablePropertyCount = 3;
    world.playableOccurrences = &occurrence;
    world.playableOccurrenceCount = 1;
    world.trackSchedules = &trackSchedule;
    world.trackScheduleCount = 1;
    world.pieceSchedules = &pieceSchedule;
    world.pieceScheduleCount = 1;
    world.actions = &action;
    world.actionCount = 1;
    world.capacity.maxKnownScheduleLeaves = 16;
    world.capacity.maxTrackPieceScheduleDepth = 8;
    world.identity.runtimeSemanticFingerprint =
        ComputeCurrentWorldFingerprintV5(world);
    return WrapWorldPartition(packStableId, partitionRevision, world, 4);
}

std::vector<std::uint8_t> BuildImmediatePiecePlayPack(
    std::uint64_t packStableId, std::uint64_t contentRevision,
    std::uint64_t partitionRevision, VnObjectId actionId,
    VnObjectId pieceId, VnObjectId trackId, VnObjectId soundId,
    std::vector<float> planar, std::uint32_t loopCount = 1,
    std::uint64_t loopStartFrame = 0,
    std::uint64_t loopEndFrame = 0,
    std::int64_t authoredDuration = 0) {
    const float* channels[1] = {planar.data()};
    std::uint64_t mediaRevision = 0;
    EXPECT_TRUE(ComputeMediaPcmContentRevisionV1(
        48000, 1, static_cast<std::uint64_t>(planar.size()), channels, 1,
        &mediaRevision, loopStartFrame, loopEndFrame));
    ImageBuilder builder(kPackKindCanonicalContent);
    builder.AddEntry(kPackEntryKindPackRequirementBlock, packStableId,
                     RequirementPayload(packStableId, contentRevision,
                                        partitionRevision));
    builder.AddEntry(kPackEntryKindCanonicalDefinitionPartition, packStableId,
                     ImmediatePiecePlayPartitionPayload(
                         packStableId, partitionRevision, actionId, pieceId,
                         trackId, soundId, mediaRevision, loopCount,
                         authoredDuration));
    builder.AddMedia(soundId, std::move(planar), 1, 48000,
                     loopStartFrame, loopEndFrame);
    return builder.Build();
}

std::vector<std::uint8_t> MusicalPieceQuantizePartitionPayload(
    std::uint64_t packStableId, std::uint64_t partitionRevision,
    VnObjectId pieceActionId, VnObjectId soundActionId,
    VnObjectId pieceId, VnObjectId trackId, VnObjectId pieceSoundId,
    VnObjectId quantizedSoundId, std::uint64_t pieceSoundRevision,
    std::uint64_t quantizedSoundRevision, ActionQuantizeTimingV1 timing) {
    PlayablePropertyProgramViewV1 pieceSound = MakeSoundProperty(pieceSoundId);
    pieceSound.authoredStableOrder = 0;
    pieceSound.contentRevision = pieceSoundRevision;
    pieceSound.programSemanticFingerprint =
        ComputePlayablePropertyFingerprintV1(pieceSound);
    PlayablePropertyProgramViewV1 quantizedSound =
        MakeSoundProperty(quantizedSoundId);
    quantizedSound.authoredStableOrder = 1;
    quantizedSound.contentRevision = quantizedSoundRevision;
    quantizedSound.programSemanticFingerprint =
        ComputePlayablePropertyFingerprintV1(quantizedSound);
    PlayablePropertyProgramViewV1 trackProperty{};
    trackProperty.contentPropertyKind =
        playableproperties::ContentPropertyKindV1::Track;
    trackProperty.stableId = harkentest::ObjectId(trackId);
    trackProperty.authoredStableOrder = 2;
    trackProperty.contentRevision = 1;
    trackProperty.routeStableId = VN_BUS_MASTER;
    trackProperty.compatibilityFingerprint = 1;
    trackProperty.payload = DelayedPlayPayload();
    trackProperty.programSemanticFingerprint =
        ComputePlayablePropertyFingerprintV1(trackProperty);
    PlayablePropertyProgramViewV1 pieceProperty{};
    pieceProperty.contentPropertyKind =
        playableproperties::ContentPropertyKindV1::Piece;
    pieceProperty.stableId = harkentest::ObjectId(pieceId);
    pieceProperty.authoredStableOrder = 3;
    pieceProperty.contentRevision = 1;
    pieceProperty.routeStableId = VN_BUS_MASTER;
    pieceProperty.compatibilityFingerprint = 1;
    pieceProperty.payload = DelayedPlayPayload();
    pieceProperty.programSemanticFingerprint =
        ComputePlayablePropertyFingerprintV1(pieceProperty);
    const PlayableRefV1 trackRef = PlayableRefFromProperty(trackProperty);
    const PlayableRefV1 pieceSoundRef = PlayableRefFromProperty(pieceSound);
    const PlayableRefV1 pieceRef = PlayableRefFromProperty(pieceProperty);

    ScheduleClipPlacementV1 placement{};
    placement.stablePlacementOrdinal = 0;
    placement.stableOccurrenceOrdinal = 0;
    placement.content = pieceSoundRef;
    placement.clipId = harkentest::ObjectId(pieceSoundId.low * 1000u + 1u);
    placement.clipGuidHigh = 1;
    TrackScheduleProgramViewV1 trackSchedule{};
    trackSchedule.rootDefinition = trackRef;
    trackSchedule.placementCount = 1;
    trackSchedule.placements = &placement;
    trackSchedule.scheduleSemanticFingerprint =
        ComputeTrackScheduleFingerprintV1(trackSchedule);

    ScheduleTrackRefV1 trackScheduleRef{};
    trackScheduleRef.trackDefinition = trackRef;
    trackScheduleRef.trackScheduleSemanticFingerprint =
        trackSchedule.scheduleSemanticFingerprint;
    ScheduleMarkerV1 markers[3]{};
    markers[0].stableMarkerId = harkentest::ObjectId(10001);
    markers[0].markerId = 11;
    markers[0].markerKind = 0;
    markers[0].position = 480;
    markers[1].stableMarkerId = harkentest::ObjectId(10002);
    markers[1].markerId = 12;
    markers[1].markerKind = 0;
    markers[1].position = 1920;
    markers[2].stableMarkerId = harkentest::ObjectId(10003);
    markers[2].markerId = 13;
    markers[2].markerKind = 0;
    markers[2].position = 7680;
    PieceScheduleProgramViewV1 pieceSchedule{};
    pieceSchedule.rootDefinition = pieceRef;
    pieceSchedule.timeKind = ScheduleTimeKindV1::MusicalTicks;
    pieceSchedule.microsPerQuarter = 20000;
    pieceSchedule.meterNumerator = 4;
    pieceSchedule.meterDenominator = 4;
    pieceSchedule.trackRefCount = 1;
    pieceSchedule.trackRefs = &trackScheduleRef;
    pieceSchedule.markerCount = 3;
    pieceSchedule.markers = markers;
    pieceSchedule.scheduleSemanticFingerprint =
        ComputePieceScheduleFingerprintV1(pieceSchedule);

    PlayableOccurrencePropertyViewV1 occurrence{};
    occurrence.parentKind = playableproperties::ContentPropertyKindV1::Track;
    occurrence.parentStableId = harkentest::ObjectId(trackId);
    occurrence.parentProgramSemanticFingerprint =
        trackProperty.programSemanticFingerprint;
    occurrence.stableOccurrenceOrdinal = 0;
    occurrence.childPlayable = pieceSoundRef;
    occurrence.payload = EmptyOccurrencePayload();
    occurrence.occurrenceSemanticFingerprint =
        ComputePlayableOccurrenceFingerprintV1(occurrence);
    PlayablePropertyProgramViewV1 properties[4] = {
        pieceSound, quantizedSound, trackProperty, pieceProperty};

    ActionStepProgramViewV1 steps[2]{};
    steps[0].opcode = ActionOpcodeV1::Play;
    steps[0].target.kind = ActionTargetKindV1::Piece;
    steps[0].target.stableId = harkentest::ObjectId(pieceId);
    steps[0].target.expectedProgramSemanticFingerprint =
        pieceProperty.programSemanticFingerprint;
    SetAbsoluteTime(&steps[0].delay, 0);
    SetAbsoluteTime(&steps[0].fade, 0);
    SetAbsoluteTime(&steps[0].cooldown, 0);
    steps[1].opcode = ActionOpcodeV1::Play;
    steps[1].target.kind = ActionTargetKindV1::Sound;
    steps[1].target.stableId = harkentest::ObjectId(quantizedSoundId);
    steps[1].target.expectedProgramSemanticFingerprint =
        quantizedSound.programSemanticFingerprint;
    SetAbsoluteTime(&steps[1].delay, 0);
    SetAbsoluteTime(&steps[1].fade, 0);
    SetAbsoluteTime(&steps[1].cooldown, 0);
    steps[1].quantizeTiming = timing;
    steps[1].quantizeReference.kind = ActionTargetKindV1::Piece;
    steps[1].quantizeReference.stableId = harkentest::ObjectId(pieceId);
    steps[1].quantizeReference.expectedProgramSemanticFingerprint =
        pieceProperty.programSemanticFingerprint;
    ActionProgramViewV1 actions[2]{};
    actions[0].actionStableId = harkentest::ObjectId(pieceActionId);
    actions[0].steps = &steps[0];
    actions[0].stepCount = 1;
    actions[0].directFeatureMask = 0;
    actions[0].transitiveFeatureMask = 0;
    actions[0].expandedStepOccurrenceCount = 1;
    actions[0].expandedFiringCount = 1;
    actions[0].programSemanticFingerprint =
        ComputeActionProgramFingerprintV1(actions[0]);
    actions[1].actionStableId = harkentest::ObjectId(soundActionId);
    actions[1].steps = &steps[1];
    actions[1].stepCount = 1;
    actions[1].directFeatureMask = 2;
    actions[1].transitiveFeatureMask = 2;
    actions[1].expandedStepOccurrenceCount = 1;
    actions[1].expandedFiringCount = 1;
    actions[1].programSemanticFingerprint =
        ComputeActionProgramFingerprintV1(actions[1]);

    ContainerWorldInstallViewV1 world{};
    world.identity.capabilityMask = kWorldCapabilityActionDefinitions |
                                    kWorldCapabilityPlayableProperties;
    world.playableProperties = properties;
    world.playablePropertyCount = 4;
    world.playableOccurrences = &occurrence;
    world.playableOccurrenceCount = 1;
    world.trackSchedules = &trackSchedule;
    world.trackScheduleCount = 1;
    world.pieceSchedules = &pieceSchedule;
    world.pieceScheduleCount = 1;
    world.actions = actions;
    world.actionCount = 2;
    world.capacity.maxKnownScheduleLeaves = 16;
    world.capacity.maxTrackPieceScheduleDepth = 8;
    world.identity.runtimeSemanticFingerprint =
        ComputeCurrentWorldFingerprintV4(world);
    return WrapWorldPartition(packStableId, partitionRevision, world, 6);
}

std::vector<std::uint8_t> BuildMusicalPieceQuantizePack(
    std::uint64_t packStableId, std::uint64_t contentRevision,
    std::uint64_t partitionRevision, VnObjectId pieceActionId,
    VnObjectId soundActionId, VnObjectId pieceId, VnObjectId trackId,
    VnObjectId pieceSoundId, VnObjectId quantizedSoundId,
    ActionQuantizeTimingV1 timing, std::vector<float> piecePlanar,
    std::vector<float> soundPlanar) {
    const float* pieceChannels[1] = {piecePlanar.data()};
    const float* soundChannels[1] = {soundPlanar.data()};
    std::uint64_t pieceRevision = 0;
    std::uint64_t soundRevision = 0;
    EXPECT_TRUE(ComputeMediaPcmContentRevisionV1(
        48000, 1, static_cast<std::uint64_t>(piecePlanar.size()), pieceChannels,
        1, &pieceRevision));
    EXPECT_TRUE(ComputeMediaPcmContentRevisionV1(
        48000, 1, static_cast<std::uint64_t>(soundPlanar.size()), soundChannels,
        1, &soundRevision));
    ImageBuilder builder(kPackKindCanonicalContent);
    builder.AddEntry(kPackEntryKindPackRequirementBlock, packStableId,
                     RequirementPayload(packStableId, contentRevision,
                                        partitionRevision));
    builder.AddEntry(kPackEntryKindCanonicalDefinitionPartition, packStableId,
                     MusicalPieceQuantizePartitionPayload(
                         packStableId, partitionRevision, pieceActionId,
                         soundActionId, pieceId, trackId, pieceSoundId,
                         quantizedSoundId, pieceRevision, soundRevision,
                         timing));
    builder.AddMedia(pieceSoundId, std::move(piecePlanar));
    builder.AddMedia(quantizedSoundId, std::move(soundPlanar));
    return builder.Build();
}

BoundaryType QuantizeBoundaryType(ActionQuantizeTimingV1 timing) {
    switch (timing) {
    case ActionQuantizeTimingV1::NextBeat:
        return BoundaryType::Beat;
    case ActionQuantizeTimingV1::NextBar:
        return BoundaryType::Bar;
    case ActionQuantizeTimingV1::NextMarker:
        return BoundaryType::Marker;
    default:
        return BoundaryType::Beat;
    }
}

std::uint64_t ImmediateQuantizeBaseFrame(const Engine& engine) {
    const std::uint64_t cutoff = engine.timelinePool.PublishCutoffFrame();
    const std::uint64_t quantum = engine.config.blockFrames;
    const std::uint64_t leadQuanta =
        std::max<std::uint64_t>(1u, engine.timelinePool.PublishLeadQuanta());
    const std::uint64_t lead = leadQuanta * quantum;
    const std::uint64_t observed = engine.mixer.BlocksRendered() * quantum;
    return std::max(cutoff, observed + lead);
}

bool ExpectedFrozenQuantizeFrame(const EnginePlayableServiceRow& pieceRow,
                                 std::uint64_t delayedFrame,
                                 ActionQuantizeTimingV1 timing,
                                 std::uint64_t sampleRate,
                                 std::uint64_t* outFrame) {
    if (outFrame == nullptr) {
        return false;
    }
    const auto piece =
        pieceRow.Invocation().packPlaybackView.ResolvePiece(pieceRow.root.stableId, 0);
    if (piece == nullptr) {
        return false;
    }
    TempoSegment tempo{};
    tempo.microsPerQuarter = piece->microsPerQuarter;
    ClockKernel clock;
    if (!clock.Reset(static_cast<std::int64_t>(sampleRate), &tempo, 1)) {
        return false;
    }
    MeterSignature meter{static_cast<std::int32_t>(piece->meterNumerator),
                         static_cast<std::int32_t>(piece->meterDenominator)};
    MarkerPoint markers[16]{};
    if (piece->markerCount > 16) {
        return false;
    }
    for (std::uint32_t index = 0; index < piece->markerCount; ++index) {
        const auto& authored = piece->markers[index];
        markers[index].id = authored.stableMarkerId;
        markers[index].kind = authored.markerKind == 1 ? MarkerKind::Exit
                                                 : MarkerKind::Custom;
        markers[index].position = authored.position;
    }
    MarkerIndex markerIndex;
    if (!markerIndex.Reset(PieceTimeType::Musical, &clock, meter, markers,
                        piece->markerCount,
                        std::max<std::size_t>(1, piece->markerCount))) {
        return false;
    }
    const std::uint64_t entry = pieceRow.startFrame;
    std::int64_t fromPosition = 0;
    if (delayedFrame > entry) {
        const std::uint64_t delta = delayedFrame - entry;
        if (delta > static_cast<std::uint64_t>(INT64_MAX)) {
            return false;
        }
        fromPosition =
            clock.FrameToTick(SampleFrame{static_cast<std::int64_t>(delta)})
                .value;
    } else if (delayedFrame < entry) {
        const std::uint64_t delta = entry - delayedFrame;
        if (delta > static_cast<std::uint64_t>(INT64_MAX)) {
            return false;
        }
        fromPosition =
            clock.FrameToTick(
                     SampleFrame{-static_cast<std::int64_t>(delta)})
                .value;
    }
    const BoundaryCandidate next =
        markerIndex.NextBoundary(fromPosition, QuantizeBoundaryType(timing));
    if (!next.hasCandidate || next.frame.value < 0) {
        return false;
    }
    *outFrame = entry + static_cast<std::uint64_t>(next.frame.value);
    return true;
}

void RunPackActionQuantizeUsesPieceRowAnchor(
    ActionQuantizeTimingV1 timing, const char* stem) {
    constexpr VnObjectId kPieceSoundId = harkentest::ObjectId(4511);
    constexpr VnObjectId kQuantizedSoundId = harkentest::ObjectId(4513);
    constexpr VnObjectId kTrackId = harkentest::ObjectId(4520);
    constexpr VnObjectId kPieceId = harkentest::ObjectId(4510);
    constexpr VnObjectId kPieceActionId = harkentest::ObjectId(2002);
    constexpr VnObjectId kSoundActionId = harkentest::ObjectId(2003);
    const std::vector<std::uint8_t> packABytes = BuildMusicalPieceQuantizePack(
        22, 1, 7, kPieceActionId, kSoundActionId, kPieceId, kTrackId,
        kPieceSoundId, kQuantizedSoundId, timing,
        harkentest::MakeDC(8192, 0.25f), harkentest::MakeDC(4096, 0.50f));
    const std::vector<std::uint8_t> packBOldBytes =
        BuildContentPack(33, 1, 9, harkentest::ObjectId(3003), harkentest::ObjectId(8));
    const std::vector<std::uint8_t> packBNextBytes =
        BuildContentPack(33, 2, 10, harkentest::ObjectId(3003), harkentest::ObjectId(8), 0, 0x3f000000u);
    PackInitCatalogRow initOwned;
    initOwned.stableId = harkentest::ObjectId(1001);
    initOwned.identityClass = kInitCatalogIdentityClassAction;
    initOwned.ownerPackStableId = 11;
    FillLocator(&initOwned, "Init.pack");
    PackInitCatalogRow contentA;
    contentA.stableId = harkentest::ObjectId(kPieceActionId);
    contentA.identityClass = kInitCatalogIdentityClassAction;
    contentA.ownerPackStableId = 22;
    contentA.expectedContentHash = Fnv1a64(packABytes.data(), packABytes.size());
    FillLocator(&contentA, "ActionA.pack");
    PackInitCatalogRow quantizedAction;
    quantizedAction.stableId = harkentest::ObjectId(kSoundActionId);
    quantizedAction.identityClass = kInitCatalogIdentityClassAction;
    quantizedAction.ownerPackStableId = 22;
    quantizedAction.expectedContentHash = contentA.expectedContentHash;
    FillLocator(&quantizedAction, "ActionA.pack");
    PackInitCatalogRow contentB;
    contentB.stableId = harkentest::ObjectId(3003);
    contentB.identityClass = kInitCatalogIdentityClassAction;
    contentB.ownerPackStableId = 33;
    contentB.expectedContentHash =
        Fnv1a64(packBOldBytes.data(), packBOldBytes.size());
    FillLocator(&contentB, "ActionB.pack");
    PackInitCatalogRow playable;
    playable.stableId = harkentest::ObjectId(kPieceId);
    playable.identityClass = kInitCatalogIdentityClassPlayable;
    playable.ownerPackStableId = 22;
    playable.expectedContentHash = contentA.expectedContentHash;
    FillLocator(&playable, "ActionA.pack");
    PackInitCatalogRow quantizedPlayable;
    quantizedPlayable.stableId = harkentest::ObjectId(kQuantizedSoundId);
    quantizedPlayable.identityClass = kInitCatalogIdentityClassPlayable;
    quantizedPlayable.ownerPackStableId = 22;
    quantizedPlayable.expectedContentHash = contentA.expectedContentHash;
    FillLocator(&quantizedPlayable, "ActionA.pack");
    const std::vector<std::uint8_t> initBytes = BuildInitCatalog(
        {initOwned, contentA, quantizedAction, contentB, playable,
         quantizedPlayable},
        {22, 33});
    const std::string initPath =
        WriteTemp(std::string(stem) + "-init.pack", initBytes);
    const std::string packAPath =
        WriteTemp(std::string(stem) + "-a.pack", packABytes);
    const std::string packBOldPath =
        WriteTemp(std::string(stem) + "-b-old.pack", packBOldBytes);
    const std::string packBNextPath =
        WriteTemp(std::string(stem) + "-b-next.pack", packBNextBytes);

    EngineSession session(MakeNullConfig(8, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    VnCanonicalPackSetMemberV1 members[3]{};
    VnCanonicalPackSetMemberResultV1 rows[3]{};
    const char* paths[] = {initPath.c_str(), packAPath.c_str(),
                           packBOldPath.c_str()};
    for (std::size_t i = 0; i < 3; ++i) {
        members[i].structSize = sizeof(members[i]);
        members[i].packStableId = 11 * (i + 1);
        members[i].packKind = i == 0 ? VN_CANONICAL_PACK_SET_MEMBER_INIT
                                    : VN_CANONICAL_PACK_SET_MEMBER_CONTENT;
        members[i].utf8Path = paths[i];
        rows[i].structSize = sizeof(rows[i]);
    }
    VnCanonicalPackSetActivationReportV1 activated{};
    ASSERT_EQ(VN_OK, harkentest::ActivateCanonicalMembersV1(
                          members, 3, rows, activated));
    const VnPackHandle packB = rows[2].handle;
    ASSERT_NE(0u, rows[1].handle);
    ASSERT_NE(0u, packB);
    VnPackLoadDesc desc{};
    desc.structSize = sizeof(desc);

    VnPostActionDesc piecePost{};
    piecePost.structSize = sizeof(piecePost);
    piecePost.actionId = harkentest::ObjectId(kPieceActionId);
    VnActionFiringHandle pieceFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&piecePost, &pieceFiring));
    VnActionStepResult pieceStep{};
    pieceStep.structSize = sizeof(pieceStep);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(pieceFiring, 0, &pieceStep));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, pieceStep.state);
    ASSERT_NE(0u, pieceStep.producedPlayableInstance);
    auto startRow = std::find_if(
        session.Engine()->playableServices.begin(),
        session.Engine()->playableServices.end(),
        [&](const EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == pieceStep.producedPlayableInstance;
        });
    ASSERT_NE(session.Engine()->playableServices.end(), startRow);
    EXPECT_EQ(PlayableKindV1::Piece, startRow->root.kind);
    EXPECT_NE(0u, startRow->Invocation().packLease.leaseToken);
    ASSERT_NE(nullptr, startRow->Invocation().packPlaybackView.ResolvePiece(
                           startRow->root.stableId, 0));
    const PackPartitionLease frozenLease = startRow->Invocation().packLease;
    const std::uint64_t frozenGeneration = frozenLease.compositeGeneration;

    harkentest::Capture pieceCapture;
    bool heardPiece = false;
    for (std::uint32_t block = 0; block < 16 && !heardPiece; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        session.Engine()->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        pieceCapture.left.insert(
            pieceCapture.left.end(),
            session.Engine()->nullBackend.LastBlock(),
            session.Engine()->nullBackend.LastBlock() +
                session.Engine()->nullBackend.BlockFrames());
        startRow = std::find_if(
            session.Engine()->playableServices.begin(),
            session.Engine()->playableServices.end(),
            [&](const EnginePlayableServiceRow& candidate) {
                return candidate.rootInstance ==
                       pieceStep.producedPlayableInstance;
            });
        ASSERT_NE(session.Engine()->playableServices.end(), startRow);
        if (session.Engine()->voices.ActiveCount() >= 1u &&
            harkentest::Peak(pieceCapture.left) > harkentest::kSilenceFloor) {
            heardPiece = true;
        }
    }
    EXPECT_TRUE(heardPiece);
    HARKENTEST_ASSERT_NON_SILENT(pieceCapture.left);

    desc.utf8Path = packBNextPath.c_str();
    ASSERT_EQ(VN_OK,
              Vn_ReplacePack(packB, reinterpret_cast<const VnPackDesc*>(&desc)));
    EXPECT_EQ(VN_OK, session.Engine()->packComposition.ValidateLease(frozenLease));
    startRow = std::find_if(
        session.Engine()->playableServices.begin(),
        session.Engine()->playableServices.end(),
        [&](const EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == pieceStep.producedPlayableInstance;
        });
    ASSERT_NE(session.Engine()->playableServices.end(), startRow);
    EXPECT_NE(0u, startRow->Invocation().packLease.leaseToken);
    EXPECT_EQ(frozenGeneration, startRow->Invocation().packLease.compositeGeneration);
    ASSERT_NE(nullptr, startRow->Invocation().packPlaybackView.ResolvePiece(
                           startRow->root.stableId, 0));
    const PlayableWorldViewV1 currentWorld =
        session.Engine()->variables.CurrentPlayableWorld();
    bool currentHasPiece = false;
    for (std::uint32_t index = 0; index < currentWorld.pieceScheduleCount;
         ++index) {
        if (currentWorld.pieceSchedules[index].rootDefinition.stableId ==
            kPieceId) {
            currentHasPiece = true;
        }
    }
    EXPECT_FALSE(currentHasPiece);

    const std::uint64_t delayedFrame =
        ImmediateQuantizeBaseFrame(*session.Engine());
    std::uint64_t expected = 0;
    ASSERT_TRUE(ExpectedFrozenQuantizeFrame(
        *startRow, delayedFrame, timing,
        session.Engine()->config.mixRate.SampleRate(), &expected));

    VnPostActionDesc soundPost{};
    soundPost.structSize = sizeof(soundPost);
    soundPost.actionId = harkentest::ObjectId(kSoundActionId);
    VnActionFiringHandle soundFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&soundPost, &soundFiring));
    startRow = std::find_if(
        session.Engine()->playableServices.begin(),
        session.Engine()->playableServices.end(),
        [&](const EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == pieceStep.producedPlayableInstance;
        });
    ASSERT_NE(session.Engine()->playableServices.end(), startRow);
    EXPECT_EQ(frozenGeneration, startRow->Invocation().packLease.compositeGeneration);
    EXPECT_EQ(pieceStep.producedPlayableInstance, startRow->rootInstance);

    if (expected >= session.Engine()->timelinePool.WindowEndFrame()) {
        EXPECT_GE(session.Engine()->actionDeferredRecords.LiveCount(), 1u);
        ActionDeferredRecordToken token{};
        ActionDeferredRecord record{};
        ActionDeferredRecordState state = ActionDeferredRecordState::Free;
        ASSERT_TRUE(session.Engine()->actionDeferredRecords.CaptureAt(
            0, &token, &record, &state));
        EXPECT_EQ(expected, record.intendedBoundaryFrame);
    } else {
        std::uint64_t soundStart = 0;
        for (const auto& row : session.Engine()->playableServices) {
            if (row.phase != EnginePlayableStartPhase::Free &&
                row.Invocation().actionFiring == soundFiring) {
                soundStart = row.startFrame;
                break;
            }
        }
        EXPECT_EQ(expected, soundStart);
        VnActionStepResult soundStep{};
        soundStep.structSize = sizeof(soundStep);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(soundFiring, 0, &soundStep));
        EXPECT_EQ(VN_ACTION_STEP_ACTIVE, soundStep.state);
        EXPECT_NE(0u, soundStep.producedPlayableInstance);
    }

    harkentest::Capture afterCapture;
    bool heardAfter = false;
    for (std::uint32_t block = 0; block < 32 && !heardAfter; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        session.Engine()->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        afterCapture.left.insert(
            afterCapture.left.end(),
            session.Engine()->nullBackend.LastBlock(),
            session.Engine()->nullBackend.LastBlock() +
                session.Engine()->nullBackend.BlockFrames());
        startRow = std::find_if(
            session.Engine()->playableServices.begin(),
            session.Engine()->playableServices.end(),
            [&](const EnginePlayableServiceRow& candidate) {
                return candidate.rootInstance ==
                       pieceStep.producedPlayableInstance;
            });
        ASSERT_NE(session.Engine()->playableServices.end(), startRow);
        EXPECT_EQ(frozenGeneration, startRow->Invocation().packLease.compositeGeneration);
        if (harkentest::Peak(afterCapture.left) > harkentest::kSilenceFloor) {
            heardAfter = true;
        }
    }
    EXPECT_TRUE(heardAfter);
    HARKENTEST_ASSERT_NON_SILENT(afterCapture.left);
    EXPECT_EQ(VN_IN_USE, Vn_ReleaseActionFiring(soundFiring));
    EXPECT_EQ(VN_IN_USE, Vn_ReleaseActionFiring(pieceFiring));
}

std::vector<std::uint8_t> ImmediateEmptyTrackPlayPartitionPayload(
    std::uint64_t packStableId, std::uint64_t partitionRevision,
    VnObjectId actionId, VnObjectId trackId) {
    PlayablePropertyProgramViewV1 trackProperty{};
    trackProperty.contentPropertyKind =
        playableproperties::ContentPropertyKindV1::Track;
    trackProperty.stableId = harkentest::ObjectId(trackId);
    trackProperty.authoredStableOrder = 1;
    trackProperty.contentRevision = 1;
    trackProperty.routeStableId = VN_BUS_MASTER;
    trackProperty.compatibilityFingerprint = 1;
    trackProperty.payload = DelayedPlayPayload();
    trackProperty.programSemanticFingerprint =
        ComputePlayablePropertyFingerprintV1(trackProperty);
    TrackScheduleProgramViewV1 schedule{};
    schedule.rootDefinition = PlayableRefFromProperty(trackProperty);
    schedule.scheduleSemanticFingerprint =
        ComputeTrackScheduleFingerprintV1(schedule);

    ActionStepProgramViewV1 step{};
    step.opcode = ActionOpcodeV1::Play;
    step.target.kind = ActionTargetKindV1::Track;
    step.target.stableId = harkentest::ObjectId(trackId);
    step.target.expectedProgramSemanticFingerprint =
        trackProperty.programSemanticFingerprint;
    SetAbsoluteTime(&step.delay, 0);
    SetAbsoluteTime(&step.fade, 0);
    SetAbsoluteTime(&step.cooldown, 0);
    ActionProgramViewV1 action{};
    action.actionStableId = actionId;
    action.steps = &step;
    action.stepCount = 1;
    action.directFeatureMask = 0;
    action.transitiveFeatureMask = 0;
    action.expandedStepOccurrenceCount = 1;
    action.expandedFiringCount = 1;
    action.programSemanticFingerprint = ComputeActionProgramFingerprintV1(action);

    ContainerWorldInstallViewV1 world{};
    world.identity.capabilityMask = kWorldCapabilityActionDefinitions |
                                    kWorldCapabilityPlayableProperties;
    world.playableProperties = &trackProperty;
    world.playablePropertyCount = 1;
    world.trackSchedules = &schedule;
    world.trackScheduleCount = 1;
    world.actions = &action;
    world.actionCount = 1;
    world.capacity.maxKnownScheduleLeaves = 16;
    world.capacity.maxTrackPieceScheduleDepth = 8;
    world.identity.runtimeSemanticFingerprint =
        ComputeCurrentWorldFingerprintV4(world);
    return WrapWorldPartition(packStableId, partitionRevision, world, 2);
}

std::vector<std::uint8_t> BuildImmediateEmptyTrackPlayPack(
    std::uint64_t packStableId, std::uint64_t contentRevision,
    std::uint64_t partitionRevision, VnObjectId actionId,
    VnObjectId trackId) {
    ImageBuilder builder(kPackKindCanonicalContent);
    builder.AddEntry(kPackEntryKindPackRequirementBlock, packStableId,
                     RequirementPayload(packStableId, contentRevision,
                                        partitionRevision));
    builder.AddEntry(kPackEntryKindCanonicalDefinitionPartition, packStableId,
                     ImmediateEmptyTrackPlayPartitionPayload(
                         packStableId, partitionRevision, actionId, trackId));
    return builder.Build();
}

bool DirectoryHasKind(const std::vector<std::uint8_t>& bytes,
                      std::uint32_t kind) {
    PackV2Header header;
    if (!ParsePackV2Header(bytes.data(), &header)) {
        return false;
    }
    for (std::uint32_t i = 0; i < header.entryCount; ++i) {
        const PackV2DirectoryEntry entry = ParsePackV2DirectoryEntry(
            bytes.data() + static_cast<std::size_t>(header.directoryOffset) +
            i * kPackV2DirectoryEntryBytes);
        if (entry.kind == kind) {
            return true;
        }
    }
    return false;
}

void ExpectCurrentProgramChapter(const std::vector<std::uint8_t>& bytes) {
    PackCanonicalImage image;
    ASSERT_EQ(VN_OK,
              ParsePackCanonicalImage(bytes.data(), bytes.size(), &image));
    ASSERT_TRUE(image.hasPartition);
    EXPECT_EQ(kCanonicalDefinitionPartitionBodyVintage,
              image.partitionHeader.bodyVintage);
    EXPECT_FALSE(DirectoryHasKind(bytes, kPackEntryKindContainer));
    EXPECT_FALSE(DirectoryHasKind(bytes, kPackEntryKindVoiceRecipe));
}

