TEST(PackComposition, PackActionBadFingerprintStaysBadPack) {
    constexpr VnObjectId kSoundId = harkentest::ObjectId(4511);
    constexpr VnObjectId kContainerId = harkentest::ObjectId(4510);
    constexpr VnObjectId kActionId = harkentest::ObjectId(2002);
    const std::vector<std::uint8_t> packBytes = BuildImmediateContainerPlayPack(
        22, 1, 7, kActionId, kContainerId, kSoundId,
        harkentest::MakeDC(2048, 0.25f), true);
    PackCanonicalImage parsedPack;
    EXPECT_EQ(VN_BAD_PACK,
              ParsePackCanonicalImage(packBytes.data(), packBytes.size(),
                                      &parsedPack));
    const std::vector<std::uint8_t> initBytes = BuildSingleIdentityInit(
        Fnv1a64(packBytes.data(), packBytes.size()), kActionId);
    const std::string initPath =
        WriteTemp("f5-bad-fingerprint-init.pack", initBytes);
    const std::string packPath =
        WriteTemp("f5-bad-fingerprint-a.pack", packBytes);

    EngineSession session(MakeNullConfig(8, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    VnCanonicalPackSetMemberV1 members[2]{};
    VnCanonicalPackSetMemberResultV1 rows[2]{};
    const char* paths[] = {initPath.c_str(), packPath.c_str()};
    for (std::size_t i = 0; i < 2; ++i) {
        members[i].structSize = sizeof(members[i]);
        members[i].packStableId = i == 0 ? 11 : 22;
        members[i].packKind = i == 0 ? VN_CANONICAL_PACK_SET_MEMBER_INIT
                                    : VN_CANONICAL_PACK_SET_MEMBER_CONTENT;
        members[i].utf8Path = paths[i];
        rows[i].structSize = sizeof(rows[i]);
    }
    VnCanonicalPackSetActivationReportV1 initial{};
    ASSERT_EQ(VN_OK, harkentest::ActivateCanonicalMembersV1(
                          members, 1, rows, initial));
    const std::uint64_t generationBefore =
        session.Engine()->packComposition.CompositeGeneration();
    const auto published = session.Engine()->packComposition.PublishedHandle();
    members[0].expectedHandle = initial.initHandle;
    VnCanonicalPackSetActivationReportV1 refused{};
    EXPECT_EQ(VN_BAD_PACK, harkentest::ActivateCanonicalMembersV1(
                               members, 2, rows, refused, initial.initHandle,
                               initial.resultSetRevision));
    EXPECT_EQ(0u, rows[1].handle);
    EXPECT_EQ(published.get(), session.Engine()->packComposition.Published());
    EXPECT_EQ(generationBefore,
              session.Engine()->packComposition.CompositeGeneration());
    EXPECT_EQ(0u, session.Engine()->voices.ActiveCount());
}

enum class DelayedPackPlayTarget {
    Sound,
    SequenceQueue,
    VariableControl,
};

struct DelayedPackPlayFixture {
    EngineSession session;
    VnPackHandle pack = 0;
    VnActionFiringHandle firing = 0;
    VnEmitterHandle emitter = 0;
    ActionDeferredRecordToken token{};
    ActionDeferredRecord record{};
    ActionDeferredRecordState state = ActionDeferredRecordState::Free;
    std::uint64_t leaseToken = 0;
    std::uint64_t packStableId = 0;
    VnObjectId targetStableId = harkentest::ObjectId(4510);
    std::uint64_t partitionRevision = 0;
    std::uint64_t resourceRevision = 0;

    explicit DelayedPackPlayFixture(VnConfig config, const char* label,
                                    std::int64_t delayNanoseconds = 1000000000,
                                    DelayedPackPlayTarget target =
                                        DelayedPackPlayTarget::Sound,
                                    bool postImmediately = true)
        : session(config) {
        constexpr VnObjectId kSoundId = harkentest::ObjectId(4510);
        constexpr VnObjectId kFirstSoundId = harkentest::ObjectId(4511);
        constexpr VnObjectId kSecondSoundId = harkentest::ObjectId(4512);
        constexpr VnObjectId kActionId = harkentest::ObjectId(2002);
        EXPECT_EQ(VN_OK, session.InitResult());
        if (session.InitResult() != VN_OK) return;
        if (delayNanoseconds < 0) {
            const std::uint64_t sampleRate =
                session.Engine()->config.mixRate.SampleRate();
            delayNanoseconds = static_cast<std::int64_t>(
                (session.Engine()->timelinePool.WindowEndFrame() *
                 1000000000ull) /
                sampleRate) +
                10000000;
        }
        const std::vector<std::uint8_t> packBytes = [&] {
            if (target == DelayedPackPlayTarget::SequenceQueue)
                return BuildImmediateSequenceQueuePlayPack(
                    22, 1, 7, kActionId, kSoundId, kFirstSoundId,
                    kSecondSoundId, harkentest::MakeDC(2048, 0.25f),
                    harkentest::MakeDC(2048, -0.25f), 1,
                    MemoryScopeV1::Global, delayNanoseconds);
            if (target == DelayedPackPlayTarget::VariableControl)
                return BuildImmediateVariableControlDiscretePlayPack(
                    22, 1, 7, kActionId, kSoundId, kFirstSoundId,
                    kSecondSoundId, harkentest::MakeDC(2048, 0.25f),
                    harkentest::MakeDC(2048, -0.25f), false,
                    delayNanoseconds);
            return BuildDelayedPlayPack(
                22, 1, 7, kActionId, kSoundId,
                harkentest::MakeDC(2048, 0.25f), delayNanoseconds);
        }();
        const std::vector<std::uint8_t> initBytes = BuildSingleIdentityInit(
            Fnv1a64(packBytes.data(), packBytes.size()), kActionId);
        const std::string initPath =
            WriteTemp((std::string(label) + "-init.pack").c_str(), initBytes);
        const std::string packPath =
            WriteTemp((std::string(label) + "-a.pack").c_str(), packBytes);
        VnCanonicalPackSetMemberV1 members[2]{};
        VnCanonicalPackSetMemberResultV1 rows[2]{};
        const char* paths[] = {initPath.c_str(), packPath.c_str()};
        for (std::size_t i = 0; i < 2; ++i) {
            members[i].structSize = sizeof(members[i]);
            members[i].packStableId = i == 0 ? 11 : 22;
            members[i].packKind = i == 0 ? VN_CANONICAL_PACK_SET_MEMBER_INIT
                                        : VN_CANONICAL_PACK_SET_MEMBER_CONTENT;
            members[i].utf8Path = paths[i];
            rows[i].structSize = sizeof(rows[i]);
        }
        VnCanonicalPackSetActivationReportV1 activated{};
        EXPECT_EQ(VN_OK, harkentest::ActivateCanonicalMembersV1(
                              members, 2, rows, activated));
        pack = rows[1].handle;
        EXPECT_NE(0u, pack);
        VnPostActionDesc post{};
        post.structSize = sizeof(post);
        post.actionId = harkentest::ObjectId(kActionId);
        if (target != DelayedPackPlayTarget::Sound) {
            EXPECT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
            post.emitter = emitter;
            std::cerr << "delayed generic input emitter=" << emitter
                      << " target=" << static_cast<unsigned>(target) << '\n';
        }
        if (postImmediately) {
            EXPECT_EQ(VN_OK, Vn_PostAction(&post, &firing));
            EXPECT_EQ(1u, session.Engine()->actionDeferredRecords.LiveCount());
            EXPECT_TRUE(session.Engine()->actionDeferredRecords.CaptureAt(
                0, &token, &record, &state));
            leaseToken = record.targetPackLease.leaseToken;
            packStableId = record.targetPackLease.packStableId;
            targetStableId = record.step.target.stableId;
            partitionRevision = record.targetPackLease.partitionRevision;
            resourceRevision = record.targetPackLease.resourceRevision;
            EXPECT_NE(0u, leaseToken);
            const auto* original = session.Engine()->OriginalDeferredPackLease(token);
            EXPECT_NE(nullptr, original);
            if (original != nullptr) {
                EXPECT_TRUE(original->Valid());
                EXPECT_EQ(leaseToken, original->OriginalLease().leaseToken);
            }
        }
    }

    void PumpUntilDeferredGone(std::uint32_t steps = 1024) {
        for (std::uint32_t step = 0;
             step < steps &&
             session.Engine()->actionDeferredRecords.LiveCount() != 0;
             ++step) {
            ASSERT_EQ(VN_OK, Vn_Update());
            session.Engine()->nullBackend.Pump(1);
        }
        ASSERT_EQ(VN_OK, Vn_Update());
        EXPECT_EQ(0u, session.Engine()->actionDeferredRecords.LiveCount());
    }

    void PumpUntilFiringTerminal() {
        ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
        for (std::uint32_t step = 0; step < 64; ++step) {
            VnActionFiringInfo info{};
            info.structSize = sizeof(info);
            ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
            if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) {
                break;
            }
            ASSERT_EQ(VN_OK, Vn_Update());
            session.Engine()->nullBackend.Pump(1);
        }
        VnActionFiringInfo info{};
        info.structSize = sizeof(info);
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
        ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
        firing = 0;
    }

    const EnginePlayableServiceRow* LiveStartRow() const {
        for (const auto& row : session.Engine()->playableServices) {
            if (row.phase != EnginePlayableStartPhase::Free &&
                row.rootInstance != 0) {
                return &row;
            }
        }
        return nullptr;
    }
};

static void CheckOriginalDeferredPlayForeignStorageLifetime(
    DelayedPackPlayTarget target, const char* label) {
    DelayedPackPlayFixture fixture(MakeNullConfig(8, 256, 48000), label,
                                   1000000000, target);
    auto& engine = *fixture.session.Engine();
    const auto* held = engine.OriginalDeferredPackLease(fixture.token);
    ASSERT_NE(nullptr, held);
    ASSERT_TRUE(held->Valid());
    EXPECT_EQ(fixture.leaseToken, held->OriginalLease().leaseToken);
    EXPECT_TRUE(engine.packComposition.HasOriginalLeaseEpisode(fixture.record.targetPackLease));
    struct Retention {
        Engine::OriginalPlayableServiceLifetimePin foreign;
        EnginePlayableServiceReference service{};
        const Engine::OriginalPlayableServiceLifetimeHolder* original = nullptr;
        EnginePlayableStartRow* invocation = nullptr;
        EngineActionPlayStorage* storage = nullptr;
        ActionDeferredRecordToken record{};
        PackPartitionLease lease{};
        unsigned reserves = 0;
    } retention;
    retention.record = fixture.token;
    retention.lease = fixture.record.targetPackLease;
    engine.originalPlayableServiceReservedContextForTest = &retention;
    engine.originalPlayableServiceReservedHookForTest = [](
        Engine& actual, const Engine::OriginalPlayableServiceLifetimeHolder& original, void* context) {
        auto& out = *static_cast<Retention*>(context);
        auto* service = detail::EngineOriginalServiceStorageTestAccess::ActualService(original);
        ASSERT_NE(nullptr, service);
        if (service->Invocation().rootService != service->identity || out.foreign.Valid()) return;
        out.original = &original;
        EXPECT_EQ(Engine::OriginalPlayableServicePackDuty::OriginalDeferredRecordOwns, original.OriginalPackDuty());
        ASSERT_TRUE(actual.MatchesOriginalPlayableServicePackDuty(original));
        EXPECT_EQ(out.lease.leaseToken, original.OriginalPackDutyLease().leaseToken);
        EXPECT_EQ(out.lease.resourceClosureToken, original.OriginalPackDutyLease().resourceClosureToken);
        ASSERT_NE(nullptr, service->Invocation().preparingStorage);
        out.storage = service->Invocation().preparingStorage;
        EXPECT_EQ(out.record.slot, out.storage->originalDeferredPackRecord.slot);
        EXPECT_EQ(out.record.generation, out.storage->originalDeferredPackRecord.generation);
        EXPECT_FALSE(out.storage->originalPackLease.Valid());
        EXPECT_FALSE(service->Invocation().originalPackLease.Valid());
        const auto* issued = actual.OriginalDeferredPackLease(out.record);
        ASSERT_NE(nullptr, issued);
        ASSERT_TRUE(issued->Valid());
        EXPECT_EQ(out.lease.leaseToken, issued->OriginalLease().leaseToken);
        ASSERT_TRUE(original.Borrow(&out.foreign));
        EXPECT_EQ(original.FactoryReference().token, out.foreign.FactoryReference().token);
        EXPECT_FALSE(original.Borrow(&out.foreign));
        out.service = original.FactoryReference();
        out.invocation = &service->Invocation();
        EXPECT_EQ(VN_IN_USE, actual.ReleasePackIdentityLease(out.lease));
        ++out.reserves;
    };
    fixture.PumpUntilDeferredGone();
    engine.originalPlayableServiceReservedHookForTest = nullptr;
    engine.originalPlayableServiceReservedContextForTest = nullptr;
    ASSERT_EQ(1u, retention.reserves);
    ASSERT_TRUE(retention.foreign.Valid());
    ASSERT_NE(nullptr, retention.invocation);
    EXPECT_EQ(nullptr, engine.OriginalDeferredPackLease(fixture.token));
    ASSERT_TRUE(retention.invocation->originalPackLease.Valid());
    ASSERT_NE(nullptr, retention.original);
    EXPECT_EQ(Engine::OriginalPlayableServicePackDuty::OriginalInvocationOwns, retention.original->OriginalPackDuty());
    ASSERT_TRUE(engine.MatchesOriginalPlayableServicePackDuty(*retention.original));
    const auto actualAlias = retention.invocation->packLease;
    retention.invocation->packLease.resourceRevision ^= 1u;
    EXPECT_FALSE(engine.MatchesOriginalPlayableServicePackDuty(*retention.original));
    retention.invocation->packLease = actualAlias;
    ASSERT_TRUE(engine.MatchesOriginalPlayableServicePackDuty(*retention.original));
    EXPECT_EQ(fixture.leaseToken, retention.invocation->originalPackLease.OriginalLease().leaseToken);
    EXPECT_EQ(retention.service.invocationGeneration, retention.invocation->generation);
    EXPECT_FALSE(retention.storage->originalPackLease.Valid());
    EXPECT_FALSE(retention.storage->originalDeferredPackRecord.Valid());
    EXPECT_EQ(0u, engine.actionFirings.OwnedDeferredCount(fixture.firing));
    const auto blockFrames = engine.nullBackend.BlockFrames();
    const auto channels = engine.nullBackend.Channels();
    ASSERT_NE(0u, blockFrames);
    ASSERT_NE(0u, channels);
    std::uint64_t firstAudibleFrame = UINT64_MAX;
    for (unsigned block = 0; block < 1024 &&
         engine.mixer.BlocksRendered() * blockFrames < fixture.record.intendedBoundaryFrame + 2048; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        const auto blockStart = engine.mixer.BlocksRendered() * blockFrames;
        engine.nullBackend.Pump(1);
        ASSERT_EQ(blockStart + blockFrames, engine.mixer.BlocksRendered() * blockFrames);
        const auto* pcm = engine.nullBackend.LastBlock();
        ASSERT_NE(nullptr, pcm);
        for (std::uint64_t frame = 0; frame < blockFrames; ++frame) {
            if (std::abs(pcm[frame * channels]) > 0.01f && firstAudibleFrame == UINT64_MAX)
                firstAudibleFrame = blockStart + frame;
            if (blockStart + frame < fixture.record.intendedBoundaryFrame)
                EXPECT_NEAR(0.0f, pcm[frame * channels], 1e-4f);
        }
    }
    EXPECT_EQ(fixture.record.intendedBoundaryFrame, firstAudibleFrame);
    ASSERT_EQ(VN_OK, Vn_StopActionFiring(fixture.firing, 0));
    for (unsigned block = 0; block < 32; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine.nullBackend.Pump(1);
    }
    EXPECT_EQ(0u, engine.voices.ActiveCount());
    ASSERT_TRUE(retention.foreign.Valid());
    ASSERT_TRUE(engine.MatchesOriginalPlayableServicePackDuty(*retention.original));
    ASSERT_TRUE(retention.invocation->originalPackLease.Valid());
    EXPECT_EQ(retention.service.invocationGeneration, retention.invocation->generation);
    EXPECT_EQ(VN_IN_USE, engine.ReleaseOriginalPackIdentityLease(retention.invocation->originalPackLease));
    EXPECT_EQ(VN_OK, engine.packComposition.ValidateLease(retention.lease));
    EXPECT_EQ(VN_OK, engine.packs.ValidateResourceClosure(retention.lease.resourceClosureToken));
    EXPECT_TRUE(engine.packComposition.HasOriginalLeaseEpisode(retention.lease));
    EXPECT_FALSE(engine.runtimeRecreateRequired);
    retention.foreign.Return();
    for (unsigned block = 0; block < 96 && engine.packComposition.HasOriginalLeaseEpisode(retention.lease); ++block) {
        engine.nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_FALSE(engine.packComposition.HasOriginalLeaseEpisode(retention.lease));
    EXPECT_NE(VN_OK, engine.packComposition.ValidateLease(retention.lease));
    EXPECT_NE(VN_OK, engine.packs.ValidateResourceClosure(retention.lease.resourceClosureToken));
    EXPECT_FALSE(retention.invocation->originalPackLease.Valid());
    EXPECT_FALSE(engine.MatchesOriginalPlayableServicePackDuty(*retention.original));
    EXPECT_EQ(Engine::OriginalPlayableServicePackDuty::Unbound, retention.original->OriginalPackDuty());
    EXPECT_FALSE(engine.runtimeRecreateRequired);
    fixture.PumpUntilFiringTerminal();
}

