TEST(PackComposition, OriginalDeferredPlayPrecommitFailureRetainsRecordUntilForeignStorageReturns) {
    DelayedPackPlayFixture fixture(MakeNullConfig(8, 256, 48000), "original-deferred-precommit-foreign");
    auto& engine = *fixture.session.Engine();
    EnginePlayablePartitionPool::OriginalStoragePin foreign;
    engine.originalPlayableServiceReservedContextForTest = &foreign;
    engine.originalPlayableServiceReservedHookForTest = [](
        Engine& actual, const Engine::OriginalPlayableServiceLifetimeHolder& original, void* context) {
        auto& pin = *static_cast<EnginePlayablePartitionPool::OriginalStoragePin*>(context);
        auto* row = detail::EngineOriginalServiceStorageTestAccess::ActualService(original);
        ASSERT_NE(nullptr, row);
        if (row->Invocation().rootService != row->identity || pin.Valid()) return;
        ASSERT_TRUE(detail::EngineOriginalServiceStorageTestAccess::BorrowAtReserve(actual, original, &pin));
    };
    engine.forceActionPlayCommitFailureForTest = true;
    for (unsigned block = 0; block < 1024 && engine.forceActionPlayCommitFailureForTest; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine.nullBackend.Pump(1);
    }
    engine.originalPlayableServiceReservedHookForTest = nullptr;
    engine.originalPlayableServiceReservedContextForTest = nullptr;
    ASSERT_FALSE(engine.forceActionPlayCommitFailureForTest);
    ASSERT_TRUE(foreign.Valid());
    ASSERT_TRUE(engine.runtimeRecreateRequired);
    ASSERT_NE(nullptr, engine.OriginalDeferredPackLease(fixture.token));
    EXPECT_TRUE(engine.OriginalDeferredPackLease(fixture.token)->Valid());
    EXPECT_EQ(fixture.leaseToken, engine.OriginalDeferredPackLease(fixture.token)->OriginalLease().leaseToken);
    for (unsigned block = 0; block < 32; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine.nullBackend.Pump(1);
    }
    EXPECT_EQ(0u, engine.voices.ActiveCount());
    EXPECT_EQ(1u, engine.actionDeferredRecords.LiveCount());
    EXPECT_EQ(1u, engine.actionFirings.OwnedDeferredCount(fixture.firing));
    EXPECT_EQ(VN_OK, engine.packComposition.ValidateLease(fixture.record.targetPackLease));
    EXPECT_EQ(VN_OK, engine.packs.ValidateResourceClosure(fixture.record.targetPackLease.resourceClosureToken));
    EXPECT_EQ(VN_IN_USE, engine.ReleaseOriginalDeferredPack(fixture.token, fixture.record.targetPackLease));
    EXPECT_TRUE(foreign.Valid());
    foreign.Return();
    for (unsigned block = 0; block < 96 && engine.actionDeferredRecords.LiveCount() != 0; ++block) {
        engine.nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_EQ(0u, engine.actionDeferredRecords.LiveCount());
    EXPECT_EQ(0u, engine.actionFirings.OwnedDeferredCount(fixture.firing));
    EXPECT_EQ(nullptr, engine.OriginalDeferredPackLease(fixture.token));
    EXPECT_FALSE(engine.packComposition.HasOriginalLeaseEpisode(fixture.record.targetPackLease));
    EXPECT_NE(VN_OK, engine.packs.ValidateResourceClosure(fixture.record.targetPackLease.resourceClosureToken));
    EXPECT_TRUE(engine.runtimeRecreateRequired);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(fixture.firing));
    fixture.firing = 0;
}

TEST(PackComposition, OriginalDeferredPlayCapacityDeadlineRetainsActualClaimWithoutRuntimeFault) {
    DelayedPackPlayFixture fixture(MakeNullConfig(8, 256, 48000), "original-deferred-capacity-foreign-deadline");
    auto& engine = *fixture.session.Engine();
    std::vector<PackPartitionLease> occupying;
    for (;;) {
        PackIdentityLookup lookup{};
        const auto result = engine.AcquirePackIdentityLease(fixture.targetStableId,
            PackLeaseSlice::Playable, &lookup);
        if (result == VN_BACKPRESSURE) break;
        ASSERT_EQ(VN_OK, result);
        occupying.push_back(lookup.lease);
    }
    ASSERT_FALSE(occupying.empty());
    EnginePlayablePartitionPool::OriginalStoragePin foreign;
    engine.originalPlayableServiceReservedContextForTest = &foreign;
    engine.originalPlayableServiceReservedHookForTest = [](
        Engine& actual, const Engine::OriginalPlayableServiceLifetimeHolder& original, void* context) {
        auto& pin = *static_cast<EnginePlayablePartitionPool::OriginalStoragePin*>(context);
        auto* row = detail::EngineOriginalServiceStorageTestAccess::ActualService(original);
        ASSERT_NE(nullptr, row);
        if (row->Invocation().rootService != row->identity || pin.Valid()) return;
        ASSERT_TRUE(detail::EngineOriginalServiceStorageTestAccess::BorrowAtReserve(actual, original, &pin));
    };
    const auto retagRefusals = engine.packComposition.RetagBackpressureCountForTests();
    const auto blockFrames = engine.nullBackend.BlockFrames();
    const auto channels = engine.nullBackend.Channels();
    ASSERT_NE(0u, blockFrames);
    ASSERT_NE(0u, channels);
    bool heard = false;
    for (unsigned block = 0; block < 1024 &&
         engine.mixer.BlocksRendered() * blockFrames <= fixture.record.intendedBoundaryFrame + blockFrames * 8; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        const auto before = engine.mixer.BlocksRendered();
        engine.nullBackend.Pump(1);
        ASSERT_EQ(before + 1, engine.mixer.BlocksRendered());
        heard = heard || harkentest::Peak(engine.nullBackend.LastBlock(), blockFrames * channels) > 0.01f;
    }
    engine.originalPlayableServiceReservedHookForTest = nullptr;
    engine.originalPlayableServiceReservedContextForTest = nullptr;
    ASSERT_TRUE(foreign.Valid());
    EXPECT_GT(engine.packComposition.RetagBackpressureCountForTests(), retagRefusals);
    EXPECT_GT(engine.mixer.BlocksRendered() * blockFrames, fixture.record.intendedBoundaryFrame);
    EXPECT_FALSE(heard);
    EXPECT_EQ(0u, engine.voices.ActiveCount());
    EXPECT_FALSE(engine.runtimeRecreateRequired);
    EXPECT_FALSE(engine.hasDeferredPairFault);
    EXPECT_EQ(ActionDeferredRecordState::Claimed, engine.actionDeferredRecords.State(fixture.token));
    EXPECT_EQ(1u, engine.actionDeferredRecords.LiveCount());
    EXPECT_EQ(1u, engine.actionFirings.OwnedDeferredCount(fixture.firing));
    ASSERT_NE(nullptr, engine.OriginalDeferredPackLease(fixture.token));
    EXPECT_EQ(fixture.leaseToken, engine.OriginalDeferredPackLease(fixture.token)->OriginalLease().leaseToken);
    EXPECT_EQ(PackComposition::OriginalLeasePhase::Live, engine.OriginalDeferredPackLease(fixture.token)->Phase());
    EXPECT_EQ(VN_OK, engine.packComposition.ValidateLease(fixture.record.targetPackLease));
    EXPECT_EQ(VN_OK, engine.packs.ValidateResourceClosure(fixture.record.targetPackLease.resourceClosureToken));
    EXPECT_EQ(VN_IN_USE, engine.ReleaseOriginalDeferredPack(fixture.token, fixture.record.targetPackLease));
    foreign.Return();
    for (const auto& lease : occupying) EXPECT_EQ(VN_OK, engine.ReleasePackIdentityLease(lease));
    for (unsigned block = 0; block < 96 && engine.actionDeferredRecords.LiveCount() != 0; ++block) {
        engine.nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_EQ(0u, engine.actionDeferredRecords.LiveCount());
    EXPECT_EQ(0u, engine.timelineDeferred.Count());
    EXPECT_EQ(0u, engine.actionFirings.OwnedDeferredCount(fixture.firing));
    EXPECT_EQ(nullptr, engine.OriginalDeferredPackLease(fixture.token));
    EXPECT_FALSE(engine.packComposition.HasOriginalLeaseEpisode(fixture.record.targetPackLease));
    EXPECT_NE(VN_OK, engine.packs.ValidateResourceClosure(fixture.record.targetPackLease.resourceClosureToken));
    VnActionStepResult step{};
    step.structSize = sizeof(step);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(fixture.firing, 0, &step));
    EXPECT_EQ(VN_ACTION_STEP_FAILED, step.state);
    EXPECT_EQ(VN_BACKPRESSURE, step.result);
    EXPECT_FALSE(engine.runtimeRecreateRequired);
    EXPECT_FALSE(engine.hasDeferredPairFault);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(fixture.firing));
    fixture.firing = 0;
}

TEST(PackComposition, OriginalDeferredPlayHeldCancelReturnsNativeLeaseBeforeRecordReuse) {
    DelayedPackPlayFixture fixture(MakeNullConfig(8, 256, 48000), "original-deferred-held-cancel");
    auto& engine = *fixture.session.Engine();
    const auto first = fixture.token;
    const auto firstLease = fixture.record.targetPackLease;
    ASSERT_NE(nullptr, engine.OriginalDeferredPackLease(first));
    EXPECT_EQ(VN_IN_USE, engine.ReleasePackIdentityLease(firstLease));
    fixture.PumpUntilFiringTerminal();
    EXPECT_EQ(0u, engine.actionDeferredRecords.LiveCount());
    EXPECT_EQ(nullptr, engine.OriginalDeferredPackLease(first));
    EXPECT_FALSE(engine.packComposition.HasOriginalLeaseEpisode(firstLease));
    EXPECT_NE(VN_OK, engine.packComposition.ValidateLease(firstLease));
    EXPECT_NE(VN_OK, engine.packs.ValidateResourceClosure(firstLease.resourceClosureToken));
    EXPECT_FALSE(engine.runtimeRecreateRequired);
    VnPostActionDesc post{};
    post.structSize = sizeof(post);
    post.actionId = harkentest::ObjectId(2002);
    ASSERT_EQ(VN_OK, Vn_PostAction(&post, &fixture.firing));
    ActionDeferredRecordToken second{};
    ActionDeferredRecord record{};
    ActionDeferredRecordState state = ActionDeferredRecordState::Free;
    ASSERT_TRUE(engine.actionDeferredRecords.CaptureAt(first.slot, &second, &record, &state));
    EXPECT_EQ(first.slot, second.slot);
    EXPECT_GT(second.generation, first.generation);
    EXPECT_EQ(ActionDeferredRecordState::Held, state);
    ASSERT_NE(nullptr, engine.OriginalDeferredPackLease(second));
    EXPECT_EQ(nullptr, engine.OriginalDeferredPackLease(first));
    EXPECT_NE(firstLease.leaseToken, record.targetPackLease.leaseToken);
    EXPECT_EQ(record.targetPackLease.leaseToken, engine.OriginalDeferredPackLease(second)->OriginalLease().leaseToken);
    fixture.PumpUntilFiringTerminal();
    EXPECT_EQ(0u, engine.actionDeferredRecords.LiveCount());
    EXPECT_FALSE(engine.packComposition.HasOriginalLeaseEpisode(record.targetPackLease));
    EXPECT_FALSE(engine.runtimeRecreateRequired);
}

TEST(PackComposition, OriginalDeferredPlayHeldCancelFaultRetainsActualOwnerUntilJoinedTerm) {
    DelayedPackPlayFixture fixture(MakeNullConfig(8, 256, 48000), "original-deferred-held-cancel-fault");
    auto& engine = *fixture.session.Engine();
    const auto token = fixture.token;
    const auto lease = fixture.record.targetPackLease;
    ASSERT_NE(nullptr, engine.OriginalDeferredPackLease(token));
    ASSERT_EQ(VN_OK, engine.packs.ReleaseResourceClosure(lease.resourceClosureToken));
    EXPECT_EQ(VN_RUNTIME_RECREATE_REQUIRED, Vn_StopActionFiring(fixture.firing, 0));
    ASSERT_TRUE(engine.runtimeRecreateRequired);
    ASSERT_NE(nullptr, engine.OriginalDeferredPackLease(token));
    EXPECT_TRUE(engine.OriginalDeferredPackLease(token)->Valid());
    EXPECT_EQ(PackComposition::OriginalLeasePhase::Faulted, engine.OriginalDeferredPackLease(token)->Phase());
    EXPECT_TRUE(engine.packComposition.HasOriginalLeaseEpisode(lease));
    EXPECT_EQ(1u, engine.actionDeferredRecords.LiveCount());
    EXPECT_EQ(1u, engine.actionFirings.OwnedDeferredCount(fixture.firing));
    EXPECT_EQ(0u, engine.playableInstances.LiveCount());
    EXPECT_EQ(0u, engine.voices.ActiveCount());
    EXPECT_EQ(VN_RUNTIME_RECREATE_REQUIRED, engine.ReleaseOriginalDeferredPack(token, lease));
    EXPECT_EQ(VN_IN_USE, engine.ReleasePackIdentityLease(lease));
    VnPostActionDesc post{};
    post.structSize = sizeof(post);
    post.actionId = harkentest::ObjectId(2002);
    VnActionFiringHandle refused = UINT64_MAX;
    EXPECT_EQ(VN_RUNTIME_RECREATE_REQUIRED, Vn_PostAction(&post, &refused));
    EXPECT_EQ(0u, refused);
    Vn_Term();
    EXPECT_EQ(VN_NOT_INITIALIZED, Vn_Update());
}

TEST(PackComposition, PackActionDelayedSoundRenders) {
    DelayedPackPlayFixture fixture(MakeNullConfig(8, 256, 48000),
                                   "f5-delayed-sound");
    ASSERT_EQ(VN_OK, fixture.session.InitResult());
    fixture.PumpUntilDeferredGone();
    ASSERT_EQ(0u, fixture.session.Engine()->actionDeferredRecords.LiveCount());
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(fixture.firing, 0, &play));
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(fixture.firing, &info));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, play.state)
        << "result=" << play.result << " firingState=" << info.state
        << " outcome=" << info.outcome
        << " terminal=" << info.terminalReason;
    EXPECT_NE(0u, play.producedPlayableInstance);
    EXPECT_EQ(1u, fixture.session.Engine()->playableInstances.LiveCount());
    EXPECT_EQ(1u, fixture.session.Engine()->voices.ActiveCount());
    const EnginePlayableServiceRow* row = fixture.LiveStartRow();
    ASSERT_NE(nullptr, row);
    EXPECT_EQ(fixture.leaseToken, row->Invocation().packLease.leaseToken);
    EXPECT_EQ(nullptr, fixture.session.Engine()->OriginalDeferredPackLease(fixture.token));
    ASSERT_TRUE(row->Invocation().originalPackLease.Valid());
    EXPECT_EQ(fixture.leaseToken, row->Invocation().originalPackLease.OriginalLease().leaseToken);
    EXPECT_EQ(VN_INVALID_ARG,
              fixture.session.Engine()->packComposition.RetagLiveLease(
                  row->Invocation().packLease, PackLeaseSlice::Playable));
    EXPECT_EQ(VN_OK, fixture.session.Engine()->packComposition.ValidateLease(
                         row->Invocation().packLease));
    ASSERT_EQ(fixture.record.intendedBoundaryFrame, row->startFrame);
    const std::uint64_t blockFrames =
        fixture.session.Engine()->nullBackend.BlockFrames();
    const std::uint32_t channels =
        fixture.session.Engine()->nullBackend.Channels();
    ASSERT_GT(channels, 0u);
    const std::uint64_t observationStart =
        fixture.session.Engine()->mixer.BlocksRendered() * blockFrames;
    ASSERT_LE(observationStart, fixture.record.intendedBoundaryFrame);
    std::uint64_t firstAudibleFrame = UINT64_MAX;
    while (fixture.session.Engine()->mixer.BlocksRendered() * blockFrames <
           fixture.record.intendedBoundaryFrame + 2048u) {
        ASSERT_EQ(VN_OK, Vn_Update());
        const std::uint64_t blockStart =
            fixture.session.Engine()->mixer.BlocksRendered() * blockFrames;
        fixture.session.Engine()->nullBackend.Pump(1);
        const float* pcm = fixture.session.Engine()->nullBackend.LastBlock();
        for (std::uint64_t frame = 0; frame < blockFrames; ++frame) {
            const float left = pcm[frame * channels];
            if (std::abs(left) > 1e-4f &&
                firstAudibleFrame == UINT64_MAX) {
                firstAudibleFrame = blockStart + frame;
            }
            if (blockStart + frame < fixture.record.intendedBoundaryFrame)
                EXPECT_NEAR(0.0f, left, 1e-4f);
        }
    }
    EXPECT_EQ(fixture.record.intendedBoundaryFrame, firstAudibleFrame);
    fixture.PumpUntilFiringTerminal();
}

void VerifyPackActionDelayedGenericContainerCommit(
    DelayedPackPlayTarget target, const char* label) {
    DelayedPackPlayFixture fixture(MakeNullConfig(8, 256, 48000), label,
                                   1000000000, target);
    ASSERT_EQ(VN_OK, fixture.session.InitResult());
    auto* engine = fixture.session.Engine();
    ASSERT_EQ(1u, engine->actionDeferredRecords.LiveCount());
    fixture.PumpUntilDeferredGone(512);
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(fixture.firing, 0, &play));
    if (play.state != VN_ACTION_STEP_ACTIVE) {
        const auto attempt = std::find_if(
            engine->actionPlayStorage.begin(), engine->actionPlayStorage.end(),
            [](const EngineActionPlayStorage& candidate) {
                return candidate.phase != EngineFrontierAttemptPhase::Free;
            });
        DeferredIntentToken poolToken{};
        const bool hasPool = engine->actionDeferredRecords.PoolToken(
            fixture.token, &poolToken);
        std::cerr << "delayed generic diagnostic: record="
                  << fixture.token.slot << '/' << fixture.token.generation
                  << " state=" << static_cast<int>(
                         engine->actionDeferredRecords.State(fixture.token))
                  << " pool=" << hasPool << ':' << poolToken.slot << '/'
                  << poolToken.generation << " firing=" << fixture.firing
                  << " attempt=" << (attempt == engine->actionPlayStorage.end()
                         ? UINT32_MAX : static_cast<std::uint32_t>(
                               attempt - engine->actionPlayStorage.begin()))
                  << " phase=" << (attempt == engine->actionPlayStorage.end()
                         ? -1 : static_cast<int>(attempt->phase))
                  << " row=" << (attempt == engine->actionPlayStorage.end()
                         ? nullptr : engine->actionPlayScratch[
                               attempt - engine->actionPlayStorage.begin()].row)
                  << " leaseToken=" << fixture.record.targetPackLease.leaseToken
                  << '\n';
    }
    ASSERT_EQ(VN_ACTION_STEP_ACTIVE, play.state)
        << "result=" << play.result
        << " recordCount=" << engine->actionDeferredRecords.LiveCount()
        << " lease=" << engine->packComposition.ValidateLease(
               fixture.record.targetPackLease);
    ASSERT_NE(0u, play.producedPlayableInstance);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const EnginePlayableServiceRow& candidate) {
            return candidate.phase != EnginePlayableStartPhase::Free &&
                candidate.rootInstance == play.producedPlayableInstance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    EXPECT_EQ(fixture.leaseToken, row->Invocation().packLease.leaseToken);
    EXPECT_EQ(nullptr, engine->OriginalDeferredPackLease(fixture.token));
    ASSERT_TRUE(row->Invocation().originalPackLease.Valid());
    EXPECT_EQ(fixture.leaseToken, row->Invocation().originalPackLease.OriginalLease().leaseToken);
    EXPECT_EQ(VN_OK, engine->packComposition.ValidateLease(
        row->Invocation().packLease));
    EXPECT_EQ(0u, engine->actionFirings.OwnedDeferredCount(fixture.firing));
}

TEST(PackComposition, PackActionDelayedSequenceQueueCommitsExistingRoute) {
    VerifyPackActionDelayedGenericContainerCommit(
        DelayedPackPlayTarget::SequenceQueue,
        "f5-delayed-sequence-queue-route");
}

TEST(PackComposition, PackActionDelayedVariableControlCommitsExistingRoute) {
    VerifyPackActionDelayedGenericContainerCommit(
        DelayedPackPlayTarget::VariableControl,
        "f5-delayed-variable-control-route");
}

void VerifyPackActionDelayedGenericContainerPcmAndStop(
    DelayedPackPlayTarget target, const char* label,
    std::uint64_t previousComposite = 0) {
    DelayedPackPlayFixture fixture(MakeNullConfig(8, 256, 48000), label,
                                   1000000000, target);
    ASSERT_EQ(VN_OK, fixture.session.InitResult());
    auto* engine = fixture.session.Engine();
    ASSERT_NE(nullptr, engine);
    if (target == DelayedPackPlayTarget::VariableControl) {
        ASSERT_GT(engine->packComposition.CompositeGeneration(), previousComposite);
        ASSERT_NE(engine->variables.CurrentWorldGeneration(),
            engine->packComposition.CompositeGeneration());
        ASSERT_EQ(engine->packComposition.CompositeGeneration(),
            fixture.record.targetPackLease.compositeGeneration);
    }
    const auto playableBaseline = engine->playableInstances.LiveCount();
    const auto voiceBaseline = engine->voices.ActiveCount();
    const auto serviceBaseline = std::count_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [](const EnginePlayableServiceRow& row) {
            return row.phase != EnginePlayableStartPhase::Free;
        });
    const auto partitionBaseline = std::count_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [](const EnginePlayableServiceRow& row) {
            return row.partition.Valid();
        });
    const auto attemptBaseline = std::count_if(
        engine->actionPlayStorage.begin(), engine->actionPlayStorage.end(),
        [](const EngineActionPlayStorage& attempt) {
            return attempt.phase != EngineFrontierAttemptPhase::Free;
        });
    fixture.PumpUntilDeferredGone(512);
    ASSERT_FALSE(engine->runtimeRecreateRequired);
    const auto targetFrame = fixture.record.intendedBoundaryFrame;
    const auto blockFrames = engine->nullBackend.BlockFrames();
    const auto channels = engine->nullBackend.Channels();
    ASSERT_NE(0u, blockFrames);
    ASSERT_NE(0u, channels);
    std::uint64_t firstAudibleFrame = UINT64_MAX;
    std::uint64_t audibleBlock = UINT64_MAX;
    for (std::uint32_t step = 0; step < 128 &&
         firstAudibleFrame == UINT64_MAX; ++step) {
        const auto blockBefore = engine->mixer.BlocksRendered();
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(blockBefore + 1u, engine->mixer.BlocksRendered());
        const auto* pcm = engine->nullBackend.LastBlock();
        ASSERT_NE(nullptr, pcm);
        for (std::uint32_t frame = 0; frame < blockFrames; ++frame) {
            const auto absolute = blockBefore * blockFrames + frame;
            const float sample = pcm[frame * channels];
            if (absolute < targetFrame)
                EXPECT_NEAR(0.0f, sample, 1e-4f);
            if (std::abs(sample) > 1e-4f &&
                firstAudibleFrame == UINT64_MAX) {
                firstAudibleFrame = absolute;
                audibleBlock = blockBefore;
            }
        }
    }
    ASSERT_EQ(targetFrame, firstAudibleFrame);
    std::cerr << "delayed generic fresh PCM target=" << targetFrame
              << " first=" << firstAudibleFrame
              << " block=" << audibleBlock << '\n';
    ASSERT_EQ(VN_OK, Vn_StopActionFiring(fixture.firing, 0));
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    bool reclaimed = false;
    for (std::uint32_t step = 0; step < 256; ++step) {
        const auto before = engine->mixer.BlocksRendered();
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(before + 1u, engine->mixer.BlocksRendered());
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(fixture.firing, &info));
        reclaimed = info.state == VN_ACTION_FIRING_TERMINAL_RETAINED &&
            engine->playableInstances.LiveCount() == playableBaseline &&
            engine->voices.ActiveCount() == voiceBaseline &&
            std::count_if(engine->playableServices.begin(),
                engine->playableServices.end(),
                [](const EnginePlayableServiceRow& row) {
                    return row.phase != EnginePlayableStartPhase::Free;
                }) == serviceBaseline &&
            std::count_if(engine->playableServices.begin(),
                engine->playableServices.end(),
                [](const EnginePlayableServiceRow& row) {
                    return row.partition.Valid();
                }) == partitionBaseline &&
            std::count_if(engine->actionPlayStorage.begin(),
                engine->actionPlayStorage.end(),
                [](const EngineActionPlayStorage& attempt) {
                    return attempt.phase != EngineFrontierAttemptPhase::Free;
                }) == attemptBaseline &&
            engine->actionDeferredRecords.LiveCount() == 0 &&
            engine->timelineDeferred.Count() == 0 &&
            engine->packComposition.ValidateLease(
                fixture.record.targetPackLease) != VN_OK;
        if (reclaimed) break;
    }
    EXPECT_TRUE(reclaimed);
    const auto silentBefore = engine->mixer.BlocksRendered();
    ASSERT_EQ(VN_OK, Vn_Update());
    engine->nullBackend.Pump(1);
    ASSERT_EQ(silentBefore + 1u, engine->mixer.BlocksRendered());
    EXPECT_LE(harkentest::Peak(engine->nullBackend.LastBlock(),
        engine->nullBackend.BlockFrames() * engine->nullBackend.Channels()),
        harkentest::kSilenceFloor);
    std::cerr << "delayed generic stop reclaimed=" << reclaimed
              << " playable=" << playableBaseline << '/'
              << engine->playableInstances.LiveCount()
              << " voice=" << voiceBaseline << '/'
              << engine->voices.ActiveCount()
              << " service=" << serviceBaseline << '/'
              << std::count_if(engine->playableServices.begin(),
                     engine->playableServices.end(),
                     [](const EnginePlayableServiceRow& row) {
                         return row.phase != EnginePlayableStartPhase::Free;
                     })
              << " partition=" << partitionBaseline << '/'
              << std::count_if(engine->playableServices.begin(),
                     engine->playableServices.end(),
                     [](const EnginePlayableServiceRow& row) {
                         return row.partition.Valid();
                     })
              << " attempt=" << attemptBaseline << '/'
              << std::count_if(engine->actionPlayStorage.begin(),
                     engine->actionPlayStorage.end(),
                     [](const EngineActionPlayStorage& attempt) {
                         return attempt.phase != EngineFrontierAttemptPhase::Free;
                     })
              << " record=" << engine->actionDeferredRecords.LiveCount()
              << " pool=" << engine->timelineDeferred.Count()
              << " targetLease=" << engine->packComposition.ValidateLease(
                     fixture.record.targetPackLease) << '\n';
    EXPECT_EQ(0u, engine->actionFirings.OwnedDeferredCount(fixture.firing));
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(fixture.firing));
    fixture.firing = 0;
    EXPECT_EQ(VN_OK, Vn_DestroyEmitter(fixture.emitter));
    fixture.emitter = 0;
}

