void DiagnoseDeferredPackVariableControlFailure(bool afterTransfer) {
    auto fixture = std::make_unique<DelayedPackPlayFixture>(
        MakeNullConfig(8, 256, 48000),
        afterTransfer ? "f5-vc-row-owns-red" : "f5-vc-record-owns-red",
        1000000000, DelayedPackPlayTarget::VariableControl);
    ASSERT_EQ(VN_OK, fixture->session.InitResult());
    auto* engine = fixture->session.Engine();
    ASSERT_NE(nullptr, engine);
    const auto playableBefore = engine->playableInstances.LiveCount();
    const auto voiceBefore = engine->voices.ActiveCount();
    const auto variableControlBefore = engine->variableControlInstances.LiveCount();
    const auto containerBefore = engine->containerPlayback.LiveCount();
    const auto decisionBefore = engine->decisions.LiveCount();
    const auto armBefore = engine->timelineArms.LiveCount();
    const auto partitionBefore = engine->playablePartitions.OccupiedCount();
    const auto ownerBefore = engine->actionFirings.OwnedDeferredCount(
        fixture->firing);
    if (afterTransfer)
        engine->forceActionVariableControlPostLeaseTransferFailureForTest = true;
    else
        engine->forceActionPlayCommitFailureForTest = true;
    VnResult update = VN_OK;
    for (std::uint32_t step = 0; step < 512 &&
         !engine->runtimeRecreateRequired; ++step) {
        update = Vn_Update();
        if (engine->runtimeRecreateRequired) break;
        engine->nullBackend.Pump(1);
    }
    harken::DeferredIntentToken pool{};
    const bool poolLive = engine->actionDeferredRecords.PoolToken(
        fixture->token, &pool);
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    const auto queried = Vn_QueryActionStep(fixture->firing, 0, &play);
    auto& scratch = engine->actionPlayScratch[0];
    const auto* row = scratch.row;
    const auto leaseStatus = engine->packComposition.ValidateLease(
        fixture->record.targetPackLease);
    const auto rowLease = row == nullptr ? 0 :
        row->Invocation().packLease.leaseToken;
    const auto rootLive = row != nullptr &&
        engine->playableInstances.Classify(row->rootInstance).live;
    const auto partitionLive = row != nullptr && row->partition.Valid();
    const auto programReader = row != nullptr &&
        (engine->timelinePool.HasProgramReference(row->schedule.runtimeProgram) ||
         engine->timelinePlanner.HasProgramReference(row->schedule.runtimeProgram));
    std::cerr << "deferred vc failure afterTransfer=" << afterTransfer
              << " update=" << update
              << " recreate=" << engine->runtimeRecreateRequired
              << " recordCount=" << engine->actionDeferredRecords.LiveCount()
              << " recordState=" << static_cast<unsigned>(
                     engine->actionDeferredRecords.State(fixture->token))
              << " pool=" << poolLive << ':' << pool.slot << '/'
              << pool.generation
              << " queried=" << queried << " step=" << play.state
              << " stepResult=" << play.result
              << " lease=" << leaseStatus
              << " rowLease=" << rowLease
              << " rowPhase=" << (row == nullptr ? -1 :
                     static_cast<int>(row->phase))
              << " rootLive=" << rootLive
              << " partitionLive=" << partitionLive
               << " partitionRetiring=" << (row != nullptr && row->partitionRetiring)
               << " partitionPublished=" << (row != nullptr && partitionLive &&
                      engine->playablePartitions.Published(row->partition, row->identity))
               << " partitionCanRelease=" << (row != nullptr && partitionLive &&
                      engine->playablePartitions.CanRelease(row->partition, row->identity,
                          engine->mixer.BlocksRendered()))
              << " programReader=" << programReader
              << " scratchOwned=" << scratch.packLeaseOwned
              << " provenance=" << static_cast<unsigned>(
                     scratch.packLeaseProvenance)
              << " origin=" << static_cast<unsigned>(
                     scratch.packLeaseOrigin)
              << " attemptPhase=" << static_cast<unsigned>(
                     scratch.storage.phase)
              << " playable=" << playableBefore << '/'
              << engine->playableInstances.LiveCount()
              << " voice=" << voiceBefore << '/'
              << engine->voices.ActiveCount()
              << " ownedDeferred=" << ownerBefore << '/'
              << engine->actionFirings.OwnedDeferredCount(fixture->firing)
              << '\n';
    const auto blockBefore = engine->mixer.BlocksRendered();
    engine->nullBackend.Pump(1);
    const auto blockAfter = engine->mixer.BlocksRendered();
    float maxAbs = 0.0f;
    const auto* pcm = engine->nullBackend.LastBlock();
    for (std::uint32_t sample = 0;
         sample < engine->nullBackend.BlockFrames() *
             engine->nullBackend.Channels(); ++sample)
        maxAbs = std::max(maxAbs, std::abs(pcm[sample]));
    std::cerr << "deferred vc post-fault PCM block=" << blockBefore
              << '/' << blockAfter << " maxAbs=" << maxAbs << '\n';
    EXPECT_EQ(blockBefore + 1u, blockAfter);
    EXPECT_TRUE(rowLease == 0 || leaseStatus == VN_OK)
        << "A retained row alias references a released Pack lease";
    EXPECT_TRUE(!scratch.packLeaseOwned || leaseStatus == VN_OK)
        << "A still-live borrowed scratch holds a released Pack lease";
    const auto settled = [&] {
        return engine->playableInstances.LiveCount() == playableBefore &&
            engine->variableControlInstances.LiveCount() == variableControlBefore &&
            engine->containerPlayback.LiveCount() == containerBefore &&
            engine->voices.ActiveCount() == voiceBefore &&
            engine->decisions.LiveCount() == decisionBefore &&
            engine->timelineArms.LiveCount() == armBefore &&
            engine->playablePartitions.OccupiedCount() == partitionBefore &&
            engine->actionDeferredRecords.LiveCount() == 0 &&
            engine->timelineDeferred.Count() == 0 &&
            engine->actionFirings.OwnedDeferredCount(fixture->firing) == 0 &&
            engine->packComposition.ValidateLease(
                fixture->record.targetPackLease) != VN_OK &&
            std::all_of(engine->playableServices.begin(),
                engine->playableServices.end(), [](const auto& service) {
                    return service.phase == EnginePlayableStartPhase::Free;
                });
    };
    for (std::uint32_t tick = 0; tick < 16 && !settled(); ++tick) {
        if (scratch.storage.deferredContainerOwner.active)
            EXPECT_EQ(VN_OK, engine->packComposition.ValidateLease(
                fixture->record.targetPackLease));
        engine->nullBackend.Pump(1);
        EXPECT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_TRUE(settled());
    const auto settledFiringCount =
        engine->actionFirings.OwnedDeferredCount(fixture->firing);
    engine->nullBackend.Pump(1);
    EXPECT_EQ(VN_OK, Vn_Update());
    EXPECT_TRUE(settled());
    EXPECT_EQ(settledFiringCount,
        engine->actionFirings.OwnedDeferredCount(fixture->firing));
}

TEST(PackComposition, PackActionDelayedVariableControlRecordOwnsFailureDiagnostic) {
    DiagnoseDeferredPackVariableControlFailure(false);
}

TEST(PackComposition, PackActionDelayedVariableControlRowOwnsFailureDiagnostic) {
    DiagnoseDeferredPackVariableControlFailure(true);
}

void DiagnoseDeferredPackVariableControlHandoffPartial(
    bool rejectChildPublish, bool forcePostcheckFault = false) {
    auto fixture = std::make_unique<DelayedPackPlayFixture>(
        MakeNullConfig(8, 256, 48000),
        rejectChildPublish ? "vc-handoff-child-publish-red" :
            "vc-handoff-post-helper-red",
        1000000000, DelayedPackPlayTarget::VariableControl);
    ASSERT_EQ(VN_OK, fixture->session.InitResult());
    auto* engine = fixture->session.Engine();
    ASSERT_NE(nullptr, engine);
    const auto playableBaseline = engine->playableInstances.LiveCount();
    const auto partitionBaseline = engine->playablePartitions.OccupiedCount();
    const auto armBaseline = engine->timelineArms.LiveCount();
    const auto decisionBaseline = engine->decisions.LiveCount();
    const auto voiceBaseline = engine->voices.ActiveCount();
    if (rejectChildPublish)
        engine->forceDeferredFrontierChildPublishFailureForTest = true;
    else
        engine->forceDeferredFrontierPostHelperFailureForTest = true;
    bool injected = false;
    for (std::uint32_t tick = 0; tick < 512; ++tick) {
        ASSERT_EQ(VN_OK, Vn_Update());
        injected = rejectChildPublish
            ? !engine->forceDeferredFrontierChildPublishFailureForTest
            : !engine->forceDeferredFrontierPostHelperFailureForTest;
        if (injected) break;
        engine->nullBackend.Pump(1);
    }
    ASSERT_TRUE(injected);
    const auto& scratch = engine->actionPlayScratch[0];
    const auto* parent = scratch.row;
    ASSERT_NE(nullptr, parent);
    const auto& owner = scratch.storage.deferredContainerOwner;
    EXPECT_TRUE(owner.active);
    EXPECT_EQ(scratch.storage.generation, owner.attemptGeneration);
    EXPECT_EQ(fixture->token.slot, owner.recordToken.slot);
    EXPECT_EQ(fixture->token.generation, owner.recordToken.generation);
    EXPECT_EQ(EngineFrontierAttemptPhase::PublishedStopping, scratch.storage.phase);
    EXPECT_EQ(scratch.storage.generation,
              parent->publishedDeferredStoppingGeneration);
    EXPECT_EQ(&scratch - engine->actionPlayScratch.data(),
              parent->publishedDeferredStoppingSlot);
    EXPECT_TRUE(engine->playablePartitions.Published(
        parent->partition, parent->identity));
    VnActionStepResult stepAtFailure{};
    stepAtFailure.structSize = sizeof(stepAtFailure);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(fixture->firing, 0,
        &stepAtFailure));
    std::array<Plan03PageGroupView, 512> liveGroups{};
    const auto liveGroupCount = engine->timelinePool.CaptureLivePlan03Groups(
        liveGroups.data(), liveGroups.size());
    ASSERT_LE(liveGroupCount, liveGroups.size());
    std::uint32_t matchingGroupCount = 0;
    for (std::size_t index = 0; index < liveGroupCount; ++index) {
        const auto& group = liveGroups[index];
        if (group.identity.decision.slot !=
                parent->variableControlDiscreteDecision.slot ||
            group.identity.decision.generation !=
                parent->variableControlDiscreteDecision.generation)
            continue;
        ++matchingGroupCount;
        const auto lease = group.lease == nullptr
            ? AudioSliceLeaseSnapshot{} : group.lease->Capture();
        std::cerr << "handoff live group quantum="
                  << group.identity.absoluteQuantum
                  << " pageGeneration=" << group.identity.pageGeneration
                  << " decision=" << group.identity.decision.slot << '/'
                  << group.identity.decision.generation
                  << " committedRow=" << group.identity.committedRow
                  << " claimGeneration=" << group.identity.rowClaimGeneration
                  << " transportEpoch=" << group.identity.transportEpoch
                  << " memberCount=" << group.memberCount
                  << " sourceControlCount=" << group.sourceControlCount
                  << " leaseState=" << static_cast<unsigned>(lease.state)
                  << " leaseReason=" << lease.pendingReasonBits
                  << " exact=" << group.identity.Exact() << '\n';
        for (std::uint32_t member = 0; member < group.memberCount; ++member)
            std::cerr << "handoff live group member="
                      << group.members[member].slot << '/'
                      << group.members[member].generation << '\n';
    }
    std::uint32_t childCount = 0;
    std::uint32_t childPublished = 0;
    std::uint32_t childPrepared = 0;
    std::cerr << "handoff inventory frontierServices="
              << scratch.frontierServiceCount
              << " nestedServices=" << scratch.variableControlNestedServices.size()
              << " root=" << parent->identity.slot << '/'
              << parent->identity.generation << '\n';
    for (const auto& child : engine->playableServices) {
        if (child.phase != EnginePlayableStartPhase::Free)
            std::cerr << "handoff live service=" << child.identity.slot << '/'
                      << child.identity.generation
                      << " parentValid=" << child.parentService.Valid()
                      << " invocationValid=" << child.InvocationValid()
                      << " sameInvocation=" << (child.invocation == parent->invocation)
                      << " invocationGeneration=" << child.invocationGeneration
                      << " phase=" << static_cast<unsigned>(child.phase)
                      << " prepared=" << child.actionPrepared
                      << " partitionPublished=" << engine->playablePartitions.Published(
                             child.partition, child.identity) << '\n';
        if (&child == parent || child.phase == EnginePlayableStartPhase::Free ||
            !child.parentService.Valid() || !child.InvocationValid() ||
            child.invocation != parent->invocation ||
            child.invocationGeneration != parent->invocationGeneration)
            continue;
        ++childCount;
        childPublished += engine->playablePartitions.Published(
            child.partition, child.identity) ? 1u : 0u;
        childPrepared += child.actionPrepared ? 1u : 0u;
        std::cerr << "handoff child slot=" << child.identity.slot
                  << " generation=" << child.identity.generation
                  << " partition=" << child.partition.slot << '/'
                  << child.partition.generation
                  << " published=" << engine->playablePartitions.Published(
                         child.partition, child.identity)
                  << " prepared=" << child.actionPrepared << '\n';
    }
    if (rejectChildPublish) {
        ASSERT_GT(childCount, 0u);
        EXPECT_TRUE(engine->deferredFrontierRejectedChildForTest.Valid());
        EXPECT_LT(childPublished, childCount);
        EXPECT_GT(childPrepared, 0u);
    } else {
        EXPECT_EQ(childCount, childPublished);
    }
    std::cerr << "handoff seam=" << (rejectChildPublish ? "child" : "post-helper")
              << " parent=" << parent->identity.slot << '/'
              << parent->identity.generation
              << " partition=" << parent->partition.slot << '/'
              << parent->partition.generation
              << " rootInstance=" << parent->rootInstance
              << " rootArmToken=" << parent->arm.slot << '/'
              << parent->arm.generation
              << " decision=" << parent->variableControlDiscreteDecision.slot
              << '/' << parent->variableControlDiscreteDecision.generation
              << " group=" << parent->variableControlDiscreteArmGroup.slot
              << '/' << parent->variableControlDiscreteArmGroup.generation
              << " pageGeneration=" << parent->initialLaneDiscreteGroup.pageGeneration
              << " memberCount=" << parent->variableControlInitialDiscreteMemberCount
              << " invocation=" << parent->invocationGeneration
              << " attempt=" << scratch.storage.generation
              << " phase=" << static_cast<unsigned>(scratch.storage.phase)
              << " owner=" << owner.active
              << " recordToken=" << owner.recordToken.slot << '/'
              << owner.recordToken.generation
              << " poolToken=" << owner.poolToken.slot << '/'
              << owner.poolToken.generation
              << " leaseToken=" << owner.targetLease.leaseToken
              << " record=" << engine->actionDeferredRecords.LiveCount()
              << " pool=" << engine->timelineDeferred.Count()
              << " firingCount=" << engine->actionFirings.OwnedDeferredCount(
                     fixture->firing)
              << " child=" << childCount << '/' << childPublished << '/'
              << childPrepared
              << " primaryGroup=" << scratch.frontierPrimary.Valid()
              << " initialSlices=" << scratch.variableControlInitialCommittedSliceCount
              << " selection=" << scratch.selectionPlayCount
              << " treeCommitted=" << scratch.playableTreeExecutor.Committed()
              << " treeTokens=" << scratch.playableTreeExecutor.OwnerTokenCount()
              << " ledgerUnresolved=" << scratch.storage.ownerLedger.UnresolvedCount()
              << " rootArm=" << parent->arm.Valid()
              << " rootProgramReader=" <<
                    (engine->timelinePool.HasProgramReference(
                         parent->schedule.runtimeProgram) ||
                     engine->timelinePlanner.HasProgramReference(
                         parent->schedule.runtimeProgram))
              << " matchingGroups=" << matchingGroupCount
              << " selectedCount=" << parent->selectionCount
              << " selectionDeltas=" << parent->selectionDeltaCount
              << " selectedOrdinal=" << parent->selectedChildOrdinals[0]
              << " stepState=" << stepAtFailure.state
              << " stepResult=" << stepAtFailure.result
              << " cutoff=" << engine->timelinePool.PublishCutoffFrame()
              << " rendered=" << engine->mixer.BlocksRendered()
              << " target=" << fixture->record.intendedBoundaryFrame
              << " lease=" << engine->packComposition.ValidateLease(
                     fixture->record.targetPackLease)
              << " recreate=" << engine->runtimeRecreateRequired << '\n';
    EXPECT_EQ(1u, engine->actionDeferredRecords.LiveCount());
    EXPECT_EQ(1u, engine->timelineDeferred.Count());
    EXPECT_EQ(1u, engine->actionFirings.OwnedDeferredCount(fixture->firing));
    const auto stoppingEntry = owner.stoppingEntry;
    const auto stoppingPrimary = owner.stoppingPrimary;
    ASSERT_TRUE(stoppingEntry.Valid());
    ASSERT_TRUE(stoppingPrimary.Exact());
    Plan03GroupSliceIdentity stoppingMember{};
    std::uint32_t exactPreStopGroups = 0;
    for (std::size_t index = 0; index < liveGroupCount; ++index) {
        if (liveGroups[index].frontier != nullptr &&
            liveGroups[index].frontier->entry == stoppingEntry) {
            ++exactPreStopGroups;
            if (liveGroups[index].frontier->role ==
                FrontierGroupRole::EntryMember)
                stoppingMember = liveGroups[index].identity;
        }
    }
    EXPECT_EQ(2u, exactPreStopGroups);
    ASSERT_TRUE(stoppingMember.Exact());
    const auto protocolViolationBeforeStop =
        engine->timelineExecutor.Stats().protocolViolation;
#if defined(HARKEN_TEST_TIMELINE_CAPACITY_OVERRIDE)
    std::uint32_t stoppingPage = 0;
    ASSERT_TRUE(engine->timelinePool.PageForFrame(owner.earliestFrame,
        &stoppingPage));
    std::array<ConsumedEvent, 8> eventsBeforeStop{};
    const auto eventCountBeforeStop =
        engine->timelinePool.CapturePageEventsForTest(stoppingPage,
            eventsBeforeStop.data(), eventsBeforeStop.size());
    ASSERT_LE(eventCountBeforeStop, eventsBeforeStop.size());
    ASSERT_EQ(3u, eventCountBeforeStop);
    const auto* stoppingPageHeader = engine->timelinePool.Page(stoppingPage);
    ASSERT_NE(nullptr, stoppingPageHeader);
    ASSERT_EQ(stoppingPrimary.transportEpoch,
              stoppingPageHeader->transportEpoch);
    ASSERT_EQ(stoppingPrimary.absoluteQuantum,
              stoppingPageHeader->absoluteQuantumIndex);
    ASSERT_EQ(stoppingPrimary.pageGeneration,
              stoppingPageHeader->pageGeneration);
    std::array<TimelineTransactionProgramRef, 3> oldPrograms{};
    std::array<std::uint64_t, 3> oldRowSequences{};
    std::array<std::uint32_t, 3> oldTransactionSlots{
        UINT32_MAX, UINT32_MAX, UINT32_MAX};
    for (std::size_t index = 0; index < eventCountBeforeStop; ++index) {
        const auto& event = eventsBeforeStop[index];
        ASSERT_EQ(stoppingEntry, event.frontier.entry);
        ASSERT_LT(event.frontier.entryEventOrdinal, oldPrograms.size());
        ASSERT_EQ(nullptr,
            oldPrograms[event.frontier.entryEventOrdinal].program);
        oldPrograms[event.frontier.entryEventOrdinal] = event.program;
        EXPECT_NE(0u, event.rowSequence);
        oldRowSequences[event.frontier.entryEventOrdinal] = event.rowSequence;
        EXPECT_EQ(owner.earliestFrame, event.executeFrame);
        EXPECT_EQ(stoppingPrimary.transportEpoch, event.frontier.transport);
        EXPECT_EQ(stoppingPrimary.absoluteQuantum,
                  event.executeFrame / engine->timelinePool.QuantumFrames());
        EXPECT_EQ(event.frontier.entryEventOrdinal == 0
                      ? stoppingPrimary : stoppingMember,
                  event.frontier.group);
        EXPECT_NE(UINT32_MAX, event.txnSlot);
        oldTransactionSlots[event.frontier.entryEventOrdinal] = event.txnSlot;
        const auto* program = event.program.program;
        const auto* payload = program != nullptr &&
            event.payload < program->payloadCount
                ? &program->payloads[event.payload] : nullptr;
        std::cerr << "handoff page payload txn=" << event.transactionId
                  << " row=" << event.rowSequence
                  << " role=" << (program == nullptr ? 255u
                      : static_cast<unsigned>(program->role))
                  << " kind=" << (payload == nullptr ? 255u
                      : static_cast<unsigned>(payload->kind)) << '\n';
    }
    for (std::size_t index = 0; index < oldRowSequences.size(); ++index)
        for (std::size_t prior = 0; prior < index; ++prior)
            EXPECT_NE(oldRowSequences[index], oldRowSequences[prior]);
    for (std::size_t index = 0; index < oldTransactionSlots.size(); ++index)
        for (std::size_t prior = 0; prior < index; ++prior)
            EXPECT_NE(oldTransactionSlots[index], oldTransactionSlots[prior]);
    std::array<ConsumedEvent, 8> eventsAfterRemoval{};
    std::size_t eventCountAfterRemoval = 0;
    bool capturedAfterRemoval = false;
    engine->timelineSink.WatchFrontierEntryForTest(stoppingEntry);
#endif
    struct SettlementReceipt {
        std::uint32_t stage = 0;
        bool result = false;
        std::uint32_t before = 0;
        std::uint32_t after = 0;
    };
    struct SettlementTrace {
        std::array<SettlementReceipt, 3> receipts{};
        std::uint32_t count = 0;
    } settlement{};
    engine->publishedDeferredSettlementContextForTest = &settlement;
    engine->publishedDeferredSettlementHookForTest = +[](
        Engine&, std::uint32_t stage, bool result, std::uint32_t before,
        std::uint32_t after, void* context) {
        auto& trace = *static_cast<SettlementTrace*>(context);
        if (trace.count < trace.receipts.size())
            trace.receipts[trace.count] = {stage, result, before, after};
        ++trace.count;
    };
    Plan03ExactGroupSnapshot primaryBeforeStop{};
    ASSERT_TRUE(engine->timelinePool.CaptureExactPlan03Group(
        stoppingPrimary, &primaryBeforeStop));
    const auto pageHoldsBeforeStop = primaryBeforeStop.pagePublicationHolds;
    ASSERT_EQ(VN_OK, Vn_StopActionFiring(fixture->firing, 0));
    const auto firstStopBlock = engine->mixer.BlocksRendered();
    const auto blockFrames = engine->nullBackend.BlockFrames();
    const auto channels = engine->nullBackend.Channels();
    ASSERT_GT(blockFrames, 0u);
    ASSERT_GT(channels, 0u);
    if (forcePostcheckFault) {
        engine->forcePublishedDeferredEntryPostcheckFailureOnceForTest = true;
        for (std::uint32_t tick = 0; tick < 32 && !owner.fault; ++tick) {
            EXPECT_EQ(VN_OK, Vn_Update());
            if (!owner.fault) engine->nullBackend.Pump(1);
        }
        ASSERT_TRUE(owner.fault);
        EXPECT_FALSE(engine->forcePublishedDeferredEntryPostcheckFailureOnceForTest);
        EXPECT_TRUE(owner.unpublishedFrontierEventRemoved);
        EXPECT_TRUE(owner.active);
        EXPECT_FALSE(owner.unpublishedDecisionTransferred);
        EXPECT_TRUE(engine->runtimeRecreateRequired);
        EXPECT_FALSE(engine->timelinePool.HasFrontierEntryEvent(stoppingEntry));
        EXPECT_EQ(0u, engine->timelinePool.LiveTransactionCount());
        EXPECT_EQ(2u, engine->decisions.LiveCount());
        EXPECT_EQ(VN_OK, engine->packComposition.ValidateLease(
            fixture->record.targetPackLease));
        const auto beforeRetry = engine->timelinePool.LiveTransactionCount();
        (void)Vn_Update();
        EXPECT_EQ(beforeRetry, engine->timelinePool.LiveTransactionCount());
        EXPECT_TRUE(owner.unpublishedFrontierEventRemoved);
        EXPECT_TRUE(owner.fault);
        EXPECT_TRUE(owner.active);
        EXPECT_EQ(2u, engine->decisions.LiveCount());
        EXPECT_EQ(VN_OK, engine->packComposition.ValidateLease(
            fixture->record.targetPackLease));
        return;
    }
    struct PcmTraceOnFailure {
        std::ostringstream stream;
        ~PcmTraceOnFailure() {
            if (::testing::Test::HasFailure()) {
                std::cerr << "PCM handoff trace:\n" << stream.str();
            }
        }
    } trace;
    auto& pcmTrace = trace.stream;
    pcmTrace << "block\tframe\tcutoff";
    for (std::uint32_t channel = 0; channel < channels; ++channel)
        pcmTrace << "\tch" << channel << "_maxAbs";
    pcmTrace << '\n';
    float maxAbsAfterStop = 0.0f;
    bool sawP3Hold = false;
    for (std::uint32_t tick = 0; tick < 320; ++tick) {
        const auto block = engine->mixer.BlocksRendered();
        EXPECT_EQ(VN_OK, Vn_Update());
#if defined(HARKEN_TEST_TIMELINE_CAPACITY_OVERRIDE)
        if (!capturedAfterRemoval && owner.unpublishedFrontierEventRemoved) {
            eventCountAfterRemoval =
                engine->timelinePool.CapturePageEventsForTest(stoppingPage,
                    eventsAfterRemoval.data(), eventsAfterRemoval.size());
            capturedAfterRemoval = true;
        }
#endif
        if (owner.unpublishedWitnessed && !owner.unpublishedGroupsRetired) {
            Plan03ExactGroupSnapshot primaryInRetirement{};
            if (engine->timelinePool.CaptureExactPlan03Group(
                    stoppingPrimary, &primaryInRetirement) &&
                primaryInRetirement.unpublishedRetirementStage != 0) {
                sawP3Hold = true;
                EXPECT_EQ(pageHoldsBeforeStop + 1u,
                          primaryInRetirement.pagePublicationHolds);
            }
        }
        engine->nullBackend.Pump(1);
        ASSERT_EQ(block + 1u, engine->mixer.BlocksRendered());
        const auto* samples = engine->nullBackend.LastBlock();
        ASSERT_NE(nullptr, samples);
        pcmTrace << block << '\t' << block * blockFrames << '\t'
                 << engine->timelinePool.PublishCutoffFrame();
        for (std::uint32_t channel = 0; channel < channels; ++channel) {
            float channelMax = 0.0f;
            for (std::uint32_t frame = 0; frame < blockFrames; ++frame)
                channelMax = std::max(channelMax,
                    std::abs(samples[frame * channels + channel]));
            pcmTrace << '\t' << channelMax;
            maxAbsAfterStop = std::max(maxAbsAfterStop, channelMax);
            EXPECT_LE(channelMax, 1e-5f)
                << "block=" << block << " frame=" << block * blockFrames
                << " channel=" << channel;
        }
        pcmTrace << '\n';
    }
    EXPECT_TRUE(sawP3Hold);
    EXPECT_GE(engine->mixer.BlocksRendered() * blockFrames,
        fixture->record.intendedBoundaryFrame + 8u * blockFrames);
    EXPECT_LE(maxAbsAfterStop, 1e-5f);
    std::cerr << "handoff after stop playable="
              << engine->playableInstances.LiveCount()
              << " partition=" << engine->playablePartitions.OccupiedCount()
              << " arm=" << engine->timelineArms.LiveCount()
              << " decision=" << engine->decisions.LiveCount()
              << " voice=" << engine->voices.ActiveCount()
              << " record=" << engine->actionDeferredRecords.LiveCount()
              << " pool=" << engine->timelineDeferred.Count()
              << " firingCount=" << engine->actionFirings.OwnedDeferredCount(
                     fixture->firing)
              << " lease=" << engine->packComposition.ValidateLease(
                     fixture->record.targetPackLease)
              << " recreate=" << engine->runtimeRecreateRequired << '\n';
    std::cerr << "handoff owner phase=" << static_cast<unsigned>(scratch.storage.phase)
              << " active=" << owner.active << " fault=" << owner.fault
              << " witnessed=" << owner.unpublishedWitnessed
              << " bindings=" << owner.unpublishedBindingsReleased
              << " activation=" << owner.unpublishedActivationReconciled
              << " groups=" << owner.unpublishedGroupsRetired
              << " decision=" << owner.unpublishedDecisionTransferred
              << " p3Valid=" << owner.unpublishedRetirement.Valid()
              << " p3MemberRow=" << owner.unpublishedRetirement.member.committedRow
              << " rowGate=" << parent->publishedDeferredStoppingGeneration
              << " blocker=" << owner.stoppingBlockerHeld << '\n';
    std::cerr << "handoff stop PCM firstBlock=" << firstStopBlock
              << " finalBlock=" << engine->mixer.BlocksRendered()
              << " channels=" << channels
              << " maxAbs=" << maxAbsAfterStop << '\n';
    VnActionStepResult stepAfterStop{};
    stepAfterStop.structSize = sizeof(stepAfterStop);
    if (Vn_QueryActionStep(fixture->firing, 0, &stepAfterStop) == VN_OK)
        std::cerr << "handoff after stop step=" << stepAfterStop.state
                  << " result=" << stepAfterStop.result
                  << " produced=" << stepAfterStop.producedPlayableInstance
                  << '\n';
    std::cerr << "handoff after stop row phase="
              << static_cast<unsigned>(parent->phase)
              << " control=" << static_cast<unsigned>(parent->controlLifecycle)
              << " reason=" << static_cast<unsigned>(parent->controlReason)
              << " intent=" << static_cast<unsigned>(parent->pendingCancellationIntent)
              << " partitionRetiring=" << parent->partitionRetiring
              << " partitionPublished=" << engine->playablePartitions.Published(
                     parent->partition, parent->identity)
              << " partitionCanRelease=" << engine->playablePartitions.CanRelease(
                     parent->partition, parent->identity,
                     engine->mixer.BlocksRendered())
              << " arm=" << parent->arm.Valid()
              << " decision=" << parent->variableControlDiscreteDecision.Valid()
              << " group=" << parent->variableControlDiscreteArmGroup.Valid()
              << " vcInstance=" << parent->variableControlInstance.Valid()
              << " discreteCommitted=" << parent->variableControlDiscreteDecisionCommitted
              << " discreteCleanup=" << parent->variableControlDiscreteCleanupStarted
              << " deferredCancellation=" << parent->variableControlDeferredCancellation
              << " rootLive=" << engine->playableInstances.Classify(
                     parent->rootInstance).live << '\n';
    const auto liveAfterStop = engine->timelinePool.CaptureLivePlan03Groups(
        liveGroups.data(), liveGroups.size());
    std::cerr << "handoff after stop liveGroups=" << liveAfterStop << '\n';
    for (std::size_t index = 0;
         index < std::min(liveAfterStop, liveGroups.size()); ++index) {
        const auto& group = liveGroups[index];
        const auto lease = group.lease == nullptr
            ? AudioSliceLeaseSnapshot{} : group.lease->Capture();
        std::cerr << "handoff after stop group q="
                  << group.identity.absoluteQuantum
                  << " pageGeneration=" << group.identity.pageGeneration
                  << " decision=" << group.identity.decision.slot << '/'
                  << group.identity.decision.generation
                  << " row=" << group.identity.committedRow
                  << " claimGeneration=" << group.identity.rowClaimGeneration
                  << " members=" << group.memberCount
                  << " leaseState=" << static_cast<unsigned>(lease.state)
                  << " leaseReason=" << lease.pendingReasonBits
                  << '\n';
        for (std::uint32_t member = 0; member < group.memberCount; ++member)
            std::cerr << "handoff after stop group member="
                      << group.members[member].slot << '/'
                      << group.members[member].generation << '\n';
    }

    EXPECT_EQ(EngineFrontierAttemptPhase::Free, scratch.storage.phase);
    EXPECT_EQ(3u, settlement.count);
    for (std::uint32_t index = 0;
         index < std::min<std::uint32_t>(settlement.count,
             settlement.receipts.size()); ++index) {
        const auto& receipt = settlement.receipts[index];
        EXPECT_EQ(index + 1u, receipt.stage);
        EXPECT_TRUE(receipt.result);
        EXPECT_EQ(1u, receipt.before);
        EXPECT_EQ(0u, receipt.after);
    }
    EXPECT_EQ(protocolViolationBeforeStop,
        engine->timelineExecutor.Stats().protocolViolation);
#if defined(HARKEN_TEST_TIMELINE_CAPACITY_OVERRIDE)
    const auto dumpEvents = [&](const char* label,
        const std::array<ConsumedEvent, 8>& events, std::size_t count) {
        for (std::size_t index = 0; index < std::min(count, events.size());
             ++index) {
            const auto& event = events[index];
            std::cerr << "handoff page " << label
                      << " txn=" << event.transactionId
                      << " slot=" << event.txnSlot
                      << " row=" << event.rowSequence
                      << " frame=" << event.executeFrame
                      << " kind=" << static_cast<unsigned>(event.frontier.kind)
                      << " programGeneration="
                      << event.program.programGeneration
                      << " payloadIndex=" << event.payload
                      << " arm=" << event.armToken.slot << '/'
                      << event.armToken.generation << '\n';
        }
    };
    dumpEvents("before", eventsBeforeStop, eventCountBeforeStop);
    if (capturedAfterRemoval)
        dumpEvents("after", eventsAfterRemoval, eventCountAfterRemoval);
    EXPECT_TRUE(capturedAfterRemoval);
    EXPECT_EQ(0u, eventCountAfterRemoval);
    for (const auto program : oldPrograms) {
        EXPECT_NE(nullptr, program.program);
        EXPECT_FALSE(engine->timelinePool.HasProgramReference(program));
        EXPECT_FALSE(engine->timelinePlanner.HasProgramReference(program));
    }
    for (std::size_t index = 0; index < std::min<std::uint64_t>(
             engine->timelineSink.WatchedFrontierStageCountForTest(), 8);
         ++index) {
        const auto staged = engine->timelineSink.WatchedFrontierStageForTest(index);
        std::cerr << "handoff staged entry txn=" << staged.transactionId
                  << " slot=" << staged.txnSlot
                  << " row=" << staged.rowSequence
                  << " frame=" << staged.executeFrame
                  << " kind=" << static_cast<unsigned>(staged.kind)
                  << " payload=" << static_cast<unsigned>(staged.payloadKind)
                  << " present=" << staged.payloadPresent
                  << " valid=" << staged.frozenTxnValid
                  << " disposition=" << static_cast<unsigned>(staged.disposition)
                  << '\n';
    }
    EXPECT_EQ(0u, engine->timelineSink.WatchedFrontierStageCountForTest());
#endif
    Plan03ExactGroupSnapshot retiredSnapshot{};
    EXPECT_FALSE(engine->timelinePool.CaptureExactPlan03Group(
        stoppingMember, &retiredSnapshot));
    EXPECT_FALSE(engine->timelinePool.CaptureExactPlan03Group(
        stoppingPrimary, &retiredSnapshot));
    std::uint32_t exactAfterStopGroups = 0;
    for (std::size_t index = 0; index < liveAfterStop; ++index)
        if (liveGroups[index].frontier != nullptr &&
            liveGroups[index].frontier->entry == stoppingEntry)
            ++exactAfterStopGroups;
    EXPECT_EQ(0u, exactAfterStopGroups);
    for (std::uint32_t pageIndex = 0;
         pageIndex < engine->timelinePool.PageCount(); ++pageIndex) {
        const auto* page = engine->timelinePool.Page(pageIndex);
        if (page == nullptr ||
            page->absoluteQuantumIndex != stoppingPrimary.absoluteQuantum ||
            page->pageGeneration != stoppingPrimary.pageGeneration) continue;
        EXPECT_EQ(0u, page->plan03GroupCount);
    }
    EXPECT_EQ(playableBaseline, engine->playableInstances.LiveCount());
    EXPECT_EQ(partitionBaseline, engine->playablePartitions.OccupiedCount());
    EXPECT_EQ(armBaseline, engine->timelineArms.LiveCount());
    EXPECT_EQ(decisionBaseline, engine->decisions.LiveCount());
    EXPECT_EQ(voiceBaseline, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->actionDeferredRecords.LiveCount());
    EXPECT_EQ(0u, engine->timelineDeferred.Count());
    EXPECT_EQ(0u, engine->actionFirings.OwnedDeferredCount(fixture->firing));
    EXPECT_NE(VN_OK, engine->packComposition.ValidateLease(
        fixture->record.targetPackLease));
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    EXPECT_EQ(nullptr, engine->OriginalDeferredPackLease(fixture->token));
    EXPECT_FALSE(engine->packComposition.HasOriginalLeaseEpisode(fixture->record.targetPackLease));
    ASSERT_FALSE(engine->runtimeRecreateRequired);
    VnPostActionDesc replay{};
    replay.structSize = sizeof(replay);
    replay.actionId = harkentest::ObjectId(2002);
    replay.emitter = fixture->emitter;
    VnActionFiringHandle nextFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&replay, &nextFiring));
    ActionDeferredRecordToken next{};
    ActionDeferredRecord nextRecord{};
    ActionDeferredRecordState nextState = ActionDeferredRecordState::Free;
    ASSERT_TRUE(engine->actionDeferredRecords.CaptureAt(fixture->token.slot,
        &next, &nextRecord, &nextState));
    EXPECT_EQ(fixture->token.slot, next.slot);
    EXPECT_GT(next.generation, fixture->token.generation);
    EXPECT_EQ(ActionDeferredRecordState::Held, nextState);
    ASSERT_NE(nullptr, engine->OriginalDeferredPackLease(next));
    EXPECT_EQ(nextRecord.targetPackLease.leaseToken,
        engine->OriginalDeferredPackLease(next)->OriginalLease().leaseToken);
    EXPECT_EQ(nullptr, engine->OriginalDeferredPackLease(fixture->token));
    ASSERT_EQ(VN_OK, Vn_StopActionFiring(nextFiring, 0));
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(nextFiring));
    EXPECT_EQ(0u, engine->actionDeferredRecords.LiveCount());
    EXPECT_FALSE(engine->packComposition.HasOriginalLeaseEpisode(nextRecord.targetPackLease));
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

