TEST(PackComposition, PackActionDelayedPlayBackpressureRetryDoesNotDoubleOccupy) {
    DelayedPackPlayFixture fixture(MakeNullConfig(8, 256, 48000),
                                   "f5-delayed-backpressure");
    ASSERT_EQ(VN_OK, fixture.session.InitResult());
    std::vector<PreparedPlayableInstance> held;
    held.resize(fixture.session.Engine()->playableInstances.FreeCount());
    for (auto& prepared : held) {
        ASSERT_TRUE(fixture.session.Engine()->playableInstances.PrepareAcquire(
            PlayableKind::Sound, 0, &prepared));
    }
    EXPECT_EQ(0u, fixture.session.Engine()->playableInstances.FreeCount());
    PackIdentityLookup extraSharedBefore;
    EXPECT_EQ(VN_OK, fixture.session.Engine()->packComposition.PrepareLookup(
                         fixture.targetStableId, &extraSharedBefore));
    fixture.session.Engine()->packComposition.AbandonPreparedLease(
        extraSharedBefore.lease);
    ASSERT_EQ(VN_OK, Vn_Update());
    fixture.session.Engine()->nullBackend.Pump(1);
    EXPECT_EQ(1u, fixture.session.Engine()->actionDeferredRecords.LiveCount());
    EXPECT_EQ(VN_OK, fixture.session.Engine()->packComposition.ValidateLease(
                         fixture.record.targetPackLease));
    EXPECT_EQ(nullptr, fixture.LiveStartRow());
    PackIdentityLookup extraSharedAfter;
    EXPECT_EQ(VN_OK, fixture.session.Engine()->packComposition.PrepareLookup(
                         fixture.targetStableId, &extraSharedAfter));
    fixture.session.Engine()->packComposition.AbandonPreparedLease(
        extraSharedAfter.lease);
    for (auto& prepared : held) {
        ASSERT_TRUE(fixture.session.Engine()->playableInstances.CancelPrepared(
            &prepared));
    }
    ASSERT_EQ(VN_OK, Vn_StopActionFiring(fixture.firing, 0));
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(fixture.firing));
}

TEST(PackComposition, PackActionDelayedPlayableSliceFullRetriesWithoutRetag) {
    DelayedPackPlayFixture fixture(MakeNullConfig(8, 256, 48000),
                                   "f5-delayed-playable-full");
    ASSERT_EQ(VN_OK, fixture.session.InitResult());
    std::vector<PackPartitionLease> occupying;
    for (;;) {
        PackIdentityLookup lookup;
        const VnResult acquired =
            fixture.session.Engine()->AcquirePackIdentityLease(
                fixture.targetStableId, PackLeaseSlice::Playable, &lookup);
        if (acquired == VN_BACKPRESSURE) {
            break;
        }
        ASSERT_EQ(VN_OK, acquired);
        occupying.push_back(lookup.lease);
    }
    ASSERT_FALSE(occupying.empty());
    const std::uint64_t retagBackpressureBefore =
        fixture.session.Engine()->packComposition
            .RetagBackpressureCountForTests();
    for (std::uint32_t block = 0; block < 512u &&
         fixture.session.Engine()->timelinePool.WindowEndFrame() <=
             fixture.record.intendedBoundaryFrame; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        fixture.session.Engine()->nullBackend.Pump(1);
    }
    ASSERT_GT(fixture.session.Engine()->timelinePool.WindowEndFrame(),
              fixture.record.intendedBoundaryFrame);
    for (std::uint32_t block = 0; block < 4u; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        fixture.session.Engine()->nullBackend.Pump(1);
    }
    EXPECT_GT(fixture.session.Engine()->packComposition
                  .RetagBackpressureCountForTests(),
              retagBackpressureBefore);
    EXPECT_EQ(1u, fixture.session.Engine()->actionDeferredRecords.LiveCount());
    EXPECT_EQ(VN_OK, fixture.session.Engine()->packComposition.ValidateLease(
                         fixture.record.targetPackLease));
    EXPECT_EQ(VN_BACKPRESSURE,
              fixture.session.Engine()->RetagOriginalDeferredPack(
                  fixture.token, fixture.record.targetPackLease));
    EXPECT_EQ(nullptr, fixture.LiveStartRow());
    EXPECT_EQ(0u, fixture.session.Engine()->playableInstances.LiveCount());
    EXPECT_FALSE(fixture.session.Engine()->actionPlayScratch[0].prepared);
    for (const auto& lease : occupying) {
        EXPECT_EQ(VN_OK, fixture.session.Engine()->ReleasePackIdentityLease(lease));
    }
    fixture.PumpUntilDeferredGone();
    const EnginePlayableServiceRow* row = fixture.LiveStartRow();
    ASSERT_NE(nullptr, row);
    EXPECT_EQ(fixture.leaseToken, row->Invocation().packLease.leaseToken);
    fixture.PumpUntilFiringTerminal();
}

