TEST(PackComposition, PackActionDelayedVariableControlRetagPendingCleanupRetries) {
    DelayedPackPlayFixture fixture(MakeNullConfig(8, 256, 48000),
                                   "f5-vc-retag-pending-cleanup",
                                   1000000000,
                                   DelayedPackPlayTarget::VariableControl);
    auto* engine = fixture.session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<PackPartitionLease> occupying;
    for (;;) {
        PackIdentityLookup lookup;
        const auto acquired = engine->AcquirePackIdentityLease(
            fixture.targetStableId, PackLeaseSlice::Playable, &lookup);
        if (acquired == VN_BACKPRESSURE) break;
        ASSERT_EQ(VN_OK, acquired);
        occupying.push_back(lookup.lease);
    }
    ASSERT_FALSE(occupying.empty());
    DeferredIntentToken originalPool{};
    ASSERT_TRUE(engine->actionDeferredRecords.PoolToken(
        fixture.token, &originalPool));
    engine->forceActionVariableControlDeferredCleanupPendingOnceForTest = true;
    const auto retagBefore = engine->packComposition.RetagBackpressureCountForTests();
    for (std::uint32_t tick = 0; tick < 512 &&
         engine->packComposition.RetagBackpressureCountForTests() == retagBefore;
         ++tick) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_GT(engine->packComposition.RetagBackpressureCountForTests(), retagBefore);
    ASSERT_FALSE(engine->forceActionVariableControlDeferredCleanupPendingOnceForTest);
    ASSERT_EQ(ActionDeferredRecordState::Claimed,
              engine->actionDeferredRecords.State(fixture.token));
    ASSERT_EQ(VN_OK, engine->packComposition.ValidateLease(
                          fixture.record.targetPackLease));
    const auto owned = std::find_if(
        engine->actionPlayStorage.begin(), engine->actionPlayStorage.end(),
        [](const auto& attempt) {
            return attempt.deferredContainerOwner.active;
        });
    ASSERT_NE(engine->actionPlayStorage.end(), owned);
    EXPECT_EQ(fixture.token.slot, owned->deferredContainerOwner.recordToken.slot);
    EXPECT_EQ(fixture.token.generation,
              owned->deferredContainerOwner.recordToken.generation);
    EXPECT_EQ(originalPool.slot, owned->deferredContainerOwner.poolToken.slot);
    EXPECT_EQ(originalPool.generation,
              owned->deferredContainerOwner.poolToken.generation);
    EXPECT_EQ(EngineFrontierAttemptPhase::CancelPending, owned->phase);
    const auto oldAttemptGeneration = owned->generation;
    VnActionStepResult step{};
    step.structSize = sizeof(step);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(fixture.firing, 0, &step));
    EXPECT_EQ(VN_ACTION_STEP_AWAITING_MATERIALIZATION, step.state);
    for (const auto& lease : occupying)
        ASSERT_EQ(VN_OK, engine->ReleasePackIdentityLease(lease));
    bool sawSamePairRetry = false;
    bool materialized = false;
    for (std::uint32_t tick = 0; tick < 64; ++tick) {
        ASSERT_EQ(VN_OK, Vn_Update());
        if (engine->actionDeferredRecords.LiveCount() == 0) {
            materialized = true;
            break;
        }
        ActionDeferredRecordToken currentToken{};
        ActionDeferredRecord currentRecord{};
        ActionDeferredRecordState currentState = ActionDeferredRecordState::Free;
        ASSERT_TRUE(engine->actionDeferredRecords.CaptureAt(
            fixture.token.slot, &currentToken, &currentRecord, &currentState));
        EXPECT_EQ(fixture.token.generation, currentToken.generation);
        DeferredIntentToken currentPool{};
        ASSERT_TRUE(engine->actionDeferredRecords.PoolToken(
            fixture.token, &currentPool));
        EXPECT_EQ(originalPool.slot, currentPool.slot);
        EXPECT_EQ(originalPool.generation, currentPool.generation);
        ActionDeferredPairState resumedPair{};
        ASSERT_TRUE(engine->actionDeferredRecords.InspectPair(
            engine->timelineDeferred, currentPool, currentToken,
            &resumedPair));
        EXPECT_FALSE(resumedPair.recordReservation.Valid());
        EXPECT_FALSE(resumedPair.poolReservation.Valid());
        sawSamePairRetry = sawSamePairRetry ||
            currentState == ActionDeferredRecordState::Held;
        engine->nullBackend.Pump(1);
    }
    ASSERT_TRUE(materialized) << "The exact deferred pair did not resume";
    EXPECT_TRUE(sawSamePairRetry);
    EXPECT_EQ(retagBefore + 1u,
              engine->packComposition.RetagBackpressureCountForTests());
    EXPECT_EQ(engine->actionPlayStorage.end(), std::find_if(
        engine->actionPlayStorage.begin(), engine->actionPlayStorage.end(),
        [](const auto& attempt) {
            return attempt.deferredContainerOwner.active;
        }));
    EXPECT_LE(oldAttemptGeneration, owned->generation);
    ASSERT_NE(nullptr, fixture.LiveStartRow());
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(fixture.firing, 0, &step));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, step.state);
    EXPECT_EQ(fixture.LiveStartRow()->rootInstance,
              step.producedPlayableInstance);
    const auto blockFrames = engine->nullBackend.BlockFrames();
    const auto channels = engine->nullBackend.Channels();
    std::uint64_t firstAudibleFrame = UINT64_MAX;
    for (std::uint32_t tick = 0; tick < 128 &&
         firstAudibleFrame == UINT64_MAX; ++tick) {
        ASSERT_EQ(VN_OK, Vn_Update());
        const auto blockStart = engine->mixer.BlocksRendered() * blockFrames;
        engine->nullBackend.Pump(1);
        const auto* pcm = engine->nullBackend.LastBlock();
        ASSERT_NE(nullptr, pcm);
        for (std::uint32_t frame = 0; frame < blockFrames; ++frame) {
            const auto absolute = blockStart + frame;
            const auto sample = pcm[frame * channels];
            if (absolute < fixture.record.intendedBoundaryFrame)
                EXPECT_NEAR(0.0f, sample, 1e-4f);
            if (firstAudibleFrame == UINT64_MAX && std::abs(sample) > 1e-4f)
                firstAudibleFrame = absolute;
        }
    }
    EXPECT_EQ(fixture.record.intendedBoundaryFrame, firstAudibleFrame);
    fixture.PumpUntilFiringTerminal();
}

TEST(PackComposition, PackActionDelayedVariableControlRetagPendingStopCancels) {
    DelayedPackPlayFixture fixture(MakeNullConfig(8, 256, 48000),
                                   "f5-vc-retag-pending-stop",
                                   1000000000,
                                   DelayedPackPlayTarget::VariableControl);
    auto* engine = fixture.session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<PackPartitionLease> occupying;
    for (;;) {
        PackIdentityLookup lookup;
        const auto acquired = engine->AcquirePackIdentityLease(
            fixture.targetStableId, PackLeaseSlice::Playable, &lookup);
        if (acquired == VN_BACKPRESSURE) break;
        ASSERT_EQ(VN_OK, acquired);
        occupying.push_back(lookup.lease);
    }
    ASSERT_FALSE(occupying.empty());
    engine->forceActionVariableControlDeferredCleanupPendingOnceForTest = true;
    const auto retagBefore = engine->packComposition.RetagBackpressureCountForTests();
    for (std::uint32_t tick = 0; tick < 512 &&
         engine->packComposition.RetagBackpressureCountForTests() == retagBefore;
         ++tick) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_GT(engine->packComposition.RetagBackpressureCountForTests(), retagBefore);
    const auto owned = std::find_if(
        engine->actionPlayStorage.begin(), engine->actionPlayStorage.end(),
        [](const auto& attempt) {
            return attempt.deferredContainerOwner.active;
        });
    ASSERT_NE(engine->actionPlayStorage.end(), owned);
    ASSERT_EQ(EngineFrontierAttemptPhase::CancelPending, owned->phase);
    ASSERT_TRUE(owned->deferredContainerOwner.retryRequested);
    ASSERT_EQ(ActionDeferredRecordState::Claimed,
              engine->actionDeferredRecords.State(fixture.token));
    const auto blockFrames = engine->nullBackend.BlockFrames();
    const auto channels = engine->nullBackend.Channels();
    ASSERT_LT(engine->mixer.BlocksRendered() * blockFrames,
              fixture.record.intendedBoundaryFrame);
    std::uint32_t checkedAfterTarget = 0;
    const auto pumpAndCheckSilence = [&] {
        const auto blockStart = engine->mixer.BlocksRendered() * blockFrames;
        engine->nullBackend.Pump(1);
        const auto* pcm = engine->nullBackend.LastBlock();
        if (pcm == nullptr) {
            ADD_FAILURE() << "Null PCM block after Stop";
            return;
        }
        bool audible = false;
        for (std::uint32_t frame = 0; frame < blockFrames; ++frame) {
            if (blockStart + frame >= fixture.record.intendedBoundaryFrame)
                ++checkedAfterTarget;
            for (std::uint32_t channel = 0; channel < channels; ++channel)
                audible |= std::abs(pcm[frame * channels + channel]) > 1e-4f;
        }
        EXPECT_FALSE(audible) << "blockStart=" << blockStart;
        EXPECT_EQ(0u, engine->voices.ActiveCount());
    };
    ASSERT_EQ(VN_OK, Vn_StopActionFiring(fixture.firing, 0));
    for (const auto& lease : occupying)
        ASSERT_EQ(VN_OK, engine->ReleasePackIdentityLease(lease));
    for (std::uint32_t tick = 0; tick < 64 &&
         engine->actionDeferredRecords.LiveCount() != 0; ++tick) {
        ASSERT_EQ(VN_OK, Vn_Update());
        pumpAndCheckSilence();
    }
    EXPECT_EQ(0u, engine->actionDeferredRecords.LiveCount());
    EXPECT_EQ(0u, engine->timelineDeferred.Count());
    EXPECT_EQ(0u, engine->actionFirings.OwnedDeferredCount(fixture.firing));
    EXPECT_EQ(engine->actionPlayStorage.end(), std::find_if(
        engine->actionPlayStorage.begin(), engine->actionPlayStorage.end(),
        [](const auto& attempt) {
            return attempt.deferredContainerOwner.active;
        }));
    EXPECT_EQ(nullptr, fixture.LiveStartRow());
    EXPECT_NE(VN_OK, engine->packComposition.ValidateLease(
                          fixture.record.targetPackLease));
    VnActionStepResult step{};
    step.structSize = sizeof(step);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(fixture.firing, 0, &step));
    EXPECT_EQ(VN_ACTION_STEP_CANCELLED, step.state);
    EXPECT_EQ(VN_OK, step.result);
    EXPECT_EQ(0u, step.producedPlayableInstance);
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(fixture.firing, &info));
    EXPECT_EQ(VN_ACTION_TERMINAL_STOP_REQUESTED, info.terminalReason);
    while (engine->mixer.BlocksRendered() * blockFrames <=
           fixture.record.intendedBoundaryFrame + 8u * blockFrames) {
        ASSERT_EQ(VN_OK, Vn_Update());
        pumpAndCheckSilence();
    }
    EXPECT_GT(checkedAfterTarget, 8u * blockFrames);
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_EQ(0u, engine->containerPlayback.LiveCount());
    EXPECT_EQ(0u, engine->variableControlInstances.LiveCount());
    EXPECT_EQ(0u, engine->timelineArms.LiveCount());
    EXPECT_EQ(0u, engine->decisions.LiveCount());
}

TEST(PackComposition, PackActionDelayedVariableControlRetagPendingDeadlineFails) {
    DelayedPackPlayFixture fixture(MakeNullConfig(8, 256, 48000),
                                   "f5-vc-retag-pending-deadline",
                                   1000000000,
                                   DelayedPackPlayTarget::VariableControl);
    auto* engine = fixture.session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<PackPartitionLease> occupying;
    for (;;) {
        PackIdentityLookup lookup;
        const auto acquired = engine->AcquirePackIdentityLease(
            fixture.targetStableId, PackLeaseSlice::Playable, &lookup);
        if (acquired == VN_BACKPRESSURE) break;
        ASSERT_EQ(VN_OK, acquired);
        occupying.push_back(lookup.lease);
    }
    ASSERT_FALSE(occupying.empty());
    engine->forceActionVariableControlDeferredCleanupPendingOnceForTest = true;
    const auto retagBefore = engine->packComposition.RetagBackpressureCountForTests();
    for (std::uint32_t tick = 0; tick < 512 &&
         engine->packComposition.RetagBackpressureCountForTests() == retagBefore;
         ++tick) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_GT(engine->packComposition.RetagBackpressureCountForTests(), retagBefore);
    const auto owned = std::find_if(
        engine->actionPlayStorage.begin(), engine->actionPlayStorage.end(),
        [](const auto& attempt) {
            return attempt.deferredContainerOwner.active;
        });
    ASSERT_NE(engine->actionPlayStorage.end(), owned);
    ASSERT_EQ(EngineFrontierAttemptPhase::CancelPending, owned->phase);
    ASSERT_TRUE(owned->deferredContainerOwner.retryRequested);
    ASSERT_EQ(ActionDeferredRecordState::Claimed,
              engine->actionDeferredRecords.State(fixture.token));
    for (const auto& lease : occupying)
        ASSERT_EQ(VN_OK, engine->ReleasePackIdentityLease(lease));

    const auto blockFrames = engine->nullBackend.BlockFrames();
    const auto channels = engine->nullBackend.Channels();
    std::uint32_t checkedAfterTarget = 0;
    while (engine->mixer.BlocksRendered() * blockFrames <=
           fixture.record.intendedBoundaryFrame + 8u * blockFrames) {
        const auto blockStart = engine->mixer.BlocksRendered() * blockFrames;
        engine->nullBackend.Pump(1);
        const auto* pcm = engine->nullBackend.LastBlock();
        ASSERT_NE(nullptr, pcm);
        for (std::uint32_t frame = 0; frame < blockFrames; ++frame) {
            if (blockStart + frame < fixture.record.intendedBoundaryFrame)
                continue;
            ++checkedAfterTarget;
            for (std::uint32_t channel = 0; channel < channels; ++channel)
                EXPECT_NEAR(0.0f, pcm[frame * channels + channel], 1e-4f);
        }
    }
    EXPECT_GT(checkedAfterTarget, 8u * blockFrames);
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_EQ(0u, engine->actionDeferredRecords.LiveCount());
    EXPECT_EQ(0u, engine->timelineDeferred.Count());
    EXPECT_EQ(0u, engine->actionFirings.OwnedDeferredCount(fixture.firing));
    EXPECT_EQ(nullptr, fixture.LiveStartRow());
    EXPECT_EQ(VN_STALE_HANDLE, engine->packComposition.ValidateLease(
                                    fixture.record.targetPackLease));
    VnActionStepResult step{};
    step.structSize = sizeof(step);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(fixture.firing, 0, &step));
    EXPECT_EQ(VN_ACTION_STEP_FAILED, step.state);
    EXPECT_EQ(VN_BACKPRESSURE, step.result);
    EXPECT_EQ(0u, step.producedPlayableInstance);
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(fixture.firing, &info));
    EXPECT_EQ(VN_ACTION_TERMINAL_DEADLINE, info.terminalReason);
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_EQ(0u, engine->containerPlayback.LiveCount());
    EXPECT_EQ(0u, engine->variableControlInstances.LiveCount());
    EXPECT_EQ(0u, engine->timelineArms.LiveCount());
    EXPECT_EQ(0u, engine->decisions.LiveCount());
}

TEST(PackComposition, PackActionDelayedVariableControlRetagRetryKeepsOwnerOnPoolGenerationMismatch) {
    DelayedPackPlayFixture fixture(MakeNullConfig(8, 256, 48000),
                                   "f5-vc-retag-retry-generation",
                                   1000000000,
                                   DelayedPackPlayTarget::VariableControl);
    auto* engine = fixture.session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<PackPartitionLease> occupying;
    for (;;) {
        PackIdentityLookup lookup;
        const auto acquired = engine->AcquirePackIdentityLease(
            fixture.targetStableId, PackLeaseSlice::Playable, &lookup);
        if (acquired == VN_BACKPRESSURE) break;
        ASSERT_EQ(VN_OK, acquired);
        occupying.push_back(lookup.lease);
    }
    ASSERT_FALSE(occupying.empty());
    engine->forceActionVariableControlDeferredCleanupPendingOnceForTest = true;
    const auto retagBefore = engine->packComposition.RetagBackpressureCountForTests();
    for (std::uint32_t tick = 0; tick < 512 &&
         engine->packComposition.RetagBackpressureCountForTests() == retagBefore;
         ++tick) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_GT(engine->packComposition.RetagBackpressureCountForTests(), retagBefore);
    const auto owned = std::find_if(
        engine->actionPlayStorage.begin(), engine->actionPlayStorage.end(),
        [](const auto& attempt) {
            return attempt.deferredContainerOwner.active;
        });
    ASSERT_NE(engine->actionPlayStorage.end(), owned);
    ASSERT_EQ(EngineFrontierAttemptPhase::CancelPending, owned->phase);
    const auto original = owned->deferredContainerOwner.poolToken;
    ASSERT_EQ(ActionDeferredRecordState::Claimed,
              engine->actionDeferredRecords.State(fixture.token));

    ASSERT_TRUE(engine->timelineDeferred.Release(original));
    DeferredIntent replacement{};
    replacement.ownerDomain = DeferredIntentOwnerDomain::Action;
    replacement.ownerHandle = UINT64_MAX;
    const auto added = engine->timelineDeferred.AddClaimable(replacement);
    ASSERT_EQ(DeferredIntentRefusal::None, added.status);
    ASSERT_EQ(original.slot, added.token.slot);
    ASSERT_NE(original.generation, added.token.generation);
    DeferredIntentClaim claim{};
    ASSERT_EQ(1u, engine->timelineDeferred.ClaimDue(
        1, engine->playableInstances, &claim, 1));
    ASSERT_EQ(added.token.generation, claim.token.generation);

    for (const auto& lease : occupying)
        ASSERT_EQ(VN_OK, engine->ReleasePackIdentityLease(lease));
    (void)Vn_Update();
    EXPECT_TRUE(engine->runtimeRecreateRequired);
    EXPECT_TRUE(owned->deferredContainerOwner.active);
    EXPECT_TRUE(owned->deferredContainerOwner.fault);
    EXPECT_EQ(fixture.token.generation,
              owned->deferredContainerOwner.recordToken.generation);
    EXPECT_EQ(original.generation,
              owned->deferredContainerOwner.poolToken.generation);
    EXPECT_EQ(ActionDeferredRecordState::Claimed,
              engine->actionDeferredRecords.State(fixture.token));
    ActionDeferredPairState pair{};
    ASSERT_TRUE(engine->actionDeferredRecords.InspectPair(
        engine->timelineDeferred, original, fixture.token, &pair));
    EXPECT_EQ(added.token.generation, pair.poolToken.generation);
    EXPECT_EQ(DeferredIntentEntryState::Claimed, pair.poolState);
}

TEST(PackComposition, PackActionDelayedVariableControlRetagRetryResetFailureKeepsExactOwner) {
    DelayedPackPlayFixture fixture(MakeNullConfig(8, 256, 48000),
                                   "f5-vc-retag-retry-reset-failure",
                                   1000000000,
                                   DelayedPackPlayTarget::VariableControl);
    auto* engine = fixture.session.Engine();
    ASSERT_NE(nullptr, engine);
    std::vector<PackPartitionLease> occupying;
    for (;;) {
        PackIdentityLookup lookup;
        const auto acquired = engine->AcquirePackIdentityLease(
            fixture.targetStableId, PackLeaseSlice::Playable, &lookup);
        if (acquired == VN_BACKPRESSURE) break;
        ASSERT_EQ(VN_OK, acquired);
        occupying.push_back(lookup.lease);
    }
    ASSERT_FALSE(occupying.empty());
    engine->forceActionVariableControlDeferredCleanupPendingOnceForTest = true;
    const auto retagBefore = engine->packComposition.RetagBackpressureCountForTests();
    for (std::uint32_t tick = 0; tick < 512 &&
         engine->packComposition.RetagBackpressureCountForTests() == retagBefore;
         ++tick) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_GT(engine->packComposition.RetagBackpressureCountForTests(), retagBefore);
    const auto owned = std::find_if(
        engine->actionPlayStorage.begin(), engine->actionPlayStorage.end(),
        [](const auto& attempt) {
            return attempt.deferredContainerOwner.active;
        });
    ASSERT_NE(engine->actionPlayStorage.end(), owned);
    const auto generation = owned->generation;
    const auto poolToken = owned->deferredContainerOwner.poolToken;
    const auto targetLeaseToken =
        owned->deferredContainerOwner.targetLease.leaseToken;
    ASSERT_EQ(ActionDeferredRecordState::Claimed,
              engine->actionDeferredRecords.State(fixture.token));
    engine->forceActionVariableControlDeferredRetryResetFailureOnceForTest = true;
    for (const auto& lease : occupying)
        ASSERT_EQ(VN_OK, engine->ReleasePackIdentityLease(lease));
    ASSERT_EQ(VN_OK, Vn_Update());
    ASSERT_FALSE(engine->forceActionVariableControlDeferredRetryResetFailureOnceForTest);
    ASSERT_TRUE(owned->deferredContainerOwner.active);
    ASSERT_TRUE(owned->deferredContainerOwner.fault);
    ASSERT_TRUE(owned->deferredContainerOwner.retryApplied);
    ASSERT_EQ(generation, owned->generation);
    EXPECT_EQ(targetLeaseToken,
              owned->deferredContainerOwner.targetLease.leaseToken);
    EXPECT_EQ(VN_OK, engine->packComposition.ValidateLease(
                         fixture.record.targetPackLease));
    ASSERT_EQ(ActionDeferredRecordState::Held,
              engine->actionDeferredRecords.State(fixture.token));
    ActionDeferredPairState pair{};
    ASSERT_TRUE(engine->actionDeferredRecords.InspectPair(
        engine->timelineDeferred, poolToken, fixture.token, &pair));
    ASSERT_EQ(DeferredIntentEntryState::Held, pair.poolState);
    ASSERT_TRUE(pair.recordReservation.Valid());
    ASSERT_TRUE(pair.poolReservation.Valid());
    EXPECT_EQ(fixture.token.slot, pair.recordReservation.recordSlot);
    EXPECT_EQ(fixture.token.generation,
              pair.recordReservation.recordGeneration);
    EXPECT_EQ(poolToken.slot, pair.poolReservation.poolToken.slot);
    EXPECT_EQ(poolToken.generation,
              pair.poolReservation.poolToken.generation);
    for (std::uint32_t tick = 0; tick < 4; ++tick) {
        engine->nullBackend.Pump(1);
        (void)Vn_Update();
        EXPECT_EQ(generation, owned->generation);
        EXPECT_TRUE(owned->deferredContainerOwner.active);
        EXPECT_TRUE(owned->deferredContainerOwner.fault);
        EXPECT_EQ(fixture.token.generation,
                  owned->deferredContainerOwner.recordToken.generation);
        EXPECT_EQ(poolToken.generation,
                  owned->deferredContainerOwner.poolToken.generation);
        EXPECT_EQ(targetLeaseToken,
                  owned->deferredContainerOwner.targetLease.leaseToken);
        EXPECT_EQ(VN_OK, engine->packComposition.ValidateLease(
                             fixture.record.targetPackLease));
        EXPECT_EQ(ActionDeferredRecordState::Held,
                  engine->actionDeferredRecords.State(fixture.token));
        ASSERT_TRUE(engine->actionDeferredRecords.InspectPair(
            engine->timelineDeferred, poolToken, fixture.token, &pair));
        EXPECT_EQ(DeferredIntentEntryState::Held, pair.poolState);
        EXPECT_TRUE(pair.recordReservation.Valid());
        EXPECT_TRUE(pair.poolReservation.Valid());
        const auto owners = std::count_if(
            engine->actionPlayStorage.begin(), engine->actionPlayStorage.end(),
            [&](const auto& attempt) {
                return attempt.deferredContainerOwner.active &&
                    attempt.deferredContainerOwner.recordToken.slot == fixture.token.slot &&
                    attempt.deferredContainerOwner.recordToken.generation == fixture.token.generation;
            });
        EXPECT_EQ(1, owners);
        EXPECT_EQ(nullptr, fixture.LiveStartRow());
        EXPECT_EQ(0u, engine->voices.ActiveCount());
    }
    ASSERT_EQ(VN_OK, Vn_StopActionFiring(fixture.firing, 0));
    EXPECT_EQ(ActionDeferredRecordState::CancelRequested,
              engine->actionDeferredRecords.State(fixture.token));
    ASSERT_TRUE(engine->actionDeferredRecords.InspectPair(
        engine->timelineDeferred, poolToken, fixture.token, &pair));
    EXPECT_EQ(DeferredIntentEntryState::Held, pair.poolState);
    EXPECT_TRUE(pair.recordReservation.Valid());
    EXPECT_TRUE(pair.poolReservation.Valid());
    EXPECT_TRUE(owned->deferredContainerOwner.active);
    EXPECT_EQ(targetLeaseToken,
              owned->deferredContainerOwner.targetLease.leaseToken);
    EXPECT_EQ(0u, engine->voices.ActiveCount());
}

TEST(PackComposition, PackActionDelayedNearBoundaryRetainsAuthoredStart) {
    DelayedPackPlayFixture fixture(MakeNullConfig(8, 256, 48000),
                                   "f5-delayed-near-boundary");
    ASSERT_EQ(VN_OK, fixture.session.InitResult());
    auto* engine = fixture.session.Engine();
    std::vector<PackPartitionLease> occupying;
    for (;;) {
        PackIdentityLookup lookup;
        const VnResult acquired = engine->AcquirePackIdentityLease(
            fixture.targetStableId, PackLeaseSlice::Playable, &lookup);
        if (acquired == VN_BACKPRESSURE) break;
        ASSERT_EQ(VN_OK, acquired);
        occupying.push_back(lookup.lease);
    }
    ASSERT_FALSE(occupying.empty());
    while (engine->mixer.BlocksRendered() < 188u) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_EQ(49024u, fixture.record.intendedBoundaryFrame);
    ASSERT_EQ(48896u, engine->timelinePool.PublishCutoffFrame());
    ASSERT_EQ(188u, engine->timelinePool.ConsumerFrontier().load(
                        std::memory_order_acquire));
    ASSERT_GT(engine->timelinePool.WindowEndFrame(),
              fixture.record.intendedBoundaryFrame);
    ASSERT_GT(engine->mixer.BlocksRendered() * 256u +
                  engine->timelinePool.PublishLeadQuanta() * 256u,
              fixture.record.intendedBoundaryFrame);
    ASSERT_EQ(1u, engine->actionDeferredRecords.LiveCount());
    for (const auto& lease : occupying)
        ASSERT_EQ(VN_OK, engine->ReleasePackIdentityLease(lease));

    std::uint64_t firstAudibleFrame = UINT64_MAX;
    bool materialized = false;
    for (std::uint32_t block = 0; block < 20u; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        if (!materialized && engine->actionDeferredRecords.LiveCount() == 0) {
            VnActionStepResult step{};
            step.structSize = sizeof(step);
            EXPECT_EQ(VN_OK, Vn_QueryActionStep(fixture.firing, 0, &step));
            EXPECT_EQ(VN_ACTION_STEP_ACTIVE, step.state);
            EXPECT_EQ(VN_OK, step.result);
            EXPECT_EQ(48896u, engine->timelinePool.PublishCutoffFrame());
            const auto* row = fixture.LiveStartRow();
            ASSERT_NE(nullptr, row);
            EXPECT_EQ(EnginePlayableStartPhase::AwaitingArmAck, row->phase);
        }
        materialized |= engine->actionDeferredRecords.LiveCount() == 0;
        if (const auto* row = fixture.LiveStartRow())
            EXPECT_EQ(fixture.record.intendedBoundaryFrame, row->startFrame);
        const std::uint64_t blockStart = engine->mixer.BlocksRendered() * 256u;
        engine->nullBackend.Pump(1);
        const float* pcm = engine->nullBackend.LastBlock();
        const auto channels = engine->nullBackend.Channels();
        ASSERT_GT(channels, 0u);
        for (std::uint32_t frame = 0; frame < 256u; ++frame) {
            const float left = pcm[frame * channels];
            if (blockStart + frame < fixture.record.intendedBoundaryFrame)
                EXPECT_NEAR(0.0f, left, 1e-4f);
            if (firstAudibleFrame == UINT64_MAX && std::abs(left) > 1e-4f)
                firstAudibleFrame = blockStart + frame;
        }
    }
    EXPECT_TRUE(materialized);
    EXPECT_EQ(fixture.record.intendedBoundaryFrame, firstAudibleFrame);
    fixture.PumpUntilFiringTerminal();
    EXPECT_EQ(VN_STALE_HANDLE,
              engine->packComposition.ValidateLease(fixture.record.targetPackLease));
}

TEST(PackComposition, PackActionDelayedAdmissionRecheckRejectsPastTarget) {
    DelayedPackPlayFixture fixture(MakeNullConfig(8, 256, 48000),
                                   "f5-delayed-recheck-past-target");
    ASSERT_EQ(VN_OK, fixture.session.InitResult());
    auto* engine = fixture.session.Engine();
    std::vector<PackPartitionLease> occupying;
    for (;;) {
        PackIdentityLookup lookup;
        const VnResult acquired = engine->AcquirePackIdentityLease(
            fixture.targetStableId, PackLeaseSlice::Playable, &lookup);
        if (acquired == VN_BACKPRESSURE) break;
        ASSERT_EQ(VN_OK, acquired);
        occupying.push_back(lookup.lease);
    }
    ASSERT_FALSE(occupying.empty());
    while (engine->mixer.BlocksRendered() < 188u) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_EQ(49024u, fixture.record.intendedBoundaryFrame);
    ASSERT_EQ(48896u, engine->timelinePool.PublishCutoffFrame());
    for (const auto& lease : occupying)
        ASSERT_EQ(VN_OK, engine->ReleasePackIdentityLease(lease));

    struct RecheckProbe {
        bool called = false;
        bool audible = false;
        std::uint64_t beforeRendered = 0;
        std::uint64_t beforeFrontier = 0;
        std::uint64_t afterRendered = 0;
        std::uint64_t afterFrontier = 0;
    } probe;
    engine->actionAdmissionRecheckHookForTest = [](Engine& current,
                                                    void* opaque) {
        auto& state = *static_cast<RecheckProbe*>(opaque);
        state.called = true;
        state.beforeRendered = current.mixer.BlocksRendered();
        state.beforeFrontier = current.timelinePool.ConsumerFrontier().load(
            std::memory_order_acquire);
        for (std::uint32_t block = 0; block < 4u; ++block) {
            current.nullBackend.Pump(1);
            const float* pcm = current.nullBackend.LastBlock();
            const auto count = current.nullBackend.BlockFrames() *
                               current.nullBackend.Channels();
            for (std::uint32_t sample = 0; sample < count; ++sample)
                state.audible |= std::abs(pcm[sample]) > 1e-4f;
        }
        state.afterRendered = current.mixer.BlocksRendered();
        state.afterFrontier = current.timelinePool.ConsumerFrontier().load(
            std::memory_order_acquire);
    };
    engine->actionAdmissionRecheckContextForTest = &probe;
    const VnResult firstUpdate = Vn_Update();
    engine->actionAdmissionRecheckHookForTest = nullptr;
    engine->actionAdmissionRecheckContextForTest = nullptr;
    ASSERT_EQ(VN_OK, firstUpdate);
    ASSERT_TRUE(probe.called);
    EXPECT_FALSE(probe.audible);
    EXPECT_EQ(188u, probe.beforeRendered);
    EXPECT_EQ(188u, probe.beforeFrontier);
    EXPECT_EQ(192u, probe.afterRendered);
    EXPECT_LT(probe.afterFrontier, probe.afterRendered);
    EXPECT_EQ(192u, engine->mixer.BlocksRendered());
    EXPECT_EQ(nullptr, fixture.LiveStartRow());
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_FALSE(engine->actionPlayScratch[0].prepared);
    if (engine->actionDeferredRecords.LiveCount() != 0) {
        EXPECT_EQ(VN_OK,
                  engine->packComposition.ValidateLease(
                      fixture.record.targetPackLease));
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_EQ(0u, engine->actionDeferredRecords.LiveCount());
    EXPECT_EQ(nullptr, fixture.LiveStartRow());
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    VnActionStepResult step{};
    step.structSize = sizeof(step);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(fixture.firing, 0, &step));
    EXPECT_EQ(VN_ACTION_STEP_FAILED, step.state);
    EXPECT_EQ(VN_BACKPRESSURE, step.result);
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(fixture.firing, &info));
    EXPECT_EQ(VN_ACTION_TERMINAL_DEADLINE, info.terminalReason);
    EXPECT_EQ(VN_STALE_HANDLE,
              engine->packComposition.ValidateLease(fixture.record.targetPackLease));
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_EQ(0u, engine->actionDeferredRecords.LiveCount());
    EXPECT_EQ(nullptr, fixture.LiveStartRow());
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(VN_STALE_HANDLE,
              engine->packComposition.ValidateLease(fixture.record.targetPackLease));
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(fixture.firing, 0, &step));
    EXPECT_EQ(VN_ACTION_STEP_FAILED, step.state);
    EXPECT_EQ(VN_BACKPRESSURE, step.result);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(fixture.firing));
    fixture.firing = 0;
    EXPECT_FALSE(engine->packComposition.HasLiveLease(
        fixture.packStableId, fixture.partitionRevision,
        fixture.resourceRevision));
}

