TEST(PackComposition, PackActionDelayedPlayCommitFailureAfterRetagReleasesLeaseOnce) {
    DelayedPackPlayFixture fixture(MakeNullConfig(8, 256, 48000),
                                   "f5-delayed-commit-fail");
    ASSERT_EQ(VN_OK, fixture.session.InitResult());
    fixture.session.Engine()->forceActionPlayCommitFailureForTest = true;
    fixture.PumpUntilDeferredGone();
    EXPECT_FALSE(fixture.session.Engine()->forceActionPlayCommitFailureForTest);
    EXPECT_TRUE(fixture.session.Engine()->runtimeRecreateRequired);
    EXPECT_EQ(0u, fixture.session.Engine()->voices.ActiveCount());
    EXPECT_EQ(0u, fixture.session.Engine()->playableInstances.LiveCount());
    EXPECT_EQ(VN_STALE_HANDLE,
              fixture.session.Engine()->packComposition.ValidateLease(
                  fixture.record.targetPackLease));
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(fixture.firing));
    EXPECT_FALSE(fixture.session.Engine()->packComposition.HasLiveLease(
        fixture.packStableId, fixture.partitionRevision,
        fixture.resourceRevision));
    PackIdentityLookup extraPlayable;
    EXPECT_EQ(VN_OK, fixture.session.Engine()->packComposition.PrepareLookup(
                         fixture.targetStableId, PackLeaseSlice::Playable,
                         &extraPlayable));
    fixture.session.Engine()->packComposition.AbandonPreparedLease(
        extraPlayable.lease);
    EXPECT_EQ(nullptr, fixture.LiveStartRow());
}

