void VerifyPackActionDelayedRetainedClaimAcrossCancelRequest(
    ActionTerminalReason reason, const char* label) {
    DelayedPackPlayFixture fixture(MakeNullConfig(8, 256, 48000),
                                   label);
    ASSERT_EQ(VN_OK, fixture.session.InitResult());
    auto* engine = fixture.session.Engine();
    engine->holdOrdinaryDeferredPageCancellationForTest = true;
    engine->forceActionPlayPostTransferCommitFailureForTest = true;
    for (std::uint32_t step = 0; step < 1024 &&
         engine->forceActionPlayPostTransferCommitFailureForTest; ++step) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_FALSE(engine->forceActionPlayPostTransferCommitFailureForTest);
    const auto* row = fixture.LiveStartRow();
    ASSERT_NE(nullptr, row);
    ASSERT_TRUE(row->ordinaryStartTransaction.Valid());
    const auto unpublishedQuantum =
        row->ordinaryStartTransaction.absoluteQuantum;
    EXPECT_TRUE(row->ordinaryStartCancelProof);
    EXPECT_FALSE(row->ordinaryStartPageRemoved);
    EXPECT_TRUE(engine->timelinePool.HasProgramReference(
        row->schedule.runtimeProgram));
    EXPECT_NE(unpublishedQuantum,
              engine->timelinePool.PageStamp(unpublishedQuantum));
    EXPECT_EQ(1u, engine->timelineDeferred.Count());
    ASSERT_EQ(1u, engine->actionDeferredRecords.LiveCount());
    EXPECT_EQ(ActionDeferredRecordState::Claimed,
              engine->actionDeferredRecords.State(fixture.token));
    EXPECT_EQ(1u, engine->actionFirings.OwnedDeferredCount(fixture.firing));
    const auto retained = std::find_if(
        engine->actionPlayStorage.begin(), engine->actionPlayStorage.end(),
        [](const EngineActionPlayStorage& attempt) {
            return attempt.ordinaryDeferredRollback.active;
        });
    ASSERT_NE(engine->actionPlayStorage.end(), retained);
    const auto attemptSlot = static_cast<std::uint32_t>(
        retained - engine->actionPlayStorage.begin());
    DeferredIntentToken poolToken{};
    ASSERT_TRUE(engine->actionDeferredRecords.PoolToken(
        fixture.token, &poolToken));
    EXPECT_EQ(poolToken.slot,
              retained->ordinaryDeferredRollback.poolToken.slot);
    EXPECT_EQ(poolToken.generation,
              retained->ordinaryDeferredRollback.poolToken.generation);
    EXPECT_EQ(fixture.token.slot,
              retained->ordinaryDeferredRollback.recordToken.slot);
    EXPECT_EQ(fixture.token.generation,
              retained->ordinaryDeferredRollback.recordToken.generation);
    EXPECT_EQ(fixture.firing,
              retained->ordinaryDeferredRollback.firing);
    EXPECT_EQ(attemptSlot, row->privateOrdinaryDeferredRollbackSlot);
    EXPECT_EQ(retained->generation,
              row->privateOrdinaryDeferredRollbackGeneration);
    EXPECT_EQ(EngineFrontierAttemptPhase::CancelPending, retained->phase);
    EXPECT_FALSE(retained->ordinaryDeferredRollback.rowReleased);
    ASSERT_TRUE(engine->actionFirings.MarkTreeStopping(
        fixture.firing, reason));
    ASSERT_EQ(ActionDeferredCancelOwnership::Claimant,
              engine->actionDeferredRecords.RequestCancel(fixture.token));
    ASSERT_EQ(ActionDeferredRecordState::CancelRequested,
              engine->actionDeferredRecords.State(fixture.token));
    for (std::uint32_t step = 0; step < 2; ++step) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        const auto* pcm = engine->nullBackend.LastBlock();
        for (std::uint32_t sample = 0;
             sample < engine->nullBackend.BlockFrames() *
                          engine->nullBackend.Channels(); ++sample)
            EXPECT_NEAR(0.0f, pcm[sample], 1e-4f);
        EXPECT_EQ(1u, engine->actionDeferredRecords.LiveCount());
        EXPECT_EQ(1u, engine->timelineDeferred.Count());
        EXPECT_TRUE(retained->ordinaryDeferredRollback.active);
        EXPECT_FALSE(retained->ordinaryDeferredRollback.rowReleased);
        EXPECT_EQ(row, fixture.LiveStartRow());
        EXPECT_FALSE(row->ordinaryStartPageRemoved);
        EXPECT_TRUE(engine->timelinePool.HasProgramReference(
            row->schedule.runtimeProgram));
        EXPECT_NE(unpublishedQuantum,
                  engine->timelinePool.PageStamp(unpublishedQuantum));
        EXPECT_EQ(VN_OK, engine->packComposition.ValidateLease(
            fixture.record.targetPackLease));
    }
    engine->holdOrdinaryDeferredPageCancellationForTest = false;
    for (std::uint32_t step = 0; step < 64 &&
         engine->actionDeferredRecords.LiveCount() != 0; ++step) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    EXPECT_EQ(0u, engine->actionDeferredRecords.LiveCount());
    EXPECT_EQ(0u, engine->timelineDeferred.Count());
    EXPECT_EQ(0u, engine->actionFirings.OwnedDeferredCount(fixture.firing));
    EXPECT_EQ(VN_STALE_HANDLE,
              engine->packComposition.ValidateLease(
                  fixture.record.targetPackLease));
    EXPECT_EQ(nullptr, fixture.LiveStartRow());
    ASSERT_EQ(VN_OK, Vn_Update());
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_EQ(0u, engine->actionDeferredRecords.LiveCount());
    EXPECT_EQ(0u, engine->timelineDeferred.Count());
    EXPECT_EQ(0u, engine->actionFirings.OwnedDeferredCount(fixture.firing));
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(fixture.firing));
}

