TEST(PackComposition,
     PackActionDelayedRetainedPageBlocksPublicationInMaterializingUpdate) {
    DelayedPackPlayFixture fixture(MakeNullConfig(8, 256, 48000),
                                   "f5-delayed-private-page-first-cutoff");
    ASSERT_EQ(VN_OK, fixture.session.InitResult());
    auto* engine = fixture.session.Engine();
    ASSERT_EQ(1u, engine->actionDeferredRecords.LiveCount());
    const auto targetQuantum = fixture.record.intendedBoundaryFrame /
        engine->config.blockFrames;
    const auto priorStamp = engine->timelinePool.PageStamp(targetQuantum);
    const auto priorCutoff = engine->timelinePool.PublishCutoffFrame();
    ASSERT_NE(targetQuantum, priorStamp);
    engine->holdOrdinaryDeferredPageCancellationForTest = true;
    engine->forceRetainedPagePublicationPressureForTest = true;
    engine->forceActionPlayPostTransferCommitFailureForTest = true;
    for (std::uint32_t step = 0; step < 1024 &&
         engine->forceActionPlayPostTransferCommitFailureForTest; ++step) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_FALSE(engine->forceActionPlayPostTransferCommitFailureForTest);
    const auto* row = fixture.LiveStartRow();
    ASSERT_NE(nullptr, row);
    ASSERT_TRUE(row->ordinaryStartTransaction.Valid());
    ASSERT_TRUE(row->ordinaryStartCancelProof);
    const auto quantum = row->ordinaryStartTransaction.absoluteQuantum;
    EXPECT_EQ(targetQuantum, quantum);
    EXPECT_LE(priorCutoff, row->startFrame);
    EXPECT_FALSE(row->ordinaryStartPageRemoved);
    EXPECT_TRUE(engine->timelinePool.HasProgramReference(
        row->schedule.runtimeProgram));
    EXPECT_NE(quantum, engine->timelinePool.PageStamp(quantum))
        << "the newly retained Page must block this same Update's publish";
    EXPECT_LE(engine->timelinePool.PublishCutoffFrame(), row->startFrame);
    engine->forceRetainedPagePublicationPressureForTest = false;
    engine->holdOrdinaryDeferredPageCancellationForTest = false;
}

TEST(PackComposition,
     PackActionDelayedRollbackCleanupKeepsFatalPostGate) {
    DelayedPackPlayFixture fixture(MakeNullConfig(8, 256, 48000),
                                   "f5-delayed-private-owner-reuse");
    ASSERT_EQ(VN_OK, fixture.session.InitResult());
    auto* engine = fixture.session.Engine();
    engine->holdOrdinaryDeferredPageCancellationForTest = true;
    engine->forceActionPlayPostTransferCommitFailureForTest = true;
    for (std::uint32_t step = 0; step < 1024 &&
         engine->forceActionPlayPostTransferCommitFailureForTest; ++step) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_FALSE(engine->forceActionPlayPostTransferCommitFailureForTest);
    ASSERT_EQ(1u, engine->actionDeferredRecords.LiveCount());
    const auto first = std::find_if(
        engine->actionPlayStorage.begin(), engine->actionPlayStorage.end(),
        [&](const EngineActionPlayStorage& attempt) {
            return attempt.ordinaryDeferredRollback.firing == fixture.firing;
        });
    ASSERT_NE(engine->actionPlayStorage.end(), first);
    ASSERT_TRUE(first->ordinaryDeferredRollback.active);
    engine->holdOrdinaryDeferredPageCancellationForTest = false;
    for (std::uint32_t step = 0; step < 64 &&
         engine->actionDeferredRecords.LiveCount() != 0; ++step) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_EQ(0u, engine->actionDeferredRecords.LiveCount());
    ASSERT_EQ(EngineFrontierAttemptPhase::Free, first->phase);
    ASSERT_FALSE(first->ordinaryDeferredRollback.active);
    EXPECT_TRUE(engine->runtimeRecreateRequired);
    EXPECT_FALSE(first->ordinaryDeferredRollback.fault);
    EXPECT_EQ(0u, engine->timelineDeferred.Count());
    EXPECT_EQ(0u, engine->actionFirings.OwnedDeferredCount(fixture.firing));
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_EQ(nullptr, fixture.LiveStartRow());
    EXPECT_EQ(VN_STALE_HANDLE, engine->packComposition.ValidateLease(fixture.record.targetPackLease));
    const auto firingsBefore = engine->actionFirings.LiveCount();
    VnPostActionDesc post{};
    post.structSize = sizeof(post);
    post.actionId = harkentest::ObjectId(2002);
    VnActionFiringHandle secondFiring = UINT64_MAX;
    EXPECT_EQ(VN_RUNTIME_RECREATE_REQUIRED, Vn_PostAction(&post, &secondFiring));
    EXPECT_EQ(0u, secondFiring);
    EXPECT_EQ(firingsBefore, engine->actionFirings.LiveCount());
    EXPECT_EQ(0u, engine->actionDeferredRecords.LiveCount());
    EXPECT_EQ(0u, engine->timelineDeferred.Count());
    EXPECT_EQ(EngineFrontierAttemptPhase::Free, first->phase);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(fixture.firing));
    fixture.firing = 0;
}

TEST(PackComposition, PackActionDelayedHealthyNativeAttemptReuseAdvancesActualGeneration) {
    DelayedPackPlayFixture fixture(MakeNullConfig(8, 256, 48000),
                                   "f5-delayed-healthy-native-reuse");
    ASSERT_EQ(VN_OK, fixture.session.InitResult());
    auto& engine = *fixture.session.Engine();
    struct ActualReserves {
        EngineActionPlayStorage* storage = nullptr;
        EnginePlayableServiceReference first{};
        std::uint64_t firstGeneration = 0;
        std::uint32_t roots = 0;
    } actual;
    engine.originalPlayableServiceReservedContextForTest = &actual;
    engine.originalPlayableServiceReservedHookForTest = [](
        Engine&, const Engine::OriginalPlayableServiceLifetimeHolder& original, void* opaque) {
        auto& output = *static_cast<ActualReserves*>(opaque);
        auto* row = detail::EngineOriginalServiceStorageTestAccess::ActualService(original);
        ASSERT_NE(nullptr, row);
        if (row->Invocation().rootService != row->identity) return;
        auto* storage = row->Invocation().preparingStorage;
        ASSERT_NE(nullptr, storage);
        EXPECT_FALSE(storage->ordinaryDeferredRollback.active);
        EXPECT_FALSE(storage->ordinaryDeferredRollback.fault);
        if (output.roots++ == 0) {
            output.storage = storage;
            output.first = original.FactoryReference();
            output.firstGeneration = storage->generation;
        } else {
            EXPECT_EQ(output.storage, storage);
            EXPECT_GT(storage->generation, output.firstGeneration);
            EXPECT_GT(original.FactoryReference().invocationGeneration, output.first.invocationGeneration);
        }
    };
    for (unsigned episode = 0; episode < 2; ++episode) {
        fixture.PumpUntilDeferredGone();
        ASSERT_EQ(episode + 1u, actual.roots);
        ASSERT_NE(nullptr, actual.storage);
        const auto lease = fixture.record.targetPackLease;
        const auto* row = fixture.LiveStartRow();
        ASSERT_NE(nullptr, row);
        EXPECT_EQ(lease.leaseToken, row->Invocation().packLease.leaseToken);
        EXPECT_FALSE(engine.runtimeRecreateRequired);
        bool audible = false;
        for (unsigned block = 0; block < 1024 &&
             engine.mixer.BlocksRendered() * engine.config.blockFrames <
                 fixture.record.intendedBoundaryFrame + 2048u; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine.nullBackend.Pump(1);
            const float* pcm = engine.nullBackend.LastBlock();
            for (std::uint32_t sample = 0;
                 sample < engine.nullBackend.BlockFrames() * engine.nullBackend.Channels(); ++sample)
                audible = audible || std::abs(pcm[sample]) > 1e-4f;
        }
        EXPECT_TRUE(audible);
        fixture.PumpUntilFiringTerminal();
        for (unsigned block = 0; block < 96 && engine.packComposition.ValidateLease(lease) == VN_OK; ++block) {
            engine.nullBackend.Pump(1);
            ASSERT_EQ(VN_OK, Vn_Update());
        }
        ASSERT_EQ(VN_STALE_HANDLE, engine.packComposition.ValidateLease(lease));
        ASSERT_EQ(nullptr, fixture.LiveStartRow());
        ASSERT_EQ(EngineFrontierAttemptPhase::Free, actual.storage->phase);
        ASSERT_FALSE(actual.storage->ordinaryDeferredRollback.active);
        ASSERT_FALSE(actual.storage->ordinaryDeferredRollback.fault);
        ASSERT_FALSE(engine.runtimeRecreateRequired);
        if (episode == 0) {
            VnPostActionDesc post{};
            post.structSize = sizeof(post);
            post.actionId = harkentest::ObjectId(2002);
            ASSERT_EQ(VN_OK, Vn_PostAction(&post, &fixture.firing));
            ASSERT_NE(0u, fixture.firing);
            const auto oldToken = fixture.token;
            ASSERT_TRUE(engine.actionDeferredRecords.CaptureAt(oldToken.slot, &fixture.token,
                                                               &fixture.record, &fixture.state));
            EXPECT_GT(fixture.token.generation, oldToken.generation);
            EXPECT_EQ(ActionDeferredRecordState::Held, fixture.state);
        }
    }
    engine.originalPlayableServiceReservedHookForTest = nullptr;
    engine.originalPlayableServiceReservedContextForTest = nullptr;
}

void PumpUntilAudible(EngineSession& session, harkentest::Capture* capture,
                      std::uint32_t blocks = 16) {
    for (std::uint32_t block = 0; block < blocks; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        session.Engine()->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        capture->left.insert(
            capture->left.end(), session.Engine()->nullBackend.LastBlock(),
            session.Engine()->nullBackend.LastBlock() +
                session.Engine()->nullBackend.BlockFrames());
    }
}

std::vector<std::uint8_t> ImmediateNestedRandomPlayPartitionPayload(
    std::uint64_t packStableId, std::uint64_t partitionRevision,
    VnObjectId actionId, VnObjectId parentId, VnObjectId childId,
    VnObjectId soundId, std::uint64_t contentRevision) {
    PlayablePropertyProgramViewV1 sound = MakeSoundProperty(soundId);
    sound.contentRevision = contentRevision;
    sound.programSemanticFingerprint = ComputePlayablePropertyFingerprintV1(sound);
    PlayablePropertyProgramViewV1 parentProperty = MakeContainerProperty(parentId, 1);
    PlayablePropertyProgramViewV1 childProperty = MakeContainerProperty(childId, 2);
    const PlayableRefV1 soundRef = PlayableRefFromProperty(sound);
    const PlayableRefV1 childRef = PlayableRefFromProperty(childProperty);
    ContainerChildProgramViewV2 nestedChild{};
    nestedChild.playable = soundRef;
    nestedChild.frequencyWeight = 1;
    nestedChild.stableChildOrdinal = 7;
    ContainerProgramViewV3 nestedProgram = MakeContainerProgram(
        childId, childProperty.programSemanticFingerprint, 2);
    nestedProgram.memoryScope = MemoryScopeV1::Global;
    nestedProgram.childCount = 1;
    nestedProgram.children = &nestedChild;
    ContainerChildProgramViewV2 parentChild{};
    parentChild.playable = childRef;
    parentChild.frequencyWeight = 1;
    parentChild.stableChildOrdinal = 8;
    ContainerProgramViewV3 parentProgram = MakeContainerProgram(
        parentId, parentProperty.programSemanticFingerprint, 1);
    parentProgram.memoryScope = MemoryScopeV1::Global;
    parentProgram.childCount = 1;
    parentProgram.children = &parentChild;
    ContainerProgramViewV3 programs[2] = {parentProgram, nestedProgram};
    PlayableOccurrencePropertyViewV1 occurrences[2]{};
    occurrences[0].parentKind = playableproperties::ContentPropertyKindV1::Container;
    occurrences[0].parentStableId = harkentest::ObjectId(parentId);
    occurrences[0].parentProgramSemanticFingerprint =
        parentProperty.programSemanticFingerprint;
    occurrences[0].stableOccurrenceOrdinal = parentChild.stableChildOrdinal;
    occurrences[0].childPlayable = childRef;
    occurrences[0].payload = EmptyOccurrencePayload();
    occurrences[0].occurrenceSemanticFingerprint =
        ComputePlayableOccurrenceFingerprintV1(occurrences[0]);
    occurrences[1] = occurrences[0];
    occurrences[1].parentStableId = harkentest::ObjectId(childId);
    occurrences[1].parentProgramSemanticFingerprint =
        childProperty.programSemanticFingerprint;
    occurrences[1].stableOccurrenceOrdinal = nestedChild.stableChildOrdinal;
    occurrences[1].childPlayable = soundRef;
    occurrences[1].occurrenceSemanticFingerprint =
        ComputePlayableOccurrenceFingerprintV1(occurrences[1]);
    PlayablePropertyProgramViewV1 properties[3] = {sound, parentProperty,
                                                   childProperty};
    ActionStepProgramViewV1 step{};
    step.opcode = ActionOpcodeV1::Play;
    step.target.kind = ActionTargetKindV1::Container;
    step.target.stableId = harkentest::ObjectId(parentId);
    step.target.expectedProgramSemanticFingerprint =
        parentProperty.programSemanticFingerprint;
    SetAbsoluteTime(&step.delay, 0);
    SetAbsoluteTime(&step.fade, 0);
    SetAbsoluteTime(&step.cooldown, 0);
    ActionProgramViewV1 action{};
    action.actionStableId = actionId;
    action.steps = &step;
    action.stepCount = 1;
    action.directFeatureMask = 0;
    action.transitiveFeatureMask = 0;
    action.expandedStepOccurrenceCount = 1;
    action.expandedFiringCount = 1;
    action.programSemanticFingerprint = ComputeActionProgramFingerprintV1(action);
    ContainerWorldInstallViewV1 world{};
    world.identity.capabilityMask = kWorldCapabilityActionDefinitions |
                                    kWorldCapabilityPlayableProperties |
                                    kWorldCapabilityRandomDraw;
    world.playableProperties = properties;
    world.playablePropertyCount = 3;
    world.playableOccurrences = occurrences;
    world.playableOccurrenceCount = 2;
    world.containers = programs;
    world.containerCount = 2;
    world.actions = &action;
    world.actionCount = 1;
    world.capacity.maxKnownScheduleLeaves = 16;
    world.capacity.maxTrackPieceScheduleDepth = 8;
    world.identity.runtimeSemanticFingerprint =
        ComputeCurrentWorldFingerprintV4(world);
    return WrapWorldPartition(packStableId, partitionRevision, world, 4);
}

std::vector<std::uint8_t> BuildImmediateNestedRandomPlayPack(
    std::uint64_t packStableId, std::uint64_t contentRevision,
    std::uint64_t partitionRevision, VnObjectId actionId,
    VnObjectId parentId, VnObjectId childId, VnObjectId soundId,
    std::vector<float> planar) {
    const float* channels[1] = {planar.data()};
    std::uint64_t mediaRevision = 0;
    EXPECT_TRUE(ComputeMediaPcmContentRevisionV1(
        48000, 1, static_cast<std::uint64_t>(planar.size()), channels, 1,
        &mediaRevision));
    ImageBuilder builder(kPackKindCanonicalContent);
    builder.AddEntry(kPackEntryKindPackRequirementBlock, packStableId,
                     RequirementPayload(packStableId, contentRevision,
                                        partitionRevision));
    builder.AddEntry(kPackEntryKindCanonicalDefinitionPartition, packStableId,
                     ImmediateNestedRandomPlayPartitionPayload(
                         packStableId, partitionRevision, actionId, parentId,
                         childId, soundId, mediaRevision));
    builder.AddMedia(soundId, std::move(planar));
    return builder.Build();
}

std::vector<std::uint8_t> ImmediateNestedQueueContainerPlayPartitionPayload(
    std::uint64_t packStableId, std::uint64_t partitionRevision,
    VnObjectId actionId, VnObjectId parentId, VnObjectId queueId,
    VnObjectId firstSoundId, VnObjectId secondSoundId,
    std::uint64_t firstRevision, std::uint64_t secondRevision,
    std::uint32_t queueLoopCount = 1,
    MemoryScopeV1 queueMemoryScope = MemoryScopeV1::Emitter,
    VnBusId route = VN_BUS_MASTER) {
    PlayablePropertyProgramViewV1 firstSound = MakeSoundProperty(firstSoundId);
    firstSound.contentRevision = firstRevision;
    firstSound.routeStableId = route;
    firstSound.payload.values[6].objectId = route;
    firstSound.programSemanticFingerprint =
        ComputePlayablePropertyFingerprintV1(firstSound);
    PlayablePropertyProgramViewV1 secondSound = MakeSoundProperty(secondSoundId);
    secondSound.authoredStableOrder = 1;
    secondSound.contentRevision = secondRevision;
    secondSound.routeStableId = route;
    secondSound.payload.values[6].objectId = route;
    secondSound.compatibilityFingerprint = 5;
    secondSound.programSemanticFingerprint =
        ComputePlayablePropertyFingerprintV1(secondSound);
    PlayablePropertyProgramViewV1 parentProperty = MakeContainerProperty(parentId, 2);
    PlayablePropertyProgramViewV1 queueProperty =
        MakeContainerProperty(queueId, 3);
    queueProperty.payload.presentMask |= UINT64_C(1) << 3u;
    queueProperty.payload.values[3].bits = queueLoopCount;
    queueProperty.programSemanticFingerprint =
        ComputePlayablePropertyFingerprintV1(queueProperty);
    const PlayableRefV1 firstRef = PlayableRefFromProperty(firstSound);
    const PlayableRefV1 secondRef = PlayableRefFromProperty(secondSound);
    const PlayableRefV1 queueRef = PlayableRefFromProperty(queueProperty);

    AuthoredCompletionLeafV1 completionLeaves[2]{};
    ContainerChildProgramViewV2 queueChildren[2]{};
    queueChildren[0].playable = firstRef;
    queueChildren[0].stableChildOrdinal = 7;
    queueChildren[0].queueStopPolicy = QueueStopPolicyV1::AdvanceQueue;
    completionLeaves[0].stableLeafOrdinal = 1;
    completionLeaves[0].content = firstRef;
    completionLeaves[0].startOffset = {
        AuthoredTimeDomainV1::SourceFrames, 0, 1};
    completionLeaves[0].duration = {
        AuthoredTimeDomainV1::NaturalMediaEnd, 0, 1};
    queueChildren[0].timingHint.kind = harken::ChildTimingHintKindV2::InlineSound;
    harkentest::CopyLeafTimingToHint(queueChildren[0], completionLeaves[0]);
    queueChildren[1] = queueChildren[0];
    queueChildren[1].playable = secondRef;
    queueChildren[1].stableChildOrdinal = 8;
    queueChildren[1].authoredStableOrder = 1;
    completionLeaves[1] = completionLeaves[0];
    completionLeaves[1].content = secondRef;
    harkentest::CopyLeafTimingToHint(queueChildren[1], completionLeaves[1]);

    ContainerProgramViewV3 queueProgram = MakeContainerProgram(
        queueId, queueProperty.programSemanticFingerprint, 3);
    queueProgram.mode = ContainerModeV1::SequenceQueue;
    queueProgram.memoryScope = queueMemoryScope;
    queueProgram.queueCycle = QueueCycleV1::Once;
    queueProgram.queueCycleCount = 0;
    queueProgram.queueSplice = QueueSpliceV1::Butt;
    queueProgram.childCount = 2;
    queueProgram.children = queueChildren;

    ContainerChildProgramViewV2 parentChild{};
    parentChild.playable = queueRef;
    parentChild.frequencyWeight = 1;
    parentChild.stableChildOrdinal = 7;
    ContainerProgramViewV3 parentProgram = MakeContainerProgram(
        parentId, parentProperty.programSemanticFingerprint, 2);
    parentProgram.memoryScope = MemoryScopeV1::Global;
    parentProgram.childCount = 1;
    parentProgram.children = &parentChild;

    PlayableOccurrencePropertyViewV1 occurrences[3]{};
    occurrences[0].parentKind =
        playableproperties::ContentPropertyKindV1::Container;
    occurrences[0].parentStableId = harkentest::ObjectId(parentId);
    occurrences[0].parentProgramSemanticFingerprint =
        parentProperty.programSemanticFingerprint;
    occurrences[0].stableOccurrenceOrdinal = parentChild.stableChildOrdinal;
    occurrences[0].childPlayable = queueRef;
    occurrences[0].payload = EmptyOccurrencePayload();
    occurrences[0].occurrenceSemanticFingerprint =
        ComputePlayableOccurrenceFingerprintV1(occurrences[0]);
    occurrences[1].parentKind =
        playableproperties::ContentPropertyKindV1::Container;
    occurrences[1].parentStableId = harkentest::ObjectId(queueId);
    occurrences[1].parentProgramSemanticFingerprint =
        queueProperty.programSemanticFingerprint;
    occurrences[1].stableOccurrenceOrdinal = queueChildren[0].stableChildOrdinal;
    occurrences[1].childPlayable = firstRef;
    occurrences[1].payload = EmptyOccurrencePayload();
    occurrences[1].occurrenceSemanticFingerprint =
        ComputePlayableOccurrenceFingerprintV1(occurrences[1]);
    occurrences[2] = occurrences[1];
    occurrences[2].stableOccurrenceOrdinal = queueChildren[1].stableChildOrdinal;
    occurrences[2].childPlayable = secondRef;
    occurrences[2].occurrenceSemanticFingerprint =
        ComputePlayableOccurrenceFingerprintV1(occurrences[2]);

    PlayablePropertyProgramViewV1 properties[4] = {
        firstSound, secondSound, parentProperty, queueProperty};
    ActionStepProgramViewV1 step{};
    step.opcode = ActionOpcodeV1::Play;
    step.target.kind = ActionTargetKindV1::Container;
    step.target.stableId = harkentest::ObjectId(parentId);
    step.target.expectedProgramSemanticFingerprint =
        parentProperty.programSemanticFingerprint;
    SetAbsoluteTime(&step.delay, 0);
    SetAbsoluteTime(&step.fade, 0);
    SetAbsoluteTime(&step.cooldown, 0);
    ActionProgramViewV1 action{};
    action.actionStableId = actionId;
    action.steps = &step;
    action.stepCount = 1;
    action.directFeatureMask = 0;
    action.transitiveFeatureMask = 0;
    action.expandedStepOccurrenceCount = 1;
    action.expandedFiringCount = 1;
    action.programSemanticFingerprint = ComputeActionProgramFingerprintV1(action);

    ContainerProgramViewV3 programs[2] = {parentProgram, queueProgram};
    ContainerWorldInstallViewV1 world{};
    world.identity.capabilityMask =
        kWorldCapabilityActionDefinitions |
        kWorldCapabilityPlayableProperties |
        kWorldCapabilityRandomDraw | kWorldCapabilitySequenceQueue;
    world.playableProperties = properties;
    world.playablePropertyCount = 4;
    world.playableOccurrences = occurrences;
    world.playableOccurrenceCount = 3;
    world.containers = programs;
    world.containerCount = 2;
    world.actions = &action;
    world.actionCount = 1;
    world.capacity.maxKnownScheduleLeaves = 16;
    world.capacity.maxTrackPieceScheduleDepth = 8;
    world.identity.runtimeSemanticFingerprint =
        ComputeCurrentWorldFingerprintV4(world);
    return WrapWorldPartition(packStableId, partitionRevision, world, 5);
}

std::vector<std::uint8_t> BuildImmediateNestedQueueContainerPlayPack(
    std::uint64_t packStableId, std::uint64_t contentRevision,
    std::uint64_t partitionRevision, VnObjectId actionId,
    VnObjectId parentId, VnObjectId queueId,
    VnObjectId firstSoundId, VnObjectId secondSoundId,
    std::vector<float> firstPlanar, std::vector<float> secondPlanar,
    std::uint32_t queueLoopCount = 1,
    MemoryScopeV1 queueMemoryScope = MemoryScopeV1::Emitter,
    VnBusId route = VN_BUS_MASTER) {
    const float* firstChannels[1] = {firstPlanar.data()};
    const float* secondChannels[1] = {secondPlanar.data()};
    std::uint64_t firstRevision = 0;
    std::uint64_t secondRevision = 0;
    EXPECT_TRUE(ComputeMediaPcmContentRevisionV1(
        48000, 1, static_cast<std::uint64_t>(firstPlanar.size()),
        firstChannels, 1, &firstRevision));
    EXPECT_TRUE(ComputeMediaPcmContentRevisionV1(
        48000, 1, static_cast<std::uint64_t>(secondPlanar.size()),
        secondChannels, 1, &secondRevision));
    ImageBuilder builder(kPackKindCanonicalContent);
    builder.AddEntry(kPackEntryKindPackRequirementBlock, packStableId,
                     RequirementPayload(packStableId, contentRevision,
                                        partitionRevision));
    builder.AddEntry(
        kPackEntryKindCanonicalDefinitionPartition, packStableId,
        ImmediateNestedQueueContainerPlayPartitionPayload(
            packStableId, partitionRevision, actionId, parentId, queueId,
            firstSoundId, secondSoundId, firstRevision, secondRevision,
            queueLoopCount, queueMemoryScope, route));
    builder.AddMedia(firstSoundId, std::move(firstPlanar));
    builder.AddMedia(secondSoundId, std::move(secondPlanar));
    return builder.Build();
}

std::vector<std::uint8_t> ImmediateSequencePlayPartitionPayload(
    std::uint64_t packStableId, std::uint64_t partitionRevision,
    VnObjectId actionId, VnObjectId containerId, VnObjectId soundId,
    std::uint64_t contentRevision) {
    PlayablePropertyProgramViewV1 sound = MakeSoundProperty(soundId);
    sound.contentRevision = contentRevision;
    sound.programSemanticFingerprint = ComputePlayablePropertyFingerprintV1(sound);
    const PlayableRefV1 child = PlayableRefFromProperty(sound);
    PlayablePropertyProgramViewV1 containerProperty =
        MakeContainerProperty(containerId, 1);
    ContainerChildProgramViewV2 childRow{};
    childRow.playable = child;
    childRow.stableChildOrdinal = 7;
    ContainerProgramViewV3 program = MakeContainerProgram(
        containerId, containerProperty.programSemanticFingerprint, 1);
    program.mode = ContainerModeV1::Sequence;
    program.randomDiscipline = {};
    program.memoryScope = MemoryScopeV1::Global;
    program.childCount = 1;
    program.children = &childRow;
    PlayableOccurrencePropertyViewV1 occurrence{};
    occurrence.parentKind = playableproperties::ContentPropertyKindV1::Container;
    occurrence.parentStableId = harkentest::ObjectId(containerId);
    occurrence.parentProgramSemanticFingerprint =
        containerProperty.programSemanticFingerprint;
    occurrence.stableOccurrenceOrdinal = childRow.stableChildOrdinal;
    occurrence.childPlayable = child;
    occurrence.payload = EmptyOccurrencePayload();
    occurrence.occurrenceSemanticFingerprint =
        ComputePlayableOccurrenceFingerprintV1(occurrence);
    PlayablePropertyProgramViewV1 properties[2] = {sound, containerProperty};
    ActionStepProgramViewV1 step{};
    step.opcode = ActionOpcodeV1::Play;
    step.target.kind = ActionTargetKindV1::Container;
    step.target.stableId = harkentest::ObjectId(containerId);
    step.target.expectedProgramSemanticFingerprint =
        containerProperty.programSemanticFingerprint;
    SetAbsoluteTime(&step.delay, 0);
    SetAbsoluteTime(&step.fade, 0);
    SetAbsoluteTime(&step.cooldown, 0);
    ActionProgramViewV1 action{};
    action.actionStableId = actionId;
    action.steps = &step;
    action.stepCount = 1;
    action.directFeatureMask = 0;
    action.transitiveFeatureMask = 0;
    action.expandedStepOccurrenceCount = 1;
    action.expandedFiringCount = 1;
    action.programSemanticFingerprint = ComputeActionProgramFingerprintV1(action);
    ContainerWorldInstallViewV1 world{};
    world.identity.capabilityMask = kWorldCapabilityActionDefinitions |
                                    kWorldCapabilityPlayableProperties |
                                    kWorldCapabilitySequence;
    world.playableProperties = properties;
    world.playablePropertyCount = 2;
    world.playableOccurrences = &occurrence;
    world.playableOccurrenceCount = 1;
    world.containers = &program;
    world.containerCount = 1;
    world.actions = &action;
    world.actionCount = 1;
    world.capacity.maxKnownScheduleLeaves = 16;
    world.capacity.maxTrackPieceScheduleDepth = 8;
    world.identity.runtimeSemanticFingerprint =
        ComputeCurrentWorldFingerprintV4(world);
    return WrapWorldPartition(packStableId, partitionRevision, world, 3);
}

std::vector<std::uint8_t> BuildImmediateSequencePlayPack(
    std::uint64_t packStableId, std::uint64_t contentRevision,
    std::uint64_t partitionRevision, VnObjectId actionId,
    VnObjectId containerId, VnObjectId soundId,
    std::vector<float> planar) {
    const float* channels[1] = {planar.data()};
    std::uint64_t mediaRevision = 0;
    EXPECT_TRUE(ComputeMediaPcmContentRevisionV1(
        48000, 1, static_cast<std::uint64_t>(planar.size()), channels, 1,
        &mediaRevision));
    ImageBuilder builder(kPackKindCanonicalContent);
    builder.AddEntry(kPackEntryKindPackRequirementBlock, packStableId,
                     RequirementPayload(packStableId, contentRevision,
                                        partitionRevision));
    builder.AddEntry(kPackEntryKindCanonicalDefinitionPartition, packStableId,
                     ImmediateSequencePlayPartitionPayload(
                         packStableId, partitionRevision, actionId, containerId,
                         soundId, mediaRevision));
    builder.AddMedia(soundId, std::move(planar));
    return builder.Build();
}

std::vector<std::uint8_t> ImmediateQueueCompositeChildPlayPartitionPayload(
    std::uint64_t packStableId, std::uint64_t partitionRevision,
    VnObjectId actionId, VnObjectId containerId, VnObjectId trackId,
    VnObjectId pieceId, VnObjectId firstSoundId, VnObjectId secondSoundId,
    std::uint64_t firstRevision, std::uint64_t secondRevision, bool pieceChild,
    bool mixedZeroWorkTrack = false,
    VnObjectId resetActionId = harkentest::ObjectId(0),
    bool logicalOnlyTrack = false,
    bool boundedSameSoundSuccessor = false,
    std::int64_t delayNanoseconds = 0) {
    PlayablePropertyProgramViewV1 firstSound = MakeSoundProperty(firstSoundId);
    firstSound.contentRevision = firstRevision;
    firstSound.programSemanticFingerprint =
        ComputePlayablePropertyFingerprintV1(firstSound);
    PlayablePropertyProgramViewV1 secondSound = MakeSoundProperty(secondSoundId);
    secondSound.authoredStableOrder = 1;
    secondSound.contentRevision = secondRevision;
    secondSound.compatibilityFingerprint = 5;
    secondSound.programSemanticFingerprint =
        ComputePlayablePropertyFingerprintV1(secondSound);
    PlayablePropertyProgramViewV1 trackProperty{};
    trackProperty.contentPropertyKind =
        playableproperties::ContentPropertyKindV1::Track;
    trackProperty.stableId = harkentest::ObjectId(trackId);
    trackProperty.authoredStableOrder = 3;
    trackProperty.contentRevision = 1;
    trackProperty.routeStableId = VN_BUS_MASTER;
    trackProperty.compatibilityFingerprint = 3;
    trackProperty.payload = DelayedPlayPayload();
    trackProperty.programSemanticFingerprint =
        ComputePlayablePropertyFingerprintV1(trackProperty);
    PlayablePropertyProgramViewV1 pieceProperty{};
    pieceProperty.contentPropertyKind =
        playableproperties::ContentPropertyKindV1::Piece;
    pieceProperty.stableId = harkentest::ObjectId(pieceId);
    pieceProperty.authoredStableOrder = 4;
    pieceProperty.contentRevision = 1;
    pieceProperty.routeStableId = VN_BUS_MASTER;
    pieceProperty.compatibilityFingerprint = 4;
    pieceProperty.payload = DelayedPlayPayload();
    pieceProperty.programSemanticFingerprint =
        ComputePlayablePropertyFingerprintV1(pieceProperty);
    PlayablePropertyProgramViewV1 containerProperty =
        MakeContainerProperty(containerId, 2);
    const PlayableRefV1 firstRef = PlayableRefFromProperty(firstSound);
    const PlayableRefV1 secondRef = PlayableRefFromProperty(secondSound);
    const PlayableRefV1 trackRef = PlayableRefFromProperty(trackProperty);
    const PlayableRefV1 pieceRef = PlayableRefFromProperty(pieceProperty);
    ScheduleClipPlacementV1 placements[2]{};
    placements[0].stablePlacementOrdinal = 0;
    placements[0].stableOccurrenceOrdinal = 11;
    placements[0].content = firstRef;
    placements[0].clipId = harkentest::ObjectId(firstSoundId.low * 1000u + 1u);
    placements[0].clipGuidHigh = 1;
    placements[1] = placements[0];
    placements[1].stablePlacementOrdinal = 1;
    placements[1].stableOccurrenceOrdinal = 12;
    placements[1].content = secondRef;
    placements[1].authoredStart = INT64_C(12000000);
    placements[1].clipId = harkentest::ObjectId(secondSoundId.low * 1000u + 1u);
    placements[1].clipGuidHigh = 2;
    if (mixedZeroWorkTrack) {
        placements[1].authoredStart = INT64_C(100000000);
        placements[1].authoredDuration = 1;
    }
    if (logicalOnlyTrack) {
        placements[0].authoredStart = INT64_C(10000000);
        placements[0].authoredDuration = 1;
        placements[1].authoredStart = INT64_C(20000000);
        placements[1].authoredDuration = 1;
    }
    if (boundedSameSoundSuccessor) {
        placements[0].authoredStart = INT64_C(5000000);
        placements[0].authoredDuration = INT64_C(10000000);
    }
    TrackScheduleProgramViewV1 trackSchedule{};
    trackSchedule.rootDefinition = trackRef;
    trackSchedule.placementCount = boundedSameSoundSuccessor ? 1 : 2;
    trackSchedule.placements = placements;
    trackSchedule.scheduleSemanticFingerprint =
        ComputeTrackScheduleFingerprintV1(trackSchedule);
    ScheduleTrackRefV1 trackScheduleRef{};
    trackScheduleRef.trackDefinition = trackRef;
    trackScheduleRef.trackScheduleSemanticFingerprint =
        trackSchedule.scheduleSemanticFingerprint;
    PieceScheduleProgramViewV1 pieceSchedule{};
    pieceSchedule.rootDefinition = pieceRef;
    pieceSchedule.trackRefCount = 1;
    pieceSchedule.trackRefs = &trackScheduleRef;
    pieceSchedule.scheduleSemanticFingerprint =
        ComputePieceScheduleFingerprintV1(pieceSchedule);
    AuthoredCompletionLeafV1 completionLeaf{};
    completionLeaf.stableLeafOrdinal = 1;
    completionLeaf.content = firstRef;
    completionLeaf.startOffset = {AuthoredTimeDomainV1::SourceFrames, 0, 1};
    completionLeaf.duration = {AuthoredTimeDomainV1::NaturalMediaEnd, 0, 1};
    ContainerChildProgramViewV2 children[2]{};
    children[0].stableChildOrdinal = 7;
    children[0].queueStopPolicy = QueueStopPolicyV1::AdvanceQueue;
    if (pieceChild) {
        children[0].playable = pieceRef;
        children[0].timingHint = MakeScheduleReferenceTimingHint(
            PlayableKindV1::Piece, pieceId,
            pieceSchedule.scheduleSemanticFingerprint);
    } else {
        children[0].playable = trackRef;
        children[0].timingHint = MakeScheduleReferenceTimingHint(
            PlayableKindV1::Track, trackId,
            trackSchedule.scheduleSemanticFingerprint);
    }
    children[1].stableChildOrdinal = 8;
    children[1].authoredStableOrder = 1;
    children[1].playable = firstRef;
    children[1].queueStopPolicy = QueueStopPolicyV1::AdvanceQueue;
    children[1].timingHint.kind = harken::ChildTimingHintKindV2::InlineSound;
    harkentest::CopyLeafTimingToHint(children[1], completionLeaf);
    if (mixedZeroWorkTrack || logicalOnlyTrack || boundedSameSoundSuccessor) {
        std::swap(children[0], children[1]);
        children[0].stableChildOrdinal = 7;
        children[0].authoredStableOrder = 0;
        children[1].stableChildOrdinal = 8;
        children[1].authoredStableOrder = 1;
    }
    ContainerProgramViewV3 program = MakeContainerProgram(
        containerId, containerProperty.programSemanticFingerprint, 2);
    program.mode = ContainerModeV1::SequenceQueue;
    program.memoryScope = MemoryScopeV1::Emitter;
    program.queueCycle = QueueCycleV1::Once;
    program.queueSplice = QueueSpliceV1::Butt;
    program.childCount = 2;
    program.children = children;
    if (mixedZeroWorkTrack || logicalOnlyTrack) {
        program.queueCycle = QueueCycleV1::Loop;
        program.resumePosition = 1;
    }
    PlayableOccurrencePropertyViewV1 occurrences[4]{};
    occurrences[0].parentKind = playableproperties::ContentPropertyKindV1::Container;
    occurrences[0].parentStableId = harkentest::ObjectId(containerId);
    occurrences[0].parentProgramSemanticFingerprint =
        containerProperty.programSemanticFingerprint;
    occurrences[0].stableOccurrenceOrdinal = children[0].stableChildOrdinal;
    occurrences[0].childPlayable = children[0].playable;
    occurrences[0].payload = EmptyOccurrencePayload();
    occurrences[0].occurrenceSemanticFingerprint =
        ComputePlayableOccurrenceFingerprintV1(occurrences[0]);
    occurrences[1] = occurrences[0];
    occurrences[1].stableOccurrenceOrdinal = children[1].stableChildOrdinal;
    occurrences[1].childPlayable = children[1].playable;
    occurrences[1].occurrenceSemanticFingerprint =
        ComputePlayableOccurrenceFingerprintV1(occurrences[1]);
    occurrences[2].parentKind = playableproperties::ContentPropertyKindV1::Track;
    occurrences[2].parentStableId = harkentest::ObjectId(trackId);
    occurrences[2].parentProgramSemanticFingerprint =
        trackProperty.programSemanticFingerprint;
    occurrences[2].stableOccurrenceOrdinal = placements[0].stableOccurrenceOrdinal;
    occurrences[2].childPlayable = firstRef;
    occurrences[2].payload = EmptyOccurrencePayload();
    occurrences[2].occurrenceSemanticFingerprint =
        ComputePlayableOccurrenceFingerprintV1(occurrences[2]);
    occurrences[3] = occurrences[2];
    occurrences[3].stableOccurrenceOrdinal = placements[1].stableOccurrenceOrdinal;
    occurrences[3].childPlayable = secondRef;
    occurrences[3].occurrenceSemanticFingerprint =
        ComputePlayableOccurrenceFingerprintV1(occurrences[3]);
    PlayablePropertyProgramViewV1 properties[5] = {
        firstSound, secondSound, containerProperty, trackProperty, pieceProperty};
    ActionStepProgramViewV1 step{};
    step.opcode = ActionOpcodeV1::Play;
    step.target.kind = ActionTargetKindV1::Container;
    step.target.stableId = harkentest::ObjectId(containerId);
    step.target.expectedProgramSemanticFingerprint =
        containerProperty.programSemanticFingerprint;
    SetAbsoluteTime(&step.delay, delayNanoseconds);
    SetAbsoluteTime(&step.fade, 0);
    SetAbsoluteTime(&step.cooldown, 0);
    ActionProgramViewV1 action{};
    action.actionStableId = actionId;
    action.steps = &step;
    action.stepCount = 1;
    action.directFeatureMask = delayNanoseconds != 0 ? 1u : 0u;
    action.transitiveFeatureMask = action.directFeatureMask;
    action.expandedStepOccurrenceCount = 1;
    action.expandedFiringCount = 1;
    action.programSemanticFingerprint = ComputeActionProgramFingerprintV1(action);
    ActionStepProgramViewV1 resetStep{};
    resetStep.opcode = ActionOpcodeV1::Reset;
    resetStep.target.kind = ActionTargetKindV1::Container;
    resetStep.target.stableId = harkentest::ObjectId(containerId);
    resetStep.target.expectedProgramSemanticFingerprint =
        containerProperty.programSemanticFingerprint;
    resetStep.scope = ActionScopeV1::Emitter;
    SetAbsoluteTime(&resetStep.delay, 0);
    SetAbsoluteTime(&resetStep.fade, 0);
    SetAbsoluteTime(&resetStep.cooldown, 0);
    ActionProgramViewV1 resetAction{};
    resetAction.actionStableId = resetActionId;
    resetAction.steps = &resetStep;
    resetAction.stepCount = 1;
    resetAction.expandedStepOccurrenceCount = 1;
    resetAction.expandedFiringCount = 1;
    resetAction.programSemanticFingerprint =
        ComputeActionProgramFingerprintV1(resetAction);
    ActionProgramViewV1 actions[2] = {action, resetAction};
    ContainerWorldInstallViewV1 world{};
    world.identity.capabilityMask = kWorldCapabilityActionDefinitions |
                                    kWorldCapabilityPlayableProperties |
                                    kWorldCapabilitySequenceQueue;
    world.playableProperties = properties;
    world.playablePropertyCount = 5;
    world.playableOccurrences = occurrences;
    world.playableOccurrenceCount = boundedSameSoundSuccessor ? 3 : 4;
    world.trackSchedules = &trackSchedule;
    world.trackScheduleCount = 1;
    world.pieceSchedules = &pieceSchedule;
    world.pieceScheduleCount = 1;
    world.containers = &program;
    world.containerCount = 1;
    world.actions = actions;
    world.actionCount = resetActionId == harkentest::ObjectId(0) ? 1 : 2;
    world.capacity.maxKnownScheduleLeaves = 16;
    world.capacity.maxTrackPieceScheduleDepth = 8;
    world.identity.runtimeSemanticFingerprint =
        ComputeCurrentWorldFingerprintV4(world);
    return WrapWorldPartition(
        packStableId, partitionRevision, world,
        resetActionId == harkentest::ObjectId(0) ? 6 : 7);
}

std::vector<std::uint8_t> BuildImmediateQueueCompositeChildPlayPack(
    std::uint64_t packStableId, std::uint64_t contentRevision,
    std::uint64_t partitionRevision, VnObjectId actionId,
    VnObjectId containerId, VnObjectId trackId, VnObjectId pieceId,
    VnObjectId firstSoundId, VnObjectId secondSoundId,
    std::vector<float> firstPlanar, std::vector<float> secondPlanar,
    bool pieceChild, bool mixedZeroWorkTrack = false,
    VnObjectId resetActionId = harkentest::ObjectId(0),
    bool logicalOnlyTrack = false,
    bool boundedSameSoundSuccessor = false,
    std::int64_t delayNanoseconds = 0) {
    const float* firstChannels[1] = {firstPlanar.data()};
    const float* secondChannels[1] = {secondPlanar.data()};
    std::uint64_t firstRevision = 0;
    std::uint64_t secondRevision = 0;
    EXPECT_TRUE(ComputeMediaPcmContentRevisionV1(
        48000, 1, static_cast<std::uint64_t>(firstPlanar.size()), firstChannels,
        1, &firstRevision));
    EXPECT_TRUE(ComputeMediaPcmContentRevisionV1(
        48000, 1, static_cast<std::uint64_t>(secondPlanar.size()),
        secondChannels, 1, &secondRevision));
    ImageBuilder builder(kPackKindCanonicalContent);
    builder.AddEntry(kPackEntryKindPackRequirementBlock, packStableId,
                     RequirementPayload(packStableId, contentRevision,
                                        partitionRevision));
    builder.AddEntry(kPackEntryKindCanonicalDefinitionPartition, packStableId,
                     ImmediateQueueCompositeChildPlayPartitionPayload(
                         packStableId, partitionRevision, actionId, containerId,
                         trackId, pieceId, firstSoundId, secondSoundId,
                          firstRevision, secondRevision, pieceChild,
                          mixedZeroWorkTrack, resetActionId,
                          logicalOnlyTrack, boundedSameSoundSuccessor, delayNanoseconds));
    builder.AddMedia(firstSoundId, std::move(firstPlanar));
    builder.AddMedia(secondSoundId, std::move(secondPlanar));
    return builder.Build();
}

