struct NormalizedNestedQueueTrace {
    bool valid = false;
    std::array<std::uint32_t, 2> selectedOrdinals{};
    std::int64_t onsetRelativeFrame = 0;
    PlayableInstanceHandle parentHandle = 0;
    std::uint64_t parentEpoch = 0;
    std::uint64_t parentPathHash = 0;
    std::uint32_t parentPathDepth = 0;
    std::uint32_t nestedLoopLimit = 0;
    bool reclaimed = false;
    bool nestedReclaimed = false;
    bool leafReclaimed = false;
    PlayableExecutionResolveStatus typedError =
        PlayableExecutionResolveStatus::InvalidRequest;
};

enum class ContainerMatrixChild : std::uint8_t {
    Sound,
    Container,
    Track,
    Piece,
};

struct ContainerMatrixWorld {
    static constexpr VnObjectId kAction = harkentest::ObjectId(72001);
    static constexpr VnObjectId kRoot = harkentest::ObjectId(72002);
    static constexpr VnObjectId kNested = harkentest::ObjectId(72003);
    static constexpr VnObjectId kTrack = harkentest::ObjectId(72004);
    static constexpr VnObjectId kPiece = harkentest::ObjectId(72005);
    static constexpr VnObjectId kFirstSound = harkentest::ObjectId(72006);
    static constexpr VnObjectId kSecondSound = harkentest::ObjectId(72007);
    static constexpr VnObjectId kVariable = harkentest::ObjectId(72008);

    std::array<PlayablePropertyProgramViewV1, 6> properties{};
    std::uint32_t propertyCount = 0;
    PlayableRefV1 rootRef{};
    std::array<ContainerProgramViewV3, 2> containers{};
    std::array<ContainerChildProgramViewV2, 3> children{};
    std::array<AuthoredCompletionLeafV1, 2> completionLeaves{};
    std::array<PlayableOccurrencePropertyViewV1, 5> occurrences{};
    std::array<EffectParamV1, 4> delayParams{};
    EffectNodeV1 delayNode{};
    SendV1 delaySend{};
    std::uint32_t occurrenceCount = 0;
    std::array<ScheduleClipPlacementV1, 2> placements{};
    TrackScheduleProgramViewV1 track{};
    ScheduleTrackRefV1 trackRef{};
    PieceScheduleProgramViewV1 piece{};
    VariableDefinitionV1 variable{};
    GridAxisV1 axis{};
    DiscreteGridCellV1 cell{};
    DiscreteGridRowViewV1 row{};
    ActionStepProgramViewV1 step{};
    ActionProgramViewV1 action{};
    ContainerWorldInstallViewV1 world{};

    ContainerMatrixWorld(ContainerModeV1 mode, ContainerMatrixChild childKind,
                  std::uint64_t firstRevision,
                  std::uint64_t secondRevision, bool multiLeaf = false,
                  std::uint32_t loopCount = 1,
                  std::uint32_t nestedLoopCount = 0,
                  MemoryScopeV1 outerScope = MemoryScopeV1::Global,
                  MemoryScopeV1 innerScope = MemoryScopeV1::Emitter,
                  bool delayTail = false) {
        const bool nestedContainer = childKind == ContainerMatrixChild::Container ||
            nestedLoopCount != 0;
        const std::uint32_t firstSoundPropertyIndex = propertyCount++;
        properties[firstSoundPropertyIndex] = MakeSoundProperty(kFirstSound);
        properties[firstSoundPropertyIndex].contentRevision = firstRevision;
        if (delayTail) {
            delayParams = {{
                {0, std::bit_cast<std::uint32_t>(20.0f)},
                {1, std::bit_cast<std::uint32_t>(0.0f)},
                {2, std::bit_cast<std::uint32_t>(1.0f)},
                {3, std::bit_cast<std::uint32_t>(1.0f)},
            }};
            delayNode = {8, VN_EFFECT_FEEDBACK_DELAY, 4, delayParams.data()};
            delaySend = {1, 0, VN_OBJECT_ID(0, 2), -6.0f, 0};
            auto& payload = properties[firstSoundPropertyIndex].payload;
            payload.presentMask |= UINT64_C(0x8080);
            payload.effectNodeCount = 1;
            payload.effectNodes = &delayNode;
            payload.sendCount = 1;
            payload.sends = &delaySend;
        }
        properties[firstSoundPropertyIndex].programSemanticFingerprint =
            ComputePlayablePropertyFingerprintV1(
                properties[firstSoundPropertyIndex]);
        std::uint32_t secondSoundPropertyIndex = UINT32_MAX;
        if (multiLeaf && (childKind == ContainerMatrixChild::Track ||
                          childKind == ContainerMatrixChild::Piece)) {
            secondSoundPropertyIndex = propertyCount++;
            auto& secondSound = properties[secondSoundPropertyIndex];
            secondSound = MakeSoundProperty(kSecondSound);
            secondSound.authoredStableOrder = secondSoundPropertyIndex;
            secondSound.contentRevision = secondRevision;
            secondSound.programSemanticFingerprint =
                ComputePlayablePropertyFingerprintV1(secondSound);
        }
        const std::uint32_t rootPropertyIndex = propertyCount++;
        properties[rootPropertyIndex] =
            MakeContainerProperty(kRoot, rootPropertyIndex);
        properties[rootPropertyIndex].compatibilityFingerprint = 2;
        SetContainerPropertyLoopCount(&properties[rootPropertyIndex], loopCount);
        properties[rootPropertyIndex].programSemanticFingerprint =
            ComputePlayablePropertyFingerprintV1(properties[rootPropertyIndex]);
        rootRef = PlayableRefFromProperty(properties[rootPropertyIndex]);
        std::uint32_t childPropertyIndex = UINT32_MAX;
        std::uint32_t nestedPropertyIndex = UINT32_MAX;
        std::uint32_t piecePropertyIndex = UINT32_MAX;
        if (nestedContainer) {
            nestedPropertyIndex = propertyCount++;
            properties[nestedPropertyIndex] =
                MakeContainerProperty(kNested, nestedPropertyIndex);
            if (nestedLoopCount != 0) {
                SetContainerPropertyLoopCount(
                    &properties[nestedPropertyIndex], nestedLoopCount);
                properties[nestedPropertyIndex].programSemanticFingerprint =
                    ComputePlayablePropertyFingerprintV1(
                        properties[nestedPropertyIndex]);
            }
        }
        if (childKind == ContainerMatrixChild::Track ||
                   childKind == ContainerMatrixChild::Piece) {
            childPropertyIndex = propertyCount++;
            auto& trackProperty = properties[childPropertyIndex];
            trackProperty.contentPropertyKind =
                playableproperties::ContentPropertyKindV1::Track;
            trackProperty.stableId = harkentest::ObjectId(kTrack);
            trackProperty.authoredStableOrder = childPropertyIndex;
            trackProperty.contentRevision = 1;
            trackProperty.routeStableId = VN_BUS_MASTER;
            trackProperty.compatibilityFingerprint = 4;
            trackProperty.payload = DelayedPlayPayload();
            trackProperty.programSemanticFingerprint =
                ComputePlayablePropertyFingerprintV1(trackProperty);
            if (childKind == ContainerMatrixChild::Piece) {
                piecePropertyIndex = propertyCount++;
                auto& pieceProperty = properties[piecePropertyIndex];
                pieceProperty.contentPropertyKind =
                    playableproperties::ContentPropertyKindV1::Piece;
                pieceProperty.stableId = harkentest::ObjectId(kPiece);
                pieceProperty.authoredStableOrder = piecePropertyIndex;
                pieceProperty.contentRevision = 1;
                pieceProperty.routeStableId = VN_BUS_MASTER;
                pieceProperty.compatibilityFingerprint = 5;
                pieceProperty.payload = DelayedPlayPayload();
                pieceProperty.programSemanticFingerprint =
                    ComputePlayablePropertyFingerprintV1(pieceProperty);
            }
        }

        const PlayableRefV1 first =
            PlayableRefFromProperty(properties[firstSoundPropertyIndex]);
        const PlayableRefV1 second = secondSoundPropertyIndex == UINT32_MAX
            ? PlayableRefV1{}
            : PlayableRefFromProperty(properties[secondSoundPropertyIndex]);
        const PlayableRefV1 nested =
            nestedContainer
                ? PlayableRefFromProperty(properties[nestedPropertyIndex])
                : PlayableRefV1{};
        const PlayableRefV1 trackPlayable =
            childKind == ContainerMatrixChild::Track ||
                    childKind == ContainerMatrixChild::Piece
                ? PlayableRefFromProperty(properties[childPropertyIndex])
                : PlayableRefV1{};
        const PlayableRefV1 piecePlayable =
            childKind == ContainerMatrixChild::Piece
                ? PlayableRefFromProperty(properties[piecePropertyIndex])
                : PlayableRefV1{};
        placements[0].stablePlacementOrdinal = 0;
        placements[0].stableOccurrenceOrdinal = 11;
        placements[0].content = first;
        placements[0].clipId = harkentest::ObjectId(1);
        placements[0].clipGuidHigh = 1;
        if (second.stableId != VnObjectId{}) {
            placements[1].stablePlacementOrdinal = 1;
            placements[1].stableOccurrenceOrdinal = 12;
            placements[1].content = second;
            placements[1].clipId = harkentest::ObjectId(2);
            placements[1].clipGuidHigh = 2;
        }
        if (childKind == ContainerMatrixChild::Track ||
            childKind == ContainerMatrixChild::Piece) {
            track.rootDefinition = trackPlayable;
            track.placementCount = second.stableId == VnObjectId{} ? 1 : 2;
            track.placements = placements.data();
            track.scheduleSemanticFingerprint =
                ComputeTrackScheduleFingerprintV1(track);
        }
        if (childKind == ContainerMatrixChild::Piece) {
            trackRef.trackDefinition = trackPlayable;
            trackRef.trackScheduleSemanticFingerprint =
                track.scheduleSemanticFingerprint;
            piece.rootDefinition = piecePlayable;
            piece.trackRefCount = 1;
            piece.trackRefs = &trackRef;
            piece.scheduleSemanticFingerprint =
                ComputePieceScheduleFingerprintV1(piece);
        }

        children[0].stableChildOrdinal = 7;
        children[0].authoredStableOrder = 1;
        const PlayableRefV1 selectedChild =
            childKind == ContainerMatrixChild::Sound ||
                    childKind == ContainerMatrixChild::Container
            ? first
            : childKind == ContainerMatrixChild::Track
                    ? trackPlayable
                    : piecePlayable;
        children[0].playable = nestedContainer ? nested : selectedChild;
        const bool randomQueue = mode == ContainerModeV1::RandomQueue;
        const bool sequenceQueue = mode == ContainerModeV1::SequenceQueue;
        const bool queue = randomQueue || sequenceQueue;
        children[0].frequencyWeight = mode == ContainerModeV1::Random ? 1 : 0;
        children[0].orderWeight = randomQueue ? 1 : 0;
        children[0].queueStopPolicy = queue
            ? QueueStopPolicyV1::AdvanceQueue
            : QueueStopPolicyV1::AbortOwningQueue;
        if (queue && (childKind == ContainerMatrixChild::Track ||
                      childKind == ContainerMatrixChild::Piece)) {
            children[0].timingHint = MakeScheduleReferenceTimingHint(
                childKind == ContainerMatrixChild::Track ? PlayableKindV1::Track
                                                  : PlayableKindV1::Piece,
                childKind == ContainerMatrixChild::Track ? kTrack : kPiece,
                childKind == ContainerMatrixChild::Track
                    ? track.scheduleSemanticFingerprint
                    : piece.scheduleSemanticFingerprint);
        } else if (queue && childKind == ContainerMatrixChild::Sound) {
            completionLeaves[0].stableLeafOrdinal = 1;
            completionLeaves[0].content = first;
            completionLeaves[0].startOffset = {
                AuthoredTimeDomainV1::SourceFrames, 0, 1};
            completionLeaves[0].duration = {
                AuthoredTimeDomainV1::NaturalMediaEnd, 0, 1};
            children[0].timingHint.kind = harken::ChildTimingHintKindV2::InlineSound;
            harkentest::CopyLeafTimingToHint(children[0], completionLeaves[0]);
        } else {
        }
        children[2].stableChildOrdinal = 9;
        children[2].playable = selectedChild;
        children[2].frequencyWeight = 1;
        children[2].queueStopPolicy = QueueStopPolicyV1::AbortOwningQueue;
        containers[0] = MakeContainerProgram(
            kRoot, properties[rootPropertyIndex].programSemanticFingerprint);
        containers[0].mode = mode;
        containers[0].memoryScope = queue ||
                mode == ContainerModeV1::VariableControl
            ? MemoryScopeV1::Emitter
            : outerScope;
        containers[0].childCount = 1;
        containers[0].children = children.data();
        containers[0].queueCycle = QueueCycleV1::Once;
        containers[0].queueSplice = QueueSpliceV1::Butt;
        if (nestedContainer) {
            containers[1] = MakeContainerProgram(
                kNested,
                properties[nestedPropertyIndex].programSemanticFingerprint, 2);
            containers[1].mode = ContainerModeV1::Random;
            containers[1].randomDiscipline = RandomDisciplineV1::Draw;
            containers[1].memoryScope = innerScope;
            containers[1].childCount = 1;
            containers[1].children = &children[2];
        }

        variable = harkentest::MakeVariableDefinition(
            kVariable, VariableKindV1::Step, 0.0f, 1.0f, 0.0f);
        axis = {0, 0, kVariable};
        cell = {DiscreteCellKindV1::Exact, 0};
        row.stableRowOrdinal = 1;
        row.childStableOrdinal = 7;
        row.cellCount = 1;
        row.cells = &cell;
        if (mode == ContainerModeV1::VariableControl) {
            containers[0].randomDiscipline = {};
            containers[0].discreteAxisCount = 1;
            containers[0].discreteAxes = &axis;
            containers[0].discreteRowCount = 1;
            containers[0].discreteRows = &row;
        }

        const auto addOccurrence = [&](std::size_t index,
                                       auto parentKind,
                                       VnObjectId parentId,
                                       std::uint64_t parentFingerprint,
                                       std::uint32_t ordinal,
                                       PlayableRefV1 child) {
            auto& occurrence = occurrences[index];
            occurrence.parentKind = parentKind;
            occurrence.parentStableId = harkentest::ObjectId(parentId);
            occurrence.parentProgramSemanticFingerprint = parentFingerprint;
            occurrence.stableOccurrenceOrdinal = ordinal;
            occurrence.childPlayable = child;
            occurrence.payload = EmptyOccurrencePayload();
            occurrence.payload.presentMask = 0;
            occurrence.payload.values[6].objectId = {};
            occurrence.occurrenceSemanticFingerprint =
                ComputePlayableOccurrenceFingerprintV1(occurrence);
        };
        addOccurrence(occurrenceCount++,
                      playableproperties::ContentPropertyKindV1::Container,
                      kRoot,
                      properties[rootPropertyIndex].programSemanticFingerprint,
                      7,
                      children[0].playable);
        if (nestedContainer) {
            addOccurrence(
                occurrenceCount++,
                playableproperties::ContentPropertyKindV1::Container,
                kNested,
                properties[nestedPropertyIndex].programSemanticFingerprint, 9,
                selectedChild);
        }
        if (childKind == ContainerMatrixChild::Track ||
            childKind == ContainerMatrixChild::Piece) {
            addOccurrence(occurrenceCount++,
                          playableproperties::ContentPropertyKindV1::Track,
                          kTrack,
                          properties[childPropertyIndex]
                              .programSemanticFingerprint,
                          11, first);
            if (second.stableId != VnObjectId{}) {
                addOccurrence(
                    occurrenceCount++,
                    playableproperties::ContentPropertyKindV1::Track,
                    kTrack,
                    properties[childPropertyIndex]
                        .programSemanticFingerprint,
                    12, second);
            }
        }

        step.opcode = ActionOpcodeV1::Play;
        step.target.kind = ActionTargetKindV1::Container;
        step.target.stableId = harkentest::ObjectId(kRoot);
        step.target.expectedProgramSemanticFingerprint =
            properties[rootPropertyIndex].programSemanticFingerprint;
        SetAbsoluteTime(&step.delay, 0);
        SetAbsoluteTime(&step.fade, 0);
        SetAbsoluteTime(&step.cooldown, 0);
        action.actionStableId = harkentest::ObjectId(kAction);
        action.steps = &step;
        action.stepCount = 1;
        action.directFeatureMask = 0;
        action.transitiveFeatureMask = 0;
        action.expandedStepOccurrenceCount = 1;
        action.expandedFiringCount = 1;
        action.programSemanticFingerprint =
            ComputeActionProgramFingerprintV1(action);

        world.identity.capabilityMask =
            kWorldCapabilityActionDefinitions |
            kWorldCapabilityPlayableProperties;
        if (mode == ContainerModeV1::Random ||
            nestedContainer) {
            world.identity.capabilityMask |= kWorldCapabilityRandomDraw;
        }
        if (mode == ContainerModeV1::Sequence) {
            world.identity.capabilityMask |= kWorldCapabilitySequence;
        }
        if (mode == ContainerModeV1::RandomQueue) {
            world.identity.capabilityMask |= kWorldCapabilityRandomQueue;
        }
        if (mode == ContainerModeV1::SequenceQueue) {
            world.identity.capabilityMask |= kWorldCapabilitySequenceQueue;
        }
        if (mode == ContainerModeV1::VariableControl) {
            world.identity.capabilityMask |= kWorldCapabilityVariableDefinitions |
                kWorldCapabilityVariableControl;
            world.variables = &variable;
            world.variableCount = 1;
        }
        world.playableProperties = properties.data();
        world.playablePropertyCount = propertyCount;
        world.playableOccurrences = occurrences.data();
        world.playableOccurrenceCount = occurrenceCount;
        world.containers = containers.data();
        world.containerCount =
            nestedContainer ? containers.size() : 1;
        if (childKind == ContainerMatrixChild::Track ||
            childKind == ContainerMatrixChild::Piece) {
            world.trackSchedules = &track;
            world.trackScheduleCount = 1;
        }
        if (childKind == ContainerMatrixChild::Piece) {
            world.pieceSchedules = &piece;
            world.pieceScheduleCount = 1;
        }
        world.actions = &action;
        world.actionCount = 1;
        world.capacity.maxKnownScheduleLeaves = 16;
        world.capacity.maxTrackPieceScheduleDepth = 8;
        world.identity.runtimeSemanticFingerprint =
            ComputeCurrentWorldFingerprintV4(world);
    }
};

struct OriginalDeferredOperationFixture {
    static constexpr std::uint32_t kSampleRate = 48000;
    static constexpr VnObjectId kOperation = harkentest::ObjectId(72009);
    EngineSession session{MakeNullConfig(8, 256, kSampleRate)};
    VnEmitterHandle emitter = 0;
    VnActionFiringHandle operation = 0;
    std::vector<VnActionFiringHandle> plays;

    explicit OriginalDeferredOperationFixture(ActionOpcodeV1 opcode,
        bool pendingLocalStop = false, bool immediatePost = false,
        bool nestedDeferredChild = false) {
        EXPECT_EQ(VN_OK, session.InitResult());
        if (session.InitResult() != VN_OK) return;
        const std::vector<float> pcm(96000, 0.25f);
        const float* channels[] = {pcm.data()};
        std::uint64_t revision = 0;
        EXPECT_TRUE(ComputeMediaPcmContentRevisionV1(48000, 1, pcm.size(),
            channels, 1, &revision));
        ContainerMatrixWorld image(ContainerModeV1::SequenceQueue,
            ContainerMatrixChild::Sound, revision, revision, false, 1, 0,
            MemoryScopeV1::Emitter);
        ActionStepProgramViewV1 play = image.step;
        play.target.kind = ActionTargetKindV1::Sound;
        play.target.stableId = ContainerMatrixWorld::kFirstSound;
        play.target.expectedProgramSemanticFingerprint =
            image.properties[0].programSemanticFingerprint;
        ActionStepProgramViewV1 nestedPost = play;
        std::array<ActionProgramViewV1, 3> actions{image.action, image.action, image.action};
        actions[0].steps = &play;
        actions[0].programSemanticFingerprint = ComputeActionProgramFingerprintV1(actions[0]);
        if (nestedDeferredChild) {
            actions[2].actionStableId = harkentest::ObjectId(72010);
            actions[2].steps = &play;
            actions[2].programSemanticFingerprint = ComputeActionProgramFingerprintV1(actions[2]);
            nestedPost.opcode = ActionOpcodeV1::PostAction;
            nestedPost.scope = ActionScopeV1::Global;
            nestedPost.target.kind = ActionTargetKindV1::Action;
            nestedPost.target.stableId = actions[2].actionStableId;
            nestedPost.target.expectedProgramSemanticFingerprint = actions[2].programSemanticFingerprint;
            actions[0].steps = &nestedPost;
            actions[0].expandedStepOccurrenceCount = 2;
            actions[0].expandedFiringCount = 2;
            actions[0].programSemanticFingerprint = ComputeActionProgramFingerprintV1(actions[0]);
        }
        ActionStepProgramViewV1 control = opcode == ActionOpcodeV1::Reset
            ? image.step : play;
        control.opcode = opcode;
        control.scope = opcode == ActionOpcodeV1::Reset
            ? ActionScopeV1::Emitter : ActionScopeV1::Global;
        SetAbsoluteTime(&control.delay, pendingLocalStop || immediatePost ? 0 : 1000000000);
        if (pendingLocalStop) control.quantizeTiming = ActionQuantizeTimingV1::NaturalEnd;
        if (opcode == ActionOpcodeV1::PostAction) {
            control.target.kind = ActionTargetKindV1::Action;
            control.target.stableId = actions[0].actionStableId;
            control.target.expectedProgramSemanticFingerprint = actions[0].programSemanticFingerprint;
            actions[1].expandedStepOccurrenceCount = nestedDeferredChild ? 3 : 2;
            actions[1].expandedFiringCount = nestedDeferredChild ? 3 : 2;
        }
        actions[1].actionStableId = kOperation;
        actions[1].steps = &control;
        actions[1].directFeatureMask = pendingLocalStop ? 2u : immediatePost ? 0u : 1u;
        actions[1].transitiveFeatureMask = actions[1].directFeatureMask;
        actions[1].programSemanticFingerprint = ComputeActionProgramFingerprintV1(actions[1]);
        image.world.actions = actions.data();
        image.world.actionCount = nestedDeferredChild ? 3 : 2;
        image.world.identity.runtimeSemanticFingerprint = ComputeCurrentWorldFingerprintV4(image.world);
        EXPECT_EQ(WorldInstallStatus::Ok, ValidateCurrentWorldV1(image.world));
        ImageBuilder builder(kPackKindCanonicalContent);
        builder.AddEntry(kPackEntryKindPackRequirementBlock, 22, RequirementPayload(22, 1, 7));
        builder.AddEntry(kPackEntryKindCanonicalDefinitionPartition, 22,
            WrapWorldPartition(22, 7, image.world, 0));
        builder.AddMedia(ContainerMatrixWorld::kFirstSound, pcm);
        const auto content = builder.Build();
        PackCanonicalImage parsedContent{};
        EXPECT_EQ(VN_OK, ParsePackCanonicalImage(content.data(), content.size(), &parsedContent));
        const auto init = BuildSingleIdentityInit(Fnv1a64(content.data(), content.size()),
            ContainerMatrixWorld::kAction, "ActionA.pack", ContainerMatrixWorld::kFirstSound,
            kOperation);
        PackCanonicalImage parsedInit{};
        EXPECT_EQ(VN_OK, ParsePackCanonicalImage(init.data(), init.size(), &parsedInit));
        const auto initPath = WriteTemp("original-deferred-operation-init.pack", init);
        const auto contentPath = WriteTemp("original-deferred-operation-a.pack", content);
        VnCanonicalPackSetMemberV1 members[2]{};
        VnCanonicalPackSetMemberResultV1 results[2]{};
        const char* paths[] = {initPath.c_str(), contentPath.c_str()};
        for (std::size_t i = 0; i < 2; ++i) {
            members[i].structSize = sizeof(members[i]);
            members[i].packStableId = i == 0 ? 11 : 22;
            members[i].packKind = i == 0 ? VN_CANONICAL_PACK_SET_MEMBER_INIT
                                       : VN_CANONICAL_PACK_SET_MEMBER_CONTENT;
            members[i].utf8Path = paths[i];
            results[i].structSize = sizeof(results[i]);
        }
        VnCanonicalPackSetActivationReportV1 report{};
        EXPECT_EQ(VN_OK, harkentest::ActivateCanonicalMembersV1(members, 2, results, report))
            << "opcode=" << static_cast<unsigned>(opcode)
            << " definitions=" << image.world.playablePropertyCount
            << " actions=" << image.world.actionCount;
        EXPECT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    }

    VnResult PostOperation() {
        VnPostActionDesc desc{};
        desc.structSize = sizeof(desc);
        desc.actionId = kOperation;
        desc.emitter = emitter;
        return Vn_PostAction(&desc, &operation);
    }

    void PostPlay() {
        VnPostActionDesc desc{};
        desc.structSize = sizeof(desc);
        desc.actionId = ContainerMatrixWorld::kAction;
        desc.emitter = emitter;
        VnActionFiringHandle firing = 0;
        ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
        plays.push_back(firing);
    }

    void Capture(std::vector<ActionDeferredRecordToken>& tokens,
        std::vector<ActionDeferredRecord>& records) {
        auto& engine = *session.Engine();
        for (std::uint32_t slot = 0; slot < engine.actionDeferredRecords.Capacity(); ++slot) {
            ActionDeferredRecordToken token{};
            ActionDeferredRecord record{};
            ActionDeferredRecordState state{};
            if (!engine.actionDeferredRecords.CaptureAt(slot, &token, &record, &state)) continue;
            ASSERT_EQ(operation, record.firing);
            ASSERT_EQ(ActionDeferredRecordState::Held, state);
            const auto* original = engine.OriginalDeferredPackLease(token);
            if (record.step.opcode == ActionOpcodeV1::Stop) {
                EXPECT_EQ(nullptr, original);
                EXPECT_EQ(0u, record.targetPackLease.leaseToken);
                EXPECT_EQ(0u, record.targetPackLease.resourceClosureToken);
            } else {
                ASSERT_NE(nullptr, original);
                ASSERT_TRUE(original->Valid());
                EXPECT_TRUE(engine.OriginalPackIdentityLeaseMatches(*original, record.targetPackLease));
                EXPECT_EQ(VN_IN_USE, engine.ReleasePackIdentityLease(record.targetPackLease));
            }
            tokens.push_back(token);
            records.push_back(record);
        }
        EXPECT_FALSE(engine.originalDeferredTargetPreparation.Valid());
    }

    void ExpectReturned(const std::vector<ActionDeferredRecordToken>& tokens,
        const std::vector<ActionDeferredRecord>& records) {
        auto& engine = *session.Engine();
        ASSERT_EQ(tokens.size(), records.size());
        for (std::size_t i = 0; i < tokens.size(); ++i) {
            EXPECT_EQ(nullptr, engine.OriginalDeferredPackLease(tokens[i]));
            EXPECT_FALSE(engine.packComposition.HasOriginalLeaseEpisode(records[i].targetPackLease));
            EXPECT_NE(VN_OK, engine.packComposition.ValidateLease(records[i].targetPackLease));
            EXPECT_NE(VN_OK, engine.packs.ValidateResourceClosure(records[i].targetPackLease.resourceClosureToken));
        }
        EXPECT_EQ(0u, engine.actionDeferredRecords.LiveCount());
        EXPECT_EQ(0u, engine.actionFirings.OwnedDeferredCount(operation));
        EXPECT_FALSE(engine.runtimeRecreateRequired);
    }
};

static void CheckOriginalDeferredOperationNormalReturn(ActionOpcodeV1 opcode) {
    OriginalDeferredOperationFixture fixture(opcode);
    ASSERT_EQ(VN_OK, fixture.PostOperation());
    std::vector<ActionDeferredRecordToken> tokens;
    std::vector<ActionDeferredRecord> records;
    ASSERT_NO_FATAL_FAILURE(fixture.Capture(tokens, records));
    ASSERT_EQ(1u, records.size());
    auto& engine = *fixture.session.Engine();
    for (std::uint32_t block = 0; block < 256 && engine.actionDeferredRecords.LiveCount() != 0; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine.nullBackend.Pump(1);
    }
    ASSERT_NO_FATAL_FAILURE(fixture.ExpectReturned(tokens, records));
    VnActionStepResult step{};
    step.structSize = sizeof(step);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(fixture.operation, 0, &step));
    EXPECT_EQ(VN_OK, step.result);
    if (opcode == ActionOpcodeV1::Stop) {
        EXPECT_EQ(VN_ACTION_STEP_SUPPRESSED, step.state);
        EXPECT_EQ(0u, step.capturedPlayableCount);
        EXPECT_EQ(0u, step.remainingPlayableCount);
    } else {
        EXPECT_TRUE(step.state == VN_ACTION_STEP_SUCCEEDED || step.state == VN_ACTION_STEP_NO_OP);
    }
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(fixture.operation));
}

TEST(PackComposition, OriginalDeferredResetNormalCompletionReturnsSameNativeLease) {
    ASSERT_NO_FATAL_FAILURE(CheckOriginalDeferredOperationNormalReturn(ActionOpcodeV1::Reset));
}

TEST(PackComposition, DeferredStopWithoutRootsCompletesWithoutTargetLease) {
    ASSERT_NO_FATAL_FAILURE(CheckOriginalDeferredOperationNormalReturn(ActionOpcodeV1::Stop));
}

TEST(PackComposition, OriginalDeferredResetHeldCancelReturnsBeforeSameSlotReuse) {
    OriginalDeferredOperationFixture fixture(ActionOpcodeV1::Reset);
    ASSERT_EQ(VN_OK, fixture.PostOperation());
    std::vector<ActionDeferredRecordToken> tokens;
    std::vector<ActionDeferredRecord> records;
    ASSERT_NO_FATAL_FAILURE(fixture.Capture(tokens, records));
    ASSERT_EQ(1u, tokens.size());
    ASSERT_EQ(VN_OK, Vn_StopActionFiring(fixture.operation, 0));
    ASSERT_NO_FATAL_FAILURE(fixture.ExpectReturned(tokens, records));
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(fixture.operation));
    ASSERT_EQ(VN_OK, fixture.PostOperation());
    std::vector<ActionDeferredRecordToken> nextTokens;
    std::vector<ActionDeferredRecord> nextRecords;
    ASSERT_NO_FATAL_FAILURE(fixture.Capture(nextTokens, nextRecords));
    ASSERT_EQ(1u, nextTokens.size());
    EXPECT_EQ(tokens[0].slot, nextTokens[0].slot);
    EXPECT_GT(nextTokens[0].generation, tokens[0].generation);
    EXPECT_NE(records[0].targetPackLease.leaseToken, nextRecords[0].targetPackLease.leaseToken);
    ASSERT_EQ(VN_OK, Vn_StopActionFiring(fixture.operation, 0));
    ASSERT_NO_FATAL_FAILURE(fixture.ExpectReturned(nextTokens, nextRecords));
}

TEST(PackComposition, OriginalDeferredResetHeldCancelFaultRetainsActualRecordUntilJoinedTerm) {
    OriginalDeferredOperationFixture fixture(ActionOpcodeV1::Reset);
    ASSERT_EQ(VN_OK, fixture.PostOperation());
    std::vector<ActionDeferredRecordToken> tokens;
    std::vector<ActionDeferredRecord> records;
    ASSERT_NO_FATAL_FAILURE(fixture.Capture(tokens, records));
    ASSERT_EQ(1u, tokens.size());
    auto& engine = *fixture.session.Engine();
    ASSERT_EQ(VN_OK, engine.packs.ReleaseResourceClosure(records[0].targetPackLease.resourceClosureToken));
    EXPECT_EQ(VN_RUNTIME_RECREATE_REQUIRED, Vn_StopActionFiring(fixture.operation, 0));
    const auto* original = engine.OriginalDeferredPackLease(tokens[0]);
    ASSERT_NE(nullptr, original);
    EXPECT_TRUE(original->Valid());
    EXPECT_EQ(PackComposition::OriginalLeasePhase::Faulted, original->Phase());
    EXPECT_TRUE(engine.OriginalDeferredHeldCancellationPending(tokens[0]));
    EXPECT_EQ(1u, engine.actionDeferredRecords.LiveCount());
    EXPECT_EQ(1u, engine.actionFirings.OwnedDeferredCount(fixture.operation));
    EXPECT_EQ(VN_RUNTIME_RECREATE_REQUIRED, fixture.PostOperation());
    Vn_Term();
    EXPECT_EQ(VN_NOT_INITIALIZED, Vn_Update());
}

TEST(PackComposition, DeferredStopCapturesEveryRootWithoutAdditionalTargetLeases) {
    OriginalDeferredOperationFixture fixture(ActionOpcodeV1::Stop);
    ASSERT_NO_FATAL_FAILURE(fixture.PostPlay());
    ASSERT_NO_FATAL_FAILURE(fixture.PostPlay());
    ASSERT_EQ(VN_OK, fixture.PostOperation());
    std::vector<ActionDeferredRecordToken> tokens;
    std::vector<ActionDeferredRecord> records;
    ASSERT_NO_FATAL_FAILURE(fixture.Capture(tokens, records));
    ASSERT_EQ(2u, tokens.size());
    EXPECT_NE(records[0].rootPlayable, records[1].rootPlayable);
    EXPECT_NE(0u, records[0].rootPlayable);
    EXPECT_NE(0u, records[1].rootPlayable);
    ASSERT_EQ(VN_OK, Vn_StopActionFiring(fixture.operation, 0));
    ASSERT_NO_FATAL_FAILURE(fixture.ExpectReturned(tokens, records));
    for (auto firing : fixture.plays) ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
}

static bool IsOriginalDeferredOperationTargetAcquisition(Engine& engine) {
    if (engine.actionFiringPlanScratch.empty()) return false;
    const auto& root = engine.actionFiringPlanScratch[0];
    return root.action != nullptr &&
        root.action->actionStableId == OriginalDeferredOperationFixture::kOperation &&
        engine.OriginalPackIdentityLeaseMatches(root.originalPackLease, root.owner.pack);
}

#if defined(HARKEN_TEST_PACK_RESOURCE_OBSERVATION)
TEST(PackComposition, DeferredStopPartialCapturePoolRefusalRollsBackWithoutTargetAcquisition) {
    OriginalDeferredOperationFixture fixture(ActionOpcodeV1::Stop);
    ASSERT_NO_FATAL_FAILURE(fixture.PostPlay());
    ASSERT_NO_FATAL_FAILURE(fixture.PostPlay());
    auto& engine = *fixture.session.Engine();
    std::vector<DeferredIntentToken> fillers;
    for (std::uint32_t i = 0; i + 1u < engine.timelineDeferred.Capacity(); ++i) {
        DeferredIntent intent{};
        intent.ownerHandle = 0x1000u + i;
        intent.ownerEpoch = 1;
        intent.dueFrame = UINT64_MAX - i;
        intent.commitSequence = i + 1u;
        const auto added = engine.timelineDeferred.AddClaimable(intent);
        ASSERT_EQ(DeferredIntentRefusal::None, added.status);
        fillers.push_back(added.token);
    }
    std::vector<PackPartitionLease> acquired;
    struct Capture { std::vector<PackPartitionLease>* targets; PackPartitionLease definition{};
        unsigned definitionCalls = 0; } capture{&acquired};
    engine.originalPackResourceAcquiredHookForTest = [](Engine& actual, const PackPartitionLease& lease,
        PackResourceClosureToken resource, void* context) {
        auto observed = lease;
        observed.resourceClosureToken = resource;
        auto& output = *static_cast<Capture*>(context);
        if (IsOriginalDeferredOperationTargetAcquisition(actual)) {
            output.targets->push_back(observed);
        } else {
            output.definition = observed;
            ++output.definitionCalls;
        }
    };
    engine.originalPackResourceAcquiredContextForTest = &capture;
    EXPECT_EQ(VN_BACKPRESSURE, fixture.PostOperation());
    engine.originalPackResourceAcquiredHookForTest = nullptr;
    engine.originalPackResourceAcquiredContextForTest = nullptr;
    EXPECT_EQ(0u, fixture.operation);
    EXPECT_TRUE(acquired.empty());
    ASSERT_EQ(1u, capture.definitionCalls);
    EXPECT_FALSE(engine.packComposition.HasOriginalLeaseEpisode(capture.definition));
    EXPECT_EQ(VN_STALE_HANDLE, engine.packs.ValidateResourceClosure(capture.definition.resourceClosureToken));
    EXPECT_FALSE(engine.actionFiringPlanScratch[0].originalPackLease.Valid());
    for (const auto& lease : acquired) {
        EXPECT_FALSE(engine.packComposition.HasOriginalLeaseEpisode(lease));
        EXPECT_NE(VN_OK, engine.packs.ValidateResourceClosure(lease.resourceClosureToken));
    }
    EXPECT_FALSE(engine.originalDeferredTargetPreparation.Valid());
    EXPECT_EQ(0u, engine.actionDeferredRecords.LiveCount());
    EXPECT_EQ(0u, engine.actionDeferredRecords.PreparedCount());
    EXPECT_EQ(fillers.size(), engine.timelineDeferred.Count());
    EXPECT_FALSE(engine.runtimeRecreateRequired);
    for (const auto token : fillers) ASSERT_TRUE(engine.timelineDeferred.Cancel(token));
}
#endif


static void CheckDeferredPendingStopSettlement(bool cancelStop) {
    OriginalDeferredOperationFixture fixture(ActionOpcodeV1::Stop, true);
    ASSERT_NO_FATAL_FAILURE(fixture.PostPlay());
    ASSERT_EQ(VN_OK, fixture.PostOperation());
    std::vector<ActionDeferredRecordToken> tokens;
    std::vector<ActionDeferredRecord> records;
    ASSERT_NO_FATAL_FAILURE(fixture.Capture(tokens, records));
    ASSERT_EQ(1u, tokens.size());
    ASSERT_TRUE(records[0].waitingForImmediateEntry);
    auto& engine = *fixture.session.Engine();
    if (cancelStop) ASSERT_EQ(VN_OK, Vn_StopActionFiring(fixture.operation, 0));
    ASSERT_EQ(VN_OK, Vn_StopActionFiring(fixture.plays[0], 0));
    EXPECT_EQ(VN_OK, Vn_Update());
    ASSERT_NO_FATAL_FAILURE(fixture.ExpectReturned(tokens, records));
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(fixture.operation));
}

TEST(PackComposition, DeferredPendingStopTargetGoneReclaimsRecordWithoutTargetLease) {
    ASSERT_NO_FATAL_FAILURE(CheckDeferredPendingStopSettlement(false));
}

TEST(PackComposition, DeferredPendingStopCancellationReclaimsPairWithoutTargetLease) {
    ASSERT_NO_FATAL_FAILURE(CheckDeferredPendingStopSettlement(true));
}

TEST(PackComposition, DeferredStopMaterializationStopsActualPcmWithoutTargetLease) {
    OriginalDeferredOperationFixture fixture(ActionOpcodeV1::Stop);
    ASSERT_NO_FATAL_FAILURE(fixture.PostPlay());
    ASSERT_EQ(VN_OK, fixture.PostOperation());
    std::vector<ActionDeferredRecordToken> tokens;
    std::vector<ActionDeferredRecord> records;
    ASSERT_NO_FATAL_FAILURE(fixture.Capture(tokens, records));
    ASSERT_EQ(1u, tokens.size());
    auto& engine = *fixture.session.Engine();
    const auto boundary = records[0].lastRowFrame;
    const auto declickFrames = static_cast<std::uint32_t>(
        (static_cast<std::uint64_t>(kTimelineStopDeclickMs) *
            OriginalDeferredOperationFixture::kSampleRate + 999u) / 1000u);
    ASSERT_GT(declickFrames, 0u);
    bool heard = false;
    while (engine.mixer.BlocksRendered() * engine.nullBackend.BlockFrames() < boundary + 4096u) {
        ASSERT_EQ(VN_OK, Vn_Update());
        const auto start = engine.mixer.BlocksRendered() * engine.nullBackend.BlockFrames();
        engine.nullBackend.Pump(1);
        const auto* pcm = engine.nullBackend.LastBlock();
        for (std::uint32_t frame = 0; frame < engine.nullBackend.BlockFrames(); ++frame) {
            const float left = pcm[frame * engine.nullBackend.Channels()];
            const auto sampleFrame = start + frame;
            if (sampleFrame >= boundary + declickFrames) {
                EXPECT_NEAR(0.0f, left, 1e-4f);
            } else if (sampleFrame >= boundary) {
                const auto elapsed = sampleFrame - boundary;
                const float expected = 0.25f * (1.0f -
                    static_cast<float>(elapsed + 1u) / declickFrames);
                EXPECT_NEAR(expected, left, 1e-4f) << sampleFrame;
            } else {
                heard |= std::abs(left) > 1e-4f;
            }
        }
    }
    EXPECT_TRUE(heard);
    ASSERT_NO_FATAL_FAILURE(fixture.ExpectReturned(tokens, records));
    EXPECT_EQ(0u, engine.playableInstances.LiveCount());
    EXPECT_EQ(0u, engine.voices.ActiveCount());
    EXPECT_EQ(0u, engine.decisions.LiveCount());
}

#if defined(HARKEN_TEST_PACK_RESOURCE_OBSERVATION)
static void CheckOriginalDeferredPreparationCapacityExit(ActionOpcodeV1 opcode, bool fault) {
    OriginalDeferredOperationFixture fixture(opcode);
    auto& engine = *fixture.session.Engine();
    // A deliberate zero staging capacity exercises the pre-record exit. It
    // neither clears a live cap nor supplies replacement ownership evidence.
    engine.actionDeferredScratch.clear();
    struct Prefix { PackPartitionLease lease{}; PackResourceClosureToken resource = 0;
        unsigned calls = 0; bool fault = false; PackPartitionLease definition{};
        unsigned definitionCalls = 0; } prefix;
    prefix.fault = fault;
    engine.originalPackResourceAcquiredHookForTest = [](Engine& actual, const PackPartitionLease& lease,
        PackResourceClosureToken resource, void* context) {
        auto& state = *static_cast<Prefix*>(context);
        if (!IsOriginalDeferredOperationTargetAcquisition(actual)) {
            state.definition = lease;
            state.definition.resourceClosureToken = resource;
            ++state.definitionCalls;
            return;
        }
        state.lease = lease;
        state.resource = resource;
        ++state.calls;
        EXPECT_TRUE(actual.packComposition.HasOriginalLeaseEpisode(lease));
        EXPECT_EQ(VN_OK, actual.packs.ValidateResourceClosure(resource));
        if (state.fault) EXPECT_EQ(VN_OK, actual.packs.ReleaseResourceClosure(resource));
    };
    engine.originalPackResourceAcquiredContextForTest = &prefix;
    EXPECT_EQ(VN_BACKPRESSURE, fixture.PostOperation());
    engine.originalPackResourceAcquiredHookForTest = nullptr;
    engine.originalPackResourceAcquiredContextForTest = nullptr;
    ASSERT_EQ(opcode == ActionOpcodeV1::Stop ? 0u : 1u, prefix.calls);
    ASSERT_EQ(1u, prefix.definitionCalls);
    EXPECT_FALSE(engine.packComposition.HasOriginalLeaseEpisode(prefix.definition));
    EXPECT_EQ(VN_STALE_HANDLE, engine.packs.ValidateResourceClosure(prefix.definition.resourceClosureToken));
    EXPECT_FALSE(engine.actionFiringPlanScratch[0].originalPackLease.Valid());
    EXPECT_EQ(0u, fixture.operation);
    EXPECT_EQ(0u, engine.actionDeferredRecords.LiveCount());
    EXPECT_EQ(0u, engine.actionDeferredRecords.PreparedCount());
    EXPECT_EQ(0u, engine.timelineDeferred.Count());
    EXPECT_NE(VN_OK, engine.packs.ValidateResourceClosure(prefix.resource));
    if (!fault) {
        EXPECT_FALSE(engine.originalDeferredTargetPreparation.Valid());
        EXPECT_FALSE(engine.packComposition.HasOriginalLeaseEpisode(prefix.lease));
        EXPECT_FALSE(engine.runtimeRecreateRequired);
    } else {
        EXPECT_TRUE(engine.originalDeferredTargetPreparation.Valid());
        EXPECT_EQ(prefix.lease.leaseToken, engine.originalDeferredTargetPreparation.OriginalLease().leaseToken);
        EXPECT_EQ(prefix.resource, engine.originalDeferredTargetPreparation.OriginalLease().resourceClosureToken);
        EXPECT_EQ(PackComposition::OriginalLeasePhase::Faulted, engine.originalDeferredTargetPreparation.Phase());
        EXPECT_TRUE(engine.packComposition.HasOriginalLeaseEpisode(prefix.lease));
        EXPECT_TRUE(engine.runtimeRecreateRequired);
        EXPECT_EQ(VN_RUNTIME_RECREATE_REQUIRED, fixture.PostOperation());
        Vn_Term();
        EXPECT_EQ(VN_NOT_INITIALIZED, Vn_Update());
    }
}
#endif


