static PackPartitionLease CaptureOriginalActionDefinition(
    Engine& engine, VnActionFiringHandle firing) {
    const auto* original = engine.OriginalActionFiringPackLease(firing);
    EXPECT_NE(nullptr, original);
    if (original == nullptr) return {};
    EXPECT_TRUE(original->Valid());
    EXPECT_EQ(PackComposition::OriginalLeasePhase::Live, original->Phase());
    ActionFiringSnapshot actual{};
    EXPECT_TRUE(engine.actionFirings.Capture(firing, &actual));
    const auto lease = original->OriginalLease();
    EXPECT_TRUE(engine.OriginalPackIdentityLeaseMatches(*original, actual.owner.pack));
    EXPECT_EQ(VN_IN_USE, engine.ReleasePackIdentityLease(lease));
    return lease;
}

static void PumpOriginalActionToTerminal(OriginalDeferredOperationFixture& fixture,
    VnActionFiringHandle firing, bool* heard = nullptr) {
    auto& engine = *fixture.session.Engine();
    bool terminal = false;
    for (std::uint32_t block = 0; block < 768; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine.nullBackend.Pump(1);
        if (heard != nullptr) {
            const auto* pcm = engine.nullBackend.LastBlock();
            for (std::uint32_t frame = 0; frame < engine.nullBackend.BlockFrames(); ++frame)
                *heard |= std::abs(pcm[frame * engine.nullBackend.Channels()]) > 1e-4f;
        }
        ActionFiringSnapshot actual{};
        ASSERT_TRUE(engine.actionFirings.Capture(firing, &actual));
        if (actual.state == ActionFiringState::TerminalRetained) { terminal = true; break; }
    }
    ASSERT_TRUE(terminal);
}

TEST(PackComposition, OriginalActionDefinitionReturnsAfterActualSoundTerminalAndReusesHigherGeneration) {
    OriginalDeferredOperationFixture fixture(ActionOpcodeV1::Stop);
    ASSERT_NO_FATAL_FAILURE(fixture.PostPlay());
    auto& engine = *fixture.session.Engine();
    const auto first = fixture.plays[0];
    const auto lease = CaptureOriginalActionDefinition(engine, first);
    bool heard = false;
    ASSERT_NO_FATAL_FAILURE(PumpOriginalActionToTerminal(fixture, first, &heard));
    EXPECT_TRUE(heard);
    ASSERT_NE(nullptr, engine.OriginalActionFiringPackLease(first));
    EXPECT_TRUE(engine.OriginalActionFiringPackLease(first)->Valid());
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(first));
    EXPECT_EQ(nullptr, engine.OriginalActionFiringPackLease(first));
    EXPECT_FALSE(engine.packComposition.HasOriginalLeaseEpisode(lease));
    EXPECT_EQ(VN_STALE_HANDLE, engine.packComposition.ValidateLease(lease));
    EXPECT_EQ(VN_STALE_HANDLE, engine.packs.ValidateResourceClosure(lease.resourceClosureToken));
    ASSERT_NO_FATAL_FAILURE(fixture.PostPlay());
    const auto second = fixture.plays[1];
    EXPECT_EQ(first & (kMaxActionFiringsHard - 1u), second & (kMaxActionFiringsHard - 1u));
    EXPECT_GT(second >> kActionFiringSlotBits, first >> kActionFiringSlotBits);
    EXPECT_EQ(nullptr, engine.OriginalActionFiringPackLease(first));
    ASSERT_NO_FATAL_FAILURE(CaptureOriginalActionDefinition(engine, second));
    ASSERT_EQ(VN_OK, Vn_StopActionFiring(second, 0));
    ASSERT_NO_FATAL_FAILURE(PumpOriginalActionToTerminal(fixture, second));
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(second));
}

