TEST(PackComposition, OriginalActionDefinitionRejectsBindingBeforeActualFiringFactoryCommit) {
    OriginalDeferredOperationFixture fixture(ActionOpcodeV1::Stop);
    auto& engine = *fixture.session.Engine();
    PackIdentityLookup actual{};
    EngineOriginalPackIdentityLease original;
    ASSERT_EQ(VN_OK, engine.AcquirePackIdentityLease(ContainerMatrixWorld::kAction,
        PackLeaseSlice::SharedActionAndDeferred, &actual, &original));
    const auto owner = ActionFiringOwnerStamp::Pack(actual.lease,
        engine.packComposition.ProjectIdAtLease(actual.lease));
    PreparedActionFiring prepared;
    ASSERT_TRUE(engine.actionFirings.PrepareRoot(ContainerMatrixWorld::kAction,
        owner, actual.action->stepCount, &prepared));
    ASSERT_TRUE(engine.actionFirings.SetPreparedProgramFingerprint(prepared,
        actual.action->programSemanticFingerprint));
    EXPECT_FALSE(engine.AdoptOriginalActionFiringPack(prepared.Handle(), original, owner));
    EXPECT_TRUE(original.Valid());
    EXPECT_EQ(nullptr, engine.OriginalActionFiringPackLease(prepared.Handle()));
    ASSERT_TRUE(engine.actionFirings.Abandon(&prepared));
    EXPECT_EQ(VN_OK, engine.ReleaseOriginalPackIdentityLease(original));
}

struct OriginalActionFiringCapacityFill {
    Engine& engine;
    PackIdentityLookup owner;
    std::vector<PreparedActionFiring> prepared;
    explicit OriginalActionFiringCapacityFill(Engine& actual) : engine(actual) {
        EXPECT_EQ(VN_OK, engine.AcquirePackIdentityLease(ContainerMatrixWorld::kAction, &owner));
        const auto stamp = ActionFiringOwnerStamp::Pack(owner.lease,
            engine.packComposition.ProjectIdAtLease(owner.lease));
        for (;;) {
            PreparedActionFiring row;
            if (!engine.actionFirings.PrepareRoot(ContainerMatrixWorld::kAction, stamp, 0, &row)) break;
            prepared.push_back(row);
        }
        EXPECT_FALSE(prepared.empty());
    }
    void Return() {
        for (auto& row : prepared) EXPECT_TRUE(engine.actionFirings.Abandon(&row));
        prepared.clear();
        EXPECT_EQ(VN_OK, engine.ReleasePackIdentityLease(owner.lease));
        owner = {};
    }
};

#if defined(HARKEN_TEST_PACK_RESOURCE_OBSERVATION)
static void CheckOriginalActionDefinitionCapacityReturn(bool fault) {
    OriginalDeferredOperationFixture fixture(ActionOpcodeV1::Reset);
    auto& engine = *fixture.session.Engine();
    OriginalActionFiringCapacityFill fill(engine);
    struct Observed { PackPartitionLease lease{}; std::uint32_t acquired = 0; bool fault = false; } observed;
    observed.fault = fault;
    engine.originalPackResourceAcquiredContextForTest = &observed;
    engine.originalPackResourceAcquiredHookForTest = [](Engine& actual,
        const PackPartitionLease& lease, PackResourceClosureToken closure, void* opaque) {
        auto& out = *static_cast<Observed*>(opaque);
        ++out.acquired; out.lease = lease; out.lease.resourceClosureToken = closure;
        if (out.fault) EXPECT_EQ(VN_OK, actual.packs.ReleaseResourceClosure(closure));
    };
    EXPECT_EQ(fault ? VN_RUNTIME_RECREATE_REQUIRED : VN_NO_ACTION, fixture.PostOperation());
    engine.originalPackResourceAcquiredHookForTest = nullptr;
    engine.originalPackResourceAcquiredContextForTest = nullptr;
    ASSERT_EQ(1u, observed.acquired);
    EXPECT_EQ(0u, fixture.operation);
    EXPECT_FALSE(engine.originalActionFiringPreparation.Valid());
    if (!fault) {
        EXPECT_FALSE(engine.actionFiringPlanScratch[0].originalPackLease.Valid());
        EXPECT_FALSE(engine.packComposition.HasOriginalLeaseEpisode(observed.lease));
        EXPECT_EQ(VN_STALE_HANDLE, engine.packComposition.ValidateLease(observed.lease));
        EXPECT_EQ(VN_STALE_HANDLE, engine.packs.ValidateResourceClosure(observed.lease.resourceClosureToken));
        fill.Return();
        ASSERT_EQ(VN_OK, fixture.PostOperation());
        ASSERT_EQ(VN_OK, Vn_StopActionFiring(fixture.operation, 0));
        EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(fixture.operation));
    } else {
        const auto& original = engine.actionFiringPlanScratch[0].originalPackLease;
        ASSERT_TRUE(original.Valid());
        EXPECT_TRUE(engine.OriginalPackIdentityLeaseMatches(original, observed.lease));
        EXPECT_EQ(PackComposition::OriginalLeasePhase::Faulted, original.Phase());
        EXPECT_TRUE(engine.runtimeRecreateRequired);
        fill.Return();
        EXPECT_EQ(VN_RUNTIME_RECREATE_REQUIRED, fixture.PostOperation());
        Vn_Term();
        EXPECT_EQ(VN_NOT_INITIALIZED, Vn_Update());
    }
}
#endif


