    EXPECT_TRUE(engine.OriginalPackIdentityLeaseMatches(
        *engine.OriginalActionFiringPackLease(child), records[0].targetPackLease));
    EXPECT_EQ(nullptr, engine.OriginalDeferredPackLease(tokens[0]));
