TEST(PackComposition, OriginalActionDefinitionNestedTerminalReturnFaultKeepsReturnedPrefixAndRealTreeUntilJoinedTerm) {
    OriginalDeferredOperationFixture fixture(ActionOpcodeV1::PostAction, false, true);
    ASSERT_EQ(VN_OK, fixture.PostOperation());
    auto& engine = *fixture.session.Engine();
    VnActionStepResult step{}; step.structSize = sizeof(step);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(fixture.operation, 0, &step));
    ASSERT_NE(0u, step.childFiring);
    const auto parent = CaptureOriginalActionDefinition(engine, fixture.operation);
    const auto child = CaptureOriginalActionDefinition(engine, step.childFiring);
    ASSERT_NO_FATAL_FAILURE(PumpOriginalActionToTerminal(fixture, fixture.operation));
    ASSERT_EQ(VN_OK, engine.packs.ReleaseResourceClosure(child.resourceClosureToken));
    ASSERT_EQ(VN_RUNTIME_RECREATE_REQUIRED, Vn_ReleaseActionFiring(fixture.operation));
    const auto* returned = engine.OriginalActionFiringPackLease(fixture.operation);
    const auto* faulted = engine.OriginalActionFiringPackLease(step.childFiring);
    ASSERT_NE(nullptr, returned); ASSERT_NE(nullptr, faulted);
    EXPECT_FALSE(returned->Valid());
    EXPECT_EQ(PackComposition::OriginalLeasePhase::Released, returned->Phase());
    EXPECT_FALSE(engine.packComposition.HasOriginalLeaseEpisode(parent));
    EXPECT_TRUE(faulted->Valid());
    EXPECT_EQ(PackComposition::OriginalLeasePhase::Faulted, faulted->Phase());
    EXPECT_TRUE(engine.OriginalPackIdentityLeaseMatches(*faulted, child));
    ActionFiringSnapshot actual{};
    ASSERT_TRUE(engine.actionFirings.Capture(fixture.operation, &actual));
    EXPECT_EQ(ActionFiringState::TerminalRetained, actual.state);
    ASSERT_TRUE(engine.actionFirings.Capture(step.childFiring, &actual));
    EXPECT_EQ(ActionFiringState::TerminalRetained, actual.state);
    EXPECT_EQ(VN_RUNTIME_RECREATE_REQUIRED, Vn_ReleaseActionFiring(fixture.operation));
    EXPECT_FALSE(returned->Valid());
    EXPECT_TRUE(faulted->Valid());
    EXPECT_EQ(VN_RUNTIME_RECREATE_REQUIRED, fixture.PostOperation());
    Vn_Term();
    EXPECT_EQ(VN_NOT_INITIALIZED, Vn_Update());
}

