struct ContainerMatrixTrace {
    std::array<std::uint32_t, kSelectionPathNodeCapacity> selected{};
    std::uint32_t selectedCount = 0;
    std::array<std::int64_t, kMaxKnownScheduleLeaves> onsets{};
    std::uint32_t onsetCount = 0;
    std::array<PlayableKind, 4> kinds{};
    std::uint32_t depth = 0;
    bool parentRelationsValid = false;
    bool epochsValid = false;
    bool reclaimed = false;
};

enum class ContainerMatrixEntry : std::uint8_t {
    Direct,
    CurrentWorldAction,
    PackAction,
};

struct VariableControlLifetimeWorld {
    ContainerMatrixWorld base;
    std::array<ContainerChildProgramViewV2, 2> children{};
    std::array<DiscreteGridCellV1, 3> discreteCells{};
    std::array<DiscreteGridRowViewV1, 3> discreteRows{};
    std::array<ContinuousGridCellV1, 2> continuousCells{};
    std::array<ContinuousGridRowViewV1, 2> continuousRows{};

    VariableControlLifetimeWorld(bool continuous, bool nested,
                         std::uint64_t firstRevision, std::uint64_t secondRevision,
                         bool delayTail = false)
        : base(ContainerModeV1::VariableControl, ContainerMatrixChild::Sound,
               firstRevision, secondRevision, false, 1, 0,
               MemoryScopeV1::Global, MemoryScopeV1::Emitter, delayTail) {
        auto control = base.containers[0];
        if (nested) {
            auto& property = base.properties[base.propertyCount++];
            property = MakeContainerProperty(ContainerMatrixWorld::kNested, 2);
            SetContainerPropertyLoopCount(&property, 1);
            property.programSemanticFingerprint = ComputePlayablePropertyFingerprintV1(property);
            control.containerStableId = property.stableId;
            control.programSemanticFingerprint = property.programSemanticFingerprint;
            control.authoredStableOrder = 2;
            SetContainerPropertyLoopCount(&base.properties[1], 2);
            base.properties[1].programSemanticFingerprint =
                ComputePlayablePropertyFingerprintV1(base.properties[1]);
            base.rootRef = PlayableRefFromProperty(base.properties[1]);
            base.containers[0] = MakeContainerProgram(ContainerMatrixWorld::kRoot,
                base.properties[1].programSemanticFingerprint);
            base.containers[0].mode = ContainerModeV1::Sequence;
            base.containers[0].childCount = 1;
            base.containers[0].children = base.children.data();
            base.children[0].playable = PlayableRefFromProperty(property);
            base.world.containerCount = 2;
            base.world.identity.capabilityMask |= kWorldCapabilitySequence;
        }
        auto& second = base.properties[base.propertyCount++];
        second = MakeSoundProperty(ContainerMatrixWorld::kSecondSound);
        second.authoredStableOrder = base.propertyCount - 1;
        second.contentRevision = secondRevision;
        second.programSemanticFingerprint = ComputePlayablePropertyFingerprintV1(second);
        for (std::uint32_t index = 0; index < children.size(); ++index) {
            children[index].stableChildOrdinal = 7u + index;
            children[index].authoredStableOrder = index;
            children[index].playable = PlayableRefFromProperty(index == 0 ? base.properties[0] : second);
            children[index].queueStopPolicy = QueueStopPolicyV1::AbortOwningQueue;
            continuousCells[index].kind = ContinuousCellKindV1::Interval;
            continuousCells[index].lower = index == 0 ? 0.0f : 2.0f;
            continuousCells[index].upper = index == 0 ? 1.0f : 3.0f;
            continuousCells[index].lowerInclusive = continuousCells[index].upperInclusive = 1;
            continuousRows[index].stableRowOrdinal = index + 1;
            continuousRows[index].authoredStableOrder = index;
            continuousRows[index].childStableOrdinal = children[index].stableChildOrdinal;
            continuousRows[index].cellCount = 1;
            continuousRows[index].cells = &continuousCells[index];
        }
        for (std::uint32_t index = 0; index < discreteRows.size(); ++index) {
            discreteCells[index] = {DiscreteCellKindV1::Exact, static_cast<std::int32_t>(index)};
            discreteRows[index].stableRowOrdinal = index + 1;
            discreteRows[index].authoredStableOrder = index;
            discreteRows[index].childStableOrdinal = index < 2 ? 7 : 8;
            discreteRows[index].cellCount = 1;
            discreteRows[index].cells = &discreteCells[index];
        }
        base.variable = harkentest::MakeVariableDefinition(ContainerMatrixWorld::kVariable,
            continuous ? VariableKindV1::Smooth : VariableKindV1::Step, 0.0f, 4.0f, 0.0f);
        control.childCount = children.size();
        control.children = children.data();
        control.discreteAxisCount = continuous ? 0 : 1;
        control.discreteAxes = continuous ? nullptr : &base.axis;
        control.discreteRowCount = continuous ? 0 : discreteRows.size();
        control.discreteRows = continuous ? nullptr : discreteRows.data();
        control.discreteTiming = continuous ? 0 : 1;
        control.continuousAxisCount = continuous ? 1 : 0;
        control.continuousAxes = continuous ? &base.axis : nullptr;
        control.continuousRowCount = continuous ? continuousRows.size() : 0;
        control.continuousRows = continuous ? continuousRows.data() : nullptr;
        control.evaluationPeriodFrames = 64;
        control.envelopeFrames = continuous ? 64 : 0;
        control.maxActiveRows = continuous ? 2 : 0;
        control.maxLiveRows = continuous ? 4 : 0;
        base.containers[nested ? 1 : 0] = control;
        base.occurrenceCount = 0;
        const auto occurrence = [&](const ContainerProgramViewV3& parent,
                                    const ContainerChildProgramViewV2& child) {
            auto& value = base.occurrences[base.occurrenceCount++];
            value = {};
            value.parentKind = playableproperties::ContentPropertyKindV1::Container;
            value.parentStableId = parent.containerStableId;
            value.parentProgramSemanticFingerprint = parent.programSemanticFingerprint;
            value.stableOccurrenceOrdinal = child.stableChildOrdinal;
            value.childPlayable = child.playable;
            value.payload = EmptyOccurrencePayload();
            value.occurrenceSemanticFingerprint = ComputePlayableOccurrenceFingerprintV1(value);
        };
        if (nested) occurrence(base.containers[0], base.children[0]);
        for (const auto& child : children) occurrence(control, child);
        base.step.target.expectedProgramSemanticFingerprint = base.rootRef.expectedProgramSemanticFingerprint;
        base.action.programSemanticFingerprint = ComputeActionProgramFingerprintV1(base.action);
        base.world.playablePropertyCount = base.propertyCount;
        base.world.playableOccurrenceCount = base.occurrenceCount;
        std::sort(base.properties.begin(), base.properties.begin() + base.propertyCount,
            [](const auto& left, const auto& right) {
                return left.contentPropertyKind != right.contentPropertyKind
                    ? left.contentPropertyKind < right.contentPropertyKind
                    : left.stableId < right.stableId;
            });
        base.world.identity.runtimeSemanticFingerprint = ComputeCurrentWorldFingerprintV4(base.world);
    }
};

void ExpectVariableControlNaturalCompletion(ContainerMatrixEntry entry, bool continuous, bool nested,
                                        bool delayTail = false) {
    SCOPED_TRACE(::testing::Message() << "entry=" << static_cast<unsigned>(entry)
        << " continuous=" << continuous << " nested=" << nested);
    (void)Vn_Term();
    const std::vector<float> firstSamples(512, 0.25f), secondSamples(4096, -0.25f);
    const float* firstChannels[] = {firstSamples.data()};
    const float* secondChannels[] = {secondSamples.data()};
    std::uint64_t firstRevision = 0, secondRevision = 0;
    ASSERT_TRUE(ComputeMediaPcmContentRevisionV1(48000, 1, firstSamples.size(), firstChannels, 1, &firstRevision));
    ASSERT_TRUE(ComputeMediaPcmContentRevisionV1(48000, 1, secondSamples.size(), secondChannels, 1, &secondRevision));
    VariableControlLifetimeWorld fixture(continuous, nested, firstRevision, secondRevision, delayTail);
    auto& image = fixture.base;
    auto config = MakeNullConfig(16, 64, 48000);
    if (delayTail) {
        config.fxSlotsPerVoice = 1;
        config.delayEffectPoolCapacity = 16;
        config.voiceSendSlots = 1;
    }
    EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    if (entry == ContainerMatrixEntry::PackAction) {
        ImageBuilder builder(kPackKindCanonicalContent);
        builder.AddEntry(kPackEntryKindPackRequirementBlock, 22, RequirementPayload(22, 1, 1));
        builder.AddEntry(kPackEntryKindCanonicalDefinitionPartition, 22,
            WrapWorldPartition(22, 1, image.world, image.world.playablePropertyCount +
                image.world.actionCount + image.world.variableCount));
        builder.AddMedia(ContainerMatrixWorld::kFirstSound, firstSamples);
        builder.AddMedia(ContainerMatrixWorld::kSecondSound, secondSamples);
        const auto bytes = builder.Build();
        const auto init = BuildSingleIdentityInit(Fnv1a64(bytes.data(), bytes.size()),
            ContainerMatrixWorld::kAction, "u6-finite-vc-a.pack", ContainerMatrixWorld::kRoot, harkentest::ObjectId(0), {}, delayTail ? 2 : 0);
        const auto initPath = WriteTemp("u6-finite-vc-init.pack", init);
        const auto path = WriteTemp("u6-finite-vc-a.pack", bytes);
        VnCanonicalPackSetMemberV1 members[2]{};
        VnCanonicalPackSetMemberResultV1 rows[2]{};
        const char* paths[] = {initPath.c_str(), path.c_str()};
        for (std::size_t i = 0; i < 2; ++i) {
            members[i].structSize = sizeof(members[i]);
            members[i].packStableId = i == 0 ? 11 : 22;
            members[i].packKind = i == 0 ? VN_CANONICAL_PACK_SET_MEMBER_INIT
                                        : VN_CANONICAL_PACK_SET_MEMBER_CONTENT;
            members[i].utf8Path = paths[i];
            rows[i].structSize = sizeof(rows[i]);
        }
        VnCanonicalPackSetActivationReportV1 activated{};
        ASSERT_EQ(VN_OK, harkentest::ActivateCanonicalMembersV1(
                              members, 2, rows, activated));
        ASSERT_NE(0u, rows[1].handle);
    } else {
        const auto first = harkentest::MonoDesc(firstSamples, 48000);
        const auto second = harkentest::MonoDesc(secondSamples, 48000);
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(ContainerMatrixWorld::kFirstSound, &first));
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(ContainerMatrixWorld::kSecondSound, &second));
        if (delayTail) ASSERT_EQ(VN_OK, Vn_CreateBus(VN_OBJECT_ID(0, 2), VN_BUS_MASTER));
        ASSERT_EQ(WorldInstallStatus::Ok, InstallContainerWorldV1(engine, image.world).status);
    }
    const auto instances = engine.playableInstances.LiveCount();
    const auto containers = engine.containerPlayback.LiveCount();
    const auto controls = engine.variableControlInstances.LiveCount();
    const auto decisions = engine.decisions.LiveCount();
    const auto arms = engine.timelineArms.LiveCount();
    const auto groups = engine.armGroups.FreeCount();
    const auto occurrences = engine.timelineOccurrences.OccupiedCount();
    const auto compositeOwners = engine.compositeCompletionOwners.OccupiedCount();
    const auto ledger = engine.ledger.AvailableEntryCount();
    const auto delays = engine.effectBank.DelayInUse();
    const auto transactions = engine.timelinePool.LiveTransactionCount();
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    PlayableInstanceHandle root = 0;
    VnActionFiringHandle firing = 0;
    if (entry == ContainerMatrixEntry::Direct) {
        const auto start = StartCurrentPlayableByIdentity(PlayableKindV1::Container, ContainerMatrixWorld::kRoot, emitter);
        ASSERT_EQ(PlayableStartStatus::Accepted, start.status);
        root = start.instance;
    } else {
        VnPostActionDesc post{};
        post.structSize = sizeof(post);
        post.actionId = harkentest::ObjectId(ContainerMatrixWorld::kAction);
        post.emitter = emitter;
        ASSERT_EQ(VN_OK, Vn_PostAction(&post, &firing));
        VnActionStepResult result{};
        result.structSize = sizeof(result);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &result));
        root = result.producedPlayableInstance;
    }
    auto row = std::find_if(engine.playableServices.begin(), engine.playableServices.end(),
        [root](const auto& candidate) { return candidate.InvocationValid() &&
            (candidate.rootInstance == root || candidate.Invocation().variableControlOuterRootInstance == root); });
    ASSERT_NE(engine.playableServices.end(), row);
    const auto controller = row->rootInstance;
    const auto controllerEpoch = engine.playableInstances.Classify(controller).scheduleEpoch;
    const auto serviceToken = row->identity;
    const auto partitionToken = row->partition;
    ASSERT_TRUE(partitionToken.Valid());
    EXPECT_EQ(controller, row->ownerInstance);
    EXPECT_EQ(controllerEpoch, row->ownerEpoch);
    EXPECT_EQ(&*row, engine.ResolvePlayableService(serviceToken, controller, controllerEpoch));
    EXPECT_EQ(nullptr, engine.ResolvePlayableService(
        {serviceToken.slot, serviceToken.generation + 1u}, controller, controllerEpoch));
    EXPECT_EQ(nullptr, engine.ResolvePlayableService(serviceToken, controller, controllerEpoch + 1u));
    EXPECT_EQ(nested ? 2u : 1u, engine.playablePartitions.OccupiedCount());
    if (nested) {
        const auto* outer = FrontierServiceForOwner(engine, root);
        ASSERT_NE(nullptr, outer);
        EXPECT_EQ(outer, engine.ResolvePlayableService(row->parentService));
        EXPECT_EQ(row->invocation, outer->invocation);
        EXPECT_NE(partitionToken.slot, outer->partition.slot);
    }
    ContainerPlaybackRow controllerExecution{};
    ASSERT_TRUE(engine.containerPlayback.Capture(controller, &controllerExecution));
    EXPECT_EQ(controllerEpoch, controllerExecution.expectedScheduleEpoch);
    EXPECT_EQ(static_cast<std::uint8_t>(ContainerModeV1::VariableControl), controllerExecution.mode);
    EXPECT_EQ(ContainerPlaybackPhase::Active, controllerExecution.phase);
    EXPECT_EQ(0u, controllerExecution.activeChild);
    EXPECT_EQ(containers + (nested ? 2u : 1u), engine.containerPlayback.LiveCount());
    const auto member = row->scheduleStorageBase + (continuous ? row->variableControlContinuousMemberOffset : 0);
    const auto initialArm = engine.playableScheduleArms[member];
    const auto initialChild = row->variableControlChildInstances[0];
    EnginePlayableMemberReference memberReference{
        {serviceToken, controller, controllerEpoch, row->invocationGeneration},
        partitionToken.generation, static_cast<std::uint32_t>(member - row->scheduleStorageBase),
        engine.variableControlMemberCompletions[member].leafInstance,
        engine.variableControlMemberCompletions[member].leafEpoch};
    EnginePlayableServiceRow* memberOwner = nullptr;
    std::size_t memberSlot = SIZE_MAX;
    ASSERT_TRUE(engine.ResolvePlayableMember(memberReference, &memberOwner, &memberSlot));
    EXPECT_EQ(&*row, memberOwner);
    EXPECT_EQ(member, memberSlot);
    for (unsigned mismatch = 0; mismatch < 4; ++mismatch) {
        auto stale = memberReference;
        if (mismatch == 0) ++stale.service.token.generation;
        if (mismatch == 1) ++stale.service.invocationGeneration;
        if (mismatch == 2) ++stale.partitionGeneration;
        if (mismatch == 3) ++stale.leafEpoch;
        memberOwner = nullptr;
        memberSlot = SIZE_MAX;
        EXPECT_FALSE(engine.ResolvePlayableMember(stale, &memberOwner, &memberSlot));
        EXPECT_EQ(nullptr, memberOwner);
        EXPECT_EQ(SIZE_MAX, memberSlot);
    }
    VoiceReleaseObserver released{};
    ASSERT_TRUE(engine.voices.CaptureReleaseObserver(engine.playableScheduleRenderHandles[member], &released));
    bool started = false, completed = false;
    bool sameBlockReleaseChecked = false;
    bool delayedReleaseChecked = false;
    for (unsigned block = 0; block < 48; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine.nullBackend.Pump(1);
        TimelineArmObservation observed{};
        if (engine.timelineArms.Observe(initialArm, &observed)) {
            started |= observed.startedBlockSequence != 0;
            completed |= observed.logicalCompletionSequence != 0;
            if (delayTail && observed.logicalCompletionSequence != 0 &&
                !engine.voices.ReleaseObserved(released)) {
                EXPECT_TRUE(engine.playableInstances.Classify(initialChild).live);
                EXPECT_EQ(delays + 1u, engine.effectBank.DelayInUse());
                EXPECT_FALSE(engine.variableControlMemberCompletions[member].resourcesRetired);
                delayedReleaseChecked = true;
            }
        }
        if (!sameBlockReleaseChecked && engine.voices.ReleaseObserved(released)) {
            const auto releaseBlock = engine.mixer.BlocksRendered();
            ASSERT_TRUE(engine.playableInstances.Classify(initialChild).live);
            ASSERT_EQ(VN_OK, Vn_Update());
            ASSERT_EQ(VN_OK, Vn_Update());
            EXPECT_EQ(releaseBlock, engine.mixer.BlocksRendered());
            EXPECT_TRUE(engine.playableInstances.Classify(initialChild).live);
            const auto* source = engine.sourceTerminals.Resolve(
                engine.variableControlMemberCompletions[member].source);
            ASSERT_NE(nullptr, source);
            EXPECT_EQ(&*row, engine.ResolveSourceResourceOwner(source->resourceOwner));
            auto staleSourceOwner = source->resourceOwner;
            ++staleSourceOwner.invocationGeneration;
            EXPECT_EQ(nullptr, engine.ResolveSourceResourceOwner(staleSourceOwner));
            EXPECT_EQ(releaseBlock, source->releaseSeenAt);
            sameBlockReleaseChecked = true;
        }
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    ASSERT_TRUE(started);
    ASSERT_TRUE(completed);
    ASSERT_TRUE(engine.voices.ReleaseObserved(released));
    ASSERT_TRUE(sameBlockReleaseChecked);
    EXPECT_EQ(delayTail, delayedReleaseChecked);
    for (unsigned block = 0; block < 96; ++block) {
        engine.nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_FALSE(engine.playableInstances.Classify(root).live);
    for (const float value : {0.0f, 1.0f, 2.0f}) {
        ASSERT_EQ(VN_OK, Vn_SetValue(ContainerMatrixWorld::kVariable, value));
        for (unsigned block = 0; block < 16; ++block) {
            engine.nullBackend.Pump(1);
            ASSERT_EQ(VN_OK, Vn_Update());
            EXPECT_EQ(0u, engine.voices.ActiveCount());
            EXPECT_FALSE(engine.playableInstances.Classify(root).live);
        }
    }
    if (firing != 0) {
        VnActionFiringInfo info{};
        info.structSize = sizeof(info);
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    }
    EXPECT_EQ(instances, engine.playableInstances.LiveCount());
    EXPECT_EQ(containers, engine.containerPlayback.LiveCount());
    EXPECT_FALSE(engine.containerPlayback.Capture(controller, &controllerExecution));
    EXPECT_EQ(0u, engine.playablePartitions.OccupiedCount());
    EXPECT_EQ(nullptr, engine.ResolvePlayableService(serviceToken, controller, controllerEpoch));
    EXPECT_FALSE(engine.ResolvePlayableMember(memberReference, &memberOwner, &memberSlot));
    EXPECT_EQ(controls, engine.variableControlInstances.LiveCount());
    EXPECT_EQ(decisions, engine.decisions.LiveCount());
    EXPECT_EQ(arms, engine.timelineArms.LiveCount());
    EXPECT_EQ(groups, engine.armGroups.FreeCount());
    EXPECT_EQ(occurrences, engine.timelineOccurrences.OccupiedCount());
    EXPECT_EQ(compositeOwners, engine.compositeCompletionOwners.OccupiedCount());
    EXPECT_EQ(ledger, engine.ledger.AvailableEntryCount());
    EXPECT_EQ(delays, engine.effectBank.DelayInUse());
    EXPECT_EQ(transactions, engine.timelinePool.LiveTransactionCount());
    EXPECT_FALSE(engine.runtimeRecreateRequired);
    if (firing != 0) ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
}

TEST(PackComposition, VariableControlNaturallyCompletesAcrossEntries) {
    for (const auto entry : {ContainerMatrixEntry::Direct, ContainerMatrixEntry::CurrentWorldAction, ContainerMatrixEntry::PackAction})
        for (const bool continuous : {false, true})
            for (const bool nested : {false, true})
                ExpectVariableControlNaturalCompletion(entry, continuous, nested);
}

TEST(PackComposition, VariableControlTailRetainsResourcesUntilReleaseAndLaterBlock) {
    for (const bool continuous : {false, true})
        ExpectVariableControlNaturalCompletion(ContainerMatrixEntry::Direct, continuous, false, true);
}

void ExpectShortVariableControlTargetPromotion(ContainerMatrixEntry entry, bool silent,
                                               std::uint32_t workers, bool staggered = false) {
    SCOPED_TRACE(::testing::Message() << "entry=" << static_cast<unsigned>(entry)
        << " silent=" << silent << " workers=" << workers << " staggered=" << staggered);
    const std::vector<float> firstSamples(512, 0.25f), secondSamples(1, -0.25f);
    const float* firstChannels[] = {firstSamples.data()};
    const float* secondChannels[] = {secondSamples.data()};
    std::uint64_t firstRevision = 0, secondRevision = 0;
    ASSERT_TRUE(ComputeMediaPcmContentRevisionV1(48000, 1, firstSamples.size(), firstChannels, 1, &firstRevision));
    ASSERT_TRUE(ComputeMediaPcmContentRevisionV1(48000, 1, secondSamples.size(), secondChannels, 1, &secondRevision));
    VariableControlLifetimeWorld fixture(false, false, firstRevision, secondRevision);
    auto& image = fixture.base;
    std::array<ContainerChildProgramViewV2, 3> children{
        fixture.children[0], fixture.children[1], fixture.children[0]};
    children[2].stableChildOrdinal = 9;
    children[2].authoredStableOrder = 2;
    if (staggered) {
        auto& trackProperty = image.properties[image.propertyCount++];
        trackProperty.contentPropertyKind = playableproperties::ContentPropertyKindV1::Track;
        trackProperty.stableId = harkentest::ObjectId(ContainerMatrixWorld::kTrack);
        trackProperty.authoredStableOrder = 3;
        trackProperty.contentRevision = 1;
        trackProperty.routeStableId = VN_BUS_MASTER;
        trackProperty.compatibilityFingerprint = 4;
        trackProperty.payload = DelayedPlayPayload();
        trackProperty.programSemanticFingerprint = ComputePlayablePropertyFingerprintV1(trackProperty);
        image.track.rootDefinition = PlayableRefFromProperty(trackProperty);
        for (std::uint32_t index = 0; index < 2; ++index) {
            auto& placement = image.placements[index];
            placement.stablePlacementOrdinal = index;
            placement.stableOccurrenceOrdinal = 11u + index;
            placement.content = children[1].playable;
            placement.authoredStart = index * INT64_C(8000000);
            placement.clipId = harkentest::ObjectId(placement.clipGuidHigh = index + 1u);
            auto& occurrence = image.occurrences[3u + index];
            occurrence.parentKind = playableproperties::ContentPropertyKindV1::Track;
            occurrence.parentStableId = trackProperty.stableId;
            occurrence.parentProgramSemanticFingerprint = trackProperty.programSemanticFingerprint;
            occurrence.stableOccurrenceOrdinal = placement.stableOccurrenceOrdinal;
            occurrence.childPlayable = placement.content;
            occurrence.payload = EmptyOccurrencePayload();
            occurrence.occurrenceSemanticFingerprint = ComputePlayableOccurrenceFingerprintV1(occurrence);
        }
        image.track.placementCount = 2;
        image.track.placements = image.placements.data();
        image.track.scheduleSemanticFingerprint = ComputeTrackScheduleFingerprintV1(image.track);
        image.world.trackSchedules = &image.track;
        image.world.trackScheduleCount = 1;
        children[1].playable = image.track.rootDefinition;
        std::sort(image.properties.begin(), image.properties.begin() + image.propertyCount,
            [](const auto& left, const auto& right) {
                return left.contentPropertyKind != right.contentPropertyKind
                    ? left.contentPropertyKind < right.contentPropertyKind : left.stableId < right.stableId;
            });
        image.world.playablePropertyCount = image.propertyCount;
    }
    image.containers[0].children = children.data();
    image.containers[0].childCount = children.size();
    image.variable = harkentest::MakeVariableDefinition(ContainerMatrixWorld::kVariable,
        VariableKindV1::Step, 0.0f, 4.0f, silent ? 4.0f : 0.0f);
    for (std::uint32_t index = 0; index < children.size(); ++index) {
        fixture.discreteRows[index].childStableOrdinal = children[index].stableChildOrdinal;
        auto& occurrence = image.occurrences[index];
        occurrence = image.occurrences[0];
        occurrence.stableOccurrenceOrdinal = children[index].stableChildOrdinal;
        occurrence.childPlayable = children[index].playable;
        occurrence.occurrenceSemanticFingerprint = ComputePlayableOccurrenceFingerprintV1(occurrence);
    }
    image.world.playableOccurrenceCount = children.size() + (staggered ? 2u : 0u);
    auto& silentProperty = image.properties[image.propertyCount++];
    silentProperty.contentPropertyKind = playableproperties::ContentPropertyKindV1::Track;
    silentProperty.stableId = harkentest::ObjectId(ContainerMatrixWorld::kPiece);
    silentProperty.authoredStableOrder = 4;
    silentProperty.contentRevision = 1;
    silentProperty.routeStableId = VN_BUS_MASTER;
    silentProperty.compatibilityFingerprint = 5;
    silentProperty.payload = DelayedPlayPayload();
    silentProperty.programSemanticFingerprint = ComputePlayablePropertyFingerprintV1(silentProperty);
    ScheduleClipPlacementV1 silentPlacement = image.placements[0];
    silentPlacement.clipId = harkentest::ObjectId(3);
    silentPlacement.clipGuidHigh = 3;
    silentPlacement.content = children[0].playable;
    silentPlacement.authoredStart = INT64_C(1000000000);
    silentPlacement.authoredDuration = 1;
    TrackScheduleProgramViewV1 silentTrack{};
    silentTrack.rootDefinition = PlayableRefFromProperty(silentProperty);
    silentTrack.placements = &silentPlacement;
    silentTrack.placementCount = 1;
    silentTrack.scheduleSemanticFingerprint = ComputeTrackScheduleFingerprintV1(silentTrack);
    std::array<TrackScheduleProgramViewV1, 2> tracks{image.track, silentTrack};
    image.world.trackSchedules = staggered ? tracks.data() : &tracks[1];
    image.world.trackScheduleCount = staggered ? 2 : 1;
    std::array<ContainerChildProgramViewV2, 4> liveChildren{children[0], children[1], children[2], {}};
    liveChildren[3].stableChildOrdinal = 10;
    liveChildren[3].authoredStableOrder = 3;
    liveChildren[3].playable = silentTrack.rootDefinition;
    liveChildren[3].queueStopPolicy = QueueStopPolicyV1::AbortOwningQueue;
    std::vector<PlayableOccurrencePropertyViewV1> occurrences(image.occurrences.begin(),
        image.occurrences.begin() + image.world.playableOccurrenceCount);
    auto silentOccurrence = image.occurrences[0];
    silentOccurrence.stableOccurrenceOrdinal = liveChildren[3].stableChildOrdinal;
    silentOccurrence.childPlayable = silentTrack.rootDefinition;
    silentOccurrence.occurrenceSemanticFingerprint = ComputePlayableOccurrenceFingerprintV1(silentOccurrence);
    occurrences.insert(occurrences.begin() + children.size(), silentOccurrence);
    silentOccurrence.parentKind = playableproperties::ContentPropertyKindV1::Track;
    silentOccurrence.parentStableId = silentProperty.stableId;
    silentOccurrence.parentProgramSemanticFingerprint = silentProperty.programSemanticFingerprint;
    silentOccurrence.stableOccurrenceOrdinal = silentPlacement.stableOccurrenceOrdinal;
    silentOccurrence.childPlayable = silentPlacement.content;
    silentOccurrence.occurrenceSemanticFingerprint = ComputePlayableOccurrenceFingerprintV1(silentOccurrence);
    occurrences.push_back(silentOccurrence);
    image.world.playableOccurrences = occurrences.data();
    image.world.playableOccurrenceCount = occurrences.size();
    ContinuousGridCellV1 liveCell{};
    ContinuousGridRowViewV1 liveRow{};
    liveRow.stableRowOrdinal = 1;
    liveRow.childStableOrdinal = liveChildren[3].stableChildOrdinal;
    liveRow.cellCount = 1;
    liveRow.cells = &liveCell;
    auto& controlProgram = image.containers[0];
    controlProgram.children = liveChildren.data();
    controlProgram.childCount = liveChildren.size();
    controlProgram.continuousAxisCount = 1;
    controlProgram.continuousAxes = &image.axis;
    controlProgram.continuousRowCount = 1;
    controlProgram.continuousRows = &liveRow;
    controlProgram.envelopeFrames = 64;
    controlProgram.maxActiveRows = 1;
    controlProgram.maxLiveRows = 2;
    std::sort(image.properties.begin(), image.properties.begin() + image.propertyCount,
        [](const auto& left, const auto& right) {
            return left.contentPropertyKind != right.contentPropertyKind
                ? left.contentPropertyKind < right.contentPropertyKind : left.stableId < right.stableId;
        });
    image.world.playablePropertyCount = image.propertyCount;
    image.world.identity.capabilityMask = detail::ComputeCurrentWorldLocalCapabilityMaskV1(image.world);
    image.world.identity.runtimeSemanticFingerprint = ComputeCurrentWorldFingerprintV4(image.world);
    auto config = MakeNullConfig(16, 64, 48000);
    config.renderWorkerCount = workers;
    EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    ASSERT_EQ(workers, engine.voices.RenderWorkerCount());
    ::testing::Test::RecordProperty("member_completion_bytes", std::to_string(sizeof(VariableControlMemberCompletion)));
    ::testing::Test::RecordProperty("member_completion_count", std::to_string(engine.variableControlMemberCompletions.size()));
    if (entry == ContainerMatrixEntry::PackAction) {
        ImageBuilder builder(kPackKindCanonicalContent);
        builder.AddEntry(kPackEntryKindPackRequirementBlock, 22, RequirementPayload(22, 1, 1));
        builder.AddEntry(kPackEntryKindCanonicalDefinitionPartition, 22,
            WrapWorldPartition(22, 1, image.world, image.world.playablePropertyCount +
                image.world.actionCount + image.world.variableCount));
        builder.AddMedia(ContainerMatrixWorld::kFirstSound, firstSamples);
        builder.AddMedia(ContainerMatrixWorld::kSecondSound, secondSamples);
        const auto bytes = builder.Build();
        const auto init = BuildSingleIdentityInit(Fnv1a64(bytes.data(), bytes.size()),
            ContainerMatrixWorld::kAction, "u6-short-vc-a.pack", ContainerMatrixWorld::kRoot);
        const auto initPath = WriteTemp("u6-short-vc-init.pack", init);
        const auto path = WriteTemp("u6-short-vc-a.pack", bytes);
        VnCanonicalPackSetMemberV1 members[2]{};
        VnCanonicalPackSetMemberResultV1 rows[2]{};
        const char* paths[] = {initPath.c_str(), path.c_str()};
        for (std::size_t i = 0; i < 2; ++i) {
            members[i].structSize = sizeof(members[i]);
            members[i].packStableId = i == 0 ? 11 : 22;
            members[i].packKind = i == 0 ? VN_CANONICAL_PACK_SET_MEMBER_INIT
                                        : VN_CANONICAL_PACK_SET_MEMBER_CONTENT;
            members[i].utf8Path = paths[i];
            rows[i].structSize = sizeof(rows[i]);
        }
        VnCanonicalPackSetActivationReportV1 activated{};
        ASSERT_EQ(VN_OK, harkentest::ActivateCanonicalMembersV1(
                              members, 2, rows, activated));
        ASSERT_NE(0u, rows[1].handle);
    } else {
        const auto first = harkentest::MonoDesc(firstSamples, 48000);
        const auto second = harkentest::MonoDesc(secondSamples, 48000);
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(ContainerMatrixWorld::kFirstSound, &first));
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(ContainerMatrixWorld::kSecondSound, &second));
        ASSERT_EQ(WorldInstallStatus::Ok, InstallContainerWorldV1(engine, image.world).status);
    }
    const auto resources = [&]() {
        std::uint32_t sources = 0;
        for (std::uint32_t index = 0; index < engine.sourceTerminals.Capacity(); ++index)
            sources += engine.sourceTerminals.At(index)->occupied ? 1u : 0u;
        return std::array<std::uint32_t, 13>{
            engine.playableInstances.FreeCount(), engine.containerPlayback.FreeCount(),
            engine.variableControlInstances.LiveCount(), engine.decisions.LiveCount(),
            engine.timelineArms.LiveCount(), engine.armGroups.FreeCount(),
            engine.timelineOccurrences.OccupiedCount(), engine.compositeCompletionOwners.OccupiedCount(),
            engine.ledger.AvailableEntryCount(), engine.timelinePool.LiveTransactionCount(),
            engine.transitionInstances.LiveCount(), engine.voices.ActiveCount(), sources};
    };
    const auto baseline = resources();
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    PlayableInstanceHandle root = 0;
    VnActionFiringHandle firing = 0;
    if (entry == ContainerMatrixEntry::Direct) {
        const auto start = StartCurrentPlayableByIdentity(PlayableKindV1::Container, ContainerMatrixWorld::kRoot, emitter);
        ASSERT_EQ(PlayableStartStatus::Accepted, start.status);
        root = start.instance;
    } else {
        VnPostActionDesc post{};
        post.structSize = sizeof(post);
        post.actionId = harkentest::ObjectId(ContainerMatrixWorld::kAction);
        post.emitter = emitter;
        ASSERT_EQ(VN_OK, Vn_PostAction(&post, &firing));
        VnActionStepResult result{};
        result.structSize = sizeof(result);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &result));
        root = result.producedPlayableInstance;
    }
    auto row = std::find_if(engine.playableServices.begin(), engine.playableServices.end(),
        [root](const auto& candidate) { return candidate.rootInstance == root; });
    ASSERT_NE(engine.playableServices.end(), row);
    const auto controllerEpoch = engine.playableInstances.Classify(root).scheduleEpoch;
    const auto controlToken = row->variableControlInstance;
    for (unsigned block = 0; block < 48; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine.nullBackend.Pump(1);
    }
    ASSERT_EQ(VN_OK, Vn_Update());
    ASSERT_EQ(0u, engine.voices.ActiveCount());
    ASSERT_EQ(silent, row->variableControlDiscreteSilent);
    ASSERT_EQ(PlayableControlLifecycle::Active, row->controlLifecycle);

    std::array<std::vector<VnVoiceHandle>, 2> onsets;
    for (std::uint32_t target = 0; target < 2; ++target) {
        SCOPED_TRACE(target);
        const auto ordinal = 8u + target;
        ASSERT_EQ(VN_OK, Vn_SetValue(ContainerMatrixWorld::kVariable, static_cast<float>(target + 1u)));
        bool admitted = false, natural = false, sameBlock = false, retiredBeforePromotion = false;
        SourceTerminalToken sourceToken{};
        VoiceReleaseObserver release{};
        PlayableInstanceHandle leaf = 0;
        std::uint64_t leafEpoch = 0;
        std::uint64_t startSequence = 0, sourceSequence = 0;
        DecisionToken decisionToken{};
        for (unsigned block = 0; block < 96; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine.nullBackend.Pump(1);
            for (std::uint32_t index = 0; index < engine.playableStorage.memberStride; ++index) {
                const auto slot = row->scheduleStorageBase + index;
                if (staggered && target == 0) {
                    if (engine.playableScheduleVoices[slot].soundId != ContainerMatrixWorld::kSecondSound) continue;
                } else if (engine.playableScheduleVoices[slot].target.occurrenceOrdinal != ordinal) continue;
                const auto arm = engine.playableScheduleArms[slot];
                TimelineArmObservation onset{};
                const auto render = engine.playableScheduleRenderHandles[slot];
                if (engine.timelineArms.Observe(arm, &onset) && onset.startedBlockSequence != 0) {
                    startSequence = onset.startedBlockSequence;
                    if (std::find(onsets[target].begin(), onsets[target].end(), render) == onsets[target].end())
                        onsets[target].push_back(render);
                }
                const auto& member = engine.variableControlMemberCompletions[slot];
                if (member.resourcesRetired && row->variableControlDiscreteRetargetPrepared &&
                    !row->variableControlDiscreteRetargetSourceExited) {
                    EXPECT_EQ(SourceTerminalKind::Natural, member.completedSource.kind);
                    EXPECT_NE(0u, member.sourceCompletionSequence);
                    EXPECT_EQ(render, member.sourceRender);
                    EXPECT_EQ(arm.slot, member.sourceStartArm.slot);
                    EXPECT_EQ(arm.generation, member.sourceStartArm.generation);
                    EXPECT_FALSE(member.source.Valid());
                    EXPECT_FALSE(engine.playableInstances.Classify(member.leafInstance).live);
                    retiredBeforePromotion = true;
                }
                const auto* source = engine.sourceTerminals.Resolve(member.source);
                if (source == nullptr) continue;
                EXPECT_EQ(render, source->render);
                EXPECT_EQ(member.leafInstance, source->leaf);
                EXPECT_EQ(member.leafEpoch, source->acceptedEpoch);
                EXPECT_EQ(root, source->controller);
                sourceToken = member.source;
                release = source->release;
                leaf = source->leaf;
                leafEpoch = source->acceptedEpoch;
                DecisionCommittedSnapshot decision{};
                if (engine.decisions.CaptureCommitted(row->variableControlDiscreteRetargetDecision, &decision) &&
                    decision.audioState == AudioGroupState::Admitted) {
                    admitted = true;
                    decisionToken = row->variableControlDiscreteRetargetDecision;
                }
                SourceTerminalPayload result{};
                if (engine.sourceTerminals.Capture(sourceToken, engine.mixer.BlocksRendered(), &result)) {
                    EXPECT_EQ(SourceTerminalKind::Natural, result.kind);
                    natural = result.kind == SourceTerminalKind::Natural;
                    sourceSequence = source->completedSequence.load(std::memory_order_acquire);
                    sameBlock |= startSequence != 0 && startSequence == sourceSequence;
                    EXPECT_TRUE(engine.voices.ReleaseObserved(release));
                    EXPECT_EQ(nullptr, engine.voices.Resolve(render));
                }
            }
            ASSERT_EQ(VN_OK, Vn_Update());
        }
        SCOPED_TRACE(::testing::Message() << "prepared=" << row->variableControlDiscreteRetargetPrepared
            << " applied=" << row->variableControlDiscreteRetargetApplied
            << " exited=" << row->variableControlDiscreteRetargetSourceExited
            << " targets=" << row->variableControlDiscreteRetargetTargetMemberCount
            << " lifecycle=" << static_cast<unsigned>(row->controlLifecycle)
            << " runtime=" << engine.runtimeRecreateRequired << " natural=" << natural
            << " start=" << startSequence << " source=" << sourceSequence
            << " retained=" << retiredBeforePromotion);
        ASSERT_EQ(staggered && target == 0 ? 2u : 1u, onsets[target].size());
        ASSERT_TRUE(admitted);
        ASSERT_TRUE(natural);
        if (target == 0) ASSERT_TRUE(sameBlock);
        if (staggered && target == 0) ASSERT_TRUE(retiredBeforePromotion);
        ASSERT_TRUE(engine.voices.ReleaseObserved(release));
        ASSERT_EQ(nullptr, engine.sourceTerminals.Resolve(sourceToken));
        ASSERT_FALSE(engine.playableInstances.Classify(leaf).live);
        ASSERT_NE(0u, leafEpoch);
        ::testing::Test::RecordProperty("short_target_" + std::to_string(static_cast<unsigned>(entry)) +
            "_" + std::to_string(silent) + "_" + std::to_string(workers) + "_" + std::to_string(target),
            "start=" + std::to_string(startSequence) + " source=" + std::to_string(sourceSequence) +
            " decision=" + std::to_string(decisionToken.slot) + ":" + std::to_string(decisionToken.generation) +
            " leaf=" + std::to_string(leaf) + " epoch=" + std::to_string(leafEpoch));
        ASSERT_FALSE(row->variableControlDiscreteRetargetPrepared)
            << "applied=" << row->variableControlDiscreteRetargetApplied
            << " sourceExited=" << row->variableControlDiscreteRetargetSourceExited;
        ASSERT_EQ(ordinal, row->variableControlDiscreteCurrentChildOrdinal);
        DecisionCommittedSnapshot retired{};
        ASSERT_FALSE(engine.decisions.CaptureCommitted(decisionToken, &retired));
        ASSERT_EQ(PlayableControlLifecycle::Active, row->controlLifecycle);
        ASSERT_EQ(controllerEpoch, engine.playableInstances.Classify(root).scheduleEpoch);
        VariableControlInstanceSnapshot control{};
        ASSERT_TRUE(engine.variableControlInstances.Capture(controlToken, &control));
        ASSERT_EQ(root, control.rootInstance);
        ASSERT_EQ(VN_OK, Vn_SetValue(ContainerMatrixWorld::kVariable, static_cast<float>(target + 1u)));
        for (unsigned block = 0; block < 32; ++block) {
            engine.nullBackend.Pump(1);
            EXPECT_EQ(0u, resources().back());
            ASSERT_EQ(VN_OK, Vn_Update());
            EXPECT_EQ(0u, engine.voices.ActiveCount());
            EXPECT_FALSE(row->variableControlDiscreteRetargetPrepared);
        }
    }
    if (firing != 0) ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
    else ASSERT_EQ(PlayableControlStatus::Ok, StopPlayable(engine, root, 0));
    for (unsigned block = 0; block < 96; ++block) {
        engine.nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_EQ(baseline, resources());
    EXPECT_FALSE(engine.runtimeRecreateRequired);
    if (firing != 0) ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
}

TEST(PackComposition, ShortVariableControlTargetPromotesAfterNaturalReleaseAcrossEntries) {
    for (const auto entry : {ContainerMatrixEntry::Direct, ContainerMatrixEntry::CurrentWorldAction, ContainerMatrixEntry::PackAction})
        for (const bool silent : {false, true})
            for (const auto workers : {0u, 2u})
                ExpectShortVariableControlTargetPromotion(entry, silent, workers);
}

TEST(PackComposition, StaggeredVariableControlTargetRetainsNaturalEvidenceAfterFirstLeafRecycles) {
    for (const auto entry : {ContainerMatrixEntry::Direct, ContainerMatrixEntry::CurrentWorldAction, ContainerMatrixEntry::PackAction})
        for (const bool silent : {false, true})
            for (const auto workers : {0u, 2u})
                ExpectShortVariableControlTargetPromotion(entry, silent, workers, true);
}

TEST(PackComposition, VariableControlPartialCompletionKeepsSurvivorsWithoutRestartingFinishedMembers) {
    EngineSession session(MakeNullConfig(16, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    const std::vector<float> firstSamples(512, 0.25f), secondSamples(65536, -0.25f);
    const auto first = harkentest::MonoDesc(firstSamples, 48000);
    const auto second = harkentest::MonoDesc(secondSamples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(ContainerMatrixWorld::kFirstSound, &first));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(ContainerMatrixWorld::kSecondSound, &second));
    VariableControlLifetimeWorld fixture(true, false,
        engine.registry.Lookup(ContainerMatrixWorld::kFirstSound).contentRevision,
        engine.registry.Lookup(ContainerMatrixWorld::kSecondSound).contentRevision);
    fixture.continuousCells[1].lower = 0.0f;
    fixture.base.world.identity.runtimeSemanticFingerprint = ComputeCurrentWorldFingerprintV4(fixture.base.world);
    ASSERT_EQ(WorldInstallStatus::Ok, InstallContainerWorldV1(engine, fixture.base.world).status);
    const auto started = StartCurrentPlayableByIdentity(PlayableKindV1::Container, ContainerMatrixWorld::kRoot, 0);
    ASSERT_EQ(PlayableStartStatus::Accepted, started.status);
    auto row = std::find_if(engine.playableServices.begin(), engine.playableServices.end(),
        [&](const auto& candidate) { return candidate.rootInstance == started.instance; });
    ASSERT_NE(engine.playableServices.end(), row);
    ASSERT_EQ(2u, row->variableControlContinuousMemberCount);
    const auto base = row->scheduleStorageBase + row->variableControlContinuousMemberOffset;
    const auto firstArm = engine.playableScheduleArms[base];
    const auto secondArm = engine.playableScheduleArms[base + 1];
    const auto secondRender = engine.playableScheduleRenderHandles[base + 1];
    bool firstStarted = false, secondStarted = false;
    for (unsigned block = 0; block < 48; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine.nullBackend.Pump(1);
        TimelineArmObservation observed{};
        firstStarted |= engine.timelineArms.Observe(firstArm, &observed) && observed.startedBlockSequence != 0;
        secondStarted |= engine.timelineArms.Observe(secondArm, &observed) && observed.startedBlockSequence != 0;
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    ASSERT_TRUE(firstStarted);
    ASSERT_TRUE(secondStarted);
    ASSERT_TRUE(engine.variableControlMemberCompletions[base].resourcesRetired);
    ASSERT_FALSE(engine.variableControlMemberCompletions[base + 1].resourcesRetired);
    ASSERT_NE(nullptr, engine.voices.Resolve(secondRender));
    ASSERT_EQ(1u, engine.voices.ActiveCount());
    const auto secondChild = engine.variableControlMemberCompletions[base + 1].leafInstance;
    const auto secondEpoch = engine.playableInstances.Classify(secondChild).scheduleEpoch;
    ASSERT_EQ(VN_OK, Vn_SetValue(ContainerMatrixWorld::kVariable, 2.0f));
    for (unsigned block = 0; block < 128; ++block) {
        engine.nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        EXPECT_NE(nullptr, engine.voices.Resolve(secondRender));
        EXPECT_EQ(1u, engine.voices.ActiveCount());
    }
    ASSERT_EQ(2u, row->variableControlContinuousMemberCount)
        << " prepared=" << row->variableControlRetargetPrepared
        << " committed=" << row->variableControlRetargetDecisionCommitted
        << " applied=" << row->variableControlRetargetApplied
        << " final=" << row->variableControlRetargetMembershipFinalized
        << " frame=" << row->variableControlRetargetFrame
        << " end=" << row->variableControlRetargetEnvelopeEndFrame
        << " now=" << engine.mixer.BlocksRendered() * 64u
        << " runtime=" << engine.runtimeRecreateRequired;
    std::size_t retainedSlot = 0;
    ASSERT_TRUE(engine.ResolvePlayableMemberSlot(base + 1u, &retainedSlot));
    EXPECT_EQ(base + 1u, retainedSlot);
    EXPECT_EQ(secondRender, engine.playableScheduleRenderHandles[retainedSlot]);
    EXPECT_EQ(firstArm.slot, engine.playableScheduleArms[base].slot);
    EXPECT_EQ(firstArm.generation, engine.playableScheduleArms[base].generation);
    EXPECT_EQ(secondEpoch, engine.playableInstances.Classify(secondChild).scheduleEpoch);
    const auto reentryBaseline = engine.mixer.BlocksRendered();
    ASSERT_EQ(VN_OK, Vn_SetValue(ContainerMatrixWorld::kVariable, 0.0f));
    std::vector<TimelineArmToken> reentries;
    for (unsigned block = 0; block < 128; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine.nullBackend.Pump(1);
        for (std::uint32_t index = 0; index < engine.playableStorage.memberStride; ++index) {
            const auto slot = row->scheduleStorageBase + index;
            if (engine.playableScheduleVoices[slot].soundId != ContainerMatrixWorld::kFirstSound) continue;
            const auto arm = engine.playableScheduleArms[slot];
            if (arm.slot == firstArm.slot && arm.generation == firstArm.generation) continue;
            TimelineArmObservation observed{};
            if (!engine.timelineArms.Observe(arm, &observed) || observed.startedBlockSequence == 0) continue;
            EXPECT_GT(observed.startedBlockSequence, reentryBaseline);
            if (std::none_of(reentries.begin(), reentries.end(), [arm](const auto& entry) {
                return arm.slot == entry.slot && arm.generation == entry.generation;
            })) reentries.push_back(arm);
        }
        ASSERT_EQ(VN_OK, Vn_Update());
        EXPECT_NE(nullptr, engine.voices.Resolve(secondRender));
    }
    EXPECT_TRUE(reentries.empty());
    EXPECT_EQ(2u, row->variableControlContinuousMemberCount);
    EXPECT_EQ(secondEpoch, engine.playableInstances.Classify(secondChild).scheduleEpoch);
    ASSERT_EQ(PlayableControlStatus::Ok, StopPlayable(engine, started.instance, 0));
    for (unsigned block = 0; block < 96; ++block) {
        engine.nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_EQ(0u, engine.playableInstances.LiveCount());
    EXPECT_EQ(0u, engine.variableControlInstances.LiveCount());
    EXPECT_EQ(0u, engine.timelineArms.LiveCount());
    EXPECT_EQ(0u, engine.decisions.LiveCount());
    EXPECT_EQ(0u, engine.voices.ActiveCount());
    EXPECT_FALSE(engine.runtimeRecreateRequired);
}

struct ContainerNavigationDepthWorld {
    ContainerMatrixWorld base;
    std::vector<PlayablePropertyProgramViewV1> properties;
    std::vector<ContainerProgramViewV3> containers;
    std::vector<ContainerChildProgramViewV2> children;
    std::vector<PlayableOccurrencePropertyViewV1> occurrences;

    ContainerNavigationDepthWorld(std::uint32_t depth, bool later,
                           std::uint64_t revision,
                           ContainerMatrixChild leafKind = ContainerMatrixChild::Sound,
                           bool deepFirst = false)
        : base(ContainerModeV1::Sequence, leafKind, revision,
               revision, false, later ? 2u : 1u),
          properties(depth + base.propertyCount - 1u), containers(depth),
          children(depth + (later ? 1u : 0u)),
          occurrences(children.size() + base.occurrenceCount - 1u) {
        properties[0] = base.properties[0];
        for (std::uint32_t index = 0; index < depth; ++index) {
            auto& property = properties[index + 1u];
            property = base.properties[1];
            property.stableId = index == 0 ? ContainerMatrixWorld::kRoot : harkentest::ObjectId(80000u + index);
            property.authoredStableOrder = 100u + index;
            SetContainerPropertyLoopCount(&property, index == 0 && later ? 2u : 1u);
            property.programSemanticFingerprint =
                ComputePlayablePropertyFingerprintV1(property);
        }
        for (std::uint32_t index = 2; index < base.propertyCount; ++index) {
            properties[depth + index - 1u] = base.properties[index];
        }
        std::uint32_t edge = 0;
        for (std::uint32_t index = 0; index < depth; ++index) {
            const auto& property = properties[index + 1u];
            auto& container = containers[index];
            container = base.containers[0];
            container.containerStableId = property.stableId;
            container.programSemanticFingerprint = property.programSemanticFingerprint;
            container.authoredStableOrder = index;
            container.childCount = index == 0 && later ? 2u : 1u;
            container.children = &children[edge];
            for (std::uint32_t childIndex = 0; childIndex < container.childCount;
                 ++childIndex, ++edge) {
                auto& child = children[edge];
                child = base.children[0];
                child.stableChildOrdinal = 41u + childIndex;
                child.authoredStableOrder = childIndex;
                const bool shortFrontier = later && index == 0 &&
                    childIndex == (deepFirst ? 1u : 0u);
                child.playable = shortFrontier ? PlayableRefFromProperty(properties[0])
                    : index + 1u == depth ? base.children[0].playable
                    : PlayableRefFromProperty(properties[index + 2u]);
                auto& occurrence = occurrences[edge];
                occurrence = base.occurrences[0];
                occurrence.parentStableId = property.stableId;
                occurrence.parentProgramSemanticFingerprint =
                    property.programSemanticFingerprint;
                occurrence.stableOccurrenceOrdinal = child.stableChildOrdinal;
                occurrence.childPlayable = child.playable;
                occurrence.occurrenceSemanticFingerprint =
                    ComputePlayableOccurrenceFingerprintV1(occurrence);
            }
        }
        for (std::uint32_t index = 1; index < base.occurrenceCount; ++index) {
            occurrences[edge++] = base.occurrences[index];
        }
        base.rootRef = PlayableRefFromProperty(properties[1]);
        base.step.target.expectedProgramSemanticFingerprint =
            properties[1].programSemanticFingerprint;
        base.action.programSemanticFingerprint =
            ComputeActionProgramFingerprintV1(base.action);
        base.world.playableProperties = properties.data();
        base.world.playablePropertyCount = static_cast<std::uint32_t>(properties.size());
        base.world.containers = containers.data();
        base.world.containerCount = static_cast<std::uint32_t>(containers.size());
        base.world.playableOccurrences = occurrences.data();
        base.world.playableOccurrenceCount = static_cast<std::uint32_t>(occurrences.size());
        base.world.capacity.maxContainerDepth = 64;
        base.world.identity.runtimeSemanticFingerprint =
            ComputeCurrentWorldFingerprintV4(base.world);
    }
};

void ExpectOrdinaryNavigationDepth(ContainerMatrixEntry entry, std::uint32_t depth,
                                  bool later,
                                  ContainerMatrixChild leafKind = ContainerMatrixChild::Sound,
                                  bool deepFirst = false) {
    SCOPED_TRACE(::testing::Message() << "entry=" << static_cast<int>(entry)
                 << " depth=" << depth << " later=" << later
                 << " leaf=" << static_cast<int>(leafKind) << " deepFirst=" << deepFirst);
    const std::vector<float> samples(256, 0.25f);
    const float* channels[] = {samples.data()};
    std::uint64_t revision = 0;
    ASSERT_TRUE(ComputeMediaPcmContentRevisionV1(
        48000, 1, samples.size(), channels, 1, &revision));
    ContainerNavigationDepthWorld image(depth, later, revision, leafKind, deepFirst);
    EngineSession session(MakeNullConfig(16, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    const auto baseline = engine->playableInstances.LiveCount();
    const auto instanceFreeBaseline = engine->playableInstances.FreeCount();
    const auto containerFreeBaseline = engine->containerPlayback.FreeCount();
    const auto selectionFreeBaseline = engine->selectionMemory.FreeDeltaCount();
    if (entry == ContainerMatrixEntry::PackAction) {
        ImageBuilder builder(kPackKindCanonicalContent);
        builder.AddEntry(kPackEntryKindPackRequirementBlock, 22,
                         RequirementPayload(22, 1, 1));
        builder.AddEntry(kPackEntryKindCanonicalDefinitionPartition, 22,
                         WrapWorldPartition(22, 1, image.base.world,
                             image.base.world.playablePropertyCount + 1u));
        builder.AddMedia(ContainerMatrixWorld::kFirstSound, samples);
        const auto bytes = builder.Build();
        const auto stem = std::string("u6-navigation-depth-") +
            std::to_string(depth) + (later ? "-later" : "-initial");
        const auto locator = stem + ".pack";
        const auto init = BuildSingleIdentityInit(
            Fnv1a64(bytes.data(), bytes.size()), ContainerMatrixWorld::kAction,
            locator.c_str(), ContainerMatrixWorld::kRoot, harkentest::ObjectId(0), image.base.world.capacity);
        const auto initPath = WriteTemp(stem + "-init.pack", init);
        const auto packPath = WriteTemp(locator, bytes);
        VnCanonicalPackSetMemberV1 member{};
        member.structSize = sizeof(member);
        member.packStableId = 11;
        member.packKind = VN_CANONICAL_PACK_SET_MEMBER_INIT;
        member.utf8Path = initPath.c_str();
        VnCanonicalPackSetMemberResultV1 row{};
        row.structSize = sizeof(row);
        VnCanonicalPackSetActivationReportV1 initial{};
        ASSERT_EQ(VN_OK, harkentest::ActivateCanonicalMembersV1(
                              &member, 1, &row, initial));
        const auto published = engine->packComposition.PublishedHandle();
        VnCanonicalPackSetMemberV1 members[2] = {member, {}};
        members[0].expectedHandle = initial.initHandle;
        members[1].structSize = sizeof(members[1]);
        members[1].packStableId = 22;
        members[1].packKind = VN_CANONICAL_PACK_SET_MEMBER_CONTENT;
        members[1].utf8Path = packPath.c_str();
        VnCanonicalPackSetMemberResultV1 rows[2]{};
        for (auto& result : rows) result.structSize = sizeof(result);
        VnCanonicalPackSetActivationReportV1 activated{};
        const auto loaded = harkentest::ActivateCanonicalMembersV1(
            members, 2, rows, activated, initial.initHandle,
            initial.resultSetRevision);
        if (depth > 64u) {
            EXPECT_EQ(VN_PACK_RESIDENT_CAPACITY, loaded);
            EXPECT_EQ(0u, rows[1].handle);
            EXPECT_EQ(published.get(), engine->packComposition.Published());
            EXPECT_EQ(baseline, engine->playableInstances.LiveCount());
            return;
        }
        ASSERT_EQ(VN_OK, loaded);
        ASSERT_NE(0u, rows[1].handle);
    } else {
        const auto pcm = harkentest::MonoDesc(samples, 48000);
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(ContainerMatrixWorld::kFirstSound, &pcm));
        const auto installed = InstallContainerWorldV1(*engine, image.base.world);
        if (depth > 64u) {
            EXPECT_EQ(WorldInstallStatus::Capacity, installed.status);
            EXPECT_EQ(baseline, engine->playableInstances.LiveCount());
            return;
        }
        ASSERT_EQ(WorldInstallStatus::Ok, installed.status);
    }
    PlayableInstanceHandle root = 0;
    if (entry == ContainerMatrixEntry::Direct) {
        PlayableStartRequest request{};
        request.root = image.base.rootRef;
        const auto started = StartPlayable(*engine, request);
        if (!later && depth > 31u) {
            EXPECT_EQ(PlayableStartStatus::Capacity, started.status);
            EXPECT_EQ(baseline, engine->playableInstances.LiveCount());
            EXPECT_EQ(0u, engine->containerPlayback.LiveCount());
            EXPECT_EQ(instanceFreeBaseline, engine->playableInstances.FreeCount());
            EXPECT_EQ(containerFreeBaseline, engine->containerPlayback.FreeCount());
            EXPECT_EQ(selectionFreeBaseline, engine->selectionMemory.FreeDeltaCount());
            return;
        }
        ASSERT_EQ(PlayableStartStatus::Accepted, started.status);
        root = started.instance;
    } else {
        VnPostActionDesc post{};
        post.structSize = sizeof(post);
        post.actionId = harkentest::ObjectId(ContainerMatrixWorld::kAction);
        VnActionFiringHandle firing = 0;
        const auto posted = Vn_PostAction(&post, &firing);
        if (!later && depth > 31u) {
            EXPECT_EQ(VN_NO_VOICE, posted);
            EXPECT_EQ(baseline, engine->playableInstances.LiveCount());
            EXPECT_EQ(0u, engine->containerPlayback.LiveCount());
            EXPECT_EQ(instanceFreeBaseline, engine->playableInstances.FreeCount());
            EXPECT_EQ(containerFreeBaseline, engine->containerPlayback.FreeCount());
            EXPECT_EQ(selectionFreeBaseline, engine->selectionMemory.FreeDeltaCount());
            return;
        }
        ASSERT_EQ(VN_OK, posted);
        VnActionStepResult step{};
        step.structSize = sizeof(step);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &step));
        ASSERT_EQ(VN_ACTION_STEP_ACTIVE, step.state);
        root = step.producedPlayableInstance;
    }
    auto row = std::find_if(engine->playableServices.begin(), engine->playableServices.end(),
        [&](const auto& candidate) { return candidate.rootInstance == root; });
    ASSERT_NE(engine->playableServices.end(), row);
    std::vector<PlayableInstanceHandle> leaves;
    std::vector<TimelineArmToken> arms;
    std::vector<bool> heard;
    std::vector<std::uint64_t> onsets;
    PlayableControlReason reason = PlayableControlReason::None;
    bool refusalVerified = false;
    SelectionMemoryKeyV1 rootKey{};
    rootKey.world = row->Invocation().worldGeneration;
    rootKey.containerStableId = image.containers[0].containerStableId;
    rootKey.programSemanticFingerprint = image.containers[0].programSemanticFingerprint;
    rootKey.memoryScope = MemoryScopeV1::Global;
    rootKey.emitterSlot = UINT32_MAX;
    struct Retirement {
        PlayableInstanceHandle root = 0;
        PlayableTerminalKind terminal = PlayableTerminalKind::None;
        std::uint32_t count = 0;
    } retirement{root};
    engine->playableRetirementContextForTest = &retirement;
    engine->playableRetirementHookForTest = [](const EnginePlayableServiceRow& service,
        PlayableInstanceHandle retired, PlayableTerminalKind terminal, void* context) {
        auto& proof = *static_cast<Retirement*>(context);
        if (retired != proof.root) return;
        EXPECT_EQ(proof.root, service.ownerInstance);
        proof.terminal = terminal;
        ++proof.count;
    };
    for (unsigned block = 0; block < 256; ++block) {
        if (row->phase != EnginePlayableStartPhase::Free) {
            reason = row->controlReason;
            auto* resource = FrontierActiveResourceService(*engine, *row);
            if (resource != nullptr && (leaves.empty() || leaves.back() != resource->activeLeafInstance)) {
                leaves.push_back(resource->activeLeafInstance);
                arms.push_back(resource->arm);
                heard.push_back(false);
                onsets.push_back(0);
                auto node = resource->activeLeafInstance;
                std::uint32_t containerCount = 0;
                while (node != 0) {
                    const auto view = engine->playableInstances.Classify(node);
                    ASSERT_TRUE(view.live);
                    if (view.kind == PlayableKind::Container) ++containerCount;
                    if (node == root) break;
                    node = view.parent;
                    ASSERT_LE(containerCount, depth);
                }
                EXPECT_EQ(root, node);
                const bool shortFrontier = later &&
                    (leaves.size() == 1u) != deepFirst;
                EXPECT_EQ(shortFrontier ? 1u : depth, containerCount);
                for (std::uint32_t index = 0; index < containerCount; ++index) {
                    EXPECT_EQ(PlayableKindV1::Container, resource->selectionPath[index].kind);
                    EXPECT_EQ(image.containers[index].containerStableId,
                              resource->selectionPath[index].objectId);
                    EXPECT_EQ(resource->selectedChildOrdinals[index],
                              resource->selectionPath[index].childOrdinal);
                    EXPECT_EQ(harkentest::ObjectId(0u), resource->selectionPath[index].trackId);
                    EXPECT_EQ(index == 0 && leaves.size() == 2u ? 42u : 41u,
                              resource->selectedChildOrdinals[index]);
                }
                EXPECT_TRUE(resource->ordinaryLifecycleOwned);
            }
            if (reason == PlayableControlReason::StartRefused && !refusalVerified) {
                EXPECT_TRUE(row->ordinaryLifecycleOwned);
                EXPECT_EQ(0u, row->containerLoopIteration);
                EXPECT_EQ(leaves.front(), row->activeLeafInstance);
                EXPECT_EQ(1u, row->selectionCount);
                EXPECT_EQ(41u, row->selectedChildOrdinals[0]);
                const auto selection = engine->selectionMemory.Snapshot(rootKey);
                ASSERT_TRUE(selection.found);
                EXPECT_EQ(1u, selection.selectionOrdinal);
                EXPECT_EQ(1u, selection.sequenceCursor);
                EXPECT_EQ(0u, selection.pendingCount);
                ContainerPlaybackRow playback{};
                ASSERT_TRUE(engine->containerPlayback.Capture(root, &playback));
                EXPECT_EQ(1u, playback.completedSelections);
                EXPECT_EQ(0u, playback.activeChild);
                const auto completedBlock = engine->mixer.BlocksRendered();
                for (unsigned repeat = 0; repeat < 3; ++repeat) {
                    ASSERT_EQ(VN_OK, Vn_Update());
                    EXPECT_EQ(completedBlock, engine->mixer.BlocksRendered());
                    const auto after = engine->selectionMemory.Snapshot(rootKey);
                    EXPECT_EQ(selection.selectionOrdinal, after.selectionOrdinal);
                    EXPECT_EQ(selection.sequenceCursor, after.sequenceCursor);
                    EXPECT_EQ(0u, after.pendingCount);
                }
                refusalVerified = true;
            }
        }
        engine->nullBackend.Pump(1);
        for (std::size_t index = 0; index < arms.size(); ++index) {
            TimelineArmObservation observed{};
            if (engine->timelineArms.Observe(arms[index], &observed) &&
                observed.startedBlockSequence != 0) {
                heard[index] = true;
                onsets[index] = observed.startedBlockSequence;
            }
        }
        ASSERT_EQ(VN_OK, Vn_Update());
        if (!engine->playableInstances.Classify(root).live) break;
    }
    const bool propertyCapacityRefused = later && depth > 31u;
    EXPECT_EQ(later && !propertyCapacityRefused ? 2u : 1u, leaves.size());
    EXPECT_TRUE(std::all_of(heard.begin(), heard.end(), [](bool value) { return value; }));
    EXPECT_EQ(1u, retirement.count);
    EXPECT_EQ(propertyCapacityRefused ? PlayableTerminalKind::Failure : PlayableTerminalKind::NaturalCompletion,
        retirement.terminal);
    engine->playableRetirementHookForTest = nullptr;
    engine->playableRetirementContextForTest = nullptr;
    EXPECT_EQ(propertyCapacityRefused, refusalVerified);
    if (onsets.size() == 2u) EXPECT_LT(onsets[0], onsets[1]);
    EXPECT_EQ(baseline, engine->playableInstances.LiveCount());
    EXPECT_EQ(0u, engine->containerPlayback.LiveCount());
    EXPECT_EQ(0u, engine->timelineArms.LiveCount());
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->timelineOccurrences.OccupiedCount());
    EXPECT_EQ(0u, engine->compositeCompletionOwners.OccupiedCount());
    EXPECT_EQ(instanceFreeBaseline, engine->playableInstances.FreeCount());
    EXPECT_EQ(containerFreeBaseline, engine->containerPlayback.FreeCount());
    EXPECT_EQ(selectionFreeBaseline, engine->selectionMemory.FreeDeltaCount());
}

TEST(PackComposition, OrdinaryNavigationInitialDepth63Through65AcrossEntries) {
    for (const auto depth : {63u, 64u, 65u}) {
        ExpectOrdinaryNavigationDepth(ContainerMatrixEntry::Direct, depth, false);
    }
}

TEST(PackComposition, OrdinaryNavigationSuccessorDepth63Through65AcrossEntries) {
    for (const auto depth : {63u, 64u, 65u}) {
        ExpectOrdinaryNavigationDepth(ContainerMatrixEntry::Direct, depth, true);
    }
}

enum class DirectQueueRefusal { None, CommandOneShort, MissingSuccessor };
enum class LaterControlProbe { Playback, CommandRefusal, PublicationRefusal, Retarget };

void ExpectQueueSequenceBranchesAcrossEntry(ContainerMatrixEntry entry, std::uint32_t cycles,
                                             bool stopAndReplay = false, bool refuseFinal = false,
                                             ContainerModeV1 outerMode = ContainerModeV1::SequenceQueue,
                                             ContainerModeV1 innerMode = ContainerModeV1::Sequence,
                                             std::uint32_t wrappers = 0, bool sharedQueueProgram = false,
                                             ContainerModeV1 wrapperMode = ContainerModeV1::SequenceQueue,
                                             bool nestedParallelControl = false,
                                             bool cancelNestedBeforeStart = false,
                                             bool nestedMixedControl = false,
                                             bool nestedSilentControl = false,
                                             bool exitNestedDiscrete = false,
                                             bool matrixCase = false,
                                             bool naturalEndNested = false,
                                             SelectionInputTrace* selectionTrace = nullptr,
                                             DirectQueueRefusal directRefusal = DirectQueueRefusal::None,
                                             bool laterControl = false,
                                             LaterControlProbe laterProbe = LaterControlProbe::Playback,
                                             bool laterWrapper = false,
                                             std::uint32_t stopAfterOnsets = 0,
                                             std::uint32_t stopFadeMs = 0,
                                             bool replayAtFiringTerminal = false) {
    const bool requestedRetarget = laterControl && laterProbe == LaterControlProbe::Retarget;
    const bool requestedRefusal = laterControl && (laterProbe == LaterControlProbe::CommandRefusal ||
        laterProbe == LaterControlProbe::PublicationRefusal);
    const std::vector<float> samples(naturalEndNested ? 4096u : exitNestedDiscrete || requestedRetarget ? 2048u : 256u, 0.25f);
    const float* channels[] = {samples.data()};
    std::uint64_t revision = 0;
    ASSERT_TRUE(ComputeMediaPcmContentRevisionV1(48000, 1, samples.size(), channels, 1, &revision));
    QueueSequenceBranchesWorldImage image({revision, revision, revision, revision}, cycles, outerMode, innerMode);
    if (sharedQueueProgram) {
        auto& parent = image.properties[5];
        parent.payload = FrontierCanonicalPayload();
        parent.programSemanticFingerprint = ComputePlayablePropertyFingerprintV1(parent);
        image.containers[1].mode = ContainerModeV1::Sequence;
        image.containers[1].programSemanticFingerprint = parent.programSemanticFingerprint;
        for (std::uint32_t index = 2; index < 6; ++index) {
            image.children[index].playable = image.Ref(index < 4 ? 4u : 5u);
            image.children[index].queueStopPolicy = QueueStopPolicyV1::AbortOwningQueue;
            image.occurrences[index].childPlayable = image.children[index].playable;
            if (index < 4) image.occurrences[index].parentProgramSemanticFingerprint = parent.programSemanticFingerprint;
            image.occurrences[index].occurrenceSemanticFingerprint = ComputePlayableOccurrenceFingerprintV1(image.occurrences[index]);
        }
    }
    const bool parallelControl = outerMode == ContainerModeV1::VariableControl;
    auto variable = harkentest::MakeVariableDefinition(harkentest::ObjectId(2400), VariableKindV1::Smooth, 0.0f, 1.0f, 0.5f);
    std::array<VariableDefinitionV1, 2> mixedVariables{
        variable, harkentest::MakeVariableDefinition(harkentest::ObjectId(2401), VariableKindV1::Step, 0.0f, 1.0f, 0.0f)};
    GridAxisV1 axis{0, 0, variable.variableId};
    GridAxisV1 discreteAxis{0, 0, harkentest::ObjectId(2401)};
    DiscreteGridCellV1 discreteCell{DiscreteCellKindV1::Exact, 0};
    DiscreteGridRowViewV1 discreteRow{};
    std::array<DiscreteGridCellV1, 2> naturalCells{};
    std::array<DiscreteGridRowViewV1, 2> naturalRows{};
    TransitionRuleViewV1 naturalRule{};
    TransitionProgramViewV1 naturalTransition{};
    CurveV1 naturalCurve{};
    std::array<ContinuousGridCellV1, 2> parallelCells{};
    std::array<ContinuousGridRowViewV1, 2> parallelRows{};
    std::array<ContinuousGridRowViewV1, 2> nestedRows{};
    std::array<ContinuousGridCellV1, 2> nestedCells{};
    std::array<std::array<ContinuousGridRowViewV1, 2>, 2> matrixInnerRows{};
    std::array<std::array<ContinuousGridCellV1, 2>, 2> matrixInnerCells{};
    if (parallelControl) {
        for (std::uint32_t index = 0; index < parallelRows.size(); ++index) {
            parallelCells[index].kind = ContinuousCellKindV1::Interval;
            parallelCells[index].lower = 0.0f;
            parallelCells[index].upper = 1.0f;
            parallelCells[index].lowerInclusive = parallelCells[index].upperInclusive = 1;
            parallelRows[index].stableRowOrdinal = index + 1u;
            parallelRows[index].authoredStableOrder = index;
            parallelRows[index].childStableOrdinal = image.children[4u + index].stableChildOrdinal;
            parallelRows[index].cellCount = 1;
            parallelRows[index].cells = &parallelCells[index];
        }
        auto& control = image.containers[2];
        control.memoryScope = MemoryScopeV1::Emitter;
        control.continuousAxisCount = 1;
        control.continuousAxes = &axis;
        control.continuousRowCount = parallelRows.size();
        control.continuousRows = parallelRows.data();
        control.evaluationPeriodFrames = 64;
        control.envelopeFrames = 64;
        control.maxActiveRows = 2;
        control.maxLiveRows = 4;
        if (nestedParallelControl) {
            auto& nested = image.containers[0];
            nested.mode = ContainerModeV1::VariableControl;
            nested.memoryScope = MemoryScopeV1::Emitter;
            nested.continuousAxisCount = 1;
            nested.continuousAxes = &axis;
            nested.continuousRowCount = nestedRows.size();
            nested.continuousRows = nestedRows.data();
            nested.evaluationPeriodFrames = 64;
            nested.envelopeFrames = 64;
            nested.maxActiveRows = 2;
            nested.maxLiveRows = 4;
            for (std::uint32_t index = 0; index < nestedRows.size(); ++index) {
                nestedRows[index] = parallelRows[index];
                nestedCells[index] = parallelCells[index];
                if (nestedSilentControl) nestedCells[index].upper = 0.1f;
                nestedRows[index].cells = &nestedCells[index];
                nestedRows[index].childStableOrdinal = image.children[index].stableChildOrdinal;
                image.children[index].queueStopPolicy = QueueStopPolicyV1::AbortOwningQueue;
            }
            if (nestedMixedControl) {
                discreteRow.stableRowOrdinal = 1;
                discreteRow.authoredStableOrder = 0;
                discreteRow.childStableOrdinal = image.children[0].stableChildOrdinal;
                discreteRow.cellCount = 1;
                discreteRow.cells = &discreteCell;
                nested.discreteAxisCount = 1;
                nested.discreteAxes = &discreteAxis;
                nested.discreteRowCount = 1;
                nested.discreteRows = &discreteRow;
                nested.discreteTiming = exitNestedDiscrete ? 1 : 0;
                nested.continuousRowCount = 1;
                nested.continuousRows = &nestedRows[1];
                if (naturalEndNested) {
                    for (std::uint32_t index = 0; index < 2; ++index) {
                        naturalCells[index] = {DiscreteCellKindV1::Exact, static_cast<std::int32_t>(index)};
                        naturalRows[index] = discreteRow;
                        naturalRows[index].stableRowOrdinal = index + 1u;
                        naturalRows[index].authoredStableOrder = index;
                        naturalRows[index].childStableOrdinal = image.children[index].stableChildOrdinal;
                        naturalRows[index].cells = &naturalCells[index];
                    }
                    nested.discreteTiming = 1;
                    nested.discreteRowCount = 2;
                    nested.discreteRows = naturalRows.data();
                    nested.continuousAxisCount = nested.continuousRowCount = 0;
                    nested.continuousAxes = nullptr;
                    nested.continuousRows = nullptr;
                    nested.maxActiveRows = nested.maxLiveRows = 0;
                    nested.envelopeFrames = 0;
                    naturalCurve.curveLocalId = 1;
                    naturalCurve.curve.pointCount = 2;
                    naturalCurve.curve.points[0] = {0.0f, 0.0f};
                    naturalCurve.curve.points[1] = {1.0f, 1.0f};
                    naturalCurve.curve.handles[0] = {1.0f / 3.0f, 1.0f / 3.0f, 2.0f / 3.0f, 2.0f / 3.0f};
                    nested.curves = &naturalCurve;
                    nested.curveCount = 1;
                    nested.transitionProgramIndex = 0;
                    naturalRule.stableRuleOrdinal = 1;
                    naturalRule.sourceAny = naturalRule.targetAny = 1;
                    naturalRule.sourceExit = TransitionSourceExitV1::NaturalEnd;
                    naturalRule.sourceFade.active = 1;
                    naturalRule.sourceFade.durationFrames = 256;
                    naturalRule.sourceFade.curveLocalId = 1;
                    naturalTransition.ownerContainerStableId = nested.containerStableId;
                    naturalTransition.rules = &naturalRule;
                    naturalTransition.ruleCount = 1;
                    naturalTransition.defaultRuleIndex = 0;
                    image.world.transitions = &naturalTransition;
                    image.world.transitionCount = 1;
                }
            }
        }
        image.world.variables = nestedMixedControl ? mixedVariables.data() : &variable;
        image.world.variableCount = nestedMixedControl ? mixedVariables.size() : 1;
        image.world.identity.capabilityMask = detail::ComputeCurrentWorldLocalCapabilityMaskV1(image.world);
        image.world.identity.runtimeSemanticFingerprint = ComputeCurrentWorldFingerprintV4(image.world);
    }
    if (matrixCase && innerMode == ContainerModeV1::VariableControl) {
        for (std::uint32_t branch = 0; branch < 2; ++branch) {
            auto& control = image.containers[branch];
            control.memoryScope = MemoryScopeV1::Emitter;
            control.continuousAxisCount = 1;
            control.continuousAxes = &axis;
            control.continuousRowCount = 2;
            control.continuousRows = matrixInnerRows[branch].data();
            control.evaluationPeriodFrames = control.envelopeFrames = 64;
            control.maxActiveRows = 2;
            control.maxLiveRows = 4;
            for (std::uint32_t child = 0; child < 2; ++child) {
                auto& cell = matrixInnerCells[branch][child];
                cell.kind = ContinuousCellKindV1::Interval;
                cell.lower = 0.0f;
                cell.upper = 1.0f;
                cell.lowerInclusive = cell.upperInclusive = 1;
                auto& selected = matrixInnerRows[branch][child];
                selected.stableRowOrdinal = child + 1u;
                selected.authoredStableOrder = child;
                selected.childStableOrdinal = image.children[2u * branch + child].stableChildOrdinal;
                selected.cellCount = 1;
                selected.cells = &cell;
            }
        }
        image.world.variables = &variable;
        image.world.variableCount = 1;
    }
    if (laterControl) {
        image.children[4].playable = image.Ref(0);
        image.occurrences[4].childPlayable = image.children[4].playable;
        image.occurrences[4].occurrenceSemanticFingerprint = ComputePlayableOccurrenceFingerprintV1(image.occurrences[4]);
        const auto volumeSlot = static_cast<std::size_t>(playableproperties::PlayablePropertyIdV1::Volume) - 1u;
        image.occurrences[5].payload.presentMask |= UINT64_C(1) << volumeSlot;
        image.occurrences[5].payload.values[volumeSlot].bits = std::bit_cast<std::uint32_t>(-6.0f);
        image.occurrences[5].occurrenceSemanticFingerprint = ComputePlayableOccurrenceFingerprintV1(image.occurrences[5]);
        auto& control = image.containers[1];
        discreteRow.stableRowOrdinal = 1;
        discreteRow.childStableOrdinal = image.children[2].stableChildOrdinal;
        discreteRow.cellCount = 1;
        discreteRow.cells = &discreteCell;
        control.discreteAxisCount = 1;
        control.discreteAxes = &discreteAxis;
        control.discreteRowCount = 1;
        control.discreteRows = &discreteRow;
        control.discreteTiming = requestedRetarget ? 1u : 0u;
        control.continuousRowCount = 1;
        control.continuousRows = &matrixInnerRows[1][1];
        image.world.variables = mixedVariables.data();
        image.world.variableCount = mixedVariables.size();
        if (laterWrapper) {
            auto& wrapper = image.containers[0];
            wrapper = {};
            wrapper.containerStableId = image.properties[4].stableId;
            wrapper.programSemanticFingerprint = image.properties[4].programSemanticFingerprint;
            wrapper.authoredStableOrder = 4;
            wrapper.mode = ContainerModeV1::Sequence;
            wrapper.memoryScope = MemoryScopeV1::Global;
            wrapper.children = image.children.data();
            wrapper.childCount = 2;
            for (std::uint32_t child : {0u, 1u, 5u}) {
                image.children[child].playable = image.Ref(child == 5u ? 4u : 5u);
                image.occurrences[child].childPlayable = image.children[child].playable;
                image.occurrences[child].occurrenceSemanticFingerprint = ComputePlayableOccurrenceFingerprintV1(image.occurrences[child]);
            }
        }
    }
    if (naturalEndNested) {
        const auto volumeSlot = static_cast<std::size_t>(playableproperties::PlayablePropertyIdV1::Volume) - 1u;
        image.occurrences[4].payload.presentMask |= UINT64_C(1) << volumeSlot;
        image.occurrences[4].payload.values[volumeSlot].bits = std::bit_cast<std::uint32_t>(-6.0f);
        image.occurrences[4].occurrenceSemanticFingerprint = ComputePlayableOccurrenceFingerprintV1(image.occurrences[4]);
    }
    image.world.identity.capabilityMask = detail::ComputeCurrentWorldLocalCapabilityMaskV1(image.world);
    image.world.identity.runtimeSemanticFingerprint = ComputeCurrentWorldFingerprintV4(image.world);
    if (wrappers != 0) image.WrapRoot(wrapperMode, wrappers);
    const auto rootRef = image.Ref(static_cast<std::uint32_t>(image.properties.size() - 1u));
    std::array<ActionStepProgramViewV1, 2> rollbackSteps{image.step, image.step};
    if (refuseFinal) {
        rollbackSteps[1].authoredEventIndex = 1;
        image.action.steps = rollbackSteps.data();
        image.action.stepCount = rollbackSteps.size();
        image.action.expandedStepOccurrenceCount = rollbackSteps.size();
        image.action.programSemanticFingerprint = ComputeActionProgramFingerprintV1(image.action);
        image.world.identity.runtimeSemanticFingerprint = ComputeCurrentWorldFingerprintV4(image.world);
    }
    EngineSession session(MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    if (entry == ContainerMatrixEntry::PackAction) {
        constexpr std::uint64_t packId = 22;
        ImageBuilder builder(kPackKindCanonicalContent);
        builder.AddEntry(kPackEntryKindPackRequirementBlock, packId, RequirementPayload(packId, 1, 1));
        builder.AddEntry(kPackEntryKindCanonicalDefinitionPartition, packId,
            WrapWorldPartition(packId, 1, image.world, image.world.playablePropertyCount + 1u + image.world.variableCount));
        for (std::uint32_t index = 0; index < 4; ++index) builder.AddMedia(harkentest::ObjectId(2300u + index), samples);
        const auto bytes = builder.Build();
        const auto locator = "u6-queue-sequences-" + std::to_string(cycles) + ".pack";
        const auto init = BuildSingleIdentityInit(Fnv1a64(bytes.data(), bytes.size()),
            image.action.actionStableId, locator.c_str(), rootRef.stableId);
        const auto initPath = WriteTemp("u6-queue-sequences-init.pack", init);
        const auto packPath = WriteTemp(locator, bytes);
        VnCanonicalPackSetMemberV1 members[2]{};
        VnCanonicalPackSetMemberResultV1 rows[2]{};
        const char* paths[] = {initPath.c_str(), packPath.c_str()};
        for (std::size_t i = 0; i < 2; ++i) {
            members[i].structSize = sizeof(members[i]);
            members[i].packStableId = i == 0 ? 11 : packId;
            members[i].packKind = i == 0 ? VN_CANONICAL_PACK_SET_MEMBER_INIT
                                        : VN_CANONICAL_PACK_SET_MEMBER_CONTENT;
            members[i].utf8Path = paths[i];
            rows[i].structSize = sizeof(rows[i]);
        }
        VnCanonicalPackSetActivationReportV1 activated{};
        ASSERT_EQ(VN_OK, harkentest::ActivateCanonicalMembersV1(
                              members, 2, rows, activated));
        ASSERT_NE(0u, rows[1].handle);
    } else {
        const auto pcm = harkentest::MonoDesc(samples, 48000);
        for (std::uint32_t index = 0; index < 4; ++index)
            ASSERT_EQ(VN_OK, Vn_RegisterPCM(harkentest::ObjectId(2300u + index), &pcm));
        ASSERT_EQ(WorldInstallStatus::Ok, InstallContainerWorldV1(engine, image.world).status);
    }
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    SelectionInputTrace localSelectionTrace;
    if (laterControl && selectionTrace == nullptr) selectionTrace = &localSelectionTrace;
    if (selectionTrace != nullptr) selectionTrace->Attach(engine);
    const bool randomControl = laterControl && outerMode == ContainerModeV1::Random;
    const auto derivePlayableCallerSeed = [&](std::uint64_t actionCallerSeed) {
        static constexpr char domain[] = "HARKEN-ACTION-PLAY-OCCURRENCE-V1";
        MediaContentRevisionHasherV1 hash(domain, sizeof(domain));
        hash.AddU64(actionCallerSeed);
        hash.AddObjectId(image.action.actionStableId);
        hash.AddU64(image.action.programSemanticFingerprint);
        hash.AddU32(0);
        SplitMix64 stream(hash.Finish());
        return stream.Next();
    };
    std::uint64_t actionCallerSeed = 0;
    if (randomControl) {
        ASSERT_EQ(1u, cycles);
        ASSERT_EQ(0u, wrappers);
        const auto& program = image.containers[2];
        ASSERT_EQ(rootRef.stableId, program.containerStableId);
        ASSERT_EQ(MemoryScopeV1::Global, program.memoryScope);
        ASSERT_EQ(RandomDisciplineV1::Draw, program.randomDiscipline);
        ASSERT_EQ(1u, program.avoidLastN);
        ASSERT_EQ(2u, program.childCount);
        ASSERT_EQ(harkentest::ObjectId(2300u), program.children[0].playable.stableId);
        const auto current = engine.variables.CurrentPlayableWorld();
        SelectionMemoryKeyV1 key{};
        key.world = current.generation;
        key.containerStableId = program.containerStableId;
        key.programSemanticFingerprint = program.programSemanticFingerprint;
        key.memoryScope = program.memoryScope;
        std::uint64_t fingerprint = current.identity.runtimeSemanticFingerprint;
        if (entry == ContainerMatrixEntry::PackAction) {
            const auto* published = engine.packComposition.Published();
            ASSERT_NE(nullptr, published);
            ASSERT_NE(nullptr, published->playbackStore);
            key.world = published->compositeGeneration;
            fingerprint = published->playbackStore->worldSemanticFingerprint;
        }
        ASSERT_FALSE(engine.selectionMemory.Snapshot(key).found);
        SelectionSeedInputV1 input{};
        input.worldSemanticFingerprint = fingerprint;
        input.programStableId = program.containerStableId;
        input.programSemanticFingerprint = program.programSemanticFingerprint;
        input.memoryScope = program.memoryScope;
        input.rootStableId = rootRef.stableId;
        input.acceptedPostOrdinal = engine.logicCommits.Current() + 1u;
        input.selectionOrdinal = 1u;
        std::array<SelectionChildV1, 2> children{};
        for (std::uint32_t index = 0; index < children.size(); ++index) {
            const auto& child = program.children[index];
            children[index] = {child.stableChildOrdinal, child.authoredStableOrder,
                child.frequencyWeight, child.orderWeight};
        }
        // A complete two-choice warmup must start at Sound and finish at VC.
        bool found = false;
        for (; actionCallerSeed < 1024u; ++actionCallerSeed) {
            input.callerSeed = derivePlayableCallerSeed(actionCallerSeed);
            std::uint64_t seed = 0;
            ASSERT_TRUE(ComputeSelectionSeedV1(input, &seed));
            SplitMix64 stream(seed);
            std::uint32_t ordinal = 0;
            ASSERT_EQ(SelectionStatusV1::Ok, SelectRandomDrawV1(
                children.data(), children.size(), nullptr, 0, &stream, &ordinal));
            if (ordinal == program.children[0].stableChildOrdinal) {
                found = true;
                break;
            }
        }
        ASSERT_TRUE(found);
    }
    for (std::uint32_t attempt = 0; attempt < (stopAndReplay || randomControl ? 2u : 1u); ++attempt) {
    SCOPED_TRACE(attempt);
    const bool controlWarmup = randomControl && attempt == 0;
    const bool laterRetarget = requestedRetarget && !controlWarmup;
    const bool laterRefusal = requestedRefusal && !controlWarmup;
    const auto selectionStart = selectionTrace == nullptr ? 0u : selectionTrace->selections.size();
    const bool stopThisRun = stopAndReplay && attempt == 0;
    VnActionFiringHandle firing = 0;
    PlayableInstanceHandle root = 0;
    if (entry == ContainerMatrixEntry::Direct) {
        PlayableStartRequest request{};
        request.root = rootRef;
        request.emitter = emitter;
        request.callerSeed = derivePlayableCallerSeed(actionCallerSeed);
        if (directRefusal != DirectQueueRefusal::None) {
            const auto owners = [&]() {
                return std::tuple(engine.playableInstances.LiveCount(), engine.containerPlayback.LiveCount(),
                    engine.playablePartitions.OccupiedCount(), engine.timelineArms.LiveCount(),
                    engine.voices.ActiveCount(), engine.queueInstances.LiveCount(),
                    engine.variableControlInstances.LiveCount(), engine.decisions.LiveCount(),
                    engine.armGroups.LiveCount(), engine.ledger.AvailableEntryCount(),
                    engine.timelineOccurrences.OccupiedCount(), engine.timelinePool.LiveTransactionCount());
            };
            if (directRefusal == DirectQueueRefusal::CommandOneShort) {
                // Two initial voices and two successors need 12 commands with natural completion.
                CommandRecord filler{};
                filler.opcode = kOpcodeStop;
                filler.payload.stop.handle = UINT64_MAX;
                while (engine.commands.FreeSlots() > 11u) ASSERT_TRUE(engine.commands.TryPush(filler));
            } else {
                ASSERT_EQ(VN_OK, Vn_UnregisterPCM(harkentest::ObjectId(2303u)));
            }
            const auto before = owners();
            const auto head = engine.commands.PublishedHead();
            const auto free = engine.commands.FreeSlots();
            const auto refused = StartPlayable(engine, request);
            ASSERT_EQ(PlayableStartStatus::Backpressure, refused.status);
            EXPECT_EQ(before, owners());
            EXPECT_EQ(head, engine.commands.PublishedHead());
            EXPECT_EQ(free, engine.commands.FreeSlots());
            EXPECT_FALSE(engine.runtimeRecreateRequired);
            EXPECT_TRUE(std::all_of(engine.actionPlayScratch.begin(), engine.actionPlayScratch.end(),
                [](const auto& scratch) { return scratch.storage.phase == EngineFrontierAttemptPhase::Free; }));
            if (directRefusal == DirectQueueRefusal::CommandOneShort) {
                CommandRecord filler{};
                while (engine.commands.TryPop(filler)) EXPECT_EQ(kOpcodeStop, filler.opcode);
            } else {
                const auto pcm = harkentest::MonoDesc(samples, 48000);
                ASSERT_EQ(VN_OK, Vn_RegisterPCM(harkentest::ObjectId(2303u), &pcm));
            }
        }
        const auto start = StartPlayable(engine, request);
        ASSERT_EQ(PlayableStartStatus::Accepted, start.status);
        root = start.instance;
    } else {
        VnPostActionDesc post{};
        post.structSize = sizeof(post);
        post.actionId = image.action.actionStableId;
        post.emitter = emitter;
        post.callerSeed = actionCallerSeed;
        engine.forceActionFinalOwnerCommitFailureForTest = refuseFinal;
        engine.actionFinalOwnerCommitFailureSkipForTest = refuseFinal && nestedParallelControl ? 1u : 0u;
        const auto commandHead = engine.commands.PublishedHead();
        const auto posted = Vn_PostAction(&post, &firing);
        if (refuseFinal) {
            ASSERT_EQ(VN_OK, posted);
            for (std::uint32_t index = 0; index < rollbackSteps.size(); ++index) {
                VnActionStepResult failed{};
                failed.structSize = sizeof(failed);
                ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, index, &failed));
                EXPECT_EQ(VN_ACTION_STEP_FAILED, failed.state);
                EXPECT_EQ(VN_RUNTIME_RECREATE_REQUIRED, failed.result);
            }
            EXPECT_FALSE(engine.forceActionFinalOwnerCommitFailureForTest);
            EXPECT_EQ(commandHead, engine.commands.PublishedHead());
            EXPECT_EQ(0u, engine.playableInstances.LiveCount());
            EXPECT_EQ(0u, engine.containerPlayback.LiveCount());
            EXPECT_EQ(0u, engine.playablePartitions.OccupiedCount());
            EXPECT_EQ(0u, engine.timelineArms.LiveCount());
            EXPECT_EQ(0u, engine.voices.ActiveCount());
            EXPECT_EQ(0u, engine.queueInstances.LiveCount());
            EXPECT_TRUE(std::none_of(engine.initialFrontierArmPins.begin(), engine.initialFrontierArmPins.end(),
                [](const auto& owned) { return owned.pin.Valid(); }));
            EXPECT_TRUE(std::all_of(engine.playableServices.begin(), engine.playableServices.end(),
                [](const auto& service) { return !service.partition.Valid() && !service.actionPrepared; }));
            EXPECT_TRUE(std::all_of(engine.actionPlayScratch.begin(), engine.actionPlayScratch.end(),
                [](const auto& scratch) { return scratch.storage.phase == EngineFrontierAttemptPhase::Free; }));
            return;
        }
        ASSERT_EQ(VN_OK, posted);
        VnActionStepResult result{};
        result.structSize = sizeof(result);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &result));
        ASSERT_EQ(VN_ACTION_STEP_ACTIVE, result.state);
        root = result.producedPlayableInstance;
    }
    ASSERT_NE(0u, root);
    if (replayAtFiringTerminal && attempt == 0u) {
        engine.queueNaturalEndRetirementHookForTest =
            [](Engine& hooked, EnginePlayableServiceRow& service) {
                hooked.queueNaturalEndRetirementHookForTest = nullptr;
                service.phase = EnginePlayableStartPhase::AwaitingArmAck;
                service.arm = {};
                return true;
            };
    }
    if (randomControl) {
        const auto begin = selectionTrace->selections.begin() + selectionStart;
        const auto end = selectionTrace->selections.end();
        const auto initial = std::find_if(begin, end,
            [&](const auto& choice) { return choice.program == rootRef.stableId; });
        ASSERT_NE(end, initial);
        EXPECT_EQ(1, std::count_if(begin, end,
            [&](const auto& choice) { return choice.program == rootRef.stableId; }));
        EXPECT_TRUE(initial->path.empty());
        ASSERT_EQ(1u, initial->subjects.size());
        ASSERT_EQ(harkentest::ObjectId(2300u), initial->subjects[0]);
    }
    if (matrixCase && parallelControl &&
        (innerMode == ContainerModeV1::Random || innerMode == ContainerModeV1::Sequence)) {
        for (const auto& service : engine.playableServices) {
            if (!service.InvocationValid() || !service.ordinaryLifecycleOwned || service.queueMode) continue;
            EXPECT_TRUE(service.arm.Valid()) << "ordinary owner=" << service.ownerInstance;
            EXPECT_NE(0u, service.renderHandle);
            EXPECT_EQ(1u, service.pendingFutureCount);
        }
    }
    if (cancelNestedBeforeStart) {
        bool cancelled = false;
        for (const auto& service : engine.playableServices) {
            if (!service.partition.Valid() || !service.variableControlInstance.Valid() ||
                service.ownerInstance == root) continue;
            ASSERT_TRUE(engine.variableControlInstances.CancelSide(service.variableControlInstance,
                VariableControlSide::Continuous, service.variableControlContinuousDecision));
            cancelled = true;
        }
        ASSERT_TRUE(cancelled);
    }
    if (parallelControl && wrappers != 0) {
        bool foundOuterService = false;
        for (const auto& service : engine.playableServices) {
            if (!service.InvocationValid() || service.ownerInstance != root) continue;
            foundOuterService = true;
            EXPECT_EQ(wrapperMode == ContainerModeV1::SequenceQueue || wrapperMode == ContainerModeV1::RandomQueue,
                service.queueMode);
            EXPECT_EQ(service.queueMode, service.queueInstance.Valid());
            EXPECT_TRUE(service.frontierChildService.Valid());
        }
        EXPECT_TRUE(foundOuterService);
    }
    FrontierTrace actual;
    bool stopped = false;
    bool stopExitViolationReported = false;
    bool discreteExitRequested = false;
    bool discreteExitObserved = false;
    bool naturalRequested = false;
    bool naturalPrelude = false;
    bool naturalCompletion = false;
    bool laterRefusalInjected = false;
    bool laterExitRequested = false;
    bool laterReentered = false;
    bool firingTerminal = false;
    bool deferredNaturalEndObserved = false;
    bool deferredNaturalEndVerified = false;
    std::size_t checkedPropertyVoices = 0;
    for (std::uint32_t block = 0; block < 256; ++block) {
        const bool verifyDeferredNaturalEnd =
            deferredNaturalEndObserved && !deferredNaturalEndVerified;
        EnginePlayableServiceRow* deferredNaturalEndRow = nullptr;
        EnginePlayableServiceToken deferredNaturalEndToken{};
        bool deferredNaturalEndWasRetiring = false;
        if (verifyDeferredNaturalEnd) {
            for (auto& service : engine.playableServices) {
                if (service.arm.Valid() ||
                    service.controlLifecycle !=
                        PlayableControlLifecycle::LogicalComplete) {
                    continue;
                }
                deferredNaturalEndRow = &service;
                deferredNaturalEndToken = service.identity;
                deferredNaturalEndWasRetiring = service.partitionRetiring;
                service.partitionRetiring = false;
                break;
            }
            ASSERT_NE(nullptr, deferredNaturalEndRow);
        }
        const auto updateResult = Vn_Update();
        if (verifyDeferredNaturalEnd) {
            EXPECT_NE(EnginePlayableStartPhase::Cancelling,
                      deferredNaturalEndRow->phase);
            EXPECT_NE(PlayableControlLifecycle::FailingSourceActive,
                      deferredNaturalEndRow->controlLifecycle);
            EXPECT_NE(PlayableControlReason::StartRefused,
                      deferredNaturalEndRow->controlReason);
            if (deferredNaturalEndRow->identity == deferredNaturalEndToken &&
                deferredNaturalEndRow->phase !=
                    EnginePlayableStartPhase::Free) {
                deferredNaturalEndRow->partitionRetiring =
                    deferredNaturalEndWasRetiring;
            }
            deferredNaturalEndVerified = true;
            EXPECT_FALSE(engine.runtimeRecreateRequired);
        }
        ASSERT_EQ(VN_OK, updateResult);
        if (stopThisRun && stopped && parallelControl && wrappers != 0 &&
            !stopExitViolationReported) {
            for (const auto& service : engine.playableServices) {
                if (service.phase == EnginePlayableStartPhase::Free) continue;
                const bool validReason = service.controlReason == PlayableControlReason::None ||
                    service.controlReason == PlayableControlReason::StopRequested;
                const bool validLifecycle = service.controlLifecycle != PlayableControlLifecycle::FailingSourceActive &&
                    service.controlLifecycle != PlayableControlLifecycle::FailingAudibleRetiring;
                if (validReason && validLifecycle) continue;
                ADD_FAILURE() << "First invalid Stop exit: block=" << block
                    << " service=" << service.identity.slot << '/' << service.identity.generation
                    << " phase/lifecycle/reason=" << static_cast<unsigned>(service.phase) << '/'
                    << static_cast<unsigned>(service.controlLifecycle) << '/'
                    << static_cast<unsigned>(service.controlReason);
                stopExitViolationReported = true;
                break;
            }
        }
        if (replayAtFiringTerminal && attempt == 1u &&
            engine.queueNaturalEndRetirementHookForTest == nullptr) {
            deferredNaturalEndObserved = true;
        }
        engine.nullBackend.Pump(1);
        actual.Capture(engine);
        if (laterControl || naturalEndNested) {
            while (checkedPropertyVoices < actual.heard.size()) {
                const auto& heard = actual.heard[checkedPropertyVoices++];
                if (laterControl ? heard.subject == harkentest::ObjectId(2300u) : heard.subject >= harkentest::ObjectId(2302u)) continue;
                bool found = false;
                for (std::size_t slot = 0; slot < engine.playableScheduleArms.size(); ++slot) {
                    const auto& arm = engine.playableScheduleArms[slot];
                    if (arm.slot != heard.token.slot || arm.generation != heard.token.generation) continue;
                    EXPECT_FLOAT_EQ(-6.0f, engine.playableScheduleVoices[slot].volumeDb);
                    found = true;
                }
                EXPECT_TRUE(found);
                if (laterWrapper) {
                    ContainerPlaybackRow wrapper{};
                    ASSERT_TRUE(engine.containerPlayback.Capture(heard.parentParent, &wrapper));
                    EXPECT_EQ(harkentest::ObjectId(2304u), wrapper.containerStableId);
                }
            }
            if (laterRefusal && !laterRefusalInjected && actual.heard.size() == 1u &&
                actual.heard[0].complete >= actual.heard[0].start) {
                if (laterProbe == LaterControlProbe::PublicationRefusal)
                    engine.forceContainerLoopPostFailureForTest = true;
                else {
                    CommandRecord filler{};
                    filler.opcode = kOpcodeStop;
                    filler.payload.stop.handle = UINT64_MAX;
                    while (engine.commands.FreeSlots() > 5u) ASSERT_TRUE(engine.commands.TryPush(filler));
                }
                laterRefusalInjected = true;
            }
            if (laterRetarget && !laterExitRequested && actual.heard.size() == 3u) {
                ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(2401), 1.0f));
                laterExitRequested = true;
            }
            if (laterRetarget && laterExitRequested && !laterReentered) {
                for (const auto& service : engine.playableServices) {
                    if (!service.partition.Valid() || !service.variableControlInstance.Valid() ||
                        service.variableControlDiscreteMemberCount != 0 || service.variableControlDiscreteRetargetPrepared) continue;
                    ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(2401), 0.0f));
                    laterReentered = true;
                    break;
                }
            }
        }
        if (naturalEndNested && !naturalRequested && actual.heard.size() == 2u) {
            ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(2401), 1.0f));
            naturalRequested = true;
        }
        if (naturalEndNested) {
            for (const auto& service : engine.playableServices) {
                if (!service.InvocationValid() || service.ownerInstance == root ||
                    !service.variableControlDiscreteRetargetPrepared ||
                    !service.variableControlDiscreteRetargetDecision.Valid()) continue;
                ASSERT_TRUE(service.frontierLifetimeEntry.Valid());
                DecisionCommittedSnapshot decision{};
                if (!engine.decisions.CaptureCommitted(service.variableControlDiscreteRetargetDecision, &decision)) continue;
                VariableControlInstanceSnapshot side{};
                ASSERT_TRUE(engine.variableControlInstances.Capture(service.variableControlInstance, &side));
                if (decision.audioState == AudioGroupState::AudioClaimed) {
                    naturalPrelude = true;
                    EXPECT_EQ(VariableControlSideState::Pending, side.discrete.state);
                    EXPECT_TRUE(std::none_of(actual.heard.begin(), actual.heard.end(),
                        [](const auto& onset) { return onset.subject == harkentest::ObjectId(2301u); }));
                }
                if (decision.audioState == AudioGroupState::Admitted) {
                    naturalCompletion = true;
                    EXPECT_EQ(VariableControlSideState::Committed, side.discrete.state);
                    for (std::uint32_t source = 0; source < service.variableControlDiscreteRetargetSourceMemberCount; ++source) {
                        ArmState state{};
                        ASSERT_TRUE(engine.timelineArms.State(service.variableControlDiscreteRetargetGroupArms[source], &state));
                        EXPECT_EQ(ArmState::Tombstoned, state);
                    }
                }
            }
        }
        if (exitNestedDiscrete && !discreteExitRequested && actual.heard.size() == 3u) {
            ASSERT_EQ(VN_OK, Vn_SetValue(harkentest::ObjectId(2401), 1.0f));
            discreteExitRequested = true;
        }
        if (discreteExitRequested && !discreteExitObserved && actual.heard.size() >= 3u) {
            const auto& departing = actual.heard[0];
            const bool gone = departing.sourceCompletionSequence != 0 &&
                departing.releasedAtBlock != 0;
            if (gone) {
                EXPECT_EQ(SourceTerminalKind::Stop, departing.terminal.kind);
                const auto& retained = actual.heard[1];
                ASSERT_TRUE(retained.source.Valid());
                EXPECT_EQ(0u, retained.sourceCompletionSequence);
                EXPECT_EQ(0u, retained.releasedAtBlock);
                const auto render = (static_cast<std::uint64_t>(retained.token.renderGeneration) << 32) |
                    retained.token.renderSlot;
                const auto* voice = engine.voices.Resolve(render);
                ASSERT_NE(nullptr, voice);
                EXPECT_FALSE(voice->timelineGated);
                ASSERT_GT(voice->variableWeightControlCount, 0u);
                for (std::uint32_t control = 0; control < voice->variableWeightControlCount; ++control)
                    EXPECT_FLOAT_EQ(1.0f, voice->variableWeightControls[control].segment.endWeight);
                EXPECT_TRUE(engine.playableInstances.Classify(root).live);
                discreteExitObserved = true;
            }
        }
        const auto stopOnsetCount = stopAfterOnsets != 0
            ? stopAfterOnsets
            : (parallelControl && !nestedParallelControl ? 2u : 3u);
        if (stopThisRun && !stopped && actual.heard.size() == stopOnsetCount) {
            ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, stopFadeMs));
            stopped = true;
        }
        if (stopThisRun && stopped && replayAtFiringTerminal) {
            VnActionFiringInfo info{};
            info.structSize = sizeof(info);
            ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
            firingTerminal =
                info.state == VN_ACTION_FIRING_TERMINAL_RETAINED;
            if (firingTerminal) break;
        }
        if (!engine.playableInstances.Classify(root).live && engine.timelineArms.LiveCount() == 0 &&
            engine.playablePartitions.OccupiedCount() == 0 && engine.queueInstances.LiveCount() == 0 &&
            engine.variableControlInstances.LiveCount() == 0 && engine.decisions.LiveCount() == 0 &&
            engine.armGroups.LiveCount() == 0 &&
            (!replayAtFiringTerminal || attempt != 1u ||
             deferredNaturalEndVerified)) break;
    }
    if (stopThisRun && parallelControl && wrappers != 0 && !replayAtFiringTerminal) {
        ASSERT_TRUE(stopped);
        ASSERT_EQ(0u, engine.voices.ActiveCount());
        ASSERT_EQ(0u, engine.playableInstances.LiveCount());
        ASSERT_EQ(0u, engine.containerPlayback.LiveCount());
        ASSERT_EQ(0u, engine.playablePartitions.OccupiedCount());
        ASSERT_EQ(0u, engine.timelineArms.LiveCount());
        ASSERT_EQ(0u, engine.queueInstances.LiveCount());
        ASSERT_EQ(0u, engine.variableControlInstances.LiveCount());
        ASSERT_EQ(0u, engine.decisions.LiveCount());
        ASSERT_EQ(0u, engine.armGroups.LiveCount());
        ASSERT_TRUE(std::none_of(engine.initialFrontierArmPins.begin(),
            engine.initialFrontierArmPins.end(),
            [](const auto& owned) { return owned.pin.Valid(); }));
    }
    if (cancelNestedBeforeStart) {
        EXPECT_TRUE(actual.heard.empty());
        EXPECT_EQ(0u, engine.playableInstances.LiveCount());
        EXPECT_EQ(0u, engine.containerPlayback.LiveCount());
        EXPECT_EQ(0u, engine.playablePartitions.OccupiedCount());
        EXPECT_EQ(0u, engine.timelineArms.LiveCount());
        EXPECT_EQ(0u, engine.queueInstances.LiveCount());
        EXPECT_EQ(0u, engine.variableControlInstances.LiveCount());
        EXPECT_EQ(0u, engine.decisions.LiveCount());
        EXPECT_EQ(0u, engine.armGroups.LiveCount());
        EXPECT_EQ(0u, engine.voices.ActiveCount());
        EXPECT_TRUE(std::none_of(engine.initialFrontierArmPins.begin(), engine.initialFrontierArmPins.end(),
            [](const auto& owned) { return owned.pin.Valid(); }));
        return;
    }
    const auto expectedCount = laterRefusal ? 1u : laterRetarget ? (laterWrapper ? 6u : 4u) :
        laterControl ? (laterWrapper ? 5u : 3u) :
        matrixCase && (outerMode == ContainerModeV1::RandomQueue ||
                       outerMode == ContainerModeV1::SequenceQueue) &&
            innerMode == ContainerModeV1::VariableControl
        ? 2u : 4u * cycles;
    const auto expectedStopCount = stopAfterOnsets != 0
        ? stopAfterOnsets
        : (parallelControl && !nestedParallelControl ? 2u : 3u);
    ASSERT_EQ(stopThisRun ? expectedStopCount : expectedCount, actual.heard.size())
        << "natural requested/prelude/completion=" << naturalRequested << '/' << naturalPrelude << '/' << naturalCompletion
        << " recreate=" << engine.runtimeRecreateRequired;
    if (controlWarmup) {
        std::vector<const SelectionInputTrace::Selection*> rootSelections;
        for (auto index = selectionStart; index < selectionTrace->selections.size(); ++index) {
            const auto& choice = selectionTrace->selections[index];
            if (choice.program == rootRef.stableId) rootSelections.push_back(&choice);
        }
        ASSERT_EQ(2u, rootSelections.size());
        for (std::uint32_t index = 0; index < rootSelections.size(); ++index) {
            const auto& choice = *rootSelections[index];
            ASSERT_EQ(1u, choice.subjects.size());
            EXPECT_TRUE(choice.path.empty());
            EXPECT_EQ(index, choice.loopIteration);
            EXPECT_EQ(index, choice.selectionOrdinal);
            EXPECT_EQ(harkentest::ObjectId(index == 0u ? 2300u : laterWrapper ? 2304u : 2305u),
                choice.subjects[0]);
        }
        ASSERT_EQ(harkentest::ObjectId(2300u), actual.heard[0].subject);
        for (std::uint32_t index = 1; index < actual.heard.size(); ++index) {
            const auto& heard = actual.heard[index];
            EXPECT_EQ(harkentest::ObjectId(index % 2u == 1u ? 2302u : 2303u), heard.subject);
            EXPECT_GT(heard.start, actual.heard[0].complete);
        }
        ASSERT_FALSE(engine.playableInstances.Classify(root).live);
        ASSERT_EQ(0u, engine.playableInstances.LiveCount());
        ASSERT_EQ(0u, engine.containerPlayback.LiveCount());
        ASSERT_EQ(0u, engine.playablePartitions.OccupiedCount());
        ASSERT_EQ(0u, engine.timelineArms.LiveCount());
        ASSERT_EQ(0u, engine.queueInstances.LiveCount());
        ASSERT_EQ(0u, engine.variableControlInstances.LiveCount());
        ASSERT_EQ(0u, engine.decisions.LiveCount());
        ASSERT_EQ(0u, engine.armGroups.LiveCount());
        ASSERT_EQ(0u, engine.voices.ActiveCount());
        ASSERT_FALSE(engine.runtimeRecreateRequired);
    }
    for (std::uint32_t index = 0; index < actual.heard.size(); ++index) {
        SCOPED_TRACE(index);
        const auto& heard = actual.heard[index];
        const auto child = matrixCase || naturalEndNested || nestedSilentControl ? static_cast<std::uint32_t>(heard.subject.low - 2300u) : nestedParallelControl ? index : sharedQueueProgram ? index / 2u : parallelControl ? (index % 2u) * 2u + index / 2u :
            replayAtFiringTerminal && attempt == 1u
            ? (std::array<std::uint32_t, 4>{1u, 0u, 2u, 3u})[index % 4u] :
            attempt == 1u && innerMode == ContainerModeV1::Sequence && index % 4u >= 2u
            ? (index % 4u == 2u ? 3u : 2u) : index % 4u;
        if (!matrixCase && !naturalEndNested) EXPECT_EQ(harkentest::ObjectId(2300u + child), heard.subject);
        EXPECT_LT(child, 4u);
        EXPECT_EQ(heard.expectedStart, heard.start);
        if ((!stopThisRun || (!parallelControl && index + 1u < actual.heard.size())) &&
            !(exitNestedDiscrete && child == 0u) && !(laterRetarget && child == 2u)) EXPECT_GE(heard.complete, heard.start);
        EXPECT_NE(0u, heard.leaf);
        EXPECT_NE(0u, heard.leafEpoch);
        EXPECT_NE(0u, heard.parent);
        EXPECT_NE(0u, heard.parentEpoch);
        EXPECT_EQ(root, heard.root);
        EXPECT_EQ((laterControl && child == 0 ? 1u : laterWrapper ? 3u : 2u) + wrappers + (sharedQueueProgram ? 1u : 0u), heard.containerDepth);
        if (laterControl && child == 0) EXPECT_EQ(root, heard.parent);
        else if (laterWrapper) EXPECT_NE(root, heard.parentParent);
        else if (wrappers == 0 && !sharedQueueProgram) EXPECT_EQ(root, heard.parentParent);
        EXPECT_EQ(harkentest::ObjectId(laterControl && child == 0 ? 2306u : 2304u + child / 2u), heard.parentStableId);
        if (matrixCase && !(laterRetarget && child == 2u)) {
            heard.ExpectNaturalSourceReleased();
        }
    }
    if (sharedQueueProgram) {
        EXPECT_NE(actual.heard[0].parent, actual.heard[1].parent);
        EXPECT_NE(actual.heard[0].parentParent, actual.heard[1].parentParent);
        if (!stopThisRun) {
            EXPECT_EQ(actual.heard[0].parent, actual.heard[2].parent);
            EXPECT_EQ(actual.heard[1].parent, actual.heard[3].parent);
        }
    }
    if (laterRefusal) {
        EXPECT_TRUE(laterRefusalInjected);
        EXPECT_FALSE(engine.forceContainerLoopPostFailureForTest);
        EXPECT_TRUE(std::all_of(engine.actionPlayScratch.begin(), engine.actionPlayScratch.end(),
            [](const auto& scratch) { return scratch.storage.phase == EngineFrontierAttemptPhase::Free; }));
    }
    if (laterRetarget) EXPECT_TRUE(laterReentered);
    if (replayAtFiringTerminal && attempt == 1u) {
        EXPECT_EQ(nullptr, engine.queueNaturalEndRetirementHookForTest);
        EXPECT_TRUE(deferredNaturalEndVerified);
    }
    if ((!stopThisRun || !replayAtFiringTerminal) && engine.playablePartitions.OccupiedCount() != 0) {
        for (const auto& service : engine.playableServices) {
            if (service.phase == EnginePlayableStartPhase::Free) continue;
            ADD_FAILURE() << "service=" << service.identity.slot << " root=" << service.rootInstance
                << " phase=" << static_cast<int>(service.phase)
                << " lifecycle=" << static_cast<int>(service.controlLifecycle)
                << " retiring=" << service.partitionRetiring << " queueEnd=" << service.queueNaturalEnd
                << " frontier=" << service.frontierEntry.Valid();
            for (const auto& ref : engine.playableMemberReferences) {
                if (ref.service.token == service.identity)
                    ADD_FAILURE() << "reference slot=" << (&ref - engine.playableMemberReferences.data());
            }
        }
    }
    if (!stopThisRun || !replayAtFiringTerminal) {
        EXPECT_EQ(0u, engine.playableInstances.LiveCount());
        EXPECT_EQ(0u, engine.containerPlayback.LiveCount());
        EXPECT_EQ(0u, engine.playablePartitions.OccupiedCount());
        EXPECT_EQ(0u, engine.timelineArms.LiveCount());
        EXPECT_EQ(0u, engine.queueInstances.LiveCount());
        EXPECT_EQ(0u, engine.variableControlInstances.LiveCount());
        EXPECT_EQ(0u, engine.decisions.LiveCount());
        EXPECT_EQ(0u, engine.armGroups.LiveCount());
        EXPECT_EQ(0u, engine.voices.ActiveCount());
    } else {
        ASSERT_TRUE(firingTerminal);
        ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    }
    if (exitNestedDiscrete) {
        EXPECT_TRUE(discreteExitObserved);
        ASSERT_EQ(1u, actual.controls.size());
        EXPECT_EQ(TimelineEventKind::Stop, actual.controls.front().kind);
        for (const auto& control : actual.controls) {
            const auto voice = std::find_if(actual.heard.begin(), actual.heard.end(), [&](const auto& heard) {
                return heard.token.renderSlot == control.token.renderSlot &&
                    heard.token.renderGeneration == control.token.renderGeneration;
            });
            ASSERT_NE(actual.heard.end(), voice);
            EXPECT_EQ(voice->subject, control.subject);
            if (control.kind == TimelineEventKind::Stop)
                EXPECT_LT(voice->start, control.applied);
            else
                EXPECT_LE(control.applied, voice->complete);
            EXPECT_EQ(control.applied, control.complete);
            EXPECT_TRUE(control.kind == TimelineEventKind::Stop || control.kind == TimelineEventKind::VariableWeight);
        }
        EXPECT_NE(actual.heard[0].leaf, actual.heard[1].leaf);
    }
    EXPECT_FALSE(engine.runtimeRecreateRequired);
    if (selectionTrace != nullptr) selectionTrace->actual = actual;
    if (naturalEndNested) {
        EXPECT_TRUE(naturalPrelude);
        EXPECT_TRUE(naturalCompletion);
        std::array<std::uint32_t, 4> counts{};
        for (const auto& onset : actual.heard) ++counts[onset.subject.low - 2300u];
        EXPECT_EQ((std::array<std::uint32_t, 4>{1, 1, 1, 1}), counts);
    }
    }
}

