void ExpectMultiLeafContainerLoopCompletesAndReclaims(
    ContainerMatrixEntry entry, ContainerMatrixChild childKind,
    std::uint32_t caseIndex,
    ContainerModeV1 mode = ContainerModeV1::Sequence,
    std::uint32_t loopCount = 2, std::uint32_t nestedLoopCount = 0,
    MemoryScopeV1 outerScope = MemoryScopeV1::Global,
    MemoryScopeV1 innerScope = MemoryScopeV1::Emitter,
    bool unequalLengths = false, bool checkRetiring = false,
    std::uint32_t availableInstances = 0, bool alternateSound = false,
    bool delayTail = false, std::uint32_t stopRunCount = 0,
    bool stopBeforeOnset = false, bool authoredStop = false,
    bool authoredStopPressure = false) {
    const bool multiLeaf = childKind == ContainerMatrixChild::Track ||
        childKind == ContainerMatrixChild::Piece;
    const std::uint32_t leafCount = multiLeaf ? 2u : 1u;
    (void)Vn_Term();
    constexpr std::uint64_t kPackStableId = 22;
    const std::vector<float> firstSamples(256, 0.25f);
    const std::vector<float> secondSamples(unequalLengths ? 512u : 256u, -0.25f);
    const float* firstChannels[1] = {firstSamples.data()};
    const float* secondChannels[1] = {secondSamples.data()};
    std::uint64_t firstRevision = 0;
    std::uint64_t secondRevision = 0;
    ASSERT_TRUE(ComputeMediaPcmContentRevisionV1(
        48000, 1, firstSamples.size(), firstChannels, 1, &firstRevision));
    ASSERT_TRUE(ComputeMediaPcmContentRevisionV1(
        48000, 1, secondSamples.size(), secondChannels, 1, &secondRevision));
    ContainerMatrixWorld image(mode, childKind, firstRevision, secondRevision,
                        multiLeaf, loopCount, nestedLoopCount,
                        outerScope, innerScope, delayTail);
    constexpr VnObjectId kStopAction = harkentest::ObjectId(72101);
    ActionStepProgramViewV1 stopStep{};
    std::array<ActionProgramViewV1, 2> actions{image.action, {}};
    if (authoredStop) {
        ASSERT_NE(ContainerMatrixEntry::Direct, entry);
        stopStep = image.step;
        stopStep.opcode = ActionOpcodeV1::Stop;
        actions[1] = image.action;
        actions[1].actionStableId = harkentest::ObjectId(kStopAction);
        actions[1].steps = &stopStep;
        actions[1].programSemanticFingerprint =
            ComputeActionProgramFingerprintV1(actions[1]);
        image.world.actions = actions.data();
        image.world.actionCount = actions.size();
        image.world.identity.runtimeSemanticFingerprint =
            ComputeCurrentWorldFingerprintV4(image.world);
    }
    if (alternateSound) {
        ASSERT_TRUE(multiLeaf);
        ASSERT_EQ(0u, nestedLoopCount);
        auto& soundChild = image.children[1];
        soundChild = image.children[0];
        soundChild.stableChildOrdinal = 8;
        soundChild.authoredStableOrder = 2;
        soundChild.playable = PlayableRefFromProperty(image.properties[0]);
        image.containers[0].childCount = 2;
        auto& occurrence = image.occurrences[image.occurrenceCount++];
        occurrence = image.occurrences[0];
        occurrence.stableOccurrenceOrdinal = soundChild.stableChildOrdinal;
        occurrence.childPlayable = soundChild.playable;
        occurrence.occurrenceSemanticFingerprint =
            ComputePlayableOccurrenceFingerprintV1(occurrence);
        std::rotate(image.occurrences.begin() + 1,
                    image.occurrences.begin() + image.occurrenceCount - 1,
                    image.occurrences.begin() + image.occurrenceCount);
        image.world.playableOccurrenceCount = image.occurrenceCount;
        image.world.identity.runtimeSemanticFingerprint =
            ComputeCurrentWorldFingerprintV4(image.world);
    }

    auto config = MakeNullConfig(16, 64, 48000);
    if (delayTail) {
        config.fxSlotsPerVoice = 1;
        config.delayEffectPoolCapacity = 16;
        config.voiceSendSlots = 1;
    }
    EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    Engine* engine = session.Engine();
    ASSERT_NE(nullptr, engine);
    VnPackHandle pack = 0;
    if (entry == ContainerMatrixEntry::PackAction) {
        ImageBuilder builder(kPackKindCanonicalContent);
        const std::uint64_t ownedDefinitionCount =
            image.world.playablePropertyCount + image.world.actionCount;
        builder.AddEntry(
            kPackEntryKindPackRequirementBlock, kPackStableId,
            RequirementPayload(kPackStableId, 1, 1));
        builder.AddEntry(
            kPackEntryKindCanonicalDefinitionPartition, kPackStableId,
            WrapWorldPartition(kPackStableId, 1, image.world,
                               ownedDefinitionCount));
        builder.AddMedia(ContainerMatrixWorld::kFirstSound, firstSamples);
        builder.AddMedia(ContainerMatrixWorld::kSecondSound, secondSamples);
        const auto packBytes = builder.Build();
        const std::string stem =
            "u4-container-loop-composite-" + std::to_string(caseIndex);
        const std::string packLocator = stem + "-a.pack";
        const auto initBytes = BuildSingleIdentityInit(
            Fnv1a64(packBytes.data(), packBytes.size()),
            ContainerMatrixWorld::kAction, packLocator.c_str(), ContainerMatrixWorld::kRoot,
            authoredStop ? kStopAction : VnObjectId{}, {}, delayTail ? 2 : 0);
        const std::string initPath =
            WriteTemp(stem + "-init.pack", initBytes);
        const std::string packPath = WriteTemp(packLocator, packBytes);
        VnCanonicalPackSetMemberV1 members[2]{};
        VnCanonicalPackSetMemberResultV1 rows[2]{};
        const char* paths[] = {initPath.c_str(), packPath.c_str()};
        for (std::size_t i = 0; i < 2; ++i) {
            members[i].structSize = sizeof(members[i]);
            members[i].packStableId = i == 0 ? 11 : kPackStableId;
            members[i].packKind = i == 0 ? VN_CANONICAL_PACK_SET_MEMBER_INIT
                                        : VN_CANONICAL_PACK_SET_MEMBER_CONTENT;
            members[i].utf8Path = paths[i];
            rows[i].structSize = sizeof(rows[i]);
        }
        VnCanonicalPackSetActivationReportV1 activated{};
        ASSERT_EQ(VN_OK, harkentest::ActivateCanonicalMembersV1(
                              members, 2, rows, activated));
        pack = rows[1].handle;
        ASSERT_NE(0u, pack);
    } else {
        const VnPCMDesc firstPcm = harkentest::MonoDesc(firstSamples, 48000);
        const VnPCMDesc secondPcm = harkentest::MonoDesc(secondSamples, 48000);
        ASSERT_EQ(VN_OK,
                  Vn_RegisterPCM(ContainerMatrixWorld::kFirstSound, &firstPcm));
        ASSERT_EQ(VN_OK,
                  Vn_RegisterPCM(ContainerMatrixWorld::kSecondSound, &secondPcm));
        if (delayTail) ASSERT_EQ(VN_OK, Vn_CreateBus(VN_OBJECT_ID(0, 2), VN_BUS_MASTER));
        if (entry == ContainerMatrixEntry::CurrentWorldAction) {
            ASSERT_EQ(WorldInstallStatus::Ok,
                      InstallContainerWorldV1(*engine, image.world).status);
        }
    }

    std::vector<PlayableInstanceHandle> capacityOccupants;
    if (availableInstances != 0) {
        ASSERT_GT(engine->playableInstances.FreeCount(), availableInstances);
        while (engine->playableInstances.FreeCount() > availableInstances) {
            const auto occupant = engine->playableInstances.Acquire(PlayableKind::Sound, 0);
            ASSERT_NE(0u, occupant);
            capacityOccupants.push_back(occupant);
        }
    }
    const auto playableBaseline = engine->playableInstances.LiveCount();
    const auto containerBaseline = engine->containerPlayback.LiveCount();
    const auto partitionBaseline = engine->playablePartitions.OccupiedCount();
    const auto voiceBaseline = engine->voices.ActiveCount();
    const auto delayBaseline = engine->effectBank.DelayInUse();
    const auto ledgerBaseline = engine->ledger.AvailableEntryCount();
    const auto armBaseline = engine->timelineArms.LiveCount();
    const auto occurrenceBaseline =
        engine->timelineOccurrences.OccupiedCount();
    const auto compositeBaseline =
        engine->compositeCompletionOwners.OccupiedCount();
    const auto transactionBaseline =
        engine->timelinePool.LiveTransactionCount();
    const auto executorBaseline = engine->timelineExecutor.Stats();
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));

    VnActionFiringHandle firing = 0;
    PlayableInstanceHandle produced = 0;
    if (entry == ContainerMatrixEntry::Direct) {
        PlayableWorldViewV1 frozen{};
        frozen.generation = 73u + caseIndex;
        frozen.identity = image.world.identity;
        frozen.properties = image.world.playableProperties;
        frozen.propertyCount = image.world.playablePropertyCount;
        frozen.occurrences = image.world.playableOccurrences;
        frozen.occurrenceCount = image.world.playableOccurrenceCount;
        frozen.trackSchedules = image.world.trackSchedules;
        frozen.trackScheduleCount = image.world.trackScheduleCount;
        frozen.pieceSchedules = image.world.pieceSchedules;
        frozen.pieceScheduleCount = image.world.pieceScheduleCount;
        frozen.maxKnownScheduleLeaves =
            image.world.capacity.maxKnownScheduleLeaves;
        frozen.maxTrackPieceScheduleDepth =
            image.world.capacity.maxTrackPieceScheduleDepth;
        frozen.containers = image.world.containers;
        frozen.containerCount = image.world.containerCount;
        PlayableStartRequest request{};
        request.root = image.rootRef;
        request.emitter = emitter;
        const PlayableStartResult started =
            StartPlayable(*engine, frozen, request);
        ASSERT_EQ(PlayableStartStatus::Accepted, started.status);
        produced = started.instance;
    } else {
        VnPostActionDesc post{};
        post.structSize = sizeof(post);
        post.actionId = harkentest::ObjectId(ContainerMatrixWorld::kAction);
        post.emitter = emitter;
        ASSERT_EQ(VN_OK, Vn_PostAction(&post, &firing));
        VnActionStepResult step{};
        step.structSize = sizeof(step);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &step));
        ASSERT_EQ(VN_ACTION_STEP_ACTIVE, step.state);
        produced = step.producedPlayableInstance;
    }
    ASSERT_NE(0u, produced);
    VnActionFiringHandle secondFiring = 0;
    PlayableInstanceHandle secondProduced = 0;
    if (authoredStopPressure) {
        ASSERT_TRUE(authoredStop);
        VnPostActionDesc post{};
        post.structSize = sizeof(post);
        post.actionId = harkentest::ObjectId(ContainerMatrixWorld::kAction);
        post.emitter = emitter;
        ASSERT_EQ(VN_OK, Vn_PostAction(&post, &secondFiring));
        VnActionStepResult result{};
        result.structSize = sizeof(result);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(secondFiring, 0, &result));
        ASSERT_EQ(VN_ACTION_STEP_ACTIVE, result.state);
        secondProduced = result.producedPlayableInstance;
        ASSERT_NE(0u, secondProduced);
        ASSERT_NE(produced, secondProduced);
    }

    auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [produced](const EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == produced;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    const PlayableExecutionAuthorityKind expectedAuthority =
        entry == ContainerMatrixEntry::Direct
            ? PlayableExecutionAuthorityKind::FrozenWorld
            : entry == ContainerMatrixEntry::CurrentWorldAction
                ? PlayableExecutionAuthorityKind::CurrentWorld
                : PlayableExecutionAuthorityKind::Pack;
    ASSERT_EQ(expectedAuthority, row->containerLoopAuthorityKind);
    ASSERT_EQ(multiLeaf ? leafCount : 0u, row->scheduleLeafCount);
    const PackPartitionLease lease = row->Invocation().packLease;
    if (entry == ContainerMatrixEntry::PackAction) {
        ASSERT_NE(0u, lease.leaseToken);
        EXPECT_TRUE(engine->packComposition.HasLiveLease(
            kPackStableId, lease.partitionRevision, lease.resourceRevision));
    }
    ContainerPlaybackRow initialPlayback{};
    ASSERT_TRUE(engine->containerPlayback.Capture(
        produced, &initialPlayback));
    ASSERT_EQ(loopCount, initialPlayback.loopLimit);
    ASSERT_EQ(0u, initialPlayback.completedSelections);
    const auto initialOwner = nestedLoopCount == 0
        ? produced : initialPlayback.activeChild;
    ContainerPlaybackRow initialOwnerPlayback{};
    ASSERT_TRUE(engine->containerPlayback.Capture(
        initialOwner, &initialOwnerPlayback));
    const PlayableInstanceHandle firstComposite =
        initialOwnerPlayback.activeChild;
    auto* initialResource = FrontierActiveResourceService(*engine, *row);
    ASSERT_NE(nullptr, initialResource);
    const PlayableInstanceHandle firstLeaf = initialResource->activeLeafInstance;
    ASSERT_NE(0u, firstComposite);
    ASSERT_NE(0u, firstLeaf);
    std::uint32_t initialLeafCount = 0;
    for (PlayableInstanceHandle child =
             engine->playableInstances.Classify(firstComposite).firstChild;
         child != 0;) {
        const auto childView = engine->playableInstances.Classify(child);
        ASSERT_TRUE(childView.live);
        EXPECT_EQ(PlayableKind::Sound, childView.kind);
        EXPECT_EQ(firstComposite, childView.parent);
        child = childView.nextSibling;
        ++initialLeafCount;
    }
    ASSERT_EQ(multiLeaf ? 2u : 0u, initialLeafCount);

    struct Run {
        PlayableInstanceHandle leaf = 0;
        PlayableInstanceHandle container = 0;
        std::uint32_t iteration = 0;
        std::uint32_t leafCount = 0;
        std::uint64_t baseline = 0;
        std::array<TimelineArmToken, 2> arms{};
        std::array<VnVoiceHandle, 2> renderHandles{};
        std::array<VoiceReleaseObserver, 2> releaseObservers{};
        std::uint64_t releaseSeenAt = 0;
        bool processingObserved = false;
        bool drainingObserved = false;
        bool successorTailOverlap = false;
        std::array<OccurrenceToken, 2> occurrences{};
        std::array<std::uint64_t, 2> onsets{};
        std::array<std::uint64_t, 2> completions{};
        std::array<ArmState, 2> lastStates{};
        std::array<std::uint64_t, 2> startFrames{};
        std::array<bool, 2> publishedProgramsVerified{};
        std::array<const TimelineProgramView*, 2> programs{};
        std::array<const TimelineEventPayload*, 2> payloads{};
    };
    std::vector<Run> runs;
    const auto captureRun = [&]() {
        auto* resource = FrontierActiveResourceService(*engine, *row);
        if (resource == nullptr || resource->phase == EnginePlayableStartPhase::Free ||
            std::any_of(runs.begin(), runs.end(), [&](const Run& run) {
                return run.leaf == resource->activeLeafInstance;
            })) return;
        const auto endpointBase = engine->playableStorage.EndpointBase(resource->partition.slot);
        const auto eventBase = engine->playableStorage.CurrentEventBase(resource->partition.slot);
        ASSERT_LT(runs.size(), loopCount * (nestedLoopCount == 0 ? 1u : nestedLoopCount));
        ContainerPlaybackRow rootPlayback{};
        ASSERT_TRUE(engine->containerPlayback.Capture(produced, &rootPlayback));
        const auto owner = nestedLoopCount == 0
            ? produced : rootPlayback.activeChild;
        ContainerPlaybackRow ownerPlayback{};
        ASSERT_TRUE(engine->containerPlayback.Capture(owner, &ownerPlayback));
        ASSERT_NE(0u, ownerPlayback.activeChild);
        const auto selected = engine->playableInstances.Classify(
            ownerPlayback.activeChild);
        ASSERT_TRUE(selected.live);
        EXPECT_EQ(owner, selected.parent);
        EXPECT_EQ(nestedLoopCount == 0 ? runs.size() : runs.size() % nestedLoopCount,
                  ownerPlayback.completedSelections);
        if (nestedLoopCount != 0) {
            EXPECT_EQ(produced, engine->playableInstances.Classify(owner).parent);
            EXPECT_EQ(runs.size() / nestedLoopCount,
                      rootPlayback.completedSelections);
        }
        Run run{};
        run.leaf = resource->activeLeafInstance;
        run.container = owner;
        run.iteration = static_cast<std::uint32_t>(runs.size());
        run.leafCount = selected.kind == PlayableKind::Sound ? 1u : 2u;
        const bool currentMultiLeaf = run.leafCount > 1u;
        if (!currentMultiLeaf) {
            EXPECT_EQ(0u, resource->voice.sourceStartFrame);
            EXPECT_EQ(harkentest::ObjectId(0u), resource->voice.target.clipId);
            EXPECT_EQ(0u, resource->voice.target.clipGuidHigh);
            EXPECT_EQ(0u, resource->voice.target.clipGuidLow);
            EXPECT_EQ(harkentest::ObjectId(0u), resource->voice.target.trackId);
        }
        run.baseline = engine->mixer.BlocksRendered();
        if (availableInstances != 0 && !runs.empty()) {
            const auto& previous = runs.back();
            for (std::uint32_t i = 0; i < previous.leafCount; ++i) {
                EXPECT_NE(0u, previous.completions[i]);
                EXPECT_EQ(nullptr, engine->voices.Resolve(previous.renderHandles[i]));
            }
            EXPECT_LE(engine->playableInstances.LiveCount() - playableBaseline,
                      availableInstances);
        }
        for (std::uint32_t i = 0; i < run.leafCount; ++i) {
            run.arms[i] = currentMultiLeaf
                ? engine->playableScheduleArms[resource->scheduleStorageBase + i]
                : resource->arm;
            run.renderHandles[i] = currentMultiLeaf
                ? engine->playableScheduleRenderHandles[resource->scheduleStorageBase + i]
                : resource->renderHandle;
            run.releaseObservers[i] = currentMultiLeaf
                ? engine->playableScheduleReleaseObservers[resource->scheduleStorageBase + i]
                : resource->releaseObserver;
            run.occurrences[i] = engine->playableScheduleOccurrences[endpointBase + i];
            run.startFrames[i] = currentMultiLeaf
                ? engine->playableScheduleStartFrames[resource->scheduleStorageBase + i]
                : resource->startFrame;
            EngineTimelineVoiceInstallIdentity identity{};
            ASSERT_TRUE(engine->CaptureTimelineVoiceInstallIdentity(run.renderHandles[i], &identity));
            auto identityOwner = run.leaf;
            while (identityOwner != 0 && identityOwner != identity.rootInstance)
                identityOwner = engine->playableInstances.Classify(identityOwner).parent;
            EXPECT_EQ(identity.rootInstance, identityOwner);
            harkentest::ExpectTimelineInstallIdentity(*engine, run.renderHandles[i],
                identityOwner, currentMultiLeaf
                    ? engine->playableScheduleVoices[resource->scheduleStorageBase + i].target
                    : resource->voice.target,
                run.startFrames[i], run.arms[i]);
            run.programs[i] = currentMultiLeaf
                ? &engine->playableScheduleRuntimePrograms[endpointBase + i] : &resource->runtimeProgram;
            run.payloads[i] = currentMultiLeaf
                ? &engine->playableSchedulePayloads[eventBase + i] : &resource->payload;
            EXPECT_EQ(run.releaseObservers[i].slot, identity.releaseObserver.slot);
            EXPECT_EQ(run.releaseObservers[i].targetSequence, identity.releaseObserver.targetSequence);
            if (currentMultiLeaf && resource->containerLoopOwnsScheduleResources) {
                const auto& schedule = engine->playableSchedules[endpointBase + i];
                const auto* occurrence = engine->timelineOccurrences.KeyOf(run.occurrences[i]);
                ASSERT_NE(nullptr, occurrence);
                const auto arranging = engine->playableInstances.Classify(
                    occurrence->arrangingInstance);
                ASSERT_TRUE(arranging.live);
                EXPECT_EQ(arranging.scheduleEpoch, schedule.ownerInstanceScheduleEpoch)
                    << "arranging=" << occurrence->arrangingInstance
                    << " scheduleOwner=" << schedule.ownerInstance;
                EXPECT_TRUE(engine->timelineOccurrences.ValidateTransaction(
                    run.occurrences[i], schedule.occurrence.occurrenceScheduleEpoch,
                    schedule.ownerInstanceScheduleEpoch, engine->playableInstances));
            }
            TimelineArmObservation observed{};
            ASSERT_TRUE(engine->timelineArms.Observe(run.arms[i], &observed));
            EXPECT_EQ(0u, observed.startedBlockSequence);
            EXPECT_EQ(0u, observed.logicalCompletionSequence);
        }
        runs.push_back(run);
    };
    const auto observePublishedPrograms = [&]() {
        for (auto& run : runs) {
            if (run.iteration == 0) continue;
            for (std::uint32_t i = 0; i < run.leafCount; ++i) {
                if (run.publishedProgramsVerified[i]) continue;
                const auto quantum = run.startFrames[i] / engine->timelinePool.QuantumFrames();
                std::array<ConsumedEvent, 8> events{};
                const auto count = engine->timelinePool.ConsumePageRt(
                    quantum, events.data(), events.size());
                for (std::size_t eventIndex = 0; eventIndex < count; ++eventIndex) {
                    const auto& event = events[eventIndex];
                    if (event.armToken.slot != run.arms[i].slot ||
                        event.armToken.generation != run.arms[i].generation ||
                        event.armToken.renderSlot != run.arms[i].renderSlot ||
                        event.armToken.renderGeneration != run.arms[i].renderGeneration) continue;
                    const auto* expectedProgram = run.programs[i];
                    const auto* expectedPayload = run.payloads[i];
                    ASSERT_EQ(expectedProgram, event.program.program);
                    EXPECT_EQ(expectedPayload, event.program.program->payloads);
                    EXPECT_EQ(event.program.programGeneration, event.program.program->generation);
                    EXPECT_TRUE(event.frozenTxnValid);
                    run.publishedProgramsVerified[i] = true;
                }
            }
        }
    };
    captureRun();
    ASSERT_FALSE(::testing::Test::HasFatalFailure());

    VnActionFiringInfo firingInfo{};
    firingInfo.structSize = sizeof(firingInfo);
    bool firingTerminal = firing == 0;
    bool secondIterationStarted = false;
    bool retirementChecked = false;
    bool tailOverlapObserved = false;
    bool stopped = false;
    VnActionFiringHandle stopFiring = 0;
    std::vector<VnVoiceHandle> authoredStoppedRenders;
    std::uint64_t authoredStopSequence = 0;
    bool authoredStopRenderChecked = false;
    bool authoredStopPressureChecked = false;
    PlayableControlReason lastReason = PlayableControlReason::None;
    for (std::uint32_t block = 0; block < 512; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        captureRun();
        ASSERT_FALSE(::testing::Test::HasFatalFailure());
        observePublishedPrograms();
        ASSERT_FALSE(::testing::Test::HasFatalFailure());
        engine->nullBackend.Pump(1);
        if (authoredStop && stopped && !authoredStopRenderChecked &&
            engine->mixer.BlocksRendered() > authoredStopSequence) {
            for (const auto render : authoredStoppedRenders) {
                EXPECT_EQ(nullptr, engine->voices.Resolve(render))
                    << "authored Stop left render " << render << " live after the next block";
            }
            EXPECT_EQ(voiceBaseline, engine->voices.ActiveCount());
            authoredStopRenderChecked = true;
        }
        for (auto& run : runs) {
            bool released = true;
            for (std::uint32_t i = 0; i < run.leafCount; ++i) {
                released = engine->voices.ReleaseObserved(run.releaseObservers[i]) && released;
            }
            if (released && run.releaseSeenAt == 0) {
                run.releaseSeenAt = engine->mixer.BlocksRendered();
            }
            if (run.releaseSeenAt == 0 ||
                engine->mixer.BlocksRendered() <= run.releaseSeenAt) {
                EXPECT_TRUE(engine->playableInstances.Classify(run.leaf).live);
            }
            for (std::uint32_t i = 0; i < run.leafCount; ++i) {
                TimelineArmObservation observed{};
                if (!engine->timelineArms.Observe(run.arms[i], &observed)) continue;
                run.lastStates[i] = observed.state;
                if (observed.startedBlockSequence != 0) {
                    EXPECT_GT(observed.startedBlockSequence, run.baseline);
                    run.onsets[i] = observed.startedBlockSequence;
                }
                if (observed.logicalCompletionSequence != 0) {
                    EXPECT_GT(observed.logicalCompletionSequence, run.baseline);
                    EXPECT_GE(observed.logicalCompletionSequence, run.onsets[i]);
                    run.completions[i] = observed.logicalCompletionSequence;
                }
                if (delayTail && i == 0 && run.onsets[i] != 0 &&
                    !run.processingObserved) {
                    SCOPED_TRACE(::testing::Message() << "case=" << caseIndex
                        << " iteration=" << run.iteration << " leaf=" << run.leaf);
                    const auto* render = engine->voices.Resolve(run.renderHandles[i]);
                    ASSERT_NE(nullptr, render);
                    EXPECT_EQ(1u, render->fxSlotCount);
                    EXPECT_NE(nullptr, render->fxSlots[0].process);
                    EXPECT_EQ(VN_EFFECT_FEEDBACK_DELAY, render->fxSlotEffectRef[0].type);
                    EXPECT_EQ(1u, render->voiceSendActiveCount);
                    EXPECT_TRUE(render->voiceSends[0].active);
                    EXPECT_EQ(image.delaySend.targetBusId,
                              engine->buses.IdAt(render->voiceSends[0].targetBusIndex));
                    EXPECT_EQ(engine->buses.GenerationAt(render->voiceSends[0].targetBusIndex),
                              render->voiceSends[0].targetBusGeneration);
                    EXPECT_NEAR(std::pow(10.0f, -6.0f / 20.0f),
                                render->voiceSends[0].gain.current, 1.0e-6f);
                    run.processingObserved = true;
                }
            }
        }
        if (delayTail) {
            for (std::size_t index = 0; index < runs.size(); ++index) {
                auto& run = runs[index];
                const auto* render = engine->voices.Resolve(run.renderHandles[0]);
                if (render == nullptr || render->phase != SourcePhase::Draining) continue;
                run.drainingObserved = true;
                EXPECT_TRUE(engine->playableInstances.Classify(run.leaf).live);
                if (index + 1u < runs.size() && runs[index + 1u].onsets[0] != 0) {
                    tailOverlapObserved = true;
                    run.successorTailOverlap = true;
                }
            }
        }
        if (stopRunCount != 0 && !stopped && tailOverlapObserved &&
            runs.size() == stopRunCount &&
            (stopBeforeOnset || runs.back().onsets[0] != 0)) {
            EXPECT_TRUE(engine->playableInstances.Classify(produced).live);
            EXPECT_TRUE(std::any_of(engine->ordinaryRetiringSources.begin(),
                engine->ordinaryRetiringSources.end(), [&](const auto& source) {
                    return source.committed && source.root == produced;
                }));
            if (authoredStop) {
                ASSERT_NE(nullptr, engine->voices.Resolve(runs.front().renderHandles[0]));
                EXPECT_EQ(SourcePhase::Draining,
                          engine->voices.Resolve(runs.front().renderHandles[0])->phase);
                for (const auto& run : runs) {
                    for (std::uint32_t leaf = 0; leaf < run.leafCount; ++leaf) {
                        const auto render = run.renderHandles[leaf];
                        if (engine->voices.Resolve(render) != nullptr) {
                            authoredStoppedRenders.push_back(render);
                        }
                    }
                }
                ASSERT_GE(authoredStoppedRenders.size(), 2u);
                VnPostActionDesc post{};
                post.structSize = sizeof(post);
                post.actionId = harkentest::ObjectId(kStopAction);
                post.emitter = emitter;
                if (authoredStopPressure) {
                    authoredStoppedRenders.clear();
                    engine->ledger.ForEachPlayableOwnedLive(
                        [&](VnVoiceHandle render, const VoiceLedger::PlayableParentRef& parent) {
                            if ((parent.internalToken == produced ||
                                 parent.internalToken == secondProduced) &&
                                engine->voices.Resolve(render) != nullptr) {
                                authoredStoppedRenders.push_back(render);
                            }
                        });
                    ASSERT_GE(authoredStoppedRenders.size(), 4u);
                    const std::array roots{produced, secondProduced};
                    std::array<PlayableInstanceView, 2> before{};
                    for (std::size_t index = 0; index < roots.size(); ++index) {
                        before[index] = engine->playableInstances.Classify(roots[index]);
                        EXPECT_FALSE(engine->playableInstances.HasCancellationClaim(roots[index]));
                    }
                    const auto remaining = static_cast<std::uint32_t>(authoredStoppedRenders.size() - 1u);
                    CommandRecord occupied{};
                    occupied.opcode = kOpcodeStop;
                    occupied.payload.stop.handle = 1;
                    while (engine->commands.FreeSlots() > remaining) {
                        ASSERT_TRUE(engine->commands.TryPush(occupied));
                    }
                    ASSERT_EQ(remaining, engine->commands.FreeSlots());
                    ASSERT_EQ(VN_BACKPRESSURE, Vn_PostAction(&post, &stopFiring));
                    EXPECT_EQ(0u, stopFiring);
                    EXPECT_EQ(remaining, engine->commands.FreeSlots());
                    for (std::size_t index = 0; index < roots.size(); ++index) {
                        const auto after = engine->playableInstances.Classify(roots[index]);
                        EXPECT_EQ(before[index].scheduleEpoch, after.scheduleEpoch);
                        EXPECT_EQ(before[index].lifecycle, after.lifecycle);
                        EXPECT_FALSE(engine->playableInstances.HasCancellationClaim(roots[index]));
                        PlayableRetirementObserver observer{};
                        EXPECT_FALSE(engine->playableInstances.CaptureRetirementObserver(
                            roots[index], &observer));
                    }
                    engine->nullBackend.Pump(1);
                    ASSERT_EQ(VN_OK, Vn_Update());
                    for (const auto handle : authoredStoppedRenders) {
                        const auto* render = engine->voices.Resolve(handle);
                        ASSERT_NE(nullptr, render);
                        EXPECT_FALSE(render->fading);
                    }
                    EXPECT_FALSE(engine->runtimeRecreateRequired);
                    authoredStopPressureChecked = true;
                }
                ASSERT_EQ(VN_OK, Vn_PostAction(&post, &stopFiring));
                VnActionStepResult result{};
                result.structSize = sizeof(result);
                ASSERT_EQ(VN_OK, Vn_QueryActionStep(stopFiring, 0, &result));
                ASSERT_EQ(VN_OK, result.result);
                ASSERT_EQ(VN_ACTION_STEP_ACTIVE, result.state);
                ASSERT_EQ(authoredStopPressure ? 2u : 1u, result.capturedPlayableCount);
                ASSERT_EQ(authoredStopPressure ? 2u : 1u, result.remainingPlayableCount);
                EXPECT_EQ(PlayableControlLifecycle::Cancelling, row->controlLifecycle);
                authoredStopSequence = engine->mixer.BlocksRendered();
            } else {
                ASSERT_EQ(PlayableControlStatus::Ok, StopPlayable(*engine, produced, 0));
            }
            std::vector<VnVoiceHandle> stopCommands;
            CommandRecord command{};
            for (std::uint32_t index = 0; engine->commands.PeekAt(index, command); ++index) {
                if (command.opcode != kOpcodeStop) continue;
                EXPECT_EQ(stopCommands.end(), std::find(stopCommands.begin(),
                    stopCommands.end(), command.payload.stop.handle));
                stopCommands.push_back(command.payload.stop.handle);
            }
            for (std::size_t index = 0; index + 1 < runs.size(); ++index) {
                for (std::uint32_t leaf = 0; leaf < runs[index].leafCount; ++leaf) {
                    const auto render = runs[index].renderHandles[leaf];
                    if (engine->voices.Resolve(render) == nullptr) continue;
                    EXPECT_NE(stopCommands.end(), std::find(stopCommands.begin(),
                        stopCommands.end(), render));
                }
                const auto old = engine->playableInstances.Classify(runs[index].leaf);
                if (old.live) EXPECT_EQ(PlayableTerminalKind::NaturalCompletion,
                                       old.terminalOutcome.kind);
            }
            stopped = true;
        }
        if (checkRetiring && !retirementChecked && runs.size() == 2u &&
            runs.back().completions[0] != 0 &&
            runs.back().completions[1] != 0) {
            const auto completedBlock = engine->mixer.BlocksRendered();
            const auto source = runs.back();
            ASSERT_EQ(1u, row->containerLoopIteration);
            ASSERT_TRUE(row->containerLoopOwnsScheduleResources);
            for (std::uint32_t i = 0; i < leafCount; ++i) {
                TimelineArmObservation observed{};
                ASSERT_TRUE(engine->timelineArms.Observe(source.arms[i], &observed));
                EXPECT_NE(0u, observed.logicalCompletionSequence);
                const auto* progress = engine->timelineOccurrences.CompletionProgressOf(
                    source.occurrences[i]);
                ASSERT_NE(nullptr, progress);
                CompletionProgressSnapshot snapshot{};
                ASSERT_TRUE(CaptureCompletionProgress(*progress, &snapshot));
                EXPECT_LE(snapshot.completedThroughBlockSequence, completedBlock);
            }
            SelectionMemoryKeyV1 key{};
            key.world = row->Invocation().worldGeneration;
            key.containerStableId = harkentest::ObjectId(ContainerMatrixWorld::kRoot);
            key.programSemanticFingerprint = image.containers[0].programSemanticFingerprint;
            key.memoryScope = outerScope;
            if (outerScope == MemoryScopeV1::Emitter) {
                key.emitterSlot = static_cast<std::uint32_t>(emitter);
                key.emitterGeneration = static_cast<std::uint32_t>(emitter >> 32);
            }
            const auto selectionBefore = engine->selectionMemory.Snapshot(key);
            ASSERT_TRUE(selectionBefore.found);
            ASSERT_EQ(VN_OK, Vn_Update());
            const auto selectionAccepted = engine->selectionMemory.Snapshot(key);
            ASSERT_EQ(selectionBefore.selectionOrdinal + 1u,
                      selectionAccepted.selectionOrdinal);
            std::uint64_t consumedOrdinal = 0;
            PlayableInstanceHandle acceptedChild = 0;
            for (unsigned repeated = 0; repeated < 3; ++repeated) {
                ASSERT_EQ(VN_OK, Vn_Update());
                EXPECT_EQ(completedBlock, engine->mixer.BlocksRendered());
                ContainerPlaybackRow waiting{};
                ASSERT_TRUE(engine->containerPlayback.Capture(produced, &waiting));
                EXPECT_EQ(2u, waiting.completedSelections);
                EXPECT_NE(0u, waiting.activeChild);
                EXPECT_EQ(ContainerPlaybackPhase::WaitingForChild, waiting.phase);
                EXPECT_EQ(2u, row->containerLoopIteration);
                EXPECT_TRUE(row->containerLoopOwnsScheduleResources);
                if (repeated == 0) {
                    consumedOrdinal = waiting.lastConsumedOutcomeOrdinal;
                    acceptedChild = waiting.activeChild;
                }
                EXPECT_NE(0u, consumedOrdinal);
                EXPECT_EQ(consumedOrdinal, waiting.lastConsumedOutcomeOrdinal);
                EXPECT_EQ(acceptedChild, waiting.activeChild);
                const auto selectionAfter = engine->selectionMemory.Snapshot(key);
                EXPECT_EQ(selectionAccepted.selectionOrdinal, selectionAfter.selectionOrdinal);
                EXPECT_EQ(selectionAccepted.sequenceCursor, selectionAfter.sequenceCursor);
                EXPECT_EQ(selectionAccepted.pendingCount, selectionAfter.pendingCount);
                bool fencePending = false;
                for (std::uint32_t i = 0; i < leafCount; ++i) {
                    TimelineArmObservation observed{};
                    (void)engine->timelineArms.Observe(source.arms[i], &observed);
                    EXPECT_NE(OccurrenceStage::Free,
                              engine->timelineOccurrences.StageOf(source.occurrences[i]));
                    fencePending = fencePending ||
                        !engine->timelineOccurrences.CompletionOwnerReleaseFencePassed(
                            source.occurrences[i], completedBlock);
                }
                EXPECT_TRUE(fencePending);
                EXPECT_EQ(compositeBaseline + 2u,
                          engine->compositeCompletionOwners.OccupiedCount());
            }
            engine->nullBackend.Pump(1);
            ASSERT_EQ(completedBlock + 1u, engine->mixer.BlocksRendered());
            ASSERT_EQ(VN_OK, Vn_Update());
            EXPECT_EQ(2u, row->containerLoopIteration);
            ContainerPlaybackRow successor{};
            ASSERT_TRUE(engine->containerPlayback.Capture(produced, &successor));
            EXPECT_EQ(2u, successor.completedSelections);
            EXPECT_NE(0u, successor.activeChild);
            EXPECT_EQ(consumedOrdinal, successor.lastConsumedOutcomeOrdinal);
            retirementChecked = true;
            captureRun();
            ASSERT_FALSE(::testing::Test::HasFatalFailure());
        }
        ASSERT_EQ(VN_OK, Vn_Update());
        captureRun();
        ASSERT_FALSE(::testing::Test::HasFatalFailure());
        observePublishedPrograms();
        ASSERT_FALSE(::testing::Test::HasFatalFailure());
        if (!secondIterationStarted && runs.size() == 2u) {
            secondIterationStarted = true;
            const auto* resource = FrontierActiveResourceService(*engine, *row);
            ASSERT_NE(nullptr, resource);
            EXPECT_EQ(expectedAuthority, resource->containerLoopAuthorityKind);
            const bool successorMultiLeaf = multiLeaf && !alternateSound;
            EXPECT_EQ(successorMultiLeaf ? leafCount : 0u, resource->scheduleLeafCount);
            EXPECT_EQ(successorMultiLeaf, resource->containerLoopOwnsScheduleResources);
            EXPECT_NE(firstLeaf, resource->activeLeafInstance);
            ContainerPlaybackRow secondPlayback{};
            ASSERT_TRUE(engine->containerPlayback.Capture(
                nestedLoopCount == 0 ? produced : initialOwner, &secondPlayback));
            EXPECT_EQ(1u, secondPlayback.completedSelections);
            ASSERT_NE(0u, secondPlayback.activeChild);
            EXPECT_NE(firstComposite, secondPlayback.activeChild);
            const PlayableKind expectedKind =
                childKind == ContainerMatrixChild::Sound || alternateSound ? PlayableKind::Sound
                : childKind == ContainerMatrixChild::Track
                    ? PlayableKind::Track
                    : PlayableKind::Piece;
            const auto compositeView = engine->playableInstances.Classify(
                secondPlayback.activeChild);
            ASSERT_TRUE(compositeView.live);
            EXPECT_EQ(expectedKind, compositeView.kind);
            std::uint32_t successorLeafCount = 0;
            for (PlayableInstanceHandle child = compositeView.firstChild;
                 child != 0;) {
                const auto childView =
                    engine->playableInstances.Classify(child);
                ASSERT_TRUE(childView.live);
                EXPECT_EQ(PlayableKind::Sound, childView.kind);
                EXPECT_EQ(secondPlayback.activeChild, childView.parent);
                child = childView.nextSibling;
                ++successorLeafCount;
            }
            EXPECT_EQ(successorMultiLeaf ? 2u : 0u, successorLeafCount);
            const std::uint32_t playingRootCount = authoredStopPressure ? 2u : 1u;
            EXPECT_EQ(compositeBaseline + (successorMultiLeaf ? playingRootCount : 0u),
                      engine->compositeCompletionOwners.OccupiedCount());
            if (entry == ContainerMatrixEntry::PackAction) {
                EXPECT_TRUE(engine->packComposition.HasLiveLease(
                    kPackStableId, lease.partitionRevision,
                    lease.resourceRevision));
            }
        }
        if (firing != 0) {
            ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &firingInfo));
            firingTerminal =
                firingInfo.state == VN_ACTION_FIRING_TERMINAL_RETAINED;
        }
        PlayableControlState control{};
        if (QueryPlayable(*engine, produced, &control) == PlayableControlStatus::Ok) {
            lastReason = control.reason;
        }
        if (!engine->playableInstances.Classify(produced).live &&
            engine->playableInstances.LiveCount() == playableBaseline &&
            engine->containerPlayback.LiveCount() == containerBaseline &&
            engine->playablePartitions.OccupiedCount() == partitionBaseline &&
            std::all_of(engine->playableServices.begin(), engine->playableServices.end(),
                [](const auto& service) { return service.phase == EnginePlayableStartPhase::Free; }) &&
            engine->voices.ActiveCount() == voiceBaseline &&
            engine->ledger.AvailableEntryCount() == ledgerBaseline &&
            engine->timelineArms.LiveCount() == armBaseline &&
            engine->timelineOccurrences.OccupiedCount() ==
                occurrenceBaseline &&
            engine->compositeCompletionOwners.OccupiedCount() ==
                compositeBaseline &&
            engine->timelinePool.LiveTransactionCount() ==
                transactionBaseline &&
            firingTerminal) {
            break;
        }
    }

    EXPECT_EQ(loopCount * (nestedLoopCount == 0 ? 1u : nestedLoopCount) > 1u,
              secondIterationStarted);
    EXPECT_EQ(checkRetiring, retirementChecked);
    EXPECT_EQ(delayTail && loopCount * (nestedLoopCount == 0 ? 1u : nestedLoopCount) > 1u,
              tailOverlapObserved);
    EXPECT_EQ(stopRunCount != 0, stopped);
    EXPECT_EQ(authoredStop, authoredStopRenderChecked);
    EXPECT_EQ(authoredStopPressure, authoredStopPressureChecked);
    EXPECT_EQ(stopRunCount != 0 ? stopRunCount :
              loopCount * (nestedLoopCount == 0 ? 1u : nestedLoopCount), runs.size());
    for (const auto& run : runs) {
        if (delayTail) {
            SCOPED_TRACE(::testing::Message() << "case=" << caseIndex
                << " iteration=" << run.iteration << " leaf=" << run.leaf);
            EXPECT_TRUE(run.processingObserved);
            if (!stopped || &run != &runs.back()) {
                EXPECT_TRUE(run.drainingObserved);
            }
            if (&run != &runs.back()) EXPECT_TRUE(run.successorTailOverlap);
        }
        for (std::uint32_t i = 0; i < run.leafCount; ++i) {
            SCOPED_TRACE(::testing::Message() << "iteration=" << run.iteration
                << " arm=" << run.arms[i].slot << ':' << run.arms[i].generation
                << " last_state=" << static_cast<unsigned>(run.lastStates[i])
                << " reason=" << static_cast<unsigned>(lastReason));
            EXPECT_GT(run.onsets[i], run.baseline);
            if (!stopped || &run != &runs.back()) {
                EXPECT_GE(run.completions[i], run.onsets[i]);
            }
            if (run.iteration != 0) {
                EXPECT_TRUE(run.publishedProgramsVerified[i]);
            }
        }
        if (unequalLengths && run.leafCount > 1u) {
            EXPECT_LT(run.completions[0], run.completions[1]);
        }
        EXPECT_FALSE(engine->playableInstances.Classify(run.leaf).live);
        EXPECT_FALSE(engine->playableInstances.Classify(run.container).live);
    }
    if (nestedLoopCount == 2 && runs.size() == 4u) {
        EXPECT_EQ(runs[0].container, runs[1].container);
        EXPECT_EQ(runs[2].container, runs[3].container);
        EXPECT_NE(runs[0].container, runs[2].container);
    }
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    EXPECT_FALSE(engine->playableInstances.Classify(produced).live);
    EXPECT_EQ(playableBaseline, engine->playableInstances.LiveCount());
    EXPECT_EQ(containerBaseline, engine->containerPlayback.LiveCount());
    EXPECT_EQ(partitionBaseline, engine->playablePartitions.OccupiedCount());
    EXPECT_TRUE(std::all_of(engine->playableServices.begin(), engine->playableServices.end(),
        [](const auto& service) { return service.phase == EnginePlayableStartPhase::Free; }));
    EXPECT_EQ(voiceBaseline, engine->voices.ActiveCount());
    EXPECT_EQ(delayBaseline, engine->effectBank.DelayInUse());
    EXPECT_EQ(ledgerBaseline, engine->ledger.AvailableEntryCount());
    EXPECT_EQ(armBaseline, engine->timelineArms.LiveCount());
    EXPECT_EQ(occurrenceBaseline,
              engine->timelineOccurrences.OccupiedCount());
    EXPECT_EQ(compositeBaseline,
              engine->compositeCompletionOwners.OccupiedCount());
    EXPECT_EQ(transactionBaseline,
              engine->timelinePool.LiveTransactionCount());
    EXPECT_TRUE(std::none_of(engine->ordinaryRetiringSources.begin(),
        engine->ordinaryRetiringSources.end(), [](const auto& source) {
            return source.root != 0;
        }));
    EXPECT_TRUE(std::none_of(engine->ordinaryRetiringLeaves.begin(),
        engine->ordinaryRetiringLeaves.end(), [](const auto& leaf) {
            return leaf.occupied;
        }));
    EXPECT_EQ(executorBaseline.staleSkippedTransactions,
              engine->timelineExecutor.Stats().staleSkippedTransactions);
    EXPECT_EQ(executorBaseline.armFailedTransactions,
              engine->timelineExecutor.Stats().armFailedTransactions);
    EXPECT_EQ(executorBaseline.protocolViolation,
              engine->timelineExecutor.Stats().protocolViolation);
    if (firing != 0) {
        ASSERT_TRUE(firingTerminal);
        EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, firingInfo.outcome);
        EXPECT_EQ(VN_ACTION_TERMINAL_NATURAL, firingInfo.terminalReason);
        ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    }
    if (stopFiring != 0) {
        VnActionFiringInfo info{};
        info.structSize = sizeof(info);
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(stopFiring, &info));
        EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
        EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
        ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(stopFiring));
    }
    if (secondFiring != 0) {
        VnActionFiringInfo info{};
        info.structSize = sizeof(info);
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(secondFiring, &info));
        EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
        EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
        EXPECT_FALSE(engine->playableInstances.Classify(secondProduced).live);
        ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(secondFiring));
    }
    if (entry == ContainerMatrixEntry::PackAction) {
        EXPECT_FALSE(engine->packComposition.HasLiveLease(
            kPackStableId, lease.partitionRevision, lease.resourceRevision));
        ASSERT_EQ(VN_OK,
                  Vn_UnloadPackEx(pack, VN_PACK_UNLOAD_REFUSE_IF_USED));
    }
    for (const auto occupant : capacityOccupants) {
        EXPECT_TRUE(engine->playableInstances.AdvanceLifecycle(
            occupant, PlayableLifecycle::Retired));
    }
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
}

