void RunContainerMatrixEntry(ContainerModeV1 mode, ContainerMatrixChild childKind,
                      ContainerMatrixEntry entry, std::uint32_t caseIndex,
                      ContainerMatrixTrace* out,
                      SelectionInputTrace* selectionTrace = nullptr) {
    ASSERT_NE(nullptr, out);
    *out = {};
    (void)Vn_Term();
    harkentest::PlayableCapacityScope limits(6, 2);
    const std::vector<float> firstSamples(2048, 0.25f);
    const std::vector<float> secondSamples(3072, -0.25f);
    const float* firstChannels[1] = {firstSamples.data()};
    const float* secondChannels[1] = {secondSamples.data()};
    std::uint64_t firstRevision = 0;
    std::uint64_t secondRevision = 0;
    ASSERT_TRUE(ComputeMediaPcmContentRevisionV1(
        48000, 1, firstSamples.size(), firstChannels, 1, &firstRevision));
    ASSERT_TRUE(ComputeMediaPcmContentRevisionV1(
        48000, 1, secondSamples.size(), secondChannels, 1, &secondRevision));
    ContainerMatrixWorld image(mode, childKind, firstRevision, secondRevision, true);
    ASSERT_NE(0u, image.world.identity.runtimeSemanticFingerprint);
    ASSERT_EQ(image.world.identity.runtimeSemanticFingerprint,
              ComputeCurrentWorldFingerprintV4(image.world));
    EngineSession session(MakeNullConfig(16, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    Engine* engine = session.Engine();
    VnPackHandle pack = 0;
    if (entry == ContainerMatrixEntry::PackAction) {
        constexpr std::uint64_t kPackStableId = 22;
        ImageBuilder builder(kPackKindCanonicalContent);
        const std::uint64_t ownedDefinitionCount =
            image.world.playablePropertyCount + image.world.actionCount +
            image.world.variableCount;
        const auto partition = WrapWorldPartition(
            kPackStableId, 1, image.world, ownedDefinitionCount);
        builder.AddEntry(kPackEntryKindPackRequirementBlock, kPackStableId,
                         RequirementPayload(kPackStableId, 1, 1));
        builder.AddEntry(kPackEntryKindCanonicalDefinitionPartition,
                         kPackStableId, partition);
        builder.AddMedia(ContainerMatrixWorld::kFirstSound, firstSamples);
        builder.AddMedia(ContainerMatrixWorld::kSecondSound, secondSamples);
        const auto packBytes = builder.Build();
        const std::string stem = "u4-matrix-" + std::to_string(caseIndex);
        const std::string packLocator = stem + "-a.pack";
        const auto initBytes = BuildSingleIdentityInit(
            Fnv1a64(packBytes.data(), packBytes.size()),
            ContainerMatrixWorld::kAction, packLocator.c_str(),
            ContainerMatrixWorld::kRoot);
        const std::string initPath =
            WriteTemp(stem + "-init.pack", initBytes);
        const std::string packPath = WriteTemp(packLocator, packBytes);
        VnCanonicalPackSetMemberV1 members[2]{};
        VnCanonicalPackSetMemberResultV1 rows[2]{};
        const char* paths[] = {initPath.c_str(), packPath.c_str()};
        for (std::size_t i = 0; i < 2; ++i) {
            members[i].structSize = sizeof(members[i]);
            members[i].packStableId = i == 0 ? 11 : kPackStableId;
            members[i].packKind = i == 0 ? VN_CANONICAL_PACK_SET_MEMBER_INIT
                                        : VN_CANONICAL_PACK_SET_MEMBER_CONTENT;
            members[i].utf8Path = paths[i];
            rows[i].structSize = sizeof(rows[i]);
        }
        VnCanonicalPackSetActivationReportV1 activated{};
        ASSERT_EQ(VN_OK, harkentest::ActivateCanonicalMembersV1(
                              members, 2, rows, activated));
        pack = rows[1].handle;
        ASSERT_NE(0u, pack);
    } else {
        const VnPCMDesc firstPcm = harkentest::MonoDesc(firstSamples, 48000);
        const VnPCMDesc secondPcm = harkentest::MonoDesc(secondSamples, 48000);
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(ContainerMatrixWorld::kFirstSound, &firstPcm));
        ASSERT_EQ(VN_OK,
                  Vn_RegisterPCM(ContainerMatrixWorld::kSecondSound, &secondPcm));
        ASSERT_EQ(WorldInstallStatus::Ok,
                  InstallContainerWorldV1(*engine, image.world).status);
    }
    const auto playableBaseline = engine->playableInstances.LiveCount();
    const auto containerBaseline = engine->containerPlayback.LiveCount();
    const auto queueBaseline = engine->queueInstances.LiveCount();
    const auto variableControlBaseline =
        engine->variableControlInstances.LiveCount();
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    if (selectionTrace != nullptr) selectionTrace->Attach(*engine);
    const auto start = [&](PlayableInstanceHandle* outProduced,
                           VnActionFiringHandle* outFiring) {
        *outProduced = 0;
        *outFiring = 0;
        if (entry == ContainerMatrixEntry::Direct) {
            static constexpr char domain[] = "HARKEN-ACTION-PLAY-OCCURRENCE-V1";
            MediaContentRevisionHasherV1 hash(domain, sizeof(domain));
            hash.AddU64(0);
            hash.AddObjectId(image.action.actionStableId);
            hash.AddU64(image.action.programSemanticFingerprint);
            hash.AddU32(0);
            SplitMix64 callerStream(hash.Finish());
            PlayableStartRequest request{};
            request.root = image.rootRef;
            request.emitter = emitter;
            request.callerSeed = callerStream.Next();
            const auto started = StartPlayable(*engine, request);
            ASSERT_EQ(PlayableStartStatus::Accepted, started.status);
            *outProduced = started.instance;
            return;
        }
        VnPostActionDesc post{};
        post.structSize = sizeof(post);
        post.actionId = harkentest::ObjectId(ContainerMatrixWorld::kAction);
        post.emitter = emitter;
        ASSERT_EQ(VN_OK, Vn_PostAction(&post, outFiring));
        VnActionStepResult step{};
        step.structSize = sizeof(step);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(*outFiring, 0, &step));
        ASSERT_EQ(VN_ACTION_STEP_ACTIVE, step.state);
        *outProduced = step.producedPlayableInstance;
    };
    VnActionFiringHandle firing = 0;
    PlayableInstanceHandle produced = 0;
    ASSERT_NO_FATAL_FAILURE(start(&produced, &firing));
    ASSERT_NE(0u, produced);
    FrontierTrace actual;
    const auto expected = childKind == ContainerMatrixChild::Track || childKind == ContainerMatrixChild::Piece ? 2u : 1u;
    bool stopped = false;
    for (std::uint32_t block = 0; block < 128; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        actual.Capture(*engine);
        if (mode == ContainerModeV1::VariableControl && !stopped && actual.heard.size() == expected &&
            std::all_of(actual.heard.begin(), actual.heard.end(), [](const auto& heard) {
                return heard.complete >= heard.start;
            })) {
            EXPECT_TRUE(engine->playableInstances.Classify(produced).live);
            if (entry == ContainerMatrixEntry::Direct)
                ASSERT_EQ(PlayableControlStatus::Ok, StopPlayable(*engine, produced, 0));
            else ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
            stopped = true;
        }
        if (!engine->playableInstances.Classify(produced).live && engine->timelineArms.LiveCount() == 0 &&
            engine->playablePartitions.OccupiedCount() == 0) break;
    }
    ASSERT_EQ(expected, actual.heard.size());
    for (std::uint32_t index = 0; index < actual.heard.size(); ++index) {
        const auto& heard = actual.heard[index];
        EXPECT_EQ(index == 0 ? ContainerMatrixWorld::kFirstSound : ContainerMatrixWorld::kSecondSound, heard.subject);
        EXPECT_EQ(heard.expectedStart, heard.start);
        EXPECT_GE(heard.complete, heard.start);
        heard.ExpectNaturalSourceReleased();
        EXPECT_NE(0u, heard.leaf);
        EXPECT_NE(0u, heard.leafEpoch);
        EXPECT_NE(0u, heard.parent);
        EXPECT_NE(0u, heard.parentEpoch);
        EXPECT_EQ(produced, heard.root);
    }
    if (expected == 2u) EXPECT_NE(actual.heard[0].leaf, actual.heard[1].leaf);
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_EQ(0u, engine->containerPlayback.LiveCount());
    EXPECT_EQ(0u, engine->playablePartitions.OccupiedCount());
    EXPECT_EQ(0u, engine->timelineArms.LiveCount());
    EXPECT_EQ(0u, engine->queueInstances.LiveCount());
    EXPECT_EQ(0u, engine->variableControlInstances.LiveCount());
    EXPECT_EQ(0u, engine->decisions.LiveCount());
    EXPECT_EQ(0u, engine->armGroups.LiveCount());
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    if (selectionTrace != nullptr) {
        selectionTrace->actual = actual;
        engine->selectionInputHookForTest = nullptr;
        engine->selectionInputContextForTest = nullptr;
        engine->queueInputHookForTest = nullptr;
    }
    if (firing != 0) ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    ASSERT_NO_FATAL_FAILURE(start(&produced, &firing));
    ASSERT_NE(0u, produced);
    auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [produced](const EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == produced ||
                   candidate.Invocation().variableControlOuterRootInstance == produced;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    PlayableInstanceHandle current = produced;
    PlayableInstanceHandle expectedParent = 0;
    out->parentRelationsValid = true;
    out->epochsValid = true;
    while (current != 0 && out->depth < out->kinds.size()) {
        const auto view = engine->playableInstances.Classify(current);
        ASSERT_TRUE(view.live);
        out->kinds[out->depth++] = view.kind;
        out->parentRelationsValid =
            view.parent == expectedParent && out->parentRelationsValid;
        out->epochsValid = view.scheduleEpoch != 0 && out->epochsValid;
        expectedParent = current;
        current = view.firstChild;
    }
    ASSERT_EQ(0u, current);
    ASSERT_GE(out->depth, 2u);
    const bool queueMode = mode == ContainerModeV1::RandomQueue ||
                           mode == ContainerModeV1::SequenceQueue;
    out->selected[0] = mode == ContainerModeV1::VariableControl
        ? row->variableControlDiscreteCurrentChildOrdinal
        : queueMode ? row->selectedChildOrdinals[0]
                    : image.children[0].stableChildOrdinal;
    out->selectedCount = 1;
    if (childKind == ContainerMatrixChild::Container) {
        out->selected[out->selectedCount++] =
            image.children[2].stableChildOrdinal;
    } else if (childKind == ContainerMatrixChild::Track ||
               childKind == ContainerMatrixChild::Piece) {
        out->selected[out->selectedCount++] =
            image.placements[0].stableOccurrenceOrdinal;
    }
    const ProgramView* observedSchedule = &row->schedule;
    if (observedSchedule->events == nullptr ||
        observedSchedule->eventCount == 0) {
        ASSERT_NE(0u, row->scheduleLeafCount);
        observedSchedule = mode == ContainerModeV1::VariableControl
            ? &engine->variableControlSchedules[row->scheduleStorageBase]
            : &engine->playableSchedules[row->scheduleStorageBase];
    }
    ASSERT_NE(nullptr, observedSchedule->events);
    ASSERT_NE(0u, observedSchedule->eventCount);
    out->onsetCount = 1;
    out->onsets[0] = observedSchedule->events[0].frameOffsetFromEntry;
    if (entry == ContainerMatrixEntry::Direct) {
        ASSERT_EQ(PlayableControlStatus::Ok,
                  StopPlayable(*engine, produced, 0));
    } else {
        ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
    }
    VnActionFiringInfo firingInfo{};
    firingInfo.structSize = sizeof(firingInfo);
    bool firingTerminal = firing == 0;
    for (std::uint32_t block = 0; block < 128; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        if (firing != 0) {
            ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &firingInfo));
            firingTerminal =
                firingInfo.state == VN_ACTION_FIRING_TERMINAL_RETAINED;
        }
        if (!engine->playableInstances.Classify(produced).live &&
            engine->containerPlayback.LiveCount() == containerBaseline &&
            engine->queueInstances.LiveCount() == queueBaseline &&
            engine->playablePartitions.OccupiedCount() == 0 &&
            engine->variableControlInstances.LiveCount() ==
                variableControlBaseline && firingTerminal) {
            break;
        }
    }
    out->reclaimed =
        !engine->playableInstances.Classify(produced).live &&
        engine->playableInstances.LiveCount() == playableBaseline &&
        engine->containerPlayback.LiveCount() == containerBaseline &&
        engine->playablePartitions.OccupiedCount() == 0 &&
        engine->queueInstances.LiveCount() == queueBaseline &&
        engine->variableControlInstances.LiveCount() == variableControlBaseline;
    if (firing != 0) {
        ASSERT_TRUE(firingTerminal);
        ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    }
    if (pack != 0) {
        ASSERT_EQ(VN_OK,
                  Vn_UnloadPackEx(pack, VN_PACK_UNLOAD_REFUSE_IF_USED));
    }
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
}

constexpr std::array<ContainerModeV1, 5> kMatrixModes{
    ContainerModeV1::Random, ContainerModeV1::Sequence, ContainerModeV1::RandomQueue,
    ContainerModeV1::SequenceQueue, ContainerModeV1::VariableControl};
constexpr std::array<ContainerMatrixEntry, 3> kMatrixEntries{
    ContainerMatrixEntry::Direct, ContainerMatrixEntry::CurrentWorldAction, ContainerMatrixEntry::PackAction};

TEST(SelectionInputTraceTest, KeepsDistinctQueueStateAndOrdinaryVisits) {
    QueueSequenceBranchesWorldImage fixture({1, 2, 3, 4}, 1,
        ContainerModeV1::VariableControl, ContainerModeV1::SequenceQueue);
    const auto& program = fixture.containers[0];
    SelectionInputTrace trace;
    harken::RandomQueueSeedContext seed{};
    harken::EffectiveQueueState state{};
    state.version = 1;
    state.currentChildOrdinal = program.children[0].stableChildOrdinal;
    state.selectionOrdinal = 1;
    SelectionInputTrace::CaptureQueue(program, seed, state, &trace);
    SelectionInputTrace::CaptureQueue(program, seed, state, &trace);
    EXPECT_EQ(1u, trace.SemanticInputs().size());
    seed.callerSeed = 2;
    SelectionInputTrace::CaptureQueue(program, seed, state, &trace);
    ++state.version;
    SelectionInputTrace::CaptureQueue(program, seed, state, &trace);
    state.cursor = 1;
    state.currentChildOrdinal = program.children[1].stableChildOrdinal;
    SelectionInputTrace::CaptureQueue(program, seed, state, &trace);
    ++state.selectionOrdinal;
    SelectionInputTrace::CaptureQueue(program, seed, state, &trace);
    ++state.cycleOrdinal;
    SelectionInputTrace::CaptureQueue(program, seed, state, &trace);
    EXPECT_EQ(6u, trace.SemanticInputs().size());
    auto ordinary = trace.selections.front();
    ordinary.queue = false;
    trace.selections.push_back(ordinary);
    trace.selections.push_back(ordinary);
    EXPECT_EQ(8u, trace.SemanticInputs().size());
    EXPECT_EQ(9u, trace.selections.size());
}

class NestedFrontierMatrix : public ::testing::TestWithParam<std::uint32_t> {};
TEST_P(NestedFrontierMatrix, CompletePlayback) {
    const auto cell = GetParam();
    const auto outer = kMatrixModes[cell / 5u];
    const auto inner = kMatrixModes[cell % 5u];
    const bool compareEntries = cell == 0;
    std::array<SelectionInputTrace, 3> traces;
    for (std::size_t index = 0; index < (compareEntries ? kMatrixEntries.size() : 1u); ++index) {
        const auto entry = kMatrixEntries[index];
        SCOPED_TRACE(::testing::Message() << "cell=" << cell * 3u + index
            << " outer=" << static_cast<unsigned>(outer)
            << " inner=" << static_cast<unsigned>(inner) << " entry=" << static_cast<unsigned>(entry));
        ExpectQueueSequenceBranchesAcrossEntry(entry, 1, false, false, outer, inner, 0, false,
            ContainerModeV1::SequenceQueue, false, false, false, false, false, true, false, &traces[index]);
        traces[0].ExpectNestedFixture(outer, inner, traces[index].actual);
        if (index != 0) traces[index].ExpectSameInputsAndPlayback(traces[0]);
    }
}
INSTANTIATE_TEST_SUITE_P(AllNestedFrontierCases, NestedFrontierMatrix, ::testing::Range(0u, 25u));

