TEST(PackComposition, RootRandomQueueEntriesHonorTheirSelectionContexts) {
    const auto packBytes = BuildImmediateRandomQueuePlayPack(
        22, 1, 7, harkentest::ObjectId(2002), harkentest::ObjectId(4510), harkentest::ObjectId(4511), harkentest::ObjectId(4512),
        harkentest::MakeDC(2048, 0.25f), harkentest::MakeDC(2048, -0.25f));
    std::uint64_t packSeed = 0;
    std::uint64_t repeatedPackSeed = 0;
    const auto pack = RunRootQueuePackTrace(packBytes, ContainerMatrixEntry::PackAction, &packSeed);
    const auto repeatedPack = RunRootQueuePackTrace(packBytes, ContainerMatrixEntry::PackAction, &repeatedPackSeed);
    ASSERT_TRUE(pack.valid);
    const auto direct = RunRootQueuePackTrace(packBytes, ContainerMatrixEntry::Direct);
    const auto action = RunRootQueuePackTrace(packBytes, ContainerMatrixEntry::CurrentWorldAction);
    ASSERT_TRUE(repeatedPack.valid);
    ASSERT_NE(0u, packSeed);
    EXPECT_EQ(packSeed, repeatedPackSeed);
    EXPECT_EQ(pack.selectedOrdinals, repeatedPack.selectedOrdinals);
    EXPECT_EQ(pack.successorOrdinal, repeatedPack.successorOrdinal);
    EXPECT_EQ(pack.parentEpoch, repeatedPack.parentEpoch);
    EXPECT_EQ(pack.parentLinked, repeatedPack.parentLinked);
    EXPECT_EQ(pack.reclaimed, repeatedPack.reclaimed);
    EXPECT_EQ(pack.leafReclaimed, repeatedPack.leafReclaimed);
    EXPECT_EQ(pack.successorObserved, repeatedPack.successorObserved);
    EXPECT_TRUE(pack.successorObserved);
    EXPECT_EQ(pack.selectedOrdinals[1], pack.successorOrdinal);
    EXPECT_EQ(repeatedPack.selectedOrdinals[1], repeatedPack.successorOrdinal);
    EXPECT_NE(pack.selectedOrdinals[0], pack.successorOrdinal);
    ASSERT_TRUE(direct.valid);
    ASSERT_TRUE(action.valid);
    EXPECT_EQ(direct.selectedOrdinals, action.selectedOrdinals);
    EXPECT_EQ(direct.successorOrdinal, action.successorOrdinal);
    EXPECT_EQ(direct.selectedOrdinals, pack.selectedOrdinals);
    EXPECT_EQ(direct.successorOrdinal, pack.successorOrdinal);
    EXPECT_EQ(direct.selectedOrdinals[1], direct.successorOrdinal);
    EXPECT_EQ(action.selectedOrdinals[1], action.successorOrdinal);
    EXPECT_TRUE(pack.parentLinked);
    EXPECT_TRUE(pack.successorObserved);
    EXPECT_TRUE(pack.reclaimed);
    EXPECT_TRUE(pack.leafReclaimed);
}

TEST(PackComposition, RandomQueueBodyIdentityPreservesInitialAndSuccessorSelection) {
    const auto packBytes = BuildImmediateRandomQueuePlayPack(
        22, 1, 7, harkentest::ObjectId(2002), harkentest::ObjectId(4510), harkentest::ObjectId(4511), harkentest::ObjectId(4512),
        harkentest::MakeDC(2048, 0.25f), harkentest::MakeDC(2048, -0.25f));
    PackCanonicalImage pack;
    ASSERT_EQ(VN_OK, ParsePackCanonicalImage(packBytes.data(), packBytes.size(),
                                             &pack));
    CurrentWorldBodyImage packBody;
    ASSERT_TRUE(packBody.Decode(pack.partitionBody.data(),
                                 pack.partitionBody.size(),
                                 pack.partitionHeader.bodyVintage,
                                 CurrentWorldDecodeMode::StrictArtifact));
    ASSERT_NE(nullptr, packBody.ProductionView());
    std::vector<std::uint8_t> artifact;
    ASSERT_TRUE(EncodeCurrentWorldArtifactV1(*packBody.ProductionView(), artifact));
    EXPECT_EQ(pack.partitionBody,
              std::vector<std::uint8_t>(
                  artifact.begin() + kCurrentWorldArtifactHeaderBytes,
                  artifact.end()));
    CurrentWorldArtifactHeaderV1 header{};
    ASSERT_EQ(CurrentWorldLoadStatusV1::Ok,
              InspectCurrentWorldArtifactHeaderV1(
                  artifact.data(), artifact.size(), artifact.size(), header));
    CurrentWorldBodyImage directBody;
    ASSERT_EQ(CurrentWorldLoadStatusV1::Ok,
              DecodeCurrentWorldArtifactBodyV1(
                  header, artifact.data() + kCurrentWorldArtifactHeaderBytes,
                  artifact.size() - kCurrentWorldArtifactHeaderBytes, directBody));
    ASSERT_NE(nullptr, directBody.ProductionView());
    ASSERT_EQ(1u, directBody.ProductionView()->containerCount);
    ASSERT_EQ(1u, packBody.ProductionView()->containerCount);
    EXPECT_EQ(packBody.ProductionView()->identity.runtimeSemanticFingerprint,
              directBody.ProductionView()->identity.runtimeSemanticFingerprint);

    RandomQueueSeedContext seed{};
    seed.worldSemanticFingerprint =
        directBody.ProductionView()->identity.runtimeSemanticFingerprint;
    seed.rootStableId = harkentest::ObjectId(4510);
    seed.acceptedPostOrdinal = 1;
    seed.emitterSlot = 0;
    seed.emitterGeneration = 1;
    seed.resetEpoch = 1;
    std::array<std::array<std::uint32_t, 2>, 2> selections{};
    const ContainerWorldInstallViewV1* worlds[] = {
        directBody.ProductionView(), packBody.ProductionView()};
    for (std::size_t i = 0; i < 2; ++i) {
        const auto& program = worlds[i]->containers[0];
        EffectiveQueueState initial{};
        initial.version = 1;
        initial.selectionOrdinal = 1;
        std::array<SelectionChildV1, 2> children{};
        std::array<std::uint32_t, 2> remaining{};
        std::array<std::uint32_t, 2> permutation{};
        ASSERT_EQ(SelectionStatusV1::Ok,
                  BuildRandomQueuePermutationV1(
                      program, seed, initial, children.data(), remaining.data(),
                      permutation.data(), permutation.size()));
        initial.currentChildOrdinal = permutation[0];
        EffectiveQueueState next{};
        ASSERT_EQ(QueueSequenceStepStatus::Successor,
                  ResolveRandomQueueStep(
                      program, seed, initial, children.data(), remaining.data(),
                      permutation.data(), permutation.size(), &next));
        selections[i] = {initial.currentChildOrdinal, next.currentChildOrdinal};
        EXPECT_NE(selections[i][0], selections[i][1]);
    }
    EXPECT_EQ(selections[0], selections[1]);
}

TEST(PackComposition, FrozenSelectionIdentityTracksCanonicalUnionNotPublicationHistory) {
    const std::array<PlayablePropertyProgramViewV1, 2> properties{
        MakeSoundProperty(harkentest::ObjectId(8201), 0), MakeSoundProperty(harkentest::ObjectId(8202), 1)};
    const auto firstBytes = BuildCanonicalPartitionPack(
        22, 1, 7, SharedSoundPartitionPayload(22, 7, properties[0]));
    const auto secondBytes = BuildCanonicalPartitionPack(
        33, 1, 9, SharedSoundPartitionPayload(33, 9, properties[1]));
    PackCanonicalImage firstImage;
    PackCanonicalImage secondImage;
    ASSERT_EQ(VN_OK, ParsePackCanonicalImage(firstBytes.data(), firstBytes.size(),
                                            &firstImage));
    ASSERT_EQ(VN_OK, ParsePackCanonicalImage(secondBytes.data(), secondBytes.size(),
                                            &secondImage));
    PackComposition composition(4, 4, 2);
    PackComposition::CandidateOwner first;
    PackComposition::CandidateOwner second;
    ASSERT_EQ(VN_OK, composition.PrepareCandidate(firstImage, 1ull << 32, &first));
    ASSERT_EQ(VN_OK, composition.PrepareCandidate(secondImage, 2ull << 32, &second));
    ContainerWorldInstallViewV1 whole{};
    whole.playableProperties = properties.data();
    whole.playablePropertyCount = properties.size();
    FinishPlayableWorld(&whole);
    ASSERT_EQ(WorldInstallStatus::Ok, ValidateCurrentWorldV1(whole));
    auto single = whole;
    single.playablePropertyCount = 1;
    FinishPlayableWorld(&single);
    const auto firstFingerprint = single.identity.runtimeSemanticFingerprint;
    std::vector<PackComposition::CandidateOwner> initial;
    initial.push_back(std::move(first));
    ASSERT_EQ(VN_OK, composition.Commit(std::move(initial), nullptr, 0, 8, 0));
    const auto original = composition.PublishedHandle();
    const auto oldLookup = composition.Lookup(harkentest::ObjectId(8201));
    ASSERT_EQ(VN_OK, oldLookup.result);
    PackPlaybackView oldView;
    ASSERT_TRUE(composition.PlaybackViewAtLease(oldLookup.lease, &oldView));
    EXPECT_EQ(firstFingerprint, oldView.WorldSemanticFingerprint());
    EXPECT_EQ(0u, PackPlaybackView{}.WorldSemanticFingerprint());

    std::vector<PackComposition::CandidateOwner> unionOwners;
    unionOwners.push_back(PackComposition::Keep(original->owners[0]));
    unionOwners.push_back(std::move(second));
    ASSERT_EQ(VN_OK, composition.Commit(std::move(unionOwners), nullptr, 0, 8, 0));
    const auto unionPublished = composition.PublishedHandle();
    const auto unionLookup = composition.Lookup(harkentest::ObjectId(8201));
    ASSERT_EQ(VN_OK, unionLookup.result);
    PackPlaybackView unionView;
    ASSERT_TRUE(composition.PlaybackViewAtLease(unionLookup.lease, &unionView));
    EXPECT_NE(oldView.CompositeGeneration(), unionView.CompositeGeneration());
    EXPECT_EQ(firstFingerprint, oldView.WorldSemanticFingerprint());
    EXPECT_EQ(whole.identity.runtimeSemanticFingerprint,
              unionView.WorldSemanticFingerprint());
    EXPECT_NE(firstFingerprint, unionView.WorldSemanticFingerprint());
    EXPECT_EQ(1u, unionView.OwnerCount());
    EXPECT_EQ(nullptr, unionView.ResolveProperty(
        playableproperties::ContentPropertyKindV1::Sound, harkentest::ObjectId(8202)));

    PackComposition::PreparedCommit invalid;
    std::vector<PackComposition::CandidateOwner> duplicate;
    duplicate.push_back(PackComposition::Keep(unionPublished->owners[0]));
    auto altered = properties[0];
    altered.payload.presentMask |= UINT64_C(1);
    altered.payload.values[0].bits = std::bit_cast<std::uint32_t>(-3.0f);
    altered.programSemanticFingerprint = ComputePlayablePropertyFingerprintV1(altered);
    const auto conflictingBytes = BuildCanonicalPartitionPack(
        44, 1, 11, SharedSoundPartitionPayload(44, 11, altered));
    PackCanonicalImage conflictingImage;
    ASSERT_EQ(VN_OK, ParsePackCanonicalImage(
        conflictingBytes.data(), conflictingBytes.size(), &conflictingImage));
    PackComposition::CandidateOwner conflicting;
    ASSERT_EQ(VN_OK, composition.PrepareCandidate(
        conflictingImage, 3ull << 32, &conflicting));
    duplicate.push_back(std::move(conflicting));
    EXPECT_EQ(VN_BAD_PACK, composition.PrepareCommit(
        std::move(duplicate), nullptr, 0, 8, 0, &invalid));
    EXPECT_EQ(unionPublished, composition.PublishedHandle());
    EXPECT_EQ(whole.identity.runtimeSemanticFingerprint,
              unionView.WorldSemanticFingerprint());

    composition.RestorePublished(original);
    const auto restoredLookup = composition.Lookup(harkentest::ObjectId(8201));
    ASSERT_EQ(VN_OK, restoredLookup.result);
    PackPlaybackView restoredView;
    ASSERT_TRUE(composition.PlaybackViewAtLease(restoredLookup.lease, &restoredView));
    EXPECT_EQ(firstFingerprint, restoredView.WorldSemanticFingerprint());
    EXPECT_EQ(whole.identity.runtimeSemanticFingerprint,
              unionView.WorldSemanticFingerprint());
    composition.RestorePublished(unionPublished);
    std::vector<PackComposition::CandidateOwner> sameOwners;
    for (const auto& owner : unionPublished->owners)
        sameOwners.push_back(PackComposition::Keep(owner));
    std::reverse(sameOwners.begin(), sameOwners.end());
    ASSERT_EQ(VN_OK, composition.Commit(std::move(sameOwners), nullptr, 0, 8, 0));
    const auto repeatedLookup = composition.Lookup(harkentest::ObjectId(8201));
    ASSERT_EQ(VN_OK, repeatedLookup.result);
    PackPlaybackView repeatedView;
    ASSERT_TRUE(composition.PlaybackViewAtLease(repeatedLookup.lease, &repeatedView));
    EXPECT_NE(unionView.CompositeGeneration(), repeatedView.CompositeGeneration());
    EXPECT_EQ(unionView.WorldSemanticFingerprint(), repeatedView.WorldSemanticFingerprint());
    EXPECT_EQ(VN_OK, composition.ReleaseLease(oldLookup.lease));
    EXPECT_EQ(VN_OK, composition.ReleaseLease(unionLookup.lease));
    EXPECT_EQ(VN_OK, composition.ReleaseLease(restoredLookup.lease));
    EXPECT_EQ(VN_OK, composition.ReleaseLease(repeatedLookup.lease));
    EXPECT_FALSE(composition.HasLiveLease(22, 7, 1));
}

std::vector<std::uint8_t> Kind26OverlayPayload(
    VnObjectId variableId, std::uint8_t writers, std::uint64_t fingerprint) {
    std::vector<std::uint8_t> payload(16 + 32 + 4, 0);
    StoreLE32(payload.data(), 1);
    StoreObjectId(payload.data() + 16, variableId);
    payload[32] = writers;
    StoreLE64(payload.data() + 40, fingerprint);
    return payload;
}

std::vector<std::uint8_t> Kind26EmptyOverlayPayload() {
    return std::vector<std::uint8_t>(16, 0);
}

std::vector<std::uint8_t> BuildInitWithVariableOverlay(
    VnObjectId variableId, std::uint64_t fingerprint,
    float rangeMin = -1.0f, float rangeMax = 1.0f,
    float defaultValue = 0.0f, bool emitOverlay = true,
    bool emptyOverlay = false, std::uint8_t writers = 1,
    VariableScopeV1 scope = VariableScopeV1::Global,
    const PackVariableNameCatalog* names = nullptr) {
    VariableDefinitionV1 variable = harkentest::MakeVariableDefinition(
        variableId, VariableKindV1::Smooth, rangeMin, rangeMax, defaultValue);
    ContainerWorldInstallViewV1 world{};
    world.variables = &variable;
    world.variableCount = 1;
    if (names) world.identity.projectId = ObjectIdFromBytes(names->projectGuid);
    world.identity.capabilityMask = kWorldCapabilityVariableDefinitions;
    world.identity.runtimeSemanticFingerprint =
        ComputeCurrentWorldFingerprintV4(world);
    ImageBuilder builder(kPackKindInit);
    const auto revision = names ? names->initContentRevision : 1;
    builder.AddEntry(kPackEntryKindPackRequirementBlock, 11,
                     RequirementPayload(11, revision, 1));
    builder.AddEntry(kPackEntryKindCanonicalDefinitionPartition, 11,
                     WrapWorldPartition(11, 1, world, 1));
    if (names) {
        std::vector<std::uint8_t> payload;
        EXPECT_TRUE(EncodeVariableNameCatalog(*names, &payload));
        builder.AddEntry(kPackEntryKindVariableNameCatalog, 0, std::move(payload));
    }
    harkentest::packfoundation::AppendNeutralMasterSnapshotV1(&builder);
    if (emitOverlay) {
        builder.AddEntry(kPackEntryKindVariablePolicyOverlay, 0,
                         emptyOverlay
                             ? Kind26EmptyOverlayPayload()
                             : Kind26OverlayPayload(variableId, writers,
                                                    fingerprint));
    }
    return builder.Build();
}

std::vector<std::uint8_t> Kind26OverlayTwo(
    std::uint64_t idA, std::uint8_t writersA, std::uint64_t fingerprintA,
    std::uint64_t idB, std::uint8_t writersB, std::uint64_t fingerprintB) {
    std::vector<std::uint8_t> payload(16 + 64 + 8, 0);
    StoreLE32(payload.data(), 2);
    StoreObjectId(payload.data() + 16, harkentest::ObjectId(idA));
    payload[32] = writersA;
    StoreLE64(payload.data() + 40, fingerprintA);
    StoreObjectId(payload.data() + 48, harkentest::ObjectId(idB));
    payload[64] = writersB;
    StoreLE64(payload.data() + 72, fingerprintB);
    return payload;
}

std::vector<std::uint8_t> BuildInitWithTwoVariables(
    VariableScopeV1 scope, std::uint8_t writersA, std::uint64_t fingerprintA,
    std::uint8_t writersB, std::uint64_t fingerprintB) {
    VariableDefinitionV1 variables[2] = {
        harkentest::MakeVariableDefinition(harkentest::ObjectId(7), VariableKindV1::Smooth, -1.0f,
                                          1.0f, 0.0f),
        harkentest::MakeVariableDefinition(harkentest::ObjectId(8), VariableKindV1::Smooth, -1.0f,
                                          1.0f, 0.0f),
    };
    ContainerWorldInstallViewV1 world{};
    world.variables = variables;
    world.variableCount = 2;
    world.identity.capabilityMask = kWorldCapabilityVariableDefinitions;
    world.identity.runtimeSemanticFingerprint =
        ComputeCurrentWorldFingerprintV4(world);
    ImageBuilder builder(kPackKindInit);
    builder.AddEntry(kPackEntryKindPackRequirementBlock, 11,
                     RequirementPayload(11, 1, 1));
    builder.AddEntry(kPackEntryKindCanonicalDefinitionPartition, 11,
                     WrapWorldPartition(11, 1, world, 2));
    harkentest::packfoundation::AppendNeutralMasterSnapshotV1(&builder);
    builder.AddEntry(kPackEntryKindVariablePolicyOverlay, 0,
                     Kind26OverlayTwo(7, writersA, fingerprintA, 8, writersB,
                                      fingerprintB));
    return builder.Build();
}

bool LoadInitPack(const std::vector<std::uint8_t>& bytes, const char* name,
                  VnPackHandle* handle) {
    const auto path = WriteTemp(name, bytes);
    *handle = 0;
    harken::PackCanonicalImage image;
    if (ParsePackCanonicalImage(bytes.data(), bytes.size(), &image) != VN_OK ||
        image.packKind != kPackKindInit) {
        return false;
    }
    return harkentest::ActivateExistingInitPackV1(path.c_str(), image.packStableId,
                                                 handle) == VN_OK;
}

TEST(PackComposition, VariableSdkSetValuePreservesWriteScopeAndPublishesInitFixture) {
    EngineSession session(MakeNullConfig());
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    const auto variable = harken::generated::kVariable_VehicleRPM;
    std::uint64_t fingerprint = 0;
    ASSERT_TRUE(ComputeVariableExecutionFingerprintV1(variable, 1, 1, 3,
        0, 1, 0, nullptr, 0, &fingerprint));
    PackVariableNameCatalog names;
    names.projectGuid[15] = 1;
    names.initPackStableId = 11;
    names.initContentRevision = 1;
    names.rows.push_back({variable, "VehicleRPM"});
    const auto bytes = BuildInitWithVariableOverlay(variable, fingerprint,
        0, 1, 0, true, false, 3, VariableScopeV1::Global, &names);
    VnPackHandle init = 0;
    ASSERT_TRUE(LoadInitPack(bytes, "variable-sdk-init.pack", &init));
    ASSERT_EQ(VN_OK, harken::GuardTypedVariableCatalog(
        harken::generated::kVariableExecutionCatalogFingerprint));
    VnEmitterHandle a = 0, b = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&a));
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&b));
    const auto expect = [&](float valueA, float valueB, std::uint32_t localA) {
        for (const auto emitter : {a, b}) {
            VnVariableQueryDescV1 query{};
            query.structSize = sizeof(query);
            query.variableId = variable;
            query.emitter = emitter;
            VnVariableQueryResultV1 result{};
            result.structSize = sizeof(result);
            ASSERT_EQ(VN_OK, Vn_QueryVariable(&query, &result));
            EXPECT_FLOAT_EQ(emitter == a ? valueA : valueB, result.currentValue);
            EXPECT_EQ(emitter == a ? localA : 0u, result.hasEmitterOverride);
            EXPECT_EQ(0u, result.pendingCount);
        }
    };
    ASSERT_EQ(VN_OK, Vn_SetValue(variable, 0.25f));
    harkentest::AdvanceVariableWrite(&engine);
    expect(0.25f, 0.25f, 0);
    ASSERT_EQ(VN_OK, Vn_SetEmitterValue(a, variable, 0.5f));
    harkentest::AdvanceVariableWrite(&engine);
    expect(0.5f, 0.25f, 1);
    ASSERT_EQ(VN_OK, Vn_SetValue(variable, 0.75f));
    harkentest::AdvanceVariableWrite(&engine);
    expect(0.75f, 0.75f, 0);
}

TEST(PackComposition, VariableNameCodecRejectsCorruptionAndAmbiguousIdentity) {
    PackVariableNameCatalog names;
    names.projectGuid[15] = 1;
    names.initPackStableId = 11;
    names.initContentRevision = 1;
    names.rows.push_back({harkentest::ObjectId(7), "Speed"});
    std::vector<std::uint8_t> payload;
    ASSERT_TRUE(EncodeVariableNameCatalog(names, &payload));
    PackVariableNameCatalog decoded;
    ASSERT_TRUE(DecodeVariableNameCatalog(payload.data(), payload.size(), &decoded));
    for (const auto offset : {0u, 8u, 24u, 32u, 44u, 48u, 56u, 64u, 80u, 86u, 88u, 96u, 103u}) {
        auto corrupt = payload;
        corrupt[offset] ^= 1;
        EXPECT_FALSE(DecodeVariableNameCatalog(corrupt.data(), corrupt.size(), &decoded)) << offset;
    }
    EXPECT_FALSE(DecodeVariableNameCatalog(payload.data(), payload.size() - 1, &decoded));
    names.rows.push_back({harkentest::ObjectId(8), "Speed"});
    EXPECT_FALSE(EncodeVariableNameCatalog(names, &payload));
    names.rows.back().name = "Velocity";
    names.rows.back().variableId = names.rows.front().variableId;
    EXPECT_FALSE(EncodeVariableNameCatalog(names, &payload));
    names.rows.back().variableId = harkentest::ObjectId(8);
    EXPECT_TRUE(EncodeVariableNameCatalog(names, &payload));
    names.rows.back().name = "Bad Name";
    EXPECT_FALSE(EncodeVariableNameCatalog(names, &payload));
}

