VnResult LoadAuthoredStopNestedVariableControlPackForTest(
    const harken::ContainerWorldInstallViewV1& world,
    VnObjectId soundId, const std::vector<float>& samples) {
    constexpr std::uint64_t kPackStableId = 22;
    constexpr const char* kLocator = "u6-stop-nested-vc.pack";
    ImageBuilder builder(kPackKindCanonicalContent);
    builder.AddEntry(kPackEntryKindPackRequirementBlock, kPackStableId,
                     RequirementPayload(kPackStableId, 1, 1));
    builder.AddEntry(kPackEntryKindCanonicalDefinitionPartition, kPackStableId,
                     WrapWorldPartition(
                         kPackStableId, 1, world,
                         world.variableCount + world.playablePropertyCount +
                             world.actionCount));
    builder.AddMedia(soundId, samples);
    const auto bytes = builder.Build();
    PackInitCatalogRow initOwned{};
    initOwned.stableId = harkentest::ObjectId(1);
    initOwned.identityClass = kInitCatalogIdentityClassAction;
    initOwned.ownerPackStableId = 11;
    FillLocator(&initOwned, "Init.pack");
    PackInitCatalogRow content{};
    content.ownerPackStableId = kPackStableId;
    content.expectedContentHash = Fnv1a64(bytes.data(), bytes.size());
    FillLocator(&content, kLocator);
    std::vector<PackInitCatalogRow> catalog{initOwned};
    content.identityClass = kInitCatalogIdentityClassAction;
    content.stableId = world.actions[0].actionStableId;
    catalog.push_back(content);
    content.stableId = world.actions[1].actionStableId;
    catalog.push_back(content);
    content.identityClass = kInitCatalogIdentityClassPlayable;
    content.stableId = world.actions[0].steps[0].target.stableId;
    catalog.push_back(content);
    const auto initBytes = BuildInitCatalog(catalog, {kPackStableId}, world.capacity);
    const auto initPath = WriteTemp("u6-stop-nested-vc-init.pack", initBytes);
    const auto contentPath = WriteTemp(kLocator, bytes);
    VnCanonicalPackSetMemberV1 members[2]{};
    VnCanonicalPackSetMemberResultV1 rows[2]{};
    const char* paths[] = {initPath.c_str(), contentPath.c_str()};
    for (std::size_t i = 0; i < 2; ++i) {
        members[i].structSize = sizeof(members[i]);
        members[i].packStableId = i == 0 ? 11 : kPackStableId;
        members[i].packKind = i == 0 ? VN_CANONICAL_PACK_SET_MEMBER_INIT
                                    : VN_CANONICAL_PACK_SET_MEMBER_CONTENT;
        members[i].utf8Path = paths[i];
        rows[i].structSize = sizeof(rows[i]);
    }
    VnCanonicalPackSetActivationReportV1 activated{};
    const VnResult result = harkentest::ActivateCanonicalMembersV1(
        members, 2, rows, activated);
    EXPECT_EQ(VN_OK, result) << "nested VC canonical pack set";
    if (result == VN_OK) {
        EXPECT_NE(0u, rows[1].handle);
    }
    return result;
}


TEST_F(NativeSlicePack, OriginalPackEpisodeSameFactoryMoveRejectsRawAndForeignReleaseThenReissuesSameRow) {
    static_assert(!std::is_copy_constructible_v<Engine::OriginalPackIdentityLease>);
    static_assert(!std::is_copy_constructible_v<PackComposition::OriginalLeaseEpisode>);
    ASSERT_NO_FATAL_FAILURE(Load(BuildContentPack(22, 1, 7, harkentest::ObjectId(2002))));
    auto& engine = *session.Engine();
    Engine::OriginalPackIdentityLease original;
    PackIdentityLookup acquired;
    ASSERT_EQ(VN_OK, engine.AcquirePackIdentityLease(harkentest::ObjectId(2002),
        PackLeaseSlice::SharedActionAndDeferred, &acquired, &original));
    ASSERT_TRUE(original.Valid());
    EXPECT_EQ(PackComposition::OriginalLeasePhase::Live, original.Phase());
    const auto row = original.OriginalRowIndex();
    const auto full = original.OriginalLease();
    EXPECT_EQ(acquired.lease.leaseToken, full.leaseToken);
    EXPECT_EQ(acquired.lease.compositeGeneration, full.compositeGeneration);
    ASSERT_EQ(VN_OK, engine.packs.ValidateResourceClosure(full.resourceClosureToken));
    EXPECT_EQ(VN_IN_USE, engine.ReleasePackIdentityLease(full));
    EXPECT_EQ(VN_IN_USE, engine.packComposition.ReleaseLease(full));
    EXPECT_EQ(VN_IN_USE, engine.packComposition.RetagLiveLease(full, PackLeaseSlice::Playable));
    EXPECT_EQ(VN_OK, engine.packs.ValidateResourceClosure(full.resourceClosureToken));
    PackIdentityLookup occupied;
    EXPECT_EQ(VN_IN_USE, engine.AcquirePackIdentityLease(harkentest::ObjectId(2002),
        PackLeaseSlice::SharedActionAndDeferred, &occupied, &original));
    EXPECT_EQ(full.leaseToken, original.OriginalLease().leaseToken);
    auto foreign = std::make_unique<Engine>(engine.config);
    EXPECT_EQ(VN_STALE_HANDLE, foreign->ReleaseOriginalPackIdentityLease(original));
    EXPECT_TRUE(original.Valid());
    Engine::OriginalPackIdentityLease moved(std::move(original));
    EXPECT_FALSE(original.Valid()); ASSERT_TRUE(moved.Valid());
    EXPECT_EQ(row, moved.OriginalRowIndex());
    ASSERT_EQ(VN_OK, engine.RetagOriginalPackIdentityLease(moved, PackLeaseSlice::Playable));
    EXPECT_EQ(full.leaseToken, moved.OriginalLease().leaseToken);
    EXPECT_EQ(full.resourceClosureToken, moved.OriginalLease().resourceClosureToken);
    ASSERT_EQ(VN_OK, engine.ReleaseOriginalPackIdentityLease(moved));
    EXPECT_FALSE(moved.Valid()); EXPECT_EQ(PackComposition::OriginalLeasePhase::Released, moved.Phase());
    EXPECT_EQ(VN_STALE_HANDLE, engine.packComposition.ValidateLease(full));
    EXPECT_EQ(VN_STALE_HANDLE, engine.packs.ValidateResourceClosure(full.resourceClosureToken));
    EXPECT_EQ(VN_STALE_HANDLE, engine.ReleaseOriginalPackIdentityLease(moved));
    Engine::OriginalPackIdentityLease next;
    ASSERT_EQ(VN_OK, engine.AcquirePackIdentityLease(harkentest::ObjectId(2002),
        PackLeaseSlice::Playable, &acquired, &next));
    EXPECT_EQ(row, next.OriginalRowIndex());
    EXPECT_NE(full.leaseToken, next.OriginalLease().leaseToken);
    EXPECT_EQ(VN_STALE_HANDLE, engine.ReleasePackIdentityLease(full));
    ASSERT_EQ(VN_OK, engine.ReleaseOriginalPackIdentityLease(next));
    EXPECT_FALSE(engine.runtimeRecreateRequired);
}

TEST_F(NativeSlicePack, OriginalPackEpisodePreparedAbortHasRealOwnerAndRawAbandonCannotClearIt) {
    ASSERT_NO_FATAL_FAILURE(Load(BuildContentPack(22, 1, 7, harkentest::ObjectId(2002))));
    auto& engine = *session.Engine();
    PackComposition::OriginalLeaseEpisode original;
    PackIdentityLookup prepared;
    ASSERT_EQ(VN_OK, engine.packComposition.PrepareLookup(harkentest::ObjectId(2002),
        PackLeaseSlice::Playable, &prepared, &original));
    ASSERT_TRUE(original.Valid());
    EXPECT_EQ(PackComposition::OriginalLeasePhase::Preparing, original.Phase());
    const auto full = original.OriginalLease();
    engine.packComposition.AbandonPreparedLease(full);
    EXPECT_TRUE(original.Valid()); EXPECT_TRUE(engine.packComposition.HasOriginalLeaseEpisode(full));
    EXPECT_EQ(VN_IN_USE, engine.packComposition.CommitPreparedLease(&prepared.lease, 0));
    ASSERT_EQ(VN_OK, engine.packComposition.AbortOriginalPreparedLease(original));
    EXPECT_FALSE(original.Valid()); EXPECT_EQ(PackComposition::OriginalLeasePhase::Released, original.Phase());
    EXPECT_FALSE(engine.packComposition.HasOriginalLeaseEpisode(full));
    EXPECT_EQ(VN_STALE_HANDLE, engine.packComposition.AbortOriginalPreparedLease(original));
    PackIdentityLookup legacy;
    ASSERT_EQ(VN_OK, engine.AcquirePackIdentityLease(harkentest::ObjectId(2002),
        PackLeaseSlice::Playable, &legacy));
    EXPECT_FALSE(engine.packComposition.HasOriginalLeaseEpisode(legacy.lease));
    ASSERT_EQ(VN_OK, engine.ReleasePackIdentityLease(legacy.lease));
    EXPECT_FALSE(engine.runtimeRecreateRequired);
}

TEST_F(NativeSlicePack, OriginalPackEpisodeResourceFailureKeepsDefinitionExitAndIndexUntilJoinedTerm) {
    ASSERT_NO_FATAL_FAILURE(Load(BuildContentPack(22, 1, 7, harkentest::ObjectId(2002))));
    auto& engine = *session.Engine();
    Engine::OriginalPackIdentityLease original;
    PackIdentityLookup acquired;
    ASSERT_EQ(VN_OK, engine.AcquirePackIdentityLease(harkentest::ObjectId(2002),
        PackLeaseSlice::Playable, &acquired, &original));
    const auto full = original.OriginalLease(); const auto row = original.OriginalRowIndex();
    // A genuine earlier receiver release makes the later original release refuse.
    ASSERT_EQ(VN_OK, engine.packs.ReleaseResourceClosure(full.resourceClosureToken));
    EXPECT_EQ(VN_RUNTIME_RECREATE_REQUIRED, engine.ReleaseOriginalPackIdentityLease(original));
    ASSERT_TRUE(original.Valid()); EXPECT_EQ(PackComposition::OriginalLeasePhase::Faulted, original.Phase());
    EXPECT_EQ(VN_STALE_HANDLE, engine.packComposition.ValidateLease(full));
    EXPECT_TRUE(engine.packComposition.HasOriginalLeaseEpisode(full));
    EXPECT_EQ(row, original.OriginalRowIndex());
    EXPECT_EQ(VN_RUNTIME_RECREATE_REQUIRED, engine.ReleaseOriginalPackIdentityLease(original));
    EXPECT_TRUE(original.Valid()); EXPECT_TRUE(engine.runtimeRecreateRequired);
    Engine::OriginalPackIdentityLease next;
    ASSERT_EQ(VN_OK, engine.AcquirePackIdentityLease(harkentest::ObjectId(2002),
        PackLeaseSlice::Playable, &acquired, &next));
    EXPECT_NE(row, next.OriginalRowIndex());
    ASSERT_EQ(VN_OK, engine.ReleaseOriginalPackIdentityLease(next));
    ASSERT_EQ(VN_OK, Vn_Term());
    EXPECT_FALSE(original.Valid());
    EXPECT_EQ(PackComposition::OriginalLeasePhase::QuiescedDisposed, original.Phase());
}

