#if defined(HARKEN_TEST_TIMELINE_CAPACITY_OVERRIDE)
TEST_F(NativeSlicePack, OriginalPackEpisodeRealAcquiredResourcePrefixReturnsAfterPreparedCommitRefusal) {
    ASSERT_NO_FATAL_FAILURE(Load(BuildContentPack(22, 1, 7, harkentest::ObjectId(2002))));
    auto& engine = *session.Engine();
    struct Prefix { PackPartitionLease prepared{}; PackResourceClosureToken resource = 0; unsigned calls = 0; } prefix;
    engine.originalPackResourceAcquiredContextForTest = &prefix;
    engine.originalPackResourceAcquiredHookForTest = [](Engine& actual, const PackPartitionLease& prepared,
        PackResourceClosureToken resource, void* context) {
        auto& observed = *static_cast<Prefix*>(context);
        observed.prepared = prepared; observed.resource = resource; ++observed.calls;
        EXPECT_NE(0u, prepared.leaseToken);
        EXPECT_EQ(VN_OK, actual.packs.ValidateResourceClosure(resource));
        EXPECT_TRUE(actual.packComposition.HasOriginalLeaseEpisode(prepared));
        actual.packComposition.refuseOriginalLeaseCommitOnceForTest = true;
    };
    Engine::OriginalPackIdentityLease refused;
    PackIdentityLookup acquired;
    EXPECT_EQ(VN_BACKPRESSURE, engine.AcquirePackIdentityLease(harkentest::ObjectId(2002),
        PackLeaseSlice::Playable, &acquired, &refused));
    engine.originalPackResourceAcquiredHookForTest = nullptr;
    engine.originalPackResourceAcquiredContextForTest = nullptr;
    ASSERT_EQ(1u, prefix.calls); EXPECT_FALSE(refused.Valid());
    EXPECT_FALSE(engine.packComposition.refuseOriginalLeaseCommitOnceForTest);
    EXPECT_EQ(VN_STALE_HANDLE, engine.packs.ValidateResourceClosure(prefix.resource));
    EXPECT_FALSE(engine.packComposition.HasOriginalLeaseEpisode(prefix.prepared));
    EXPECT_FALSE(engine.runtimeRecreateRequired);
    Engine::OriginalPackIdentityLease next;
    ASSERT_EQ(VN_OK, engine.AcquirePackIdentityLease(harkentest::ObjectId(2002),
        PackLeaseSlice::Playable, &acquired, &next));
    EXPECT_NE(prefix.prepared.leaseToken, next.OriginalLease().leaseToken);
    ASSERT_EQ(VN_OK, engine.ReleaseOriginalPackIdentityLease(next));
}
#endif

class QueueBusQualification : public ::testing::TestWithParam<unsigned> {};

TEST_P(QueueBusQualification, ReplacementPreservesPlaybackAndReclaimsForReplay) {
    const bool random = GetParam() == 1;
    const bool nested = GetParam() == 2;
    constexpr auto busId = VN_OBJECT_ID(0, 2);
    constexpr auto actionId = harkentest::ObjectId(2002);
    constexpr auto rootId = harkentest::ObjectId(4510);
    constexpr auto firstId = harkentest::ObjectId(4511);
    constexpr auto secondId = harkentest::ObjectId(4512);
    const std::vector<float> first(8192, 0.125f);
    const std::vector<float> second(8192, -0.25f);
    const auto content = random
        ? BuildImmediateRandomQueuePlayPack(22, 1, 7, actionId, rootId,
              firstId, secondId, first, second, busId)
        : nested
            ? BuildImmediateNestedQueueContainerPlayPack(22, 1, 7, actionId,
                  rootId, harkentest::ObjectId(4513), firstId, secondId,
                  first, second, 1, MemoryScopeV1::Emitter, busId)
            : BuildImmediateSequenceQueuePlayPack(22, 1, 7, actionId, rootId,
                  firstId, secondId, first, second, 1, MemoryScopeV1::Emitter,
                  0, busId);
    const auto makeInit = [&](float sendDb, VnBusId target = VN_BUS_MASTER) {
        const auto bus = harkentest::packfoundation::MasterSendRuntimeBusFixtureV1(
            sendDb, 1, target);
        return BuildSingleIdentityInit(Fnv1a64(content.data(), content.size()),
            actionId, "ActionA.pack", rootId, VnObjectId{}, {}, 0, &bus);
    };
    const auto initialPath = WriteTemp("queue-bus-initial.pack", makeInit(-6.0f));
    const auto replacementPath = WriteTemp("queue-bus-replacement.pack", makeInit(-12.0f));
    const auto invalidPath = WriteTemp("queue-bus-invalid.pack", makeInit(-12.0f, busId));
    const auto contentPath = WriteTemp("queue-bus-content.pack", content);
    EngineSession session(MakeNullConfig(8, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    VnCanonicalPackSetMemberV1 members[2]{};
    VnCanonicalPackSetMemberResultV1 membersOut[2]{};
    for (unsigned i = 0; i < 2; ++i) {
        members[i].structSize = sizeof(members[i]);
        members[i].packStableId = i == 0 ? 11 : 22;
        members[i].packKind = i == 0 ? VN_CANONICAL_PACK_SET_MEMBER_INIT
                                   : VN_CANONICAL_PACK_SET_MEMBER_CONTENT;
        members[i].utf8Path = i == 0 ? initialPath.c_str() : contentPath.c_str();
        membersOut[i].structSize = sizeof(membersOut[i]);
    }
    VnCanonicalPackSetActivationReportV1 active{};
    ASSERT_EQ(VN_OK, harkentest::ActivateCanonicalMembersV1(
        members, 2, membersOut, active));
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    ASSERT_EQ(VN_OK, Vn_Update());
    engine.nullBackend.Pump(2);
    ASSERT_EQ(VN_OK, Vn_Update());
    const auto baseline = CaptureRootQueueOwners(engine);

    const auto unloadSet = [&]() {
        VnCanonicalPackSetUnloadDescV1 unload{};
        unload.structSize = sizeof(unload);
        unload.expectedInitHandle = active.initHandle;
        unload.baseSetRevision = active.resultSetRevision;
        unload.unloadRevision = active.resultSetRevision + 1;
        ASSERT_EQ(VN_OK, Vn_UnloadCanonicalPackSetV1(&unload));
        EXPECT_EQ(0u, engine.packs.LoadedCount());
        EXPECT_EQ(harken::kInvalidBusIndex, engine.buses.FindIndex(busId));
    };

    for (unsigned run = 0; run < 3; ++run) {
        SCOPED_TRACE(::testing::Message() << "run=" << run);
        ASSERT_EQ(VN_OK, Vn_SetBusVolume(busId, -6.0f, 0));
        // Init owns Master Volume; its separate output trim remains mutable.
        EXPECT_EQ(VN_IN_USE, Vn_SetBusVolume(VN_BUS_MASTER, -3.0f, 0));
        ASSERT_EQ(VN_OK, Vn_SetBusOutputVolume(VN_BUS_MASTER, -3.0f, 0));
        ASSERT_EQ(VN_OK, Vn_SetBusOutputVolume(busId, -6.0f, 0));
        VnPostActionDesc post{};
        post.structSize = sizeof(post);
        post.actionId = actionId;
        post.emitter = emitter;
        post.callerSeed = 37;
        VnActionFiringHandle firing = 0;
        ASSERT_EQ(VN_OK, Vn_PostAction(&post, &firing));
        VnActionStepResult step{};
        step.structSize = sizeof(step);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &step));
        ASSERT_EQ(VN_ACTION_STEP_ACTIVE, step.state);
        ASSERT_EQ(VN_OK, step.result);
        EXPECT_EQ(actionId, step.ownerActionId);
        EXPECT_EQ(rootId, step.targetStableId);
        const auto produced = step.producedPlayableInstance;
        ASSERT_NE(0u, produced);
        const auto liveLease = [&]() {
            const auto it = std::find_if(engine.playableServices.begin(),
                engine.playableServices.end(), [&](const auto& row) {
                    return row.rootInstance == produced;
                });
            return it == engine.playableServices.end() ? PackPartitionLease{}
                                                       : it->Invocation().packLease;
        };
        const auto originalLease = liveLease();
        ASSERT_NE(0u, originalLease.leaseToken);
        SelectionMemoryKeyV1 parentMemory{};
        if (nested) {
            const auto row = std::find_if(engine.playableServices.begin(),
                engine.playableServices.end(), [&](const auto& service) {
                    return service.rootInstance == produced;
                });
            ASSERT_NE(engine.playableServices.end(), row);
            parentMemory.world = row->Invocation().worldGeneration;
            parentMemory.containerStableId = rootId;
            parentMemory.programSemanticFingerprint =
                MakeContainerProperty(rootId, 2).programSemanticFingerprint;
            parentMemory.memoryScope = MemoryScopeV1::Global;
        }
        bool replaced = run != 0;
        bool refusalPending = false;
        bool refusalAudioChecked = false;
        bool stopRequested = false;
        unsigned blocksAfterStop = 0;
        unsigned positiveBlocks = 0, negativeBlocks = 0;
        std::uint64_t onset = UINT64_MAX;
        bool startsPositive = true;
        TimelineArmToken firstArm{};
        bool onsetChecked = false;
        VnActionFiringInfo info{};
        info.structSize = sizeof(info);
        const auto gain = [](float db) { return std::pow(10.0f, db / 20.0f); };
        for (unsigned block = 0; block < 160; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            if (block == 0) {
                // Freeze the bound plan before rendering; PCM cannot define its own oracle.
                const auto row = std::find_if(engine.playableServices.begin(),
                    engine.playableServices.end(), [&](const auto& service) {
                        return service.rootInstance == produced;
                    });
                ASSERT_NE(engine.playableServices.end(), row);
                auto* resource = FrontierActiveResourceService(engine, *row);
                ASSERT_NE(nullptr, resource);
                const auto installedArm = resource->arm;
                TimelineArmObservation installation{};
                ASSERT_TRUE(engine.timelineArms.Observe(installedArm, &installation));
                if (installation.state == ArmState::PendingApply) {
                    // One audio callback installs the source before Update can bind its start.
                    ASSERT_TRUE(resource->phase == EnginePlayableStartPhase::PendingImmediateEntry ||
                                resource->phase == EnginePlayableStartPhase::AwaitingArmAck);
                    EXPECT_EQ(0u, installation.startedBlockSequence);
                    const auto installBefore = engine.mixer.BlocksRendered();
                    engine.nullBackend.Pump(1);
                    ASSERT_EQ(installBefore + 1u, engine.mixer.BlocksRendered());
                    const auto* installPcm = engine.nullBackend.LastBlock();
                    ASSERT_NE(nullptr, installPcm);
                    for (unsigned i = 0; i < engine.nullBackend.BlockFrames() *
                                              engine.nullBackend.Channels(); ++i)
                        ASSERT_EQ(0.0f, installPcm[i]) << "unpublished installation frame " << i;
                    ASSERT_TRUE(engine.timelineArms.Observe(installedArm, &installation));
                    ASSERT_EQ(ArmState::Armed, installation.state);
                    EXPECT_EQ(installBefore + 1u, installation.armedCompletionSequence);
                    EXPECT_EQ(0u, installation.startedBlockSequence);
                    ASSERT_EQ(VN_OK, Vn_Update());
                    resource = FrontierActiveResourceService(engine, *row);
                    ASSERT_NE(nullptr, resource);
                }
                EXPECT_EQ(installedArm.slot, resource->arm.slot);
                EXPECT_EQ(installedArm.generation, resource->arm.generation);
                EXPECT_EQ(installedArm.renderSlot, resource->arm.renderSlot);
                EXPECT_EQ(installedArm.renderGeneration, resource->arm.renderGeneration);
                ASSERT_TRUE(engine.timelineArms.Observe(resource->arm, &installation));
                ASSERT_EQ(ArmState::Published, installation.state);
                EXPECT_EQ(0u, installation.startedBlockSequence);
                ASSERT_EQ(PlayableKindV1::Sound, resource->leaf.kind);
                EXPECT_EQ(resource->leaf.stableId, resource->voice.soundId);
                EXPECT_EQ(busId, resource->voice.outputBusId);
                ASSERT_TRUE(resource->voice.soundId == firstId ||
                            resource->voice.soundId == secondId);
                startsPositive = resource->voice.soundId == firstId;
                if (!random) EXPECT_TRUE(startsPositive);
                ContainerPlaybackRow outer{};
                ASSERT_TRUE(engine.containerPlayback.Capture(produced, &outer));
                const auto queueOwner = nested ? outer.activeChild : produced;
                ContainerPlaybackRow queue{};
                ASSERT_TRUE(engine.containerPlayback.Capture(queueOwner, &queue));
                ASSERT_EQ(resource->activeLeafInstance, queue.activeChild);
                const auto leaf = engine.playableInstances.Classify(queue.activeChild);
                ASSERT_TRUE(leaf.live);
                EXPECT_EQ(queueOwner, leaf.parent);
                if (nested) {
                    const auto queueView = engine.playableInstances.Classify(queueOwner);
                    ASSERT_TRUE(queueView.live);
                    EXPECT_EQ(produced, queueView.parent);
                }
                onset = resource->startFrame;
                EXPECT_EQ(onset, resource->schedule.entryAnchorFrame);
                ASSERT_GE(onset, engine.mixer.BlocksRendered() *
                                     engine.nullBackend.BlockFrames());
                firstArm = resource->arm;
            }
            const auto before = engine.mixer.BlocksRendered();
            engine.nullBackend.Pump(1);
            ASSERT_GT(engine.mixer.BlocksRendered(), before);
            const auto* pcm = engine.nullBackend.LastBlock();
            ASSERT_NE(nullptr, pcm);
            const auto frames = engine.nullBackend.BlockFrames();
            ASSERT_EQ(2u, engine.nullBackend.Channels());
            if (stopRequested) ++blocksAfterStop;
            bool positive = false, negative = false;
            for (unsigned frame = 0; frame < frames; ++frame) {
                const auto absoluteFrame = before * frames + frame;
                const auto left = pcm[frame * 2];
                const auto right = pcm[frame * 2 + 1];
                ASSERT_TRUE(std::isfinite(left));
                ASSERT_TRUE(std::isfinite(right));
                const auto elapsed = absoluteFrame < onset
                    ? UINT64_MAX : absoluteFrame - onset;
                const bool inClip = elapsed < first.size() + second.size();
                const bool firstClip = elapsed < first.size();
                const bool positiveClip = firstClip == startsPositive;
                const float sample = inClip ? (positiveClip ? 0.125f : -0.25f) : 0.0f;
                const float sendDb = run == 2 || !replaced ? -6.0f : -12.0f;
                const float childDb = run == 0 && replaced ? -12.0f : -6.0f;
                const float expected = sample *
                    gain(childDb - 3.0f) * (gain(-6.0f) + gain(sendDb));
                if (stopRequested && blocksAfterStop == 1) {
                    // The zero-fade stop may include its one-block de-click tail.
                    ASSERT_LE(std::abs(left), std::abs(expected) + 1e-5f);
                    ASSERT_NEAR(left, right, 1e-5f);
                } else {
                    const float target = stopRequested ? 0.0f : expected;
                    ASSERT_NEAR(target, left, 1e-5f) << "block=" << block << " frame=" << frame;
                    ASSERT_NEAR(target, right, 1e-5f) << "block=" << block << " frame=" << frame;
                }
                positive |= inClip && positiveClip && !stopRequested;
                negative |= inClip && !positiveClip && !stopRequested;
            }
            if (before == onset / frames) {
                TimelineArmObservation started{};
                ASSERT_TRUE(engine.timelineArms.Observe(firstArm, &started));
                EXPECT_EQ(onset / frames + 1u, started.startedBlockSequence);
                onsetChecked = true;
            }
            positiveBlocks += positive;
            negativeBlocks += negative;
            ASSERT_EQ(VN_OK, Vn_Update());
            ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
            EXPECT_EQ(actionId, info.actionId);
            EXPECT_EQ(1u, info.directStepCount);
            if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED &&
                (!stopRequested || blocksAfterStop >= 2)) break;
            VnActionStepResult current{};
            current.structSize = sizeof(current);
            ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &current));
            EXPECT_EQ(produced, current.producedPlayableInstance);
            if (refusalPending) {
                // This newly rendered block used the old Send and both old trims.
                ASSERT_TRUE(positive || negative);
                refusalAudioChecked = true;
                EXPECT_EQ(originalLease.leaseToken, liveLease().leaseToken);
                EXPECT_EQ(VN_OK, engine.packComposition.ValidateLease(originalLease));
                members[0].utf8Path = replacementPath.c_str();
                VnCanonicalPackSetActivationReportV1 next{};
                ASSERT_EQ(VN_OK, harkentest::ActivateCanonicalMembersV1(
                    members, 2, membersOut, next, active.initHandle,
                    active.resultSetRevision));
                EXPECT_EQ(active.resultSetRevision + 1, next.resultSetRevision);
                active = next;
                EXPECT_EQ(originalLease.leaseToken, liveLease().leaseToken);
                EXPECT_EQ(VN_OK, engine.packComposition.ValidateLease(originalLease));
                ASSERT_EQ(VN_OK, Vn_SetBusVolume(busId, -12.0f, 0));
                replaced = true;
                refusalPending = false;
                positiveBlocks = negativeBlocks = 0;
            } else if (!replaced && positiveBlocks + negativeBlocks >= 2) {
                const auto publication = engine.packComposition.PublishedHandle();
                const auto owners = CaptureRootQueueOwners(engine);
                const auto topologyRevision = engine.acceptedBusTopologyRevision;
                members[0].expectedHandle = membersOut[0].handle;
                members[1].expectedHandle = membersOut[1].handle;
                members[0].utf8Path = invalidPath.c_str();
                VnCanonicalPackSetActivationReportV1 refused{};
                EXPECT_EQ(VN_BAD_PACK, harkentest::ActivateCanonicalMembersV1(
                    members, 2, membersOut, refused, active.initHandle,
                    active.resultSetRevision));
                EXPECT_EQ(publication, engine.packComposition.PublishedHandle());
                EXPECT_EQ(topologyRevision, engine.acceptedBusTopologyRevision);
                EXPECT_EQ(owners, CaptureRootQueueOwners(engine));
                EXPECT_EQ(VN_INVALID_ARG, Vn_SetBusVolume(busId,
                    std::numeric_limits<float>::quiet_NaN(), 0));
                EXPECT_EQ(VN_IN_USE, Vn_UnloadPackEx(members[1].expectedHandle,
                    VN_PACK_UNLOAD_REFUSE_IF_USED));
                refusalPending = true;
            }
            if (run == 1 && positiveBlocks > 1 && negativeBlocks > 1 && !stopRequested) {
                ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
                stopRequested = true;
            }
        }
        ASSERT_TRUE(onsetChecked);
        ASSERT_TRUE(replaced);
        if (run == 0) EXPECT_TRUE(refusalAudioChecked);
        EXPECT_GT(positiveBlocks, 1u);
        EXPECT_GT(negativeBlocks, 1u);
        ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
        if (run != 1) {
            ASSERT_NE(UINT64_MAX, onset);
            EXPECT_GE(engine.mixer.BlocksRendered() * engine.nullBackend.BlockFrames(),
                onset + first.size() + second.size());
            EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
            EXPECT_EQ(VN_ACTION_TERMINAL_NATURAL, info.terminalReason);
        } else {
            EXPECT_TRUE(stopRequested);
            EXPECT_EQ(VN_ACTION_OUTCOME_CANCELLED, info.outcome);
            EXPECT_EQ(VN_ACTION_TERMINAL_STOP_REQUESTED, info.terminalReason);
            EXPECT_GE(blocksAfterStop, 2u);
        }
        ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
        for (unsigned block = 0; block < 16; ++block) {
            const auto before = engine.mixer.BlocksRendered();
            engine.nullBackend.Pump(1);
            ASSERT_GT(engine.mixer.BlocksRendered(), before);
            ASSERT_EQ(VN_OK, Vn_Update());
        }
        auto expectedOwners = baseline;
        // The parent RandomDraw retains one committed Global selection row
        // in the current world. Run 0's replacement retires its old world;
        // playback owners and pending selection deltas must still all return.
        constexpr unsigned kSelectionRows = 17;
        expectedOwners[kSelectionRows] += nested && run != 0 ? 1u : 0u;
        EXPECT_EQ(expectedOwners, CaptureRootQueueOwners(engine));
        if (nested) {
            const auto memory = engine.selectionMemory.Snapshot(parentMemory);
            EXPECT_EQ(run != 0, memory.found);
            EXPECT_EQ(0u, memory.pendingCount);
            if (run != 0) EXPECT_EQ(1u, memory.selectionOrdinal);
        }
        for (unsigned i = 0; i < engine.nullBackend.BlockFrames() * 2; ++i)
            EXPECT_NEAR(0.0f, engine.nullBackend.LastBlock()[i], harkentest::kSilenceFloor);
        if (run == 1) {
            ASSERT_NO_FATAL_FAILURE(unloadSet());
            members[0].expectedHandle = members[1].expectedHandle = 0;
            members[0].utf8Path = initialPath.c_str();
            ASSERT_EQ(VN_OK, harkentest::ActivateCanonicalMembersV1(
                members, 2, membersOut, active));
            ASSERT_EQ(VN_OK, Vn_Update());
            if (nested) EXPECT_FALSE(engine.selectionMemory.Snapshot(parentMemory).found);
        }
    }
    ASSERT_NO_FATAL_FAILURE(unloadSet());
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
    EXPECT_FALSE(engine.runtimeRecreateRequired);
}

INSTANTIATE_TEST_SUITE_P(SequenceRandomNested, QueueBusQualification,
    ::testing::Values(0u, 1u, 2u));

TEST(PackComposition, InitialCapabilityUsesActualReachableDefinitionsAndQueueEntry) {
    std::array<PlayablePropertyProgramViewV1, 3> legacyProperties{};
    for (unsigned i = 0; i < legacyProperties.size(); ++i) {
        legacyProperties[i].stableId = harkentest::ObjectId(i + 1);
        legacyProperties[i].programSemanticFingerprint = 101 + i;
        legacyProperties[i].contentPropertyKind =
            playableproperties::ContentPropertyKindV1::Container;
    }
    auto modernProperty = MakeSoundProperty(harkentest::ObjectId(4));
    std::array<ContainerChildProgramViewV2, 2> children{};
    children[0].stableChildOrdinal = 1;
    children[0].frequencyWeight = 1;
    children[0].playable = {PlayableKindV1::Container, 0, legacyProperties[1].stableId,
                           legacyProperties[1].programSemanticFingerprint};
    children[1].stableChildOrdinal = 2;
    children[1].frequencyWeight = 1;
    children[1].playable = {PlayableKindV1::Sound, 0, modernProperty.stableId,
                           modernProperty.programSemanticFingerprint};
    ContainerProgramViewV3 root{};
    root.containerStableId = legacyProperties[0].stableId;
    root.mode = ContainerModeV1::SequenceQueue;
    root.children = children.data();
    root.childCount = 2;
    ContainerWorldInstallViewV1 worlds[2]{};
    worlds[0].playableProperties = legacyProperties.data();
    worlds[0].playablePropertyCount = legacyProperties.size();
    worlds[0].containers = &root;
    worlds[0].containerCount = 1;
    worlds[1].sourceBodyVintage = 19;
    worlds[1].playableProperties = &modernProperty;
    worlds[1].playablePropertyCount = 1;
    std::vector<ProgramCapabilitySummaryV1> summaries;
    const auto capability = [&](VnObjectId id) {
        const auto found = std::find_if(summaries.begin(), summaries.end(),
            [&](const auto& row) { return row.stableId == id; });
        EXPECT_NE(summaries.end(), found);
        return found != summaries.end() ? found->initialClosureCapabilities : UINT32_MAX;
    };
    ASSERT_TRUE(BuildProgramCapabilitySummariesV1(worlds, 2, summaries));
    EXPECT_EQ(0u, capability(legacyProperties[0].stableId));
    EXPECT_EQ(0u, capability(legacyProperties[2].stableId));
    EXPECT_EQ(kProgramCapabilityEntrySchedulingV1, capability(modernProperty.stableId));
    root.initialSequenceCursor = 1;
    ASSERT_TRUE(BuildProgramCapabilitySummariesV1(worlds, 2, summaries));
    EXPECT_EQ(kProgramCapabilityEntrySchedulingV1, capability(legacyProperties[0].stableId));
    root.initialSequenceCursor = 0;
    root.resumePosition = 1;
    ASSERT_TRUE(BuildProgramCapabilitySummariesV1(worlds, 2, summaries));
    EXPECT_EQ(kProgramCapabilityEntrySchedulingV1, capability(legacyProperties[0].stableId));
    root.mode = ContainerModeV1::Random;
    children[1].frequencyWeight = 0;
    ASSERT_TRUE(BuildProgramCapabilitySummariesV1(worlds, 2, summaries));
    EXPECT_EQ(0u, capability(legacyProperties[0].stableId));
    children[1].frequencyWeight = 1;
    ASSERT_TRUE(BuildProgramCapabilitySummariesV1(worlds, 2, summaries));
    EXPECT_EQ(kProgramCapabilityEntrySchedulingV1, capability(legacyProperties[0].stableId));
    ++children[1].playable.expectedProgramSemanticFingerprint;
    EXPECT_FALSE(BuildProgramCapabilitySummariesV1(worlds, 2, summaries));
    EXPECT_TRUE(summaries.empty());
    --children[1].playable.expectedProgramSemanticFingerprint;
    children[0].playable = {PlayableKindV1::Container, 0, legacyProperties[0].stableId,
                           legacyProperties[0].programSemanticFingerprint};
    EXPECT_FALSE(BuildProgramCapabilitySummariesV1(worlds, 2, summaries));
    worlds[1].sourceBodyVintage = 18;
    ASSERT_TRUE(BuildProgramCapabilitySummariesV1(worlds, 2, summaries));
    EXPECT_TRUE(summaries.empty());
}

TEST(PackComposition, V19PartitionReaderAndFallbackKeepVintageButActivationStaysDisabled) {
    auto property = MakeSoundProperty(harkentest::ObjectId(20));
    ContainerWorldInstallViewV1 world{};
    world.sourceBodyVintage = 19;
    world.identity.projectId = {0x1234, 0};
    world.playableProperties = &property;
    world.playablePropertyCount = 1;
    world.identity.capabilityMask = detail::ComputeCurrentWorldLocalCapabilityMaskV1(world);
    world.identity.runtimeSemanticFingerprint = ComputeCurrentWorldFingerprintV6(world);
    ASSERT_EQ(WorldInstallStatus::Ok, detail::ValidateCurrentWorldPartitionLocalV1(world));
    const auto bytes = BuildCanonicalPartitionPack(22, 1, 7, WrapWorldPartition(22, 7, world, 1));
    PackCanonicalImage image;
    ASSERT_EQ(VN_OK, ParsePackCanonicalImage(bytes.data(), bytes.size(), &image));
    EXPECT_EQ(19u, image.partitionHeader.bodyVintage);
    PackComposition composition(4, 8, 4);
    PackComposition::CandidateOwner candidate;
    ASSERT_EQ(VN_OK, composition.PrepareCandidate(image, 1, &candidate));
    EXPECT_EQ(19u, candidate.partitionBodyVintage);
    EXPECT_EQ(nullptr, candidate.body);
    CurrentWorldBodyImage decoded;
    ASSERT_TRUE(decoded.Decode(candidate.partitionBody.data(), candidate.partitionBody.size(),
        candidate.partitionBodyVintage, CurrentWorldDecodeMode::StrictArtifact));
    EXPECT_EQ(19u, decoded.ProductionView()->sourceBodyVintage);
    PackComposition::PreparedCommit prepared;
    std::vector<PackComposition::CandidateOwner> candidates;
    candidates.push_back(std::move(candidate));
    EXPECT_EQ(VN_CAPABILITY_UNAVAILABLE, composition.PrepareCommit(
        std::move(candidates), nullptr, 0, 8, 0, &prepared));
    EXPECT_FALSE(prepared.IsPrepared());
    EXPECT_EQ(nullptr, composition.Published());
}
